// memhub build script
//
// Stages the bundled retrieval model files into OUT_DIR so the main crate
// can include them via include_bytes!. Two models are bundled:
//
//   * BGE-small-en-v1.5 — bi-encoder used by the M8 hybrid recall path.
//     ~127 MB. Source: BAAI/bge-small-en-v1.5@main, commit
//     5c38ec7c405ec4b44b94cc5a9bb96e735b38267a.
//
//   * ms-marco-MiniLM-L-6-v2 — cross-encoder re-ranker bundled by the
//     task-#21 work. ~22 MB (int8-quantized `model_int8.onnx`; issue #75
//     / Q18, decision 148 — was ~91 MB fp32). Source:
//     Xenova/ms-marco-MiniLM-L-6-v2@main (an ONNX export of
//     cross-encoder/ms-marco-MiniLM-L-6-v2). Selected over BGE-reranker-
//     v2-m3 in the bake-off (decisions 68–70): +17.7pp Recall@1 over
//     baseline, 15× faster than BGE-v2-m3, no keyword regressions.
//     BAAI publishes no quantized bge-small ONNX (verified against the
//     HF repo file tree), so the bi-encoder stays fp32 — only the
//     re-ranker is int8 here (partial adoption, issue #75).
//
// On a clean build this downloads ~150 MB total from Hugging Face (was
// ~218 MB before the int8 re-ranker swap). On
// rebuilds the staged files are reused if their SHA256 matches the
// pinned value. All hashes were computed locally over the downloaded
// bytes (or, for BGE-small's model.onnx, match the x-linked-etag
// returned by Hugging Face for the pinned commit).
//
// BUILD-TIME NETWORK CONTRACT (task 52). memhub's offline-first
// principle is a *runtime* guarantee: the built binary never reaches the
// network (the lone exception is the explicit, opt-in `memhub metrics
// calibrate`). Building from source is a different matter — this fetch is
// the one point where producing the binary touches the network. The
// OUT_DIR staging cache is the only offline fallback, and `cargo clean`
// discards it, so the next build re-fetches. Airgapped *source* builds
// are therefore unsupported; there is no offline asset override today.

use std::env;
use std::fs;
use std::io::{Read, Write};
use std::path::{Path, PathBuf};

use sha2::{Digest, Sha256};

struct ModelFile {
    /// Path inside the Hugging Face repo, relative to the model's base URL.
    remote_path: &'static str,
    /// Filename to use under OUT_DIR/<model_dir>/.
    local_name: &'static str,
    /// Hex-encoded SHA256 of the expected file contents.
    sha256: &'static str,
}

struct ModelBundle {
    /// Subdirectory under OUT_DIR where the files are staged.
    local_dir: &'static str,
    /// Hugging Face base URL (resolve/main).
    base_url: &'static str,
    files: &'static [ModelFile],
}

const BGE_SMALL: ModelBundle = ModelBundle {
    local_dir: "bge-small-en-v1.5",
    base_url: "https://huggingface.co/BAAI/bge-small-en-v1.5/resolve/main",
    files: &[
        ModelFile {
            remote_path: "onnx/model.onnx",
            local_name: "model.onnx",
            sha256: "828e1496d7fabb79cfa4dcd84fa38625c0d3d21da474a00f08db0f559940cf35",
        },
        ModelFile {
            remote_path: "tokenizer.json",
            local_name: "tokenizer.json",
            sha256: "d241a60d5e8f04cc1b2b3e9ef7a4921b27bf526d9f6050ab90f9267a1f9e5c66",
        },
        ModelFile {
            remote_path: "config.json",
            local_name: "config.json",
            sha256: "094f8e891b932f2000c92cfc663bac4c62069f5d8af5b5278c4306aef3084750",
        },
        ModelFile {
            remote_path: "special_tokens_map.json",
            local_name: "special_tokens_map.json",
            sha256: "b6d346be366a7d1d48332dbc9fdf3bf8960b5d879522b7799ddba59e76237ee3",
        },
        ModelFile {
            remote_path: "tokenizer_config.json",
            local_name: "tokenizer_config.json",
            sha256: "9261e7d79b44c8195c1cada2b453e55b00aeb81e907a6664974b4d7776172ab3",
        },
    ],
};

const RERANKER: ModelBundle = ModelBundle {
    local_dir: "ms-marco-MiniLM-L-6-v2",
    base_url: "https://huggingface.co/Xenova/ms-marco-MiniLM-L-6-v2/resolve/main",
    files: &[
        // int8-quantized cross-encoder (issue #75 / Q18, decision 148).
        // Xenova publishes several quant variants under onnx/;
        // `model_int8.onnx` is the QInt8 dynamic quantization (91 MB fp32
        // -> 22 MB). Staged under the same local name `model.onnx` so
        // rerank.rs's include_bytes! is unchanged. The SHA-256 is the HF
        // LFS oid (x-linked-etag) for the pinned file, read from the repo
        // file tree and re-verified over the downloaded bytes by
        // ensure_file below.
        ModelFile {
            remote_path: "onnx/model_int8.onnx",
            local_name: "model.onnx",
            sha256: "a13ec391ca99f49886694e12d3e800521f36d4267d7d448c34421c541a2baf50",
        },
        // tokenizer.json and special_tokens_map.json are byte-identical to
        // BGE-small's (shared BERT WordPiece vocab); SHAs match accordingly.
        ModelFile {
            remote_path: "tokenizer.json",
            local_name: "tokenizer.json",
            sha256: "d241a60d5e8f04cc1b2b3e9ef7a4921b27bf526d9f6050ab90f9267a1f9e5c66",
        },
        ModelFile {
            remote_path: "config.json",
            local_name: "config.json",
            sha256: "d827779a72d27ae68cf878a6fc2e954542663fe21ca515d9f4783fc96be2d37e",
        },
        ModelFile {
            remote_path: "special_tokens_map.json",
            local_name: "special_tokens_map.json",
            sha256: "b6d346be366a7d1d48332dbc9fdf3bf8960b5d879522b7799ddba59e76237ee3",
        },
        ModelFile {
            remote_path: "tokenizer_config.json",
            local_name: "tokenizer_config.json",
            sha256: "0b29c7bfc889e53b36d9dd3e686dd4300f6525110eaa98c76a5dafceb2029f53",
        },
    ],
};

const BUNDLES: &[&ModelBundle] = &[&BGE_SMALL, &RERANKER];

fn main() {
    println!("cargo:rerun-if-changed=build.rs");

    let out_dir = PathBuf::from(env::var_os("OUT_DIR").expect("OUT_DIR not set by cargo"));
    for bundle in BUNDLES {
        let stage_dir = out_dir.join(bundle.local_dir);
        fs::create_dir_all(&stage_dir).unwrap_or_else(|e| {
            panic!("failed to create {}: {e}", stage_dir.display());
        });
        for file in bundle.files {
            let dest = stage_dir.join(file.local_name);
            ensure_file(&dest, bundle.base_url, file);
        }
    }
}

fn ensure_file(dest: &Path, base_url: &str, file: &ModelFile) {
    if let Ok(actual) = sha256_of(dest) {
        if actual.eq_ignore_ascii_case(file.sha256) {
            return;
        }
        println!(
            "cargo:warning=cached {} has unexpected hash {actual}; re-downloading",
            dest.display()
        );
        let _ = fs::remove_file(dest);
    }

    let url = format!("{base_url}/{}", file.remote_path);
    println!(
        "cargo:warning=memhub: downloading {} -> {}",
        url,
        dest.display()
    );

    let response = ureq::get(&url)
        .call()
        .unwrap_or_else(|e| panic!("failed to fetch {url}: {e}"));

    let capacity = response
        .header("Content-Length")
        .and_then(|s| s.parse::<usize>().ok())
        .unwrap_or(0);
    let mut bytes: Vec<u8> = Vec::with_capacity(capacity);
    response
        .into_reader()
        .read_to_end(&mut bytes)
        .unwrap_or_else(|e| panic!("failed to read body of {url}: {e}"));

    let actual = hex_sha256(&bytes);
    if !actual.eq_ignore_ascii_case(file.sha256) {
        panic!(
            "{url} sha256 mismatch: expected {}, got {actual}",
            file.sha256
        );
    }

    let tmp = dest.with_extension("download");
    let mut f = fs::File::create(&tmp)
        .unwrap_or_else(|e| panic!("failed to create {}: {e}", tmp.display()));
    f.write_all(&bytes)
        .unwrap_or_else(|e| panic!("failed to write {}: {e}", tmp.display()));
    f.sync_all().ok();
    drop(f);
    fs::rename(&tmp, dest)
        .unwrap_or_else(|e| panic!("failed to rename into {}: {e}", dest.display()));
}

fn sha256_of(path: &Path) -> std::io::Result<String> {
    let mut f = fs::File::open(path)?;
    let mut hasher = Sha256::new();
    let mut buf = [0u8; 64 * 1024];
    loop {
        let n = f.read(&mut buf)?;
        if n == 0 {
            break;
        }
        hasher.update(&buf[..n]);
    }
    Ok(hex_encode(hasher.finalize().as_slice()))
}

fn hex_sha256(bytes: &[u8]) -> String {
    let mut hasher = Sha256::new();
    hasher.update(bytes);
    hex_encode(hasher.finalize().as_slice())
}

fn hex_encode(bytes: &[u8]) -> String {
    const HEX: &[u8; 16] = b"0123456789abcdef";
    let mut out = String::with_capacity(bytes.len() * 2);
    for &b in bytes {
        out.push(HEX[(b >> 4) as usize] as char);
        out.push(HEX[(b & 0x0f) as usize] as char);
    }
    out
}

//! Throwaway bake-off harness for task #20 (cross-encoder re-ranker bundle decision).
//!
//! Compares two candidate cross-encoders for memhub's hybrid recall:
//!   * cross-encoder/ms-marco-MiniLM-L-6-v2 (~80 MB, Xenova ONNX export)
//!   * BAAI/bge-reranker-v2-m3              (~280 MB + external data, rozgo ONNX export)
//!
//! Each candidate runs over the **same** top-N hybrid pool fetched from
//! `memhub recall --json --mode hybrid --max-results N`, then is scored on
//! `tests/retrieval_golden.json` (Recall@1, Recall@3, MRR) plus the gibberish
//! safety probe (max rerank score — lower is better). Latency is mean
//! per-query reranking time only; recall fetch is excluded.
//!
//! This is not production code. After the bake-off informs the bundle
//! decision, `src/retrieval/rerank.rs` + `build.rs` integration for the
//! winner happens in a separate PR; this example can stay (as a regression
//! harness for future re-ranker swaps) or be deleted.
//!
//! Run:
//!   cargo run --release --example rerank_bakeoff -- --candidate-pool 30
//!
//! Model files cache at /tmp/memhub-rerank-bakeoff/{minilm,bge_v2_m3}/.
//! ~1.5 GB of HuggingFace downloads on first run; subsequent runs reuse.

use std::{
    fs, io,
    path::{Path, PathBuf},
    process::Command,
    time::Instant,
};

use anyhow::{Context, Result, anyhow};
use fastembed::{
    OnnxSource, RerankInitOptionsUserDefined, TextRerank, TokenizerFiles, UserDefinedRerankingModel,
};
use serde::Deserialize;

const CACHE_ROOT: &str = "/tmp/memhub-rerank-bakeoff";

struct ModelSpec {
    label: &'static str,
    cache_subdir: &'static str,
    base_url: &'static str,
    /// (remote_path_under_base_url, local_filename)
    files: &'static [(&'static str, &'static str)],
}

const MINILM: ModelSpec = ModelSpec {
    label: "cross-encoder/ms-marco-MiniLM-L-6-v2 (Xenova)",
    cache_subdir: "minilm",
    base_url: "https://huggingface.co/Xenova/ms-marco-MiniLM-L-6-v2/resolve/main",
    files: &[
        ("onnx/model.onnx", "model.onnx"),
        ("tokenizer.json", "tokenizer.json"),
        ("config.json", "config.json"),
        ("special_tokens_map.json", "special_tokens_map.json"),
        ("tokenizer_config.json", "tokenizer_config.json"),
    ],
};

const BGE_V2_M3: ModelSpec = ModelSpec {
    label: "BAAI/bge-reranker-v2-m3 (rozgo)",
    cache_subdir: "bge_v2_m3",
    base_url: "https://huggingface.co/rozgo/bge-reranker-v2-m3/resolve/main",
    files: &[
        ("model.onnx", "model.onnx"),
        ("model.onnx.data", "model.onnx.data"),
        ("tokenizer.json", "tokenizer.json"),
        ("config.json", "config.json"),
        ("special_tokens_map.json", "special_tokens_map.json"),
        ("tokenizer_config.json", "tokenizer_config.json"),
    ],
};

#[derive(Debug, Deserialize)]
struct GoldenFile {
    queries: Vec<GoldenQuery>,
}

#[derive(Debug, Deserialize, Clone)]
struct GoldenQuery {
    id: String,
    query: String,
    kind: String,
    #[serde(default)]
    source_type: Option<String>,
    #[serde(default)]
    title_contains: Vec<String>,
    #[serde(default)]
    body_contains: Vec<String>,
}

#[derive(Debug, Deserialize, Clone)]
struct RecallResponse {
    results: Vec<RecallHit>,
}

#[derive(Debug, Deserialize, Clone)]
struct RecallHit {
    #[allow(dead_code)]
    rank: usize,
    source_type: String,
    title: String,
    body: String,
}

fn ensure_model(spec: &ModelSpec) -> Result<PathBuf> {
    let dir = Path::new(CACHE_ROOT).join(spec.cache_subdir);
    fs::create_dir_all(&dir).with_context(|| format!("mkdir {}", dir.display()))?;
    for (remote, local) in spec.files {
        let dest = dir.join(local);
        if dest.exists() {
            continue;
        }
        let url = format!("{}/{remote}", spec.base_url);
        eprintln!("  fetch {url}");
        eprintln!("     -> {}", dest.display());
        let resp = ureq::get(&url)
            .call()
            .with_context(|| format!("GET {url}"))?;
        let mut writer = fs::File::create(&dest)?;
        let mut reader = resp.into_reader();
        let copied = io::copy(&mut reader, &mut writer)?;
        eprintln!("     {} bytes", copied);
    }
    Ok(dir)
}

fn load_reranker(spec: &ModelSpec) -> Result<TextRerank> {
    let dir = ensure_model(spec)?;
    // OnnxSource::File so the runtime can resolve sibling `model.onnx.data`
    // for split-weight models (BGE-reranker-v2-m3). Memory mode strips that
    // context and fails to initialize.
    let onnx_path = dir.join("model.onnx");
    let tokenizer_files = TokenizerFiles {
        tokenizer_file: fs::read(dir.join("tokenizer.json"))?,
        config_file: fs::read(dir.join("config.json"))?,
        special_tokens_map_file: fs::read(dir.join("special_tokens_map.json"))?,
        tokenizer_config_file: fs::read(dir.join("tokenizer_config.json"))?,
    };
    let model = UserDefinedRerankingModel::new(OnnxSource::File(onnx_path), tokenizer_files);
    TextRerank::try_new_from_user_defined(model, RerankInitOptionsUserDefined::default())
        .with_context(|| format!("init reranker {}", spec.label))
}

fn run_recall(query: &str, pool: usize) -> Result<Vec<RecallHit>> {
    let out = Command::new("memhub")
        .args([
            "recall",
            query,
            "--json",
            "--mode",
            "hybrid",
            "--max-results",
        ])
        .arg(pool.to_string())
        .output()
        .context("spawn memhub recall")?;
    if !out.status.success() {
        return Err(anyhow!(
            "memhub recall failed: {}",
            String::from_utf8_lossy(&out.stderr)
        ));
    }
    let resp: RecallResponse = serde_json::from_slice(&out.stdout)
        .with_context(|| format!("parse recall JSON for {query:?}"))?;
    Ok(resp.results)
}

fn matches_hit(hit: &RecallHit, q: &GoldenQuery) -> bool {
    if let Some(st) = &q.source_type
        && !hit.source_type.eq_ignore_ascii_case(st)
    {
        return false;
    }
    let t = hit.title.to_lowercase();
    let b = hit.body.to_lowercase();
    q.title_contains
        .iter()
        .all(|s| t.contains(&s.to_lowercase()))
        && q.body_contains
            .iter()
            .all(|s| b.contains(&s.to_lowercase()))
}

/// Score an ordering (permutation of candidate indices) against a query.
fn score_order(order: &[usize], hits: &[RecallHit], q: &GoldenQuery, m: &mut MatchMetrics) {
    m.queries_total += 1;
    for (rank0, &idx) in order.iter().enumerate() {
        if matches_hit(&hits[idx], q) {
            let r = rank0 + 1;
            if r == 1 {
                m.recall_at_1 += 1;
            }
            if r <= 3 {
                m.recall_at_3 += 1;
            }
            m.mrr_sum += 1.0 / r as f64;
            m.found_ranks.push((q.id.clone(), r));
            return;
        }
    }
    m.found_ranks.push((q.id.clone(), 0)); // 0 = not found
}

#[derive(Default, Debug)]
struct MatchMetrics {
    queries_total: usize,
    recall_at_1: usize,
    recall_at_3: usize,
    mrr_sum: f64,
    rerank_ms_total: f64,
    found_ranks: Vec<(String, usize)>, // (query_id, found_rank or 0)
}

impl MatchMetrics {
    fn r_at_1(&self) -> f64 {
        100.0 * self.recall_at_1 as f64 / self.queries_total as f64
    }
    fn r_at_3(&self) -> f64 {
        100.0 * self.recall_at_3 as f64 / self.queries_total as f64
    }
    fn mrr(&self) -> f64 {
        self.mrr_sum / self.queries_total as f64
    }
    fn mean_rerank_ms(&self) -> f64 {
        if self.queries_total == 0 {
            0.0
        } else {
            self.rerank_ms_total / self.queries_total as f64
        }
    }
}

fn rerank_score(
    reranker: &mut TextRerank,
    query: &str,
    docs: &[String],
) -> Result<(Vec<usize>, f64, f32)> {
    let doc_refs: Vec<&str> = docs.iter().map(|s| s.as_str()).collect();
    let t0 = Instant::now();
    let results = reranker.rerank(query, &doc_refs, false, None)?;
    let elapsed_ms = t0.elapsed().as_secs_f64() * 1000.0;
    let order: Vec<usize> = results.iter().map(|r| r.index).collect();
    let top_score = results
        .first()
        .map(|r| r.score)
        .unwrap_or(f32::NEG_INFINITY);
    Ok((order, elapsed_ms, top_score))
}

fn print_table_row(label: &str, m: &MatchMetrics) {
    println!(
        "  {:<48}  {:>7.1}%  {:>7.1}%  {:>5.3}   {:>7.1} ms",
        label,
        m.r_at_1(),
        m.r_at_3(),
        m.mrr(),
        m.mean_rerank_ms()
    );
}

fn main() -> Result<()> {
    let mut pool: usize = 30;
    let mut args = std::env::args().skip(1);
    while let Some(a) = args.next() {
        match a.as_str() {
            "--candidate-pool" => {
                pool = args
                    .next()
                    .ok_or_else(|| anyhow!("--candidate-pool needs N"))?
                    .parse()?
            }
            "-h" | "--help" => {
                eprintln!(
                    "Usage: cargo run --release --example rerank_bakeoff -- [--candidate-pool N]"
                );
                return Ok(());
            }
            other => return Err(anyhow!("unknown arg: {other}")),
        }
    }

    let golden_path = "tests/retrieval_golden.json";
    let golden: GoldenFile = serde_json::from_slice(&fs::read(golden_path)?)
        .with_context(|| format!("parse {golden_path}"))?;
    let match_queries: Vec<&GoldenQuery> = golden
        .queries
        .iter()
        .filter(|q| q.kind == "match")
        .collect();
    let empty_queries: Vec<&GoldenQuery> = golden
        .queries
        .iter()
        .filter(|q| q.kind == "empty")
        .collect();
    eprintln!(
        "Golden set: {} match queries, {} empty (safety) queries",
        match_queries.len(),
        empty_queries.len()
    );
    eprintln!("Candidate pool: top-{pool} by hybrid blend\n");

    eprintln!("Loading MiniLM...");
    let mut minilm = load_reranker(&MINILM)?;
    eprintln!("Loading BGE-reranker-v2-m3...");
    let mut bge = load_reranker(&BGE_V2_M3)?;
    eprintln!("Models loaded.\n");

    let mut base = MatchMetrics::default();
    let mut m_minilm = MatchMetrics::default();
    let mut m_bge = MatchMetrics::default();

    for q in &match_queries {
        let hits = run_recall(&q.query, pool)?;
        if hits.is_empty() {
            eprintln!("  [skip] {} — recall returned 0 candidates", q.id);
            continue;
        }
        let baseline_order: Vec<usize> = (0..hits.len()).collect();
        let docs: Vec<String> = hits
            .iter()
            .map(|h| format!("{}\n\n{}", h.title, h.body))
            .collect();

        let (minilm_order, minilm_ms, _) = rerank_score(&mut minilm, &q.query, &docs)?;
        m_minilm.rerank_ms_total += minilm_ms;
        let (bge_order, bge_ms, _) = rerank_score(&mut bge, &q.query, &docs)?;
        m_bge.rerank_ms_total += bge_ms;

        score_order(&baseline_order, &hits, q, &mut base);
        // Use the matching reranker's metrics for the rest, but rerank_ms_total
        // is already added above; score_order also bumps queries_total/etc.
        score_order(&minilm_order, &hits, q, &mut m_minilm);
        score_order(&bge_order, &hits, q, &mut m_bge);
    }

    println!(
        "=== Match-query results ({} queries, candidate pool top-{}) ===\n",
        match_queries.len(),
        pool
    );
    println!(
        "  {:<48}  {:>8}  {:>8}  {:>5}   {:>10}",
        "config", "Recall@1", "Recall@3", "MRR", "mean ms"
    );
    println!("  {}", "-".repeat(48 + 2 + 8 + 2 + 8 + 2 + 5 + 3 + 10));
    print_table_row("baseline (hybrid blend, no rerank)", &base);
    print_table_row("+ MiniLM-L-6-v2", &m_minilm);
    print_table_row("+ BGE-reranker-v2-m3", &m_bge);

    // Per-query rank table — useful for spotting regressions
    println!("\n=== Per-query target rank (0 = not found in top-{pool}) ===\n");
    println!(
        "  {:<46}  {:>8}  {:>8}  {:>8}",
        "query id", "baseline", "minilm", "bge-v2-m3"
    );
    println!("  {}", "-".repeat(46 + 2 + 8 + 2 + 8 + 2 + 8));
    for (i, q) in match_queries.iter().enumerate() {
        let b = base.found_ranks.get(i).map(|(_, r)| *r).unwrap_or(0);
        let mm = m_minilm.found_ranks.get(i).map(|(_, r)| *r).unwrap_or(0);
        let bg = m_bge.found_ranks.get(i).map(|(_, r)| *r).unwrap_or(0);
        println!("  {:<46}  {:>8}  {:>8}  {:>8}", q.id, b, mm, bg);
    }

    // Safety probes: how well do the rerankers discriminate against gibberish?
    println!("\n=== Safety probe (max rerank score over top-{pool} nonsense candidates) ===\n");
    println!(
        "  {:<46}  {:>14}  {:>14}",
        "query id", "minilm top", "bge top"
    );
    println!("  {}", "-".repeat(46 + 2 + 14 + 2 + 14));
    for q in &empty_queries {
        let hits = run_recall(&q.query, pool)?;
        if hits.is_empty() {
            println!(
                "  {:<46}  {:>14}  {:>14}",
                q.id, "(empty pool)", "(empty pool)"
            );
            continue;
        }
        let docs: Vec<String> = hits
            .iter()
            .map(|h| format!("{}\n\n{}", h.title, h.body))
            .collect();
        let (_, _, minilm_top) = rerank_score(&mut minilm, &q.query, &docs)?;
        let (_, _, bge_top) = rerank_score(&mut bge, &q.query, &docs)?;
        println!("  {:<46}  {:>14.4}  {:>14.4}", q.id, minilm_top, bge_top);
    }
    println!("\n(Lower top score = better safety discrimination.)");

    Ok(())
}

//! Derive `AGENTS.md` (the Codex / OpenCode orientation file) from
//! `CLAUDE.md` so the two can never silently drift.
//!
//! `CLAUDE.md` is the single hand-edited source. `AGENTS.md` is a pure
//! transform of it: swap the `# memhub` H1 for the Codex-flavored title,
//! inject a "generated — do not hand-edit" counterpart note after the
//! intro, and append the two Codex/OpenCode-only sections that have no
//! `CLAUDE.md` counterpart (the Codex attribution block and the Q41
//! fail-safe routing block). Nothing else is rewritten — the retained
//! `## ` sections carry through verbatim.
//!
//! If `CLAUDE.md` ends with an Orch-managed block (`<!-- orchestrator:managed:start -->`
//! … `<!-- orchestrator:managed:end -->`, appended and maintained by Orch's
//! installer — see `.orchestrator/config.toml`), it is split off before the
//! transform above and re-appended last, verbatim, after the two
//! Codex/OpenCode-only sections. Orch's installer expects to find that block
//! at EOF, so the generated file keeps it there instead of letting the
//! appended sections push it out of place.
//!
//! `tests/upgrade/skill_parity.rs` asserts `AGENTS.md == generate_agents_md(CLAUDE.md)`
//! (modulo line endings), so any edit to `CLAUDE.md` must be followed by a
//! regenerate-and-commit of `AGENTS.md`. The regeneration path is
//! `MEMHUB_REGEN=1 cargo test skill_parity` (see that test).

/// The `# memhub` H1 line `CLAUDE.md` must start with.
///
/// `pub(crate)` so `commands::audit_md` (issue #32) can check this same
/// precondition itself before calling [`generate_agents_md`] — that
/// function `assert!`s on it (a deliberate contract-frozen panic for a
/// programmer error, not a recoverable `Result`), so a read-only linter
/// over arbitrary repo content must verify it first rather than risk
/// crashing the CLI on a malformed `CLAUDE.md`.
pub(crate) const CLAUDE_TITLE: &str = "# memhub";

/// The H1 line the generated `AGENTS.md` carries instead.
const AGENTS_TITLE: &str = "# memhub — Codex CLI instructions";

/// Injected right after `CLAUDE.md`'s intro paragraphs (before the first
/// `## ` section). Explains that this file is a generated derivative — not
/// present in `CLAUDE.md`.
const COUNTERPART_NOTE: &str = "This file is the Codex / OpenCode counterpart to `CLAUDE.md`, and is **generated** from it by `generate_agents_md` — do not hand-edit it; edit `CLAUDE.md` and regenerate with `MEMHUB_REGEN=1 cargo test skill_parity`. The two exist so Codex CLI, OpenCode CLI, and Claude Code sessions get the same orientation when they open this repo; where they diverge it is intentional (a different H1, plus the Codex/OpenCode-only sections injected at the end).";

/// Codex-specific attribution guidance, appended to the generated file.
/// Has no `CLAUDE.md` counterpart by design (Claude attributes via the MCP
/// `clientInfo.name`, not these CLI flags).
const AGENT_ATTRIBUTION: &str = "\
## Agent attribution (Codex-specific)

When you write to memhub from the CLI, identify yourself so the row gets attributed correctly. Two flags matter:

- `--source` — origin of the claim. Pass `--source user+agent:codex` on `memhub fact add` / `memhub decision add` writes that go through `/wrap-up` (agent surfaced, user approved). For direct CLI writes the user typed themselves, omit the flag and take the `user` default.
- `--actor` — who performed the write. Pass `--actor codex:wrap-up` from the wrap-up skill; `--actor codex:<skill-name>` from other skills.

See [docs/reference/memhub-prd-source-vocabulary-addendum.md](docs/reference/memhub-prd-source-vocabulary-addendum.md) for the full vocabulary (`user`, `agent:<id>`, `user+agent:<id>`, `git`, `observed`).

Once `memhub serve` is registered in `~/.codex/config.toml` (a per-machine step — see README's \"Register the MCP server\"; `memhub doctor` reports current status), writes via MCP attribute automatically — the server reads `clientInfo.name` from `initialize` and tags writes as `codex` / `codex:wrap-up` without you needing to pass anything.";

/// The Q41 fail-safe routing block (decision Q41, issue #30), appended after
/// the attribution section. Claude Code receives these routing rules through
/// the MCP server's `instructions` field; Codex/OpenCode delivery is
/// unverified until the Wave 4 spike, so they carry this compact copy here.
/// Deliberately **not** in `CLAUDE.md`.
const ROUTING_BLOCK: &str = "\
## memhub routing (Codex / OpenCode)
memhub is this repo's project memory. When intent matches, use the memhub MCP tools — do
not fall through to Grep/Read/manual scan:
- past decisions / status / \"is there a fact/task about X\" → `recall`
- find code by what it does / \"where is X\" → `locate`
- session start (turn 1 only) → read `.memhub/rendered/PROJECT.md` once
- new task / mark done → `task_add` / `task_done`; ingest a spec doc → `doc_add`
Never Grep for code by intent before `locate`. Never read `PROJECT_LEDGER.md` before `recall`
(it is the fallback). Never write facts/decisions directly — stage via `propose_fact` /
`propose_decision`, durable on `memhub review accept`.
(Carrier note: Claude Code gets these rules from the MCP `instructions` field; this block is
the Codex/OpenCode fallback pending the Wave 4 delivery spike.)";

/// Opening marker of the Orch-managed block Orch's installer appends to
/// `CLAUDE.md` (and, via [`generate_agents_md`], to `AGENTS.md`). See the
/// module doc comment.
const MANAGED_BLOCK_START: &str = "<!-- orchestrator:managed:start";

/// Closing marker of the Orch-managed block; see [`MANAGED_BLOCK_START`].
const MANAGED_BLOCK_END: &str = "<!-- orchestrator:managed:end -->";

/// Split `claude_md` into `(body, managed_block)`: `body` is the content
/// before a trailing Orch-managed block (line-ending-normalized to `\n`),
/// and `managed_block` is that block's verbatim text when the input ends
/// (modulo trailing newlines) with one, `None` otherwise.
///
/// `pub(crate)` and shared between [`generate_agents_md`]'s step 0 and
/// `commands::audit_md`'s precondition check (issue #148 / audit C3) — the
/// two must agree on exactly what "the managed block" is, or a `CLAUDE.md`
/// whose only `## ` heading lives inside that block can pass the
/// precondition check against the raw text while `generate_agents_md`
/// still panics against the stripped text it actually transforms.
pub(crate) fn split_trailing_managed_block(claude_md: &str) -> (String, Option<String>) {
    let claude = claude_md.replace("\r\n", "\n");
    let trimmed = claude.trim_end_matches('\n');
    let managed_block = trimmed.rfind(MANAGED_BLOCK_START).and_then(|start| {
        let end = start + trimmed[start..].find(MANAGED_BLOCK_END)? + MANAGED_BLOCK_END.len();
        (end == trimmed.len()).then(|| (start, trimmed[start..end].to_string()))
    });
    match managed_block {
        Some((start, block)) => (
            trimmed[..start].trim_end_matches('\n').to_string(),
            Some(block),
        ),
        None => (claude, None),
    }
}

/// Transform `CLAUDE.md` content into the `AGENTS.md` content.
///
/// Pure string work, no dependencies. Line-ending-agnostic: the input is
/// normalized to `\n` and the output is emitted with `\n`, so the committed
/// `AGENTS.md` compares equal to this on every platform (this repo checks
/// out CRLF on Windows under `core.autocrlf=true`).
pub fn generate_agents_md(claude_md: &str) -> String {
    // 0. Split off a trailing Orch-managed block, if present, so it can be
    //    re-appended last after the Codex/OpenCode-only sections rather
    //    than getting pushed out of EOF position by step 3.
    let (claude, managed_block) = split_trailing_managed_block(claude_md);

    // 1. Swap the H1 title line.
    let (first_line, rest) = claude.split_once('\n').unwrap_or((claude.as_str(), ""));
    assert_eq!(
        first_line, CLAUDE_TITLE,
        "CLAUDE.md must start with the `{CLAUDE_TITLE}` H1 title"
    );
    let retitled = format!("{AGENTS_TITLE}\n{rest}");

    // 2. Inject the counterpart note just before the first `## ` section, so
    //    it sits after the intro paragraphs and before Session Continuity.
    let marker = "\n## ";
    let idx = retitled
        .find(marker)
        .expect("CLAUDE.md must contain at least one `## ` section");
    let (head, tail) = retitled.split_at(idx);
    let with_note = format!("{head}\n{COUNTERPART_NOTE}\n{tail}");

    // 3. Append the Codex/OpenCode-only sections after the last CLAUDE.md
    //    section, separated by a blank line, with a single trailing newline.
    //    A trailing Orch-managed block (split off in step 0) is carried
    //    through verbatim and re-appended last of all, so it stays at EOF.
    let body = with_note.trim_end_matches('\n');
    match managed_block {
        Some(block) => {
            format!("{body}\n\n{AGENT_ATTRIBUTION}\n\n{ROUTING_BLOCK}\n\n{block}\n")
        }
        None => format!("{body}\n\n{AGENT_ATTRIBUTION}\n\n{ROUTING_BLOCK}\n"),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const SAMPLE: &str = "# memhub\n\nIntro line.\n\nPointer line.\n\n## Session Continuity\n\nBody.\n\n## Build / Test / Run\n\n```bash\ncargo build\n```\n";

    const MANAGED_BLOCK: &str = "<!-- orchestrator:managed:start version=1 -->\nManaged line one.\nManaged line two.\n<!-- orchestrator:managed:end -->";

    const SAMPLE_WITH_MANAGED_BLOCK: &str = "# memhub\n\nIntro line.\n\nPointer line.\n\n## Session Continuity\n\nBody.\n\n## Build / Test / Run\n\n```bash\ncargo build\n```\n\n<!-- orchestrator:managed:start version=1 -->\nManaged line one.\nManaged line two.\n<!-- orchestrator:managed:end -->";

    #[test]
    fn swaps_title_and_keeps_body_sections() {
        let out = generate_agents_md(SAMPLE);
        assert!(out.starts_with("# memhub — Codex CLI instructions\n"));
        assert!(!out.contains("\n# memhub\n"));
        assert!(out.contains("## Session Continuity"));
        assert!(out.contains("## Build / Test / Run"));
        // Intro content carries through verbatim.
        assert!(out.contains("Intro line."));
        assert!(out.contains("Pointer line."));
    }

    #[test]
    fn injects_counterpart_note_before_first_section() {
        let out = generate_agents_md(SAMPLE);
        let note_at = out.find("generated").expect("counterpart note present");
        let first_section = out.find("## Session Continuity").expect("first section");
        assert!(
            note_at < first_section,
            "counterpart note must precede the first ## section"
        );
    }

    #[test]
    fn appends_codex_only_sections_at_end() {
        let out = generate_agents_md(SAMPLE);
        let attrib = out
            .find("## Agent attribution (Codex-specific)")
            .expect("attribution section appended");
        let routing = out
            .find("## memhub routing (Codex / OpenCode)")
            .expect("routing block appended");
        let last_body = out.find("## Build / Test / Run").expect("body section");
        assert!(last_body < attrib, "injected sections come after the body");
        assert!(attrib < routing, "attribution precedes routing");
        assert!(
            out.ends_with("delivery spike.)\n"),
            "single trailing newline"
        );
    }

    #[test]
    fn is_line_ending_agnostic() {
        let crlf = SAMPLE.replace('\n', "\r\n");
        assert_eq!(generate_agents_md(SAMPLE), generate_agents_md(&crlf));
    }

    #[test]
    fn keeps_trailing_managed_block_last() {
        let out = generate_agents_md(SAMPLE_WITH_MANAGED_BLOCK);
        let last_body = out.find("## Build / Test / Run").expect("body section");
        let attrib = out
            .find("## Agent attribution (Codex-specific)")
            .expect("attribution section appended");
        let routing = out
            .find("## memhub routing (Codex / OpenCode)")
            .expect("routing block appended");
        let managed = out
            .find(MANAGED_BLOCK_START)
            .expect("managed block carried through");
        assert!(last_body < attrib, "injected sections come after the body");
        assert!(attrib < routing, "attribution precedes routing");
        assert!(routing < managed, "managed block stays last, after routing");
        assert!(
            out.ends_with("<!-- orchestrator:managed:end -->\n"),
            "single trailing newline after the managed block"
        );
    }

    #[test]
    fn carries_managed_block_verbatim() {
        let out = generate_agents_md(SAMPLE_WITH_MANAGED_BLOCK);
        assert!(
            out.contains(MANAGED_BLOCK),
            "managed block content must be carried through unmodified"
        );
    }

    #[test]
    fn is_line_ending_agnostic_with_managed_block() {
        let crlf = SAMPLE_WITH_MANAGED_BLOCK.replace('\n', "\r\n");
        assert_eq!(
            generate_agents_md(SAMPLE_WITH_MANAGED_BLOCK),
            generate_agents_md(&crlf)
        );
    }
}

