/// Shared by `import` and `init --from-backup` (both funnel through
/// `commands::import::run`). `retained_doc_chunks` is only ever nonzero
/// when importing into a target that already had docs ingested (tracker
/// X2) — a fresh `init --from-backup` target is always 0, but the hint
/// still needs to fire there so a fresh machine is told docs are not
/// carried, not just silently left with none.
pub(crate) fn print_retained_docs_hint(retained_doc_chunks: usize) {
    if retained_doc_chunks > 0 {
        println!(
            "  retained doc chunks: {retained_doc_chunks} (pre-existing ingested docs on this \
             target were left untouched — import neither carries nor wipes docs; re-run \
             `memhub doc add` to refresh them)"
        );
    } else {
        println!(
            "  docs: not carried by import — ingested reference docs are excluded from the \
             export/import format; re-run `memhub doc add <path>` to re-ingest them here"
        );
    }
}

/// Loud, non-blocking warning (issue #148 / audit C3): nonzero means the
/// target's pre-existing `writes_log` audit trail was destroyed by this
/// import's wipe. `writes_log` isn't counted by the no-`--force` emptiness
/// guard (a docs-only target must still pass it, decisions 86/90), so this
/// is the only place that loss ever surfaces -- printed unconditionally,
/// forced or not, since forcing doesn't make the loss less real.
pub(crate) fn print_overwritten_writes_log_warning(overwritten: usize) {
    if overwritten > 0 {
        let plural = if overwritten == 1 { "entry" } else { "entries" };
        println!(
            "WARNING: {overwritten} pre-existing writes_log {plural} on this target were \
             overwritten by this import — its audit trail from before this import is gone."
        );
    }
}

/// Tracker X2: the export/import format is deliberately narrow (decisions
/// 86/90 and friends) — printed after every successful `import` and
/// `init --from-backup` so a fresh machine knows what it still needs to
/// set up rather than discovering the gaps one command at a time.
///
/// Every bullet must name a subcommand that actually exists in the running
/// binary (issue: onboarding surfaces must not offer hibernated toggles) —
/// the metrics bullet is gated behind the `metrics` feature so a default
/// build never tells a user to run `memhub metrics enable` when `metrics`
/// isn't even a recognized subcommand.
pub(crate) fn not_carried_checklist_lines() -> Vec<String> {
    let mut lines = vec![
        "  - Ingested reference docs: re-add via `memhub doc add <path>`".to_string(),
        "  - Machine-global memory store (~/.memhub/global.sqlite): opt in via `memhub global enable`".to_string(),
    ];
    if cfg!(feature = "metrics") {
        lines.push(
            "  - Metrics collection: enable via `memhub metrics enable` ([metrics] in .memhub/config.toml)".to_string(),
        );
    }
    lines.push(
        "  - Drive sync: enable via `memhub sync enable` ([sync] in .memhub/config.toml)"
            .to_string(),
    );
    lines.push("  - Code index: run `memhub code index` to build it here".to_string());
    lines
}

pub(crate) fn print_not_carried_checklist() {
    println!();
    println!("Not carried by export/import — set these up on this machine if needed:");
    for line in not_carried_checklist_lines() {
        println!("{line}");
    }
}

