fn check_to_json(c: &Check) -> serde_json::Value {
    let mut v = json!({
        "id": c.id,
        "group": c.group.as_str(),
        "status": c.status.as_str(),
        "message": c.message,
    });
    if let Some(detail) = &c.detail {
        v["detail"] = json!(detail);
    }
    v
