            "body-less method must still get its own member chunk; chunks: {chunks:?}"
        );
        // No placeholder was inserted (there was nothing to excise).
        assert!(
            !header.body.contains("{ ... }"),
            "body-less member must not produce a placeholder"
        );
    }

