    // nests its specs under a `var_spec_list` the walker must see through.
    #[test]
    fn go_grouped_const_and_var_specs_are_chunked() {
        let src = "\
package cfg

const Pi = 3.14

const (
	A = 1
	B = 2
)

var lonely int

var (
