//! Language → grammar registry for the AST chunker (M11, decisions
//! 107 and 115).
//!
//! Each supported language maps to a tree-sitter [`Language`] plus a
//! declarative [`GrammarSpec`]: role sets naming the node kinds the
//! walker keys off, and three typed hooks for the handful of per-language
//! quirks the role sets cannot express. The hooks' `Standard` /
//! `Direct` / `PrecedingSiblings` defaults reproduce Rust exactly, so a
//! conventional language is one all-default row.
//!
//! The multi-language rollout (decision 115) landed the spec shape and the
//! generalized walker, then added the grammars row by row: Rust, C#, Java,
//! TypeScript, JavaScript, Python, and Go. A language with no row falls
//! back to the line-window chunker (the same path a parse failure takes),
//! so an unsupported file is never silently dropped.
//!
//! The `language` keys match [`super::infer_language`]'s extension map.

use tree_sitter::Language;

/// How a method's symbol prefix is derived.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum MethodNaming {
    /// Prefix from the enclosing container: an `impl`/class `prefix_field`
    /// (Rust `impl` `type`) or a containing type's name. Yields
    /// `Prefix::method`. The Rust default.
    Standard,
    /// Go: the prefix comes from the method's own receiver parameter, not
    /// an enclosing container (T5). A `method_declaration` is reached at the
    /// top level — `type_prefix` is `None` — so the receiver type is read
    /// from the node itself; a `function_declaration` has no receiver and
    /// stays a bare-named free function.
    GoReceiver,
}

/// How a free function's base name is derived.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum FunctionNaming {
    /// Name from the node's `name` field. The Rust default.
    Direct,
    /// JS/TS: an arrow or function expression bound to a
    /// `variable_declarator` takes the declarator's name. Implemented in
    /// the TypeScript/JavaScript task (T3).
    JsDeclarator,
}

/// How the file-level module doc comment (inner doc, `//!` / `/*!`) is
/// captured as its own chunk before the first item.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ModuleDoc {
    /// Collect the contiguous leading run of inner-doc comment nodes
    /// (`line_comment` / `block_comment` whose text begins with `//!` or
    /// `/*!`) from the root and emit them as a single `module-doc` chunk.
    /// Rust only — task 85.
    LeadingInnerComments,
    /// Collect the contiguous leading run of comment nodes whose text starts
    /// with any of the given prefixes (e.g. `["///"]` for C# XML-doc,
    /// `["/**"]` for Javadoc / JSDoc). The run stops at the first comment
    /// that does not match a prefix, at a gap > 1 row, or at the first
    /// non-comment sibling. C#, Java, TypeScript, JavaScript — task 87.
    LeadingFileDoc(&'static [&'static str]),
    /// Emit the Go package-level doc: the contiguous `//` comment block
    /// that immediately precedes (gap ≤ 1 row) the first top-level
    /// declaration. The `package` clause itself is a non-comment node and
    /// stops nothing; the run is the last contiguous block before the first
    /// declaration, matching Go's godoc convention. Go only — task 87.
    GoPackageDoc,
    /// Emit the Python module docstring: the first statement of the module
    /// when it is an `expression_statement` whose sole child is a string
    /// literal. Python only — task 87.
    PythonModuleDocstring,
    /// No module-doc chunk emitted. All other languages.
    None,
}

/// How preceding documentation is folded into an item's chunk.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DocFold {
    /// Fold a contiguous run of preceding comment / attribute siblings
    /// into the item's chunk. The Rust default.
    PrecedingSiblings,
    /// Python: ignore preceding `#` comments (they are not docs), keep the
    /// leading body docstring inside a class's header chunk (it is the
    /// first body `expression_statement`, which has no `body_field` and so
    /// is never excised), and climb a `decorated_definition` wrapper so a
    /// def's decorators are included in its chunk.
    PythonDocstring,
    /// No doc folding; a chunk starts at the item node itself.
    None,
}

/// A method-bearing container: a node kind plus the field its member
/// methods take their type prefix from (Rust `impl_item` → `type`).
pub struct MethodContainer {
    /// Node kind of the container.
    pub node: &'static str,
    /// Field whose text is the type prefix for the container's methods.
    pub prefix_field: &'static str,
}

/// A tree-sitter grammar plus the node-kind vocabulary and per-language
/// hooks the walker keys off. Kinds are matched against `node.kind()`.
pub struct GrammarSpec {
    /// The tree-sitter language/grammar handle.
    pub language: Language,
    /// Node kinds of a free function definition (module- or block-level).
    /// Inside a [`MethodContainer`] body these are emitted as methods.
    pub function_kinds: &'static [&'static str],
    /// Node kinds of a type that contains members (classes, etc.): emitted
    /// as a header-only chunk and recursed into ([`body_field`]) with a
    /// name-derived prefix, nesting qualified. Empty for Rust, whose
    /// structs/enums are leaf [`item_kinds`]. Walker support lands in T2.
    ///
    /// [`body_field`]: GrammarSpec::body_field
    pub type_container_kinds: &'static [&'static str],
    /// Method-bearing containers whose member functions are emitted as
    /// `Prefix::method`, the prefix read from each entry's `prefix_field`
    /// (Rust `impl`).
    pub method_containers: &'static [MethodContainer],
    /// Namespace / inline-module kinds: recursed into via [`body_field`]
    /// with no chunk of their own (Rust `mod_item`).
    ///
    /// [`body_field`]: GrammarSpec::body_field
    pub namespace_kinds: &'static [&'static str],
    /// Structural wrapper kinds the walker recurses *through* by iterating
    /// their named children directly — no chunk, no prefix change, no
    /// `body_field`. Distinct from [`namespace_kinds`], whose children hang
    /// off a `body_field` subtree. Used for JS/TS `export_statement` (which
    /// wraps nearly every top-level declaration) and the `expression_
    /// statement` that wraps a TS `internal_module`. Empty for Rust/C#/Java,
    /// where declarations are direct statement children.
    ///
    /// [`namespace_kinds`]: GrammarSpec::namespace_kinds
    pub transparent_kinds: &'static [&'static str],
    /// Node kinds emitted as a single self-contained symbol chunk
    /// (Rust structs, enums, traits, type/const/static items, macros).
    pub item_kinds: &'static [&'static str],
    /// Member kinds chunked inside a [`type_container_kinds`] with the
    /// type prefix (methods, properties, constructors). Empty for Rust.
    /// Walker support lands in T2.
    ///
    /// [`type_container_kinds`]: GrammarSpec::type_container_kinds
    pub member_kinds: &'static [&'static str],
    /// Comment node kinds folded as documentation ahead of an item
    /// (Rust `line_comment`, `block_comment`).
    pub comment_kinds: &'static [&'static str],
    /// Attribute / annotation node kinds folded ahead of an item
    /// (Rust `attribute_item`).
    pub attribute_kinds: &'static [&'static str],
    /// Field name holding a container's or namespace's body subtree.
    pub body_field: &'static str,
    /// Method-prefix derivation hook.
    pub method_naming: MethodNaming,
    /// Free-function naming hook.
    pub function_naming: FunctionNaming,
    /// Documentation-folding hook.
    pub doc_fold: DocFold,
    /// File-level module-doc hook: whether to emit a leading `//!`/`/*!`
    /// comment run as a `module-doc` chunk before the first item. Rust only.
    pub module_doc: ModuleDoc,
}

impl GrammarSpec {
    /// Returns `true` when every hook on this spec uses a fully implemented
    /// variant. A spec with an unimplemented hook (e.g.
    /// [`MethodNaming::GoReceiver`], [`DocFold::PythonDocstring`]) must
    /// return `false` here so `chunk_file` falls back to line windows
    /// instead of reaching a `todo!()` in the walker. Remove a variant from
    /// the guards below once its task lands.
    pub fn hooks_implemented(&self) -> bool {
        matches!(
            self.function_naming,
            FunctionNaming::Direct | FunctionNaming::JsDeclarator
        ) && matches!(
            self.method_naming,
            MethodNaming::Standard | MethodNaming::GoReceiver
        ) && matches!(
            self.doc_fold,
            DocFold::PrecedingSiblings | DocFold::None | DocFold::PythonDocstring
        )
    }
}

/// The grammar for `language` (as keyed by [`super::infer_language`]), or
/// `None` when no grammar is registered — the caller then line-windows.
pub fn grammar_for(language: Option<&str>) -> Option<GrammarSpec> {
    match language? {
        "rust" => Some(GrammarSpec {
            language: tree_sitter_rust::LANGUAGE.into(),
            function_kinds: &["function_item"],
            type_container_kinds: &[],
            method_containers: &[MethodContainer {
                node: "impl_item",
                prefix_field: "type",
            }],
            namespace_kinds: &["mod_item"],
            transparent_kinds: &[],
            item_kinds: &[
                "struct_item",
                "enum_item",
                "union_item",
                "trait_item",
                "type_item",
                "const_item",
                "static_item",
                "macro_definition",
            ],
            member_kinds: &[],
            comment_kinds: &["line_comment", "block_comment"],
            attribute_kinds: &["attribute_item"],
            body_field: "body",
            method_naming: MethodNaming::Standard,
            function_naming: FunctionNaming::Direct,
            doc_fold: DocFold::PrecedingSiblings,
            module_doc: ModuleDoc::LeadingInnerComments,
        }),
        // C# and Java are conventional type-container languages: no free
        // functions, methods/constructors/properties are members of a
        // class/record/interface, and all three hooks take their defaults.
        // Node kinds verified against tree-sitter-c-sharp / -java 0.23.
        "csharp" => Some(GrammarSpec {
            language: tree_sitter_c_sharp::LANGUAGE.into(),
            function_kinds: &[],
            type_container_kinds: &[
                "class_declaration",
                "struct_declaration",
                "interface_declaration",
                "record_declaration",
            ],
            method_containers: &[],
            // Block `namespace X { … }` recurses; `file_scoped_namespace_
            // declaration` has no body, so its types are top-level siblings
            // and are walked directly (it matches no role set and is skipped).
            namespace_kinds: &["namespace_declaration"],
            transparent_kinds: &[],
            item_kinds: &["enum_declaration", "delegate_declaration"],
            member_kinds: &[
                "method_declaration",
                "constructor_declaration",
                "property_declaration",
            ],
            // C# has one comment node kind for `//`, `///`, and `/* */`.
            comment_kinds: &["comment"],
            attribute_kinds: &["attribute_list"],
            body_field: "body",
            method_naming: MethodNaming::Standard,
            function_naming: FunctionNaming::Direct,
            doc_fold: DocFold::PrecedingSiblings,
            module_doc: ModuleDoc::LeadingFileDoc(&["///"]),
        }),
        "java" => Some(GrammarSpec {
            language: tree_sitter_java::LANGUAGE.into(),
            function_kinds: &[],
            type_container_kinds: &[
                "class_declaration",
                "interface_declaration",
                "record_declaration",
            ],
            method_containers: &[],
            // `package_declaration` has no body; types are top-level
            // siblings, so no namespace recursion is needed.
            namespace_kinds: &[],
            transparent_kinds: &[],
            item_kinds: &["enum_declaration", "annotation_type_declaration"],
            member_kinds: &["method_declaration", "constructor_declaration"],
            // Javadoc is a `block_comment` sibling, folded as a doc.
            // Annotations live inside the declaration's `modifiers` node,
            // so they are already within the item's byte range — no
            // attribute set needed.
            comment_kinds: &["line_comment", "block_comment"],
            attribute_kinds: &[],
            body_field: "body",
            method_naming: MethodNaming::Standard,
            function_naming: FunctionNaming::Direct,
            doc_fold: DocFold::PrecedingSiblings,
            module_doc: ModuleDoc::LeadingFileDoc(&["/**"]),
        }),
        // TypeScript (covers .tsx via the same grammar). Mixes free functions
        // (`function_declaration`) with arrow/function bindings named via their
        // declarator (the JsDeclarator hook), and type containers (class,
        // abstract class, interface). Nearly every top-level declaration is
        // wrapped in `export_statement`; a `namespace`/`module` parses as an
        // `expression_statement` wrapping an `internal_module` — both are walked
        // through via `transparent_kinds`. Node kinds verified against
        // tree-sitter-typescript 0.23 via an AST-dump probe.
        "typescript" => Some(GrammarSpec {
            language: tree_sitter_typescript::LANGUAGE_TYPESCRIPT.into(),
            function_kinds: &["function_declaration", "generator_function_declaration"],
            type_container_kinds: &[
                "class_declaration",
                "abstract_class_declaration",
                "interface_declaration",
            ],
            method_containers: &[],
            namespace_kinds: &["internal_module"],
            transparent_kinds: &["export_statement", "expression_statement"],
            item_kinds: &["type_alias_declaration", "enum_declaration"],
            // method_definition covers methods, constructors, and get/set;
            // method_signature covers body-less interface methods. Plain fields
            // and property signatures stay in the type header only. Arrow-valued
            // fields are routed as members by the JsDeclarator hook in the walker.
            member_kinds: &["method_definition", "method_signature"],
            // One `comment` kind for //, /* */, and /** */ JSDoc.
            comment_kinds: &["comment"],
            // Class/method decorators are an internal `decorator` field of the
            // declaration (within its byte range), but a decorator can also be a
            // preceding sibling; folding it as a leading attribute is harmless in
            // the internal case and correct in the sibling case.
            attribute_kinds: &["decorator"],
            body_field: "body",
            method_naming: MethodNaming::Standard,
            function_naming: FunctionNaming::JsDeclarator,
            doc_fold: DocFold::PrecedingSiblings,
            module_doc: ModuleDoc::LeadingFileDoc(&["/**"]),
        }),
        // JavaScript (covers .jsx). The TypeScript row minus the type-only
        // constructs (no interface/type-alias/enum/namespace). Class fields use
        // `field_definition` (vs TS `public_field_definition`); both are routed
        // by the JsDeclarator hook. Node kinds verified against
        // tree-sitter-javascript 0.25 via an AST-dump probe.
        "javascript" => Some(GrammarSpec {
            language: tree_sitter_javascript::LANGUAGE.into(),
            function_kinds: &["function_declaration", "generator_function_declaration"],
            type_container_kinds: &["class_declaration"],
            method_containers: &[],
            namespace_kinds: &[],
            transparent_kinds: &["export_statement"],
            item_kinds: &[],
            member_kinds: &["method_definition"],
            comment_kinds: &["comment"],
            attribute_kinds: &["decorator"],
            body_field: "body",
            method_naming: MethodNaming::Standard,
            function_naming: FunctionNaming::JsDeclarator,
            doc_fold: DocFold::PrecedingSiblings,
            module_doc: ModuleDoc::LeadingFileDoc(&["/**"]),
        }),
        // Python. `function_definition` (covers `async def` too) is a free
        // function at module level and a method inside a class; `class_
        // definition` is the one type container. A decorated def/class parses
        // as `decorated_definition` wrapping the real node, so it is a
        // `transparent_kind`: the walker recurses through it to reach the def,
        // and `leading_start` (PythonDocstring) climbs back through it so the
        // decorators are folded into the chunk. The PythonDocstring hook also
        // suppresses `#`-comment folding, so `comment_kinds`/`attribute_kinds`
        // are never consulted for Python (left empty for attributes —
        // decorators arrive via the transparent climb, not as preceding
        // siblings). A class's leading docstring is the first body
        // `expression_statement`; it has no `body` field, so `slice_header`
        // leaves it verbatim in the header chunk. Node kinds verified against
        // tree-sitter-python 0.23 via an AST-dump probe.
        "python" => Some(GrammarSpec {
            language: tree_sitter_python::LANGUAGE.into(),
            function_kinds: &["function_definition"],
            type_container_kinds: &["class_definition"],
            method_containers: &[],
            namespace_kinds: &[],
            transparent_kinds: &["decorated_definition"],
            item_kinds: &[],
            member_kinds: &[],
            comment_kinds: &["comment"],
            attribute_kinds: &[],
            body_field: "body",
            method_naming: MethodNaming::Standard,
            function_naming: FunctionNaming::Direct,
            doc_fold: DocFold::PythonDocstring,
            module_doc: ModuleDoc::PythonModuleDocstring,
        }),
        // Go. Free functions are `function_declaration`; methods are
        // top-level `method_declaration` nodes whose type prefix comes from
        // the `receiver` parameter, not an enclosing container (the
        // GoReceiver hook). Go has no method-bearing type container: a
        // `type_spec` (struct/interface/alias) is a leaf chunk, and the
        // methods that operate on it live separately as siblings. `type_/
        // const_/var_declaration` are transparent wrappers around one or more
        // `*_spec` leaves; grouped `var ( … )` nests its specs under an extra
        // `var_spec_list`, so that wrapper is transparent too. Godoc `//`
        // lines fold as preceding-sibling docs. Node kinds verified against
        // tree-sitter-go 0.23 via an AST-dump probe.
        "go" => Some(GrammarSpec {
            language: tree_sitter_go::LANGUAGE.into(),
            function_kinds: &["function_declaration", "method_declaration"],
            type_container_kinds: &[],
            method_containers: &[],
            namespace_kinds: &[],
            transparent_kinds: &[
                "type_declaration",
                "const_declaration",
                "var_declaration",
                "var_spec_list",
            ],
            item_kinds: &["type_spec", "const_spec", "var_spec"],
            member_kinds: &[],
            comment_kinds: &["comment"],
            attribute_kinds: &[],
            body_field: "body",
            method_naming: MethodNaming::GoReceiver,
            function_naming: FunctionNaming::Direct,
            doc_fold: DocFold::PrecedingSiblings,
            module_doc: ModuleDoc::GoPackageDoc,
        }),
        _ => None,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Parse a trivial snippet through `language`'s grammar and assert the
    /// root node kind — the canary for a tree-sitter / grammar ABI skew.
    fn assert_loads(language: &str, source: &str, expected_root: &str) {
        let spec = grammar_for(Some(language)).expect("grammar present");
        let mut parser = tree_sitter::Parser::new();
        parser
            .set_language(&spec.language)
            .expect("set language (ABI compatible)");
        let tree = parser.parse(source, None).expect("parse");
        assert_eq!(tree.root_node().kind(), expected_root);
    }

    #[test]
    fn csharp_grammar_is_registered_and_loadable() {
        assert_loads("csharp", "class C { void M() {} }", "compilation_unit");
    }

    #[test]
    fn java_grammar_is_registered_and_loadable() {
        assert_loads("java", "class C { void m() {} }", "program");
    }

    #[test]
    fn typescript_grammar_is_registered_and_loadable() {
        assert_loads("typescript", "const f = (): void => {};", "program");
    }

    #[test]
    fn javascript_grammar_is_registered_and_loadable() {
        assert_loads("javascript", "const f = () => {};", "program");
    }

    #[test]
    fn python_grammar_is_registered_and_loadable() {
        assert_loads("python", "def f():\n    pass\n", "module");
    }

    #[test]
    fn go_grammar_is_registered_and_loadable() {
        assert_loads("go", "package main\nfunc main() {}\n", "source_file");
    }

    #[test]
    fn rust_grammar_is_registered_and_loadable() {
        let spec = grammar_for(Some("rust")).expect("rust grammar present");
        // A parser must accept the language without an ABI-version panic;
        // this is the canary for a tree-sitter / grammar version skew.
        let mut parser = tree_sitter::Parser::new();
        parser
            .set_language(&spec.language)
            .expect("set rust language (ABI compatible)");
        let tree = parser.parse("fn main() {}", None).expect("parse");
        assert_eq!(tree.root_node().kind(), "source_file");
    }

    #[test]
    fn rust_row_uses_all_default_hooks() {
        let spec = grammar_for(Some("rust")).expect("rust grammar present");
        assert_eq!(spec.method_naming, MethodNaming::Standard);
        assert_eq!(spec.function_naming, FunctionNaming::Direct);
        assert_eq!(spec.doc_fold, DocFold::PrecedingSiblings);
    }

    #[test]
    fn unknown_and_absent_languages_have_no_grammar() {
        assert!(grammar_for(Some("cobol")).is_none());
        assert!(grammar_for(Some("markdown")).is_none());
        assert!(grammar_for(None).is_none());
    }

    // M11 review L1: every currently registered grammar must report all
    // hooks implemented so no live row can reach a `todo!()` in the walker.
    #[test]
    fn all_registered_grammars_have_fully_implemented_hooks() {
        for lang in [
            "rust",
            "csharp",
            "java",
            "typescript",
            "javascript",
            "python",
            "go",
        ] {
            let spec = grammar_for(Some(lang)).expect(lang);
            assert!(
                spec.hooks_implemented(),
                "{lang} grammar has an unimplemented hook — chunk_file would degrade to line windows"
            );
        }
    }
}

//! Code locator query path (M11 PR3, decision 107).
//!
//! [`locate`] is the read side of the sibling code index. It mirrors the
//! project recall fusion ([`crate::retrieval::recall`]) but over the
//! `code_chunks` / `code_embeddings` / `code_chunks_fts` tables in
//! `.memhub/code_index.sqlite`: FTS5 BM25 blended with brute-force cosine
//! similarity (hybrid mode only), min-max normalized and weighted by its
//! own `[code_index]` knobs — split from recall's `[retrieval.scoring]`
//! (R11, issue #73) so tuning one no longer silently retunes the other.
//! There is no stale penalty — a code chunk is either present or not,
//! never "decayed".
//!
//! **Lazy freshness (decision 107).** A locate first runs [`super::refresh`]
//! so the index always reflects the working tree; the PR1 staleness engine
//! makes that stat-only (no read, no embed) when nothing changed, so a warm
//! index pays almost nothing. `memhub code index` is the explicit warm-up /
//! rebuild for callers that want to pay that cost up front. `--no-refresh`
//! (issue #67) opts out of that pass entirely — no `git ls-files`, no stat,
//! no `git rev-parse HEAD` — for callers making tight repeat calls against
//! a warm index who accept stale-by-choice results in exchange for the
//! lowest possible latency.
//!
//! **Reranker off by default (PR3).** The bundled ms-marco cross-encoder is
//! NL-trained; its fit on code is unproven until PR5 measures it. So
//! `--rerank` gates it and there is no min-score floor here — when on, it
//! only reorders the candidate pool. The default fusion path never loads
//! the cross-encoder.

use std::collections::HashMap;
use std::path::Path;
use std::time::Instant;

use rusqlite::{Connection, params};

use crate::Result;
use crate::config::{CodeIndexConfig, ProjectConfig, RetrievalMode};
use crate::db;
use crate::retrieval::embeddings::{EMBEDDING_DIMENSION, EMBEDDING_MODEL_NAME, embed_one};
use crate::retrieval::util::{build_fts_match, bytes_to_vector, cosine_similarity, normalize_fts};

use super::{code_index_db_path, open_code_index, refresh};

/// FTS candidates pulled before blending. Generous so the vector side can
/// re-rank a broad keyword pool; the final list is truncated to `limit`.
const FTS_CANDIDATE_LIMIT: i64 = 100;

/// Default result count when the caller passes 0.
pub const DEFAULT_LOCATE_LIMIT: usize = 10;

/// Snippet caps: a locator returns a breadcrumb, never full code. The body
/// is clipped to the first [`SNIPPET_MAX_LINES`] lines of the chunk and at
/// most [`SNIPPET_MAX_CHARS`] characters, with a trailing `…` when clipped.
const SNIPPET_MAX_LINES: usize = 6;
const SNIPPET_MAX_CHARS: usize = 400;

/// Caller-supplied locate request.
#[derive(Debug, Clone)]
pub struct LocateOptions {
    pub query: String,
    /// 0 means "use [`DEFAULT_LOCATE_LIMIT`]".
    pub limit: usize,
    /// Run the bundled cross-encoder over the candidate pool. Off by
    /// default in PR3; ignored in fts mode (no vectors to draw a pool from
    /// — FTS order stands).
    pub use_reranker: bool,
    /// Skip the pre-query [`super::refresh`] (issue #67): no `git
    /// ls-files`, no per-file stat, no `git rev-parse HEAD`. Queries the
    /// index exactly as it last stood. Stale-by-choice — an explicit
    /// opt-in for tight repeat-locate loops on a warm index; the default
    /// (`false`) keeps the lazy-freshness guarantee described on
    /// [`locate`].
    pub no_refresh: bool,
}

/// One ranked locator hit.
#[derive(Debug, Clone)]
pub struct LocateHit {
    pub rank: usize,
    /// Repo-relative, forward-slashed path.
    pub path: String,
    /// 1-indexed inclusive line range of the chunk.
    pub start_line: usize,
    pub end_line: usize,
    /// Symbol name when the chunk is symbol-aware (`None` for line windows).
    pub symbol: Option<String>,
    /// Chunk kind tag (`function`, `struct`, `line-window`, …).
    pub kind: String,
    /// Blended fusion score (or the rerank logit's rank position when
    /// reranking reordered the pool — `score` stays the fusion score so the
    /// fusion signal is still visible; `rerank_score` carries the logit).
    pub score: f64,
    pub fts_score: f64,
    pub vector_score: f64,
    /// Cross-encoder relevance logit when `--rerank` ran, else `None`.
    pub rerank_score: Option<f32>,
    /// A short, clipped excerpt of the chunk body read from disk.
    pub snippet: String,
}

/// Locate response bundle.
#[derive(Debug, Clone)]
pub struct LocateResponse {
    pub query: String,
    pub mode: RetrievalMode,
    pub results: Vec<LocateHit>,
    /// Distinct chunks that matched before truncation to `limit`.
    pub candidate_count: usize,
    pub returned_count: usize,
    /// Whether the cross-encoder actually ran this call.
    pub reranked: bool,
    /// Files / chunks in the index after the pre-query refresh.
    pub files_total: usize,
    pub chunks_total: usize,
    /// Indexed `HEAD` after the refresh, if resolvable.
    pub head: Option<String>,
    /// Count of `code_embeddings` rows in scope for this query whose
    /// stored vector blob is the wrong byte length for
    /// `EMBEDDING_DIMENSION` -- a corrupt or truncated write. These chunks
    /// are silently degraded to FTS-only for this call (there's nothing
    /// to compute cosine similarity against); this count is the caller's
    /// only signal that degradation happened, since the code index has
    /// no `stale_embeddings`-style warning list of its own. Always 0 in
    /// `fts` mode (the vector path never runs).
    pub corrupt_embeddings: usize,
    pub elapsed_ms: u128,
}

/// Run a code locate: refresh the index to the working tree, then blend
/// FTS + vector candidates and return the ranked breadcrumbs.
pub fn locate(start: &Path, options: LocateOptions) -> Result<LocateResponse> {
    let started = Instant::now();

    // Lazy freshness: bring the index in line with the tree first. Cheap
    // (stat-only, no embed) when nothing changed. `--no-refresh` skips this
    // entirely — no `git ls-files`, no per-file stat, no `git rev-parse
    // HEAD` — trading freshness for the lowest possible warm latency
    // (issue #67). `files_total`/`chunks_total`/`head` are then read
    // straight off the index below instead of off this summary.
    let summary = if options.no_refresh {
        None
    } else {
        Some(refresh(start)?)
    };

    // Resolve repo root + config the same decoupled way refresh does — no
    // open_project, so the code index stays independent of project.sqlite.
    let paths = db::discover_paths(start)?;
    let repo_root = paths.repo_root.clone();
    let config = if paths.config_path.exists() {
        ProjectConfig::load(&paths.config_path)?
    } else {
        let repo_name = repo_root
            .file_name()
            .and_then(|name| name.to_str())
            .unwrap_or("memhub");
        ProjectConfig::default_for_repo_name(repo_name)
    };
    let mode = config.retrieval.mode;
    let scoring = &config.code_index;

    let limit = if options.limit == 0 {
        DEFAULT_LOCATE_LIMIT
    } else {
        options.limit
    };

    let db_path = code_index_db_path(&repo_root);
    let conn = open_code_index(&db_path)?;

    // With a refresh, its summary already carries the post-refresh counts
    // + resolved HEAD. Without one, read the same three values straight
    // off the index (mirrors `status()`) rather than trusting a summary
    // that never ran — `head` here is the last-*indexed* HEAD, not a fresh
    // `git rev-parse`, since `--no-refresh` promises no git calls.
    let (files_total, chunks_total, head) = match &summary {
        Some(s) => (s.files_total, s.chunks_total, s.head.clone()),
        None => index_snapshot(&conn)?,
    };

    let (mut candidates, corrupt_embeddings) = gather_candidates(&conn, &options.query, mode)?;
    let candidate_count = candidates.len();

    // Blend + sort by descending fusion score.
    score_candidates(&mut candidates, scoring);
    candidates.sort_by(|a, b| {
        b.score
            .partial_cmp(&a.score)
            .unwrap_or(std::cmp::Ordering::Equal)
            .then_with(|| a.chunk_id.cmp(&b.chunk_id))
    });

    // Optional rerank over the top pool. Only meaningful in hybrid mode —
    // in fts mode there is no embed pool worth reordering, so FTS rank
    // stands (mirrors recall's reranker-is-hybrid-only rule).
    let mut reranked = false;
    if options.use_reranker && mode == RetrievalMode::Hybrid && !candidates.is_empty() {
        let pool = config.retrieval.rerank_candidate_pool.max(limit);
        let pool_len = pool.min(candidates.len());
        let pool_texts = fetch_embed_texts(&conn, &candidates[..pool_len])?;
        let doc_refs: Vec<String> = pool_texts.iter().map(|(_, t)| t.clone()).collect();
        let ranked = crate::retrieval::rerank::rerank(&options.query, &doc_refs)?;
        // ranked is (pool_index, logit) sorted descending. Rebuild the pool
        // in that order, stamping the logit; the tail past the pool keeps
        // its fusion order behind the reranked head.
        let mut new_head: Vec<Candidate> = Vec::with_capacity(pool_len);
        for (pool_idx, logit) in &ranked {
            let mut c = candidates[*pool_idx].clone();
            c.rerank_score = Some(*logit);
            new_head.push(c);
        }
        let tail = candidates.split_off(pool_len);
        candidates = new_head;
        candidates.extend(tail);
        reranked = true;
    }

    candidates.truncate(limit);

    let mut line_cache: HashMap<String, Option<Vec<String>>> = HashMap::new();
    let mut results = Vec::with_capacity(candidates.len());
    for (idx, c) in candidates.iter().enumerate() {
        let meta = fetch_chunk_meta(&conn, c.chunk_id)?;
        let Some(meta) = meta else { continue };
        let snippet = read_snippet(
            &repo_root,
            &meta.path,
            meta.start_line,
            meta.end_line,
            &mut line_cache,
        );
        results.push(LocateHit {
            rank: idx + 1,
            path: meta.path,
            start_line: meta.start_line,
            end_line: meta.end_line,
            symbol: meta.symbol,
            kind: meta.kind,
            score: c.score,
            fts_score: c.fts_score,
            vector_score: c.vector_score,
            rerank_score: c.rerank_score,
            snippet,
        });
    }

    let returned_count = results.len();
    Ok(LocateResponse {
        query: options.query,
        mode,
        results,
        candidate_count,
        returned_count,
        reranked,
        files_total,
        chunks_total,
        head,
        corrupt_embeddings,
        elapsed_ms: started.elapsed().as_millis(),
    })
}

/// Read `files_total` / `chunks_total` / last-indexed `head` straight off
/// the index DB without touching the working tree or spawning `git`. The
/// `--no-refresh` counterpart to the counts a [`super::RefreshSummary`]
/// carries; mirrors [`super::status`]'s snapshot query.
fn index_snapshot(conn: &Connection) -> Result<(usize, usize, Option<String>)> {
    let files_total = conn.query_row("SELECT COUNT(*) FROM indexed_files", [], |r| {
        r.get::<_, i64>(0)
    })? as usize;
    let chunks_total = conn.query_row("SELECT COUNT(*) FROM code_chunks", [], |r| {
        r.get::<_, i64>(0)
    })? as usize;
    let head: Option<String> = conn
        .query_row(
            "SELECT value FROM index_meta WHERE key = 'last_head'",
            [],
            |r| r.get(0),
        )
        .ok();
    Ok((files_total, chunks_total, head))
}

#[derive(Debug, Clone)]
struct Candidate {
    chunk_id: i64,
    /// Raw BM25 (lower is better); `None` if the chunk only matched on the
    /// vector side.
    fts_raw: Option<f64>,
    /// Cosine similarity in [-1, 1]; `None` if FTS-only.
    cosine: Option<f64>,
    fts_score: f64,
    vector_score: f64,
    score: f64,
    rerank_score: Option<f32>,
    /// Repo-relative forward-slashed path of the source file this chunk
    /// belongs to. Used by `score_candidates` to apply the test-path penalty.
    path: String,
}

/// Returns `true` when `path` is inside a top-level test / bench / example
/// directory (`tests/`, `benches/`, or `examples/`). Paths in the index
/// are already forward-slashed repo-relative strings.
fn is_test_path(path: &str) -> bool {
    path.starts_with("tests/") || path.starts_with("benches/") || path.starts_with("examples/")
}

/// Gather the union of FTS and (hybrid only) vector matches keyed by chunk.
/// Returns the candidates plus a count of length-mismatched embedding
/// blobs found while scanning `code_embeddings` (see [`LocateResponse::
/// corrupt_embeddings`]).
fn gather_candidates(
    conn: &Connection,
    query: &str,
    mode: RetrievalMode,
) -> Result<(Vec<Candidate>, usize)> {
    let mut map: HashMap<i64, Candidate> = HashMap::new();
    let mut corrupt_embeddings = 0usize;

    if let Some(match_expr) = build_fts_match(query) {
        let mut stmt = conn.prepare(
            "SELECT c.id, bm25(code_chunks_fts) AS score, f.path \
             FROM code_chunks_fts \
             JOIN code_chunks c ON c.id = code_chunks_fts.rowid \
             JOIN indexed_files f ON f.id = c.file_id \
             WHERE code_chunks_fts MATCH ?1 \
             ORDER BY score ASC \
             LIMIT ?2",
        )?;
        let rows = stmt.query_map(params![match_expr, FTS_CANDIDATE_LIMIT], |row| {
            Ok((
                row.get::<_, i64>(0)?,
                row.get::<_, f64>(1)?,
                row.get::<_, String>(2)?,
            ))
        })?;
        for row in rows {
            let (chunk_id, bm25, path) = row?;
            map.entry(chunk_id)
                .or_insert_with(|| new_candidate(chunk_id, path))
                .fts_raw = Some(bm25);
        }
    }

    if mode == RetrievalMode::Hybrid {
        let query_vec = embed_one(query)?;
        if query_vec.len() == EMBEDDING_DIMENSION {
            let mut stmt = conn.prepare(
                "SELECT e.chunk_id, e.vector, f.path \
                 FROM code_embeddings e \
                 JOIN code_chunks c ON c.id = e.chunk_id \
                 JOIN indexed_files f ON f.id = c.file_id \
                 WHERE e.model_name = ?1 AND e.dimension = ?2",
            )?;
            let rows = stmt.query_map(
                params![EMBEDDING_MODEL_NAME, EMBEDDING_DIMENSION as i64],
                |row| {
                    Ok((
                        row.get::<_, i64>(0)?,
                        row.get::<_, Vec<u8>>(1)?,
                        row.get::<_, String>(2)?,
                    ))
                },
            )?;
            for row in rows {
                let (chunk_id, blob, path) = row?;
                if blob.len() != EMBEDDING_DIMENSION * 4 {
                    // Corrupt or truncated write: nothing to compute
                    // cosine similarity against. Skipped for scoring but
                    // counted so the caller isn't told the pool is clean
                    // when it silently degraded to FTS-only for this
                    // chunk.
                    corrupt_embeddings += 1;
                    continue;
                }
                let cosine = cosine_similarity(&query_vec, &bytes_to_vector(&blob));
                map.entry(chunk_id)
                    .or_insert_with(|| new_candidate(chunk_id, path))
                    .cosine = Some(cosine);
            }
        }
    }

    Ok((map.into_values().collect(), corrupt_embeddings))
}

fn new_candidate(chunk_id: i64, path: String) -> Candidate {
    Candidate {
        chunk_id,
        fts_raw: None,
        cosine: None,
        fts_score: 0.0,
        vector_score: 0.0,
        score: 0.0,
        rerank_score: None,
        path,
    }
}

/// Min-max normalize FTS across the candidate set and blend with the
/// clamped cosine, weighted by `[code_index]` config. No stale penalty
/// (code chunks don't decay). Mirrors [`crate::retrieval::recall`]'s
/// `score`, but reads its own `CodeIndexConfig` rather than recall's
/// `RetrievalScoringConfig` (R11, issue #73) — see the module doc.
fn score_candidates(candidates: &mut [Candidate], scoring: &CodeIndexConfig) {
    let (fts_min, fts_max) =
        candidates
            .iter()
            .fold((f64::INFINITY, f64::NEG_INFINITY), |acc, c| {
                match c.fts_raw {
                    Some(raw) => {
                        let pos = -raw; // BM25 lower-is-better → invert.
                        (acc.0.min(pos), acc.1.max(pos))
                    }
                    None => acc,
                }
            });

    for c in candidates.iter_mut() {
        c.fts_score = match c.fts_raw {
            Some(raw) => normalize_fts(-raw, fts_min, fts_max),
            None => 0.0,
        };
        c.vector_score = c.cosine.unwrap_or(0.0).clamp(0.0, 1.0);
        c.score = scoring.fts_weight * c.fts_score + scoring.vector_weight * c.vector_score;
        if is_test_path(&c.path) {
            c.score *= scoring.test_path_penalty;
        }
    }
}

/// Pull `(chunk_id, embed_text)` for a slice of candidates, preserving
/// their order so the reranker's returned indices line up.
fn fetch_embed_texts(conn: &Connection, pool: &[Candidate]) -> Result<Vec<(i64, String)>> {
    let mut stmt = conn.prepare("SELECT embed_text FROM code_chunks WHERE id = ?1")?;
    let mut out = Vec::with_capacity(pool.len());
    for c in pool {
        let text: String = stmt.query_row(params![c.chunk_id], |row| row.get(0))?;
        out.push((c.chunk_id, text));
    }
    Ok(out)
}

struct ChunkMeta {
    path: String,
    start_line: usize,
    end_line: usize,
    symbol: Option<String>,
    kind: String,
}

fn fetch_chunk_meta(conn: &Connection, chunk_id: i64) -> Result<Option<ChunkMeta>> {
    let mut stmt = conn.prepare(
        "SELECT f.path, c.start_line, c.end_line, c.symbol, c.kind \
         FROM code_chunks c JOIN indexed_files f ON f.id = c.file_id \
         WHERE c.id = ?1",
    )?;
    let row = stmt.query_map(params![chunk_id], |row| {
        Ok(ChunkMeta {
            path: row.get(0)?,
            start_line: row.get::<_, i64>(1)? as usize,
            end_line: row.get::<_, i64>(2)? as usize,
            symbol: row.get(3)?,
            kind: row.get(4)?,
        })
    })?;
    Ok(row.into_iter().next().transpose()?)
}

/// Read a clipped excerpt for `path` at the chunk's 1-indexed line range.
/// File contents are cached across hits in the same locate; a `None` cache
/// entry records an unreadable/absent file so it is not re-read.
fn read_snippet(
    repo_root: &Path,
    path: &str,
    start_line: usize,
    end_line: usize,
    cache: &mut HashMap<String, Option<Vec<String>>>,
) -> String {
    let lines = cache.entry(path.to_string()).or_insert_with(|| {
        std::fs::read_to_string(repo_root.join(path))
            .ok()
            .map(|s| s.lines().map(|l| l.to_string()).collect())
    });
    let Some(lines) = lines else {
        return String::new();
    };
    if start_line == 0 || start_line > lines.len() {
        return String::new();
    }
    // start_line/end_line are 1-indexed inclusive; clamp end to the file.
    let from = start_line - 1;
    let to = end_line.min(lines.len());
    let mut out = String::new();
    let mut truncated = false;
    for (i, line) in lines[from..to].iter().enumerate() {
        if i >= SNIPPET_MAX_LINES {
            truncated = true;
            break;
        }
        if !out.is_empty() {
            out.push('\n');
        }
        out.push_str(line);
        if out.len() >= SNIPPET_MAX_CHARS {
            truncated = true;
            break;
        }
    }
    if out.len() > SNIPPET_MAX_CHARS {
        // Clip on a char boundary, not a byte index.
        let mut end = SNIPPET_MAX_CHARS;
        while end > 0 && !out.is_char_boundary(end) {
            end -= 1;
        }
        out.truncate(end);
        truncated = true;
    }
    if truncated {
        out.push('…');
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Regression for the bug this fix addresses: a `code_embeddings` row
    /// whose vector blob is the wrong byte length (corrupt/truncated) was
    /// silently skipped with no signal at all -- unlike recall's
    /// `stale_embeddings` warning, locate had no staleness surface
    /// whatsoever. `gather_candidates` must now count it.
    #[test]
    fn gather_candidates_counts_corrupt_length_embeddings() {
        let conn = Connection::open_in_memory().expect("open");
        crate::code_index::schema::bootstrap(&conn).expect("bootstrap");

        conn.execute(
            "INSERT INTO indexed_files(path, mtime, size, content_hash, language) \
             VALUES ('src/lib.rs', 0, 0, 'h', 'rust')",
            [],
        )
        .expect("insert file");
        conn.execute(
            "INSERT INTO code_chunks(\
                file_id, start_line, end_line, symbol, kind, content_hash, embed_text\
             ) VALUES (1, 1, 5, 'foo', 'function', 'h', 'fn foo() {}')",
            [],
        )
        .expect("insert chunk");
        // Corrupt-length vector: 4 bytes instead of EMBEDDING_DIMENSION * 4.
        conn.execute(
            "INSERT INTO code_embeddings(chunk_id, model_name, dimension, vector, content_hash) \
             VALUES (1, ?1, ?2, ?3, 'h')",
            params![
                EMBEDDING_MODEL_NAME,
                EMBEDDING_DIMENSION as i64,
                vec![0u8; 4]
            ],
        )
        .expect("insert embedding");

        let (candidates, corrupt) =
            gather_candidates(&conn, "foo", RetrievalMode::Hybrid).expect("gather");

        assert_eq!(corrupt, 1, "corrupt-length blob must be counted");
        assert!(
            candidates.iter().all(|c| c.cosine.is_none()),
            "corrupt blob must not contribute a vector score"
        );
    }

    #[test]
    fn is_test_path_classifies_top_level_dirs() {
        assert!(is_test_path("tests/foo.rs"));
        assert!(is_test_path("benches/bench.rs"));
        assert!(is_test_path("examples/ex.rs"));
        assert!(!is_test_path("src/foo.rs"));
        assert!(!is_test_path("src/tests/foo.rs"));
        assert!(!is_test_path(""));
    }

    #[test]
    fn build_fts_match_quotes_and_ands_tokens() {
        assert_eq!(
            build_fts_match("parse manifest"),
            Some("\"parse\" AND \"manifest\"".to_string())
        );
        assert_eq!(build_fts_match("   "), None);
        assert_eq!(build_fts_match(",.;"), None);
    }

    #[test]
    fn normalize_fts_single_hit_is_full_strength() {
        assert_eq!(normalize_fts(-5.0, -5.0, -5.0), 1.0);
    }

    #[test]
    fn normalize_fts_scales_within_range() {
        assert_eq!(normalize_fts(0.0, -10.0, 10.0), 0.5);
    }

    #[test]
    fn cosine_identical_vectors_is_one() {
        let v = vec![1.0, 2.0, 3.0];
        assert!((cosine_similarity(&v, &v) - 1.0).abs() < 1e-9);
    }

    // -- R11 (issue #73): [code_index] split off [retrieval.scoring] ---

    #[test]
    fn code_index_config_defaults_match_pre_split_shared_values() {
        // The old shared values were DEFAULT_FTS_WEIGHT/DEFAULT_VECTOR_WEIGHT
        // (0.5/0.5, still recall's own defaults post-split) and the
        // hardcoded TEST_PATH_PENALTY const (0.90, task 85). An untouched
        // install's locate ranking must not move.
        let cfg = CodeIndexConfig::default();
        assert_eq!(cfg.fts_weight, crate::config::DEFAULT_FTS_WEIGHT);
        assert_eq!(cfg.vector_weight, crate::config::DEFAULT_VECTOR_WEIGHT);
        assert_eq!(cfg.test_path_penalty, 0.90);
    }

    #[test]
    fn code_index_config_defaults_are_used_when_toml_omits_the_section() {
        // Every config.toml written before this PR has no [code_index]
        // table at all. It must still deserialize — via #[serde(default)]
        // on both the ProjectConfig field and every CodeIndexConfig field
        // — to the byte-identical pre-split defaults, not fail or zero out.
        let raw = r#"
project_name = "x"
auto_sync_md = false
log_level = "info"
"#;
        let cfg: ProjectConfig = toml::from_str(raw).expect("parse");
        assert_eq!(
            cfg.code_index.fts_weight,
            crate::config::DEFAULT_CODE_INDEX_FTS_WEIGHT
        );
        assert_eq!(
            cfg.code_index.vector_weight,
            crate::config::DEFAULT_CODE_INDEX_VECTOR_WEIGHT
        );
        assert_eq!(
            cfg.code_index.test_path_penalty,
            crate::config::DEFAULT_TEST_PATH_PENALTY
        );
    }

    /// The score seam: default-config locate scoring must equal the
    /// pre-split hardcoded formula (`0.5 * fts + 0.5 * vector`, `* 0.90`
    /// for test paths) bit-for-bit. Data is chosen so `normalize_fts`
    /// lands on clean fractions.
    #[test]
    fn score_candidates_default_config_matches_pre_split_formula() {
        let mut candidates = vec![
            new_candidate(1, "src/lib.rs".to_string()),
            new_candidate(2, "tests/foo.rs".to_string()),
        ];
        candidates[0].fts_raw = Some(-10.0); // pos = 10.0 -> fts_score 1.0
        candidates[0].cosine = Some(0.4);
        candidates[1].fts_raw = Some(0.0); // pos = 0.0 -> fts_score 0.0
        candidates[1].cosine = Some(1.0);

        score_candidates(&mut candidates, &CodeIndexConfig::default());

        // src/lib.rs: 0.5*1.0 + 0.5*0.4 = 0.7, no test-path penalty.
        assert!(
            (candidates[0].score - 0.7).abs() < 1e-9,
            "non-test-path score: {}",
            candidates[0].score
        );
        // tests/foo.rs: 0.5*0.0 + 0.5*1.0 = 0.5, times 0.90 penalty = 0.45.
        assert!(
            (candidates[1].score - 0.45).abs() < 1e-9,
            "test-path score: {}",
            candidates[1].score
        );
    }

    /// Regression guard for the bug this issue fixes: locate must read
    /// `[code_index]`, never `[retrieval.scoring]`. Distinctive,
    /// asymmetric weights (1.0/0.0) make it unambiguous which config
    /// path actually drove the score.
    #[test]
    fn score_candidates_uses_code_index_weights_not_retrieval_scoring() {
        let mut candidates = vec![new_candidate(1, "src/lib.rs".to_string())];
        candidates[0].fts_raw = Some(0.0); // single FTS hit -> fts_score 1.0
        candidates[0].cosine = Some(0.0); // vector_score 0.0

        let scoring = CodeIndexConfig {
            fts_weight: 1.0,
            vector_weight: 0.0,
            test_path_penalty: 1.0,
        };
        score_candidates(&mut candidates, &scoring);

        assert!(
            (candidates[0].score - 1.0).abs() < 1e-9,
            "expected fts-only score of 1.0, got {}",
            candidates[0].score
        );
    }
}

//! Code locator index (M11, decision 107).
//!
//! A cheap semantic locator over the repo's own source. It lives in a
//! **sibling DB** at `.memhub/code_index.sqlite`, physically separate
//! from `project.sqlite`, and is NEVER read by recall, NEVER exported,
//! NEVER synced. That physical separation is what preserves the recall
//! eval-regression guarantee structurally (mirrors the M9
//! registry-is-not-recall split).
//!
//! PR1 shipped the spine: the sibling-DB schema + bootstrap, a git-aware
//! walker, and the lazy `(mtime,size)`+hash staleness diff. PR2 (here)
//! adds the tree-sitter AST chunker ([`chunker`]/[`grammar`]), eager
//! embedding of chunks into `code_embeddings` (hybrid mode), and FTS
//! population via the schema's `code_chunks_fts` triggers. The `memhub
//! code index|status` CLI is PR3; the `memhub locate` query path also PR3.

pub mod chunker;
pub mod grammar;
pub mod locate;
pub mod schema;
pub mod walker;

use std::collections::HashMap;
use std::fs;
use std::path::{Path, PathBuf};
use std::time::UNIX_EPOCH;

use rusqlite::{Connection, Statement, Transaction, params};

use crate::Result;
use crate::config::{PathMatcher, ProjectConfig, RetrievalMode};
use crate::db::{self, MEMHUB_DIR};
use crate::retrieval::embeddings::{EMBEDDING_DIMENSION, EMBEDDING_MODEL_NAME, embed_batch};
use crate::retrieval::util::{bytes_to_vector, sha256_hex, vector_to_le_bytes};

/// Filename of the sibling code-index DB inside `.memhub/`.
pub const CODE_INDEX_DB_FILENAME: &str = "code_index.sqlite";

/// Resolve the sibling DB path for a repo root: `<root>/.memhub/code_index.sqlite`.
pub fn code_index_db_path(repo_root: &Path) -> PathBuf {
    repo_root.join(MEMHUB_DIR).join(CODE_INDEX_DB_FILENAME)
}

/// Open (creating + bootstrapping if necessary) the sibling code-index DB
/// at the given path. This connection is independent of the project DB —
/// callers must never run code-index DDL/DML against `project.sqlite`.
pub fn open_code_index(db_path: &Path) -> Result<Connection> {
    if let Some(parent) = db_path.parent() {
        fs::create_dir_all(parent)?;
    }
    let conn = Connection::open(db_path)?;
    conn.execute_batch(
        "PRAGMA foreign_keys = ON;
         PRAGMA journal_mode = WAL;
         PRAGMA synchronous = NORMAL;
         PRAGMA busy_timeout = 5000;
         PRAGMA recursive_triggers = OFF;",
    )?;
    schema::bootstrap(&conn)?;
    Ok(conn)
}

/// Outcome of a [`refresh`] pass over the working tree.
#[derive(Debug, Default, Clone)]
pub struct RefreshSummary {
    /// Indexable source files in the index after this refresh. Scoped to
    /// the grammar-known source languages (task 69); non-source files —
    /// docs, lockfiles, JSON/YAML/TOML, vendored `*.min.*` bundles — are
    /// excluded (see [`excluded_files`]). A source file that is non-UTF-8
    /// is still counted here but carries zero chunks.
    ///
    /// [`excluded_files`]: RefreshSummary::excluded_files
    pub files_total: usize,
    /// Total code chunks in the index after this refresh.
    pub chunks_total: usize,
    /// Files newly added to the index this pass.
    pub new_files: usize,
    /// Files whose content changed and were re-chunked this pass.
    pub changed_files: usize,
    /// Files left untouched (metadata or content matched the index).
    pub unchanged_files: usize,
    /// Index rows dropped because the file is no longer tracked (or was
    /// absent on disk this pass).
    pub deleted_files: usize,
    /// Tracked files examined but not indexed this pass: absent on disk,
    /// a symlink, or present-but-unreadable. Together with new/changed/
    /// unchanged this reconciles against the indexable set:
    /// `new + changed + unchanged + skipped == indexable tracked files`.
    pub skipped_files: usize,
    /// Tracked files excluded from the index because they are not an
    /// indexable source language, or are a vendored/minified bundle (task
    /// 69). These never enter the per-file loop; one previously indexed is
    /// dropped via the cleanup pass. With the four loop counters this
    /// reconciles against the full tracked set:
    /// `new + changed + unchanged + skipped + excluded == tracked total`.
    pub excluded_files: usize,
    /// Subset of new/changed files that were non-UTF-8 (tracked, but
    /// produced no chunks — a line-window chunker can't window binary).
    pub binary_skipped: usize,
    /// Chunks embedded this pass (hybrid mode only; 0 in fts mode or when
    /// every chunk already had a current vector).
    pub embedded_chunks: usize,
    /// Indexed `HEAD`, if resolvable.
    pub head: Option<String>,
}

struct ExistingFile {
    id: i64,
    mtime: i64,
    size: i64,
    content_hash: String,
}

/// Bring the code index in line with the current working tree.
///
/// Lazy and git-aware (decision 107): the tracked set comes from `git
/// ls-files` minus the deny-list, and per file we diff `(mtime, size)`
/// against the index, confirming with a content hash only when metadata
/// moved. Unchanged files are never read; changed/added files are
/// re-chunked; files no longer tracked have their rows (and, via cascade,
/// chunks) dropped. The whole pass is one transaction.
pub fn refresh(start: &Path) -> Result<RefreshSummary> {
    // Resolve the canonical repo root + deny-list WITHOUT opening
    // project.sqlite: discover_paths + a config read are all we need, and
    // they skip open_project's heavy side effects (migrations, Claude
    // transcript scrape, registry upsert). The code index is a separate DB
    // and stays decoupled from project.sqlite (finding M1).
    let paths = db::discover_paths(start)?;
    let repo_root = paths.repo_root.clone();
    let config = if paths.config_path.exists() {
        ProjectConfig::load(&paths.config_path)?
    } else {
        let repo_name = repo_root
            .file_name()
            .and_then(|name| name.to_str())
            .unwrap_or("memhub");
        ProjectConfig::default_for_repo_name(repo_name)
    };
    let matcher = PathMatcher::from_patterns(&config.deny_list.patterns)?;

    // `list_tracked_files` is the deny-list-filtered git set; scope it
    // further to indexable source files (task 69). Non-source files —
    // docs, lockfiles, JSON/YAML/TOML, vendored `*.min.*` bundles — are
    // dropped here so they can't out-rank real implementation files in
    // `locate`. Any such file already in the index is left in `existing`
    // and dropped by the cleanup pass below, so a re-index auto-prunes.
    let all_tracked = walker::list_tracked_files(&repo_root, &matcher)?;
    let tracked_total = all_tracked.len();
    let tracked: Vec<String> = all_tracked
        .into_iter()
        .filter(|p| is_indexable_source(p))
        .collect();
    let head = walker::current_head(&repo_root);

    let db_path = code_index_db_path(&repo_root);
    let mut conn = open_code_index(&db_path)?;
    let tx = conn.transaction()?;

    let mut existing = load_existing_files(&tx)?;
    let mut summary = RefreshSummary {
        head: head.clone(),
        excluded_files: tracked_total - tracked.len(),
        ..Default::default()
    };

    // Prepared once and reused across every file instead of re-preparing
    // per file (finding L2). Dropped before the cleanup writes + commit so
    // the transaction carries no outstanding borrow when consumed.
    let mut insert_chunk_stmt = tx.prepare(
        "INSERT INTO code_chunks(
            file_id, start_line, end_line, symbol, kind, content_hash, embed_text
         ) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7)",
    )?;

    for path in &tracked {
        let abs = repo_root.join(path);
        // symlink_metadata does NOT follow links, so a tracked symlink is
        // detected here rather than silently read by-target (finding M3),
        // and an absent file is distinguished from a present one.
        let meta = match fs::symlink_metadata(&abs) {
            Ok(m) => m,
            // Tracked but absent on disk: deleted-but-unstaged, or a sparse
            // checkout. Do NOT remove it from `existing` — leaving it there
            // lets the cleanup loop drop any stale row, which is the correct
            // staleness behavior (finding P2). A re-checkout re-indexes it.
            Err(_) => {
                summary.skipped_files += 1;
                continue;
            }
        };
        if meta.file_type().is_symlink() {
            // Never index a symlink — reading it would follow the link,
            // possibly outside the repo. Leave it in `existing` so a row
            // for a path that used to be a regular file is cleaned up.
            summary.skipped_files += 1;
            continue;
        }
        let mtime = mtime_millis(&meta);
        let size = meta.len() as i64;

        if let Some(prev) = existing.remove(path) {
            // Fast path: identical metadata => assume unchanged, no read.
            // Only valid when mtime is actually known; if the platform
            // can't report it we fall through to the content hash so a
            // same-size edit is never missed (finding M2).
            if let Some(mtime) = mtime
                && prev.mtime == mtime
                && prev.size == size
            {
                summary.unchanged_files += 1;
                continue;
            }
            let bytes = match fs::read(&abs) {
                Ok(b) => b,
                // Present but unreadable (permissions / TOCTOU vanish).
                // Skip and count; `prev` is already out of `existing`, so
                // the prior row survives the cleanup loop — don't wipe a
                // good entry over a transient blip (finding H1).
                Err(_) => {
                    summary.skipped_files += 1;
                    continue;
                }
            };
            let hash = sha256_hex(&bytes);
            if hash == prev.content_hash {
                // Content identical (touched / re-checked-out); refresh stat only.
                tx.execute(
                    "UPDATE indexed_files
                     SET mtime = ?1, size = ?2, last_indexed_at = CURRENT_TIMESTAMP
                     WHERE id = ?3",
                    params![mtime.unwrap_or(0), size, prev.id],
                )?;
                summary.unchanged_files += 1;
                continue;
            }
            // Real content change: re-chunk in place.
            tx.execute(
                "DELETE FROM code_chunks WHERE file_id = ?1",
                params![prev.id],
            )?;
            let is_binary = insert_chunks(
                &mut insert_chunk_stmt,
                prev.id,
                path,
                infer_language(path),
                &bytes,
            )?;
            tx.execute(
                "UPDATE indexed_files
                 SET mtime = ?1, size = ?2, content_hash = ?3,
                     language = ?4, last_indexed_at = CURRENT_TIMESTAMP
                 WHERE id = ?5",
                params![
                    mtime.unwrap_or(0),
                    size,
                    hash,
                    infer_language(path),
                    prev.id
                ],
            )?;
            summary.changed_files += 1;
            if is_binary {
                summary.binary_skipped += 1;
            }
        } else {
            let bytes = match fs::read(&abs) {
                Ok(b) => b,
                Err(_) => {
                    summary.skipped_files += 1;
                    continue;
                }
            };
            let hash = sha256_hex(&bytes);
            tx.execute(
                "INSERT INTO indexed_files(path, mtime, size, content_hash, language)
                 VALUES (?1, ?2, ?3, ?4, ?5)",
                params![path, mtime.unwrap_or(0), size, hash, infer_language(path)],
            )?;
            let file_id = tx.last_insert_rowid();
            let is_binary = insert_chunks(
                &mut insert_chunk_stmt,
                file_id,
                path,
                infer_language(path),
                &bytes,
            )?;
            summary.new_files += 1;
            if is_binary {
                summary.binary_skipped += 1;
            }
        }
    }

    drop(insert_chunk_stmt);

    // Anything still in the map is no longer tracked (or absent on disk):
    // drop it (the ON DELETE CASCADE on code_chunks.file_id removes its
    // chunks).
    for prev in existing.values() {
        tx.execute("DELETE FROM indexed_files WHERE id = ?1", params![prev.id])?;
        summary.deleted_files += 1;
    }

    if let Some(h) = &head {
        tx.execute(
            "INSERT INTO index_meta(key, value) VALUES ('last_head', ?1)
             ON CONFLICT(key) DO UPDATE SET value = excluded.value",
            params![h],
        )?;
    }

    summary.files_total = tx.query_row("SELECT COUNT(*) FROM indexed_files", [], |r| {
        r.get::<_, i64>(0)
    })? as usize;
    summary.chunks_total = tx.query_row("SELECT COUNT(*) FROM code_chunks", [], |r| {
        r.get::<_, i64>(0)
    })? as usize;

    tx.commit()?;

    // Phase 2: embed any chunk that lacks a current vector. Hybrid-only —
    // in fts mode `code_embeddings` stays empty and the locator (PR3) runs
    // FTS-only, mirroring the project DB's eager-embed gating. This runs
    // AFTER the chunk transaction commits (not inside it) so the heavy
    // model inference never holds the index write lock, and a transient
    // embed failure leaves a complete chunk+FTS index that degrades to FTS
    // rather than rolling the whole refresh back. Backfill semantics —
    // embed every missing chunk, not just this pass's new ones — means such
    // a failure self-heals on the next refresh.
    if config.retrieval.mode == RetrievalMode::Hybrid {
        summary.embedded_chunks = embed_missing(&mut conn)?;
    }
    Ok(summary)
}

/// A read-only snapshot of the sibling code index for `memhub code status`.
#[derive(Debug, Clone)]
pub struct CodeIndexStatus {
    /// Absolute path to the sibling DB.
    pub db_path: PathBuf,
    /// Whether the DB file exists yet (a never-indexed repo reports false
    /// with all-zero counts; status never creates the DB).
    pub exists: bool,
    /// Stored schema version, or `None` when absent/unparseable.
    pub schema_version: Option<i64>,
    /// Configured retrieval mode (governs whether vectors are populated).
    pub mode: RetrievalMode,
    pub files_total: i64,
    pub chunks_total: i64,
    pub embeddings_total: i64,
    /// `HEAD` recorded at the last refresh.
    pub last_head: Option<String>,
    /// Current repo `HEAD`, if resolvable.
    pub current_head: Option<String>,
}

impl CodeIndexStatus {
    /// True when the index was built against a different commit than the
    /// current `HEAD` — a coarse staleness cue. `false` when either side is
    /// unknown (no claim either way) or the index is empty.
    pub fn head_stale(&self) -> bool {
        match (&self.last_head, &self.current_head) {
            (Some(last), Some(current)) => last != current,
            _ => false,
        }
    }
}

/// Snapshot the sibling index without refreshing it. Reports `exists:
/// false` (and zero counts) when the DB has never been created, rather than
/// bootstrapping it — a status check must not have side effects.
pub fn status(start: &Path) -> Result<CodeIndexStatus> {
    let paths = db::discover_paths(start)?;
    let repo_root = paths.repo_root.clone();
    let config = if paths.config_path.exists() {
        ProjectConfig::load(&paths.config_path)?
    } else {
        let repo_name = repo_root
            .file_name()
            .and_then(|name| name.to_str())
            .unwrap_or("memhub");
        ProjectConfig::default_for_repo_name(repo_name)
    };
    let db_path = code_index_db_path(&repo_root);
    let current_head = walker::current_head(&repo_root);

    if !db_path.exists() {
        return Ok(CodeIndexStatus {
            db_path,
            exists: false,
            schema_version: None,
            mode: config.retrieval.mode,
            files_total: 0,
            chunks_total: 0,
            embeddings_total: 0,
            last_head: None,
            current_head,
        });
    }

    let conn = Connection::open(&db_path)?;
    let schema_version = schema::stored_version(&conn)?;
    let files_total = conn.query_row("SELECT COUNT(*) FROM indexed_files", [], |r| r.get(0))?;
    let chunks_total = conn.query_row("SELECT COUNT(*) FROM code_chunks", [], |r| r.get(0))?;
    let embeddings_total =
        conn.query_row("SELECT COUNT(*) FROM code_embeddings", [], |r| r.get(0))?;
    let last_head: Option<String> = conn
        .query_row(
            "SELECT value FROM index_meta WHERE key = 'last_head'",
            [],
            |r| r.get(0),
        )
        .ok();

    Ok(CodeIndexStatus {
        db_path,
        exists: true,
        schema_version,
        mode: config.retrieval.mode,
        files_total,
        chunks_total,
        embeddings_total,
        last_head,
        current_head,
    })
}

/// Outcome of [`remove_index`].
#[derive(Debug, Clone)]
pub struct RemoveOutcome {
    pub db_path: PathBuf,
    /// True when the main DB file existed and was deleted.
    pub removed: bool,
}

/// Delete the sibling code-index DB (and its `-wal` / `-shm` companions).
/// The index is fully regenerable from the working tree (decision 107), so
/// this is a disposable-cache wipe, not a destructive data loss. A
/// `removed: false` means there was nothing to delete.
pub fn remove_index(start: &Path) -> Result<RemoveOutcome> {
    let paths = db::discover_paths(start)?;
    let db_path = code_index_db_path(&paths.repo_root);
    let removed = db_path.exists();
    for suffix in ["", "-wal", "-shm"] {
        let candidate = if suffix.is_empty() {
            db_path.clone()
        } else {
            let mut name = db_path.as_os_str().to_os_string();
            name.push(suffix);
            PathBuf::from(name)
        };
        if candidate.exists() {
            // A missing WAL/SHM is fine; only surface a real removal error.
            fs::remove_file(&candidate)?;
        }
    }
    Ok(RemoveOutcome { db_path, removed })
}

/// Embed every `code_chunks` row that has no `code_embeddings` row yet and
/// persist the vectors. Reuses the shared BGE model ([`embed_batch`]).
///
/// An in-run cache keyed by the `embed_text` hash means a chunk whose text
/// matches one already embedded — duplicated code, or an unchanged sibling
/// whose vector survived this refresh — reuses that vector instead of
/// re-running the model. Cache misses are gathered into a single batched
/// inference. Returns the number of chunks given an embedding row.
fn embed_missing(conn: &mut Connection) -> Result<usize> {
    // Chunks still missing a vector (new this pass, or a prior embed blip).
    // Queried FIRST so a warm `locate` — where nothing is missing — returns
    // before decoding the entire `code_embeddings` table into the cache.
    let missing: Vec<(i64, String)> = {
        let mut stmt = conn.prepare(
            "SELECT c.id, c.embed_text FROM code_chunks c
             LEFT JOIN code_embeddings e ON e.chunk_id = c.id
             WHERE e.chunk_id IS NULL",
        )?;
        let rows = stmt.query_map([], |r| Ok((r.get::<_, i64>(0)?, r.get::<_, String>(1)?)))?;
        rows.collect::<std::result::Result<Vec<_>, _>>()?
    };
    if missing.is_empty() {
        return Ok(0);
    }

    // Seed the cache from embeddings that survived the chunk diff.
    let mut cache: HashMap<String, Vec<f32>> = HashMap::new();
    {
        let mut stmt = conn.prepare("SELECT content_hash, vector FROM code_embeddings")?;
        let rows = stmt.query_map([], |r| {
            Ok((r.get::<_, String>(0)?, r.get::<_, Vec<u8>>(1)?))
        })?;
        for row in rows {
            let (hash, blob) = row?;
            cache.insert(hash, bytes_to_vector(&blob));
        }
    }

    // Hash each chunk's embed_text; gather the unique cache-miss texts for
    // one batched model call. `pending` maps a hash to its slot in the batch
    // so duplicates within this pass embed exactly once.
    let mut hashes: Vec<String> = Vec::with_capacity(missing.len());
    let mut pending: HashMap<String, usize> = HashMap::new();
    let mut batch_texts: Vec<&str> = Vec::new();
    for (_, text) in &missing {
        let hash = sha256_hex(text.as_bytes());
        if !cache.contains_key(&hash) && !pending.contains_key(&hash) {
            pending.insert(hash.clone(), batch_texts.len());
            batch_texts.push(text.as_str());
        }
        hashes.push(hash);
    }

    if !batch_texts.is_empty() {
        let vectors = embed_batch(&batch_texts)?;
        for (hash, idx) in &pending {
            cache.insert(hash.clone(), vectors[*idx].clone());
        }
    }

    let tx = conn.transaction()?;
    {
        let mut insert = tx.prepare(
            "INSERT INTO code_embeddings(chunk_id, model_name, dimension, vector, content_hash)
             VALUES (?1, ?2, ?3, ?4, ?5)",
        )?;
        for ((chunk_id, _), hash) in missing.iter().zip(&hashes) {
            let vector = cache
                .get(hash)
                .expect("every missing chunk's vector is cached or freshly embedded");
            insert.execute(params![
                chunk_id,
                EMBEDDING_MODEL_NAME,
                EMBEDDING_DIMENSION as i64,
                vector_to_le_bytes(vector),
                hash,
            ])?;
        }
    }
    tx.commit()?;
    Ok(missing.len())
}

fn load_existing_files(tx: &Transaction<'_>) -> Result<HashMap<String, ExistingFile>> {
    let mut stmt = tx.prepare("SELECT id, path, mtime, size, content_hash FROM indexed_files")?;
    let rows = stmt.query_map([], |row| {
        Ok((
            row.get::<_, String>(1)?,
            ExistingFile {
                id: row.get(0)?,
                mtime: row.get(2)?,
                size: row.get(3)?,
                content_hash: row.get(4)?,
            },
        ))
    })?;
    let mut map = HashMap::new();
    for row in rows {
        let (path, file) = row?;
        map.insert(path, file);
    }
    Ok(map)
}

/// Chunk `bytes` and insert the chunks for `file_id` via the caller's
/// hoisted statement. The `language` hint (from [`infer_language`]) picks
/// the AST grammar. Since task 69, only indexable source reaches here, so
/// the line-window fallback now covers just a grammar-known file that fails
/// to parse (not unknown extensions, which are filtered upstream). Returns
/// `true` when the file was non-UTF-8 (tracked, zero chunks) so callers can
/// count it.
fn insert_chunks(
    stmt: &mut Statement<'_>,
    file_id: i64,
    path: &str,
    language: Option<&str>,
    bytes: &[u8],
) -> Result<bool> {
    let Ok(text) = std::str::from_utf8(bytes) else {
        return Ok(true);
    };
    for c in &chunker::chunk_file(path, text, language) {
        stmt.execute(params![
            file_id,
            c.start_line as i64,
            c.end_line as i64,
            c.symbol,
            c.kind,
            sha256_hex(c.body.as_bytes()),
            c.embed_text,
        ])?;
    }
    Ok(false)
}

/// File mtime in milliseconds since the epoch, or `None` when the platform
/// can't report a modified time. Callers must treat `None` as "metadata
/// fast path unavailable" and fall back to the content hash, never as a
/// concrete `0` (which would make every same-size edit look unchanged).
fn mtime_millis(meta: &fs::Metadata) -> Option<i64> {
    meta.modified()
        .ok()
        .and_then(|t| t.duration_since(UNIX_EPOCH).ok())
        .map(|d| d.as_millis() as i64)
}

/// True when a tracked path should enter the code index (task 69): a
/// source language the grammar registry can chunk, and not a
/// vendored/minified bundle. This deliberately reverses the pre-task-69
/// "index every tracked file" behavior — docs, lockfiles, JSON/YAML/TOML,
/// and `*.min.*` artifacts are excluded so they cannot out-rank real
/// implementation files in `locate` (the dominant Recall error mode,
/// decision 114). The grammar registry is the single source of truth for
/// "indexable source", so a future language row is included automatically.
fn is_indexable_source(path: &str) -> bool {
    !is_vendored(path) && grammar::grammar_for(infer_language(path)).is_some()
}

/// A generated/minified bundle that has a real source extension but is not
/// hand-written code we want surfacing as a hit (e.g. `uplot.min.js`). The
/// `.min.` filename infix is the precise marker; matching it rather than a
/// `vendor/` directory name avoids excluding hand-written code that merely
/// lives under such a path.
fn is_vendored(path: &str) -> bool {
    path.rsplit('/').next().unwrap_or(path).contains(".min.")
}

/// Best-effort language hint from the file extension. Mirrors the set in
/// `ingest_git`; the grammar registry keys off this. Note the `toml`,
/// `markdown`, `json`, `yaml`, and `sql` arms have no grammar row, so
/// [`is_indexable_source`] excludes those files from the index; the hint
/// remains for parity with `ingest_git`.
fn infer_language(path: &str) -> Option<&'static str> {
    let extension = path.rsplit('.').next()?;
    match extension.to_ascii_lowercase().as_str() {
        "rs" => Some("rust"),
        "toml" => Some("toml"),
        "md" => Some("markdown"),
        "json" => Some("json"),
        "yaml" | "yml" => Some("yaml"),
        "ts" | "tsx" | "mts" | "cts" => Some("typescript"),
        "js" | "jsx" | "mjs" | "cjs" => Some("javascript"),
        "py" => Some("python"),
        "cs" => Some("csharp"),
        "java" => Some("java"),
        "go" => Some("go"),
        "sql" => Some("sql"),
        _ => None,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use rusqlite::params;
    use schema::CODE_INDEX_SCHEMA_VERSION;
    use tempfile::tempdir;

    fn table_exists(conn: &Connection, name: &str) -> bool {
        conn.query_row(
            "SELECT 1 FROM sqlite_master WHERE type IN ('table','view') AND name = ?1",
            params![name],
            |row| row.get::<_, i64>(0),
        )
        .is_ok()
    }

    #[test]
    fn bootstrap_creates_schema_at_current_version() {
        let temp = tempdir().expect("tempdir");
        let path = temp.path().join("code_index.sqlite");
        let conn = open_code_index(&path).expect("open");

        for table in [
            "index_meta",
            "indexed_files",
            "code_chunks",
            "code_embeddings",
            "code_chunks_fts",
        ] {
            assert!(table_exists(&conn, table), "missing table: {table}");
        }
        assert_eq!(
            schema::stored_version(&conn).expect("version"),
            Some(CODE_INDEX_SCHEMA_VERSION)
        );
    }

    #[test]
    fn embeddings_and_fts_start_empty_on_fresh_bootstrap() {
        // A bootstrapped-but-never-refreshed index has no chunks, so the
        // embedding + FTS tables exist and are empty. Population happens in
        // refresh() (FTS via triggers, embeddings in hybrid mode).
        let temp = tempdir().expect("tempdir");
        let path = temp.path().join("code_index.sqlite");
        let conn = open_code_index(&path).expect("open");

        let embeddings: i64 = conn
            .query_row("SELECT COUNT(*) FROM code_embeddings", [], |r| r.get(0))
            .expect("count embeddings");
        let fts: i64 = conn
            .query_row("SELECT COUNT(*) FROM code_chunks_fts", [], |r| r.get(0))
            .expect("count fts");
        assert_eq!(embeddings, 0);
        assert_eq!(fts, 0);
    }

    #[test]
    fn synchronous_pragma_is_normal_on_open() {
        // D5/Q35: WAL is paired with `synchronous = NORMAL` (decision 140)
        // rather than the SQLite default FULL, dropping one fsync per
        // commit. 1 is SQLite's integer encoding for NORMAL.
        let temp = tempdir().expect("tempdir");
        let path = temp.path().join("code_index.sqlite");
        let conn = open_code_index(&path).expect("open");

        let synchronous: i64 = conn
            .query_row("PRAGMA synchronous", [], |row| row.get(0))
            .expect("query synchronous pragma");
        assert_eq!(synchronous, 1, "expected synchronous = NORMAL (1)");
    }

    #[test]
    fn reopen_is_idempotent() {
        let temp = tempdir().expect("tempdir");
        let path = temp.path().join("code_index.sqlite");
        open_code_index(&path).expect("first open");
        let conn = open_code_index(&path).expect("second open");
        assert_eq!(
            schema::stored_version(&conn).expect("version"),
            Some(CODE_INDEX_SCHEMA_VERSION)
        );
    }

    #[test]
    fn version_mismatch_triggers_drop_and_rebuild() {
        let temp = tempdir().expect("tempdir");
        let path = temp.path().join("code_index.sqlite");

        // Bootstrap, then plant a row and stamp a stale version.
        {
            let conn = open_code_index(&path).expect("open");
            conn.execute(
                "INSERT INTO indexed_files(path, mtime, size, content_hash)
                 VALUES ('src/main.rs', 1, 2, 'deadbeef')",
                [],
            )
            .expect("seed file row");
            conn.execute(
                "UPDATE index_meta SET value = ?1 WHERE key = 'schema_version'",
                params![(CODE_INDEX_SCHEMA_VERSION - 1).to_string()],
            )
            .expect("stale version");
        }

        // Reopening sees the mismatch and rebuilds from scratch.
        let conn = open_code_index(&path).expect("reopen");
        assert_eq!(
            schema::stored_version(&conn).expect("version"),
            Some(CODE_INDEX_SCHEMA_VERSION)
        );
        let files: i64 = conn
            .query_row("SELECT COUNT(*) FROM indexed_files", [], |r| r.get(0))
            .expect("count files");
        assert_eq!(files, 0, "stale rows should be dropped on rebuild");
    }

    #[test]
    fn indexable_source_accepts_grammar_languages_and_rejects_the_rest() {
        // Every grammar-known source language is indexable.
        for path in [
            "src/main.rs",
            "app/handler.ts",
            "ui/button.tsx",
            "lib/util.js",
            "server.mjs",
            "scripts/run.py",
            "cmd/main.go",
            "Service.cs",
            "Widget.java",
        ] {
            assert!(is_indexable_source(path), "should index: {path}");
        }
        // Non-source files have no grammar row and are excluded — these are
        // the locate pollutants task 69 targets.
        for path in [
            "README.md",
            "AGENTS.md",
            "Cargo.lock",
            "Cargo.toml",
            "data.json",
            "config.yaml",
            "deploy.yml",
            "migrations/0001_init.sql",
            "tests/code_locate_golden.json",
            "LICENSE",
        ] {
            assert!(!is_indexable_source(path), "should exclude: {path}");
        }
    }

    #[test]
    fn vendored_minified_bundles_are_excluded_despite_source_extension() {
        // A real .js extension has a grammar, but a minified bundle must
        // not surface as a code hit (task 69).
        assert!(is_vendored("src/dashboard/static/vendor/uplot.min.js"));
        assert!(is_vendored("uplot.min.css"));
        assert!(is_vendored("dist/app.min.mjs"));
        assert!(!is_indexable_source(
            "src/dashboard/static/vendor/uplot.min.js"
        ));
        // Hand-written code is not minified, even under a vendor-ish path.
        assert!(!is_vendored("src/vendor/adapter.js"));
        assert!(is_indexable_source("src/vendor/adapter.js"));
    }

    #[test]
    fn corrupt_version_value_triggers_drop_and_rebuild() {
        let temp = tempdir().expect("tempdir");
        let path = temp.path().join("code_index.sqlite");

        // Bootstrap, plant a row, then corrupt the version to a non-integer
        // so it no longer parses (finding L5).
        {
            let conn = open_code_index(&path).expect("open");
            conn.execute(
                "INSERT INTO indexed_files(path, mtime, size, content_hash)
                 VALUES ('src/main.rs', 1, 2, 'deadbeef')",
                [],
            )
            .expect("seed file row");
            conn.execute(
                "UPDATE index_meta SET value = 'not-a-number' WHERE key = 'schema_version'",
                [],
            )
            .expect("corrupt version");
        }

        let conn = open_code_index(&path).expect("reopen");
        assert_eq!(
            schema::stored_version(&conn).expect("version"),
            Some(CODE_INDEX_SCHEMA_VERSION)
        );
        let files: i64 = conn
            .query_row("SELECT COUNT(*) FROM indexed_files", [], |r| r.get(0))
            .expect("count files");
        assert_eq!(files, 0, "corrupt version should force a rebuild");
    }
}

//! Sibling code-index DB schema + bootstrap (M11 PR1, decision 107).
//!
//! The code index lives in its own file at `.memhub/code_index.sqlite`,
//! physically separate from `project.sqlite`. It is derivable and
//! disposable, so it carries **no migration framework**: bootstrap is
//! `CREATE TABLE IF NOT EXISTS` plus a single `schema_version` row in
//! `index_meta`. When the stored version disagrees with the version this
//! binary knows, every table is dropped and recreated — a rebuild is
//! free because the whole index is regenerable from the working tree.
//! This is what makes `memhub upgrade` a no-op for the code index.
//!
//! `code_embeddings` is populated by [`super::embed_missing`] in hybrid
//! mode; `code_chunks_fts` is kept current by the sync triggers created
//! here (added in v2), so a chunk insert/delete flows into FTS without
//! the writer touching it.

use rusqlite::{Connection, OptionalExtension, params};

use crate::Result;

/// Schema version stamped into `index_meta`. Bumping this triggers a
/// DROP+REBUILD on the next open — intentional and cheap, since the index
/// is rebuilt from tracked files.
///
/// v2 (PR2): adds the `code_chunks_fts` sync triggers so chunk writes keep
/// the contentless FTS index current. A v1 index built by PR1 carried the
/// FTS table but no triggers; the bump rebuilds it from the working tree.
pub const CODE_INDEX_SCHEMA_VERSION: i64 = 2;

const META_VERSION_KEY: &str = "schema_version";

/// Bring the sibling DB to the current schema version.
///
/// If a prior version is recorded and differs from
/// [`CODE_INDEX_SCHEMA_VERSION`], the whole index is dropped and rebuilt.
/// Otherwise the `CREATE TABLE IF NOT EXISTS` statements are idempotent.
pub fn bootstrap(conn: &Connection) -> Result<()> {
    let needs_rebuild = match stored_version(conn)? {
        Some(version) => version != CODE_INDEX_SCHEMA_VERSION,
        // `index_meta` exists but holds no parseable version: a corrupt or
        // partially-written prior state. Treat it as a mismatch and rebuild
        // — the index is regenerable, so a spurious rebuild is only cheap,
        // never lossy. A genuinely fresh DB has no `index_meta` table and
        // is reported as `false` here, so it is created, not dropped.
        None => meta_table_present(conn)?,
    };
    if needs_rebuild {
        drop_all(conn)?;
    }

    create_all(conn)?;

    conn.execute(
        "INSERT INTO index_meta(key, value) VALUES (?1, ?2)
         ON CONFLICT(key) DO UPDATE SET value = excluded.value",
        params![META_VERSION_KEY, CODE_INDEX_SCHEMA_VERSION.to_string()],
    )?;

    Ok(())
}

/// The schema version recorded in `index_meta`, or `None` when the index
/// has never been bootstrapped (the `index_meta` table is absent).
pub fn stored_version(conn: &Connection) -> Result<Option<i64>> {
    if !meta_table_present(conn)? {
        return Ok(None);
    }

    let raw: Option<String> = conn
        .query_row(
            "SELECT value FROM index_meta WHERE key = ?1",
            params![META_VERSION_KEY],
            |row| row.get(0),
        )
        .optional()?;
    Ok(raw.and_then(|v| v.parse::<i64>().ok()))
}

/// Whether the `index_meta` table exists — i.e. the DB has been
/// bootstrapped at least once (even if its version row is corrupt).
fn meta_table_present(conn: &Connection) -> Result<bool> {
    let present: Option<i64> = conn
        .query_row(
            "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = 'index_meta'",
            [],
            |row| row.get(0),
        )
        .optional()?;
    Ok(present.is_some())
}

fn create_all(conn: &Connection) -> Result<()> {
    conn.execute_batch(
        "CREATE TABLE IF NOT EXISTS index_meta (
            key   TEXT PRIMARY KEY,
            value TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS indexed_files (
            id              INTEGER PRIMARY KEY,
            path            TEXT NOT NULL UNIQUE,
            mtime           INTEGER NOT NULL,
            size            INTEGER NOT NULL,
            content_hash    TEXT NOT NULL,
            language        TEXT,
            last_indexed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
        );

        CREATE TABLE IF NOT EXISTS code_chunks (
            id           INTEGER PRIMARY KEY,
            file_id      INTEGER NOT NULL REFERENCES indexed_files(id) ON DELETE CASCADE,
            start_line   INTEGER NOT NULL,
            end_line     INTEGER NOT NULL,
            symbol       TEXT,
            kind         TEXT,
            content_hash TEXT NOT NULL,
            embed_text   TEXT NOT NULL,
            created_at   TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
        );

        CREATE INDEX IF NOT EXISTS idx_code_chunks_file ON code_chunks(file_id);

        -- Populated in PR2 (tree-sitter chunker + embed). Empty in PR1.
        CREATE TABLE IF NOT EXISTS code_embeddings (
            chunk_id     INTEGER PRIMARY KEY REFERENCES code_chunks(id) ON DELETE CASCADE,
            model_name   TEXT NOT NULL,
            dimension    INTEGER NOT NULL,
            vector       BLOB NOT NULL,
            content_hash TEXT NOT NULL,
            created_at   TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
        );

        -- Contentless FTS5 over code_chunks (mirror of the doc_chunks_fts
        -- shape in migration 0014). symbol is indexed alongside embed_text
        -- so a query naming a function/type matches on the symbol token as
        -- well as the body.
        CREATE VIRTUAL TABLE IF NOT EXISTS code_chunks_fts USING fts5(
            symbol,
            embed_text,
            content='code_chunks',
            content_rowid='id'
        );

        -- Keep the contentless FTS index in step with code_chunks (mirror
        -- the 0014 doc_chunks triggers). The delete trigger fires on direct
        -- chunk deletes AND on the ON DELETE CASCADE from an indexed_files
        -- row removal, so a dropped file's FTS rows go with it.
        CREATE TRIGGER IF NOT EXISTS code_chunks_fts_ai AFTER INSERT ON code_chunks BEGIN
            INSERT INTO code_chunks_fts(rowid, symbol, embed_text)
                VALUES (new.id, new.symbol, new.embed_text);
        END;
        CREATE TRIGGER IF NOT EXISTS code_chunks_fts_ad AFTER DELETE ON code_chunks BEGIN
            INSERT INTO code_chunks_fts(code_chunks_fts, rowid, symbol, embed_text)
                VALUES ('delete', old.id, old.symbol, old.embed_text);
        END;
        CREATE TRIGGER IF NOT EXISTS code_chunks_fts_au AFTER UPDATE ON code_chunks BEGIN
            INSERT INTO code_chunks_fts(code_chunks_fts, rowid, symbol, embed_text)
                VALUES ('delete', old.id, old.symbol, old.embed_text);
            INSERT INTO code_chunks_fts(rowid, symbol, embed_text)
                VALUES (new.id, new.symbol, new.embed_text);
        END;",
    )?;
    Ok(())
}

fn drop_all(conn: &Connection) -> Result<()> {
    // Drop children before parents; FTS vtable first. `DROP TABLE IF
    // EXISTS` is idempotent, so a partial prior schema drops cleanly.
    conn.execute_batch(
        "DROP TABLE IF EXISTS code_chunks_fts;
         DROP TABLE IF EXISTS code_embeddings;
         DROP TABLE IF EXISTS code_chunks;
         DROP TABLE IF EXISTS indexed_files;
         DROP TABLE IF EXISTS index_meta;",
    )?;
    Ok(())
}

//! Git-aware file walker for the code index (M11 PR1, decision 107).
//!
//! The index set is `git ls-files` filtered through the project's
//! existing deny-list ([`PathMatcher`]). Driving it off git (rather than
//! a raw directory walk) means untracked scratch is ignored and
//! `.gitignore` is respected for free, with no extra config.

use std::path::Path;
use std::process::Command;

use crate::Result;
use crate::config::PathMatcher;
use crate::errors::MemhubError;

/// List repo-relative paths tracked by git, minus deny-listed ones.
///
/// Paths use forward slashes (git's native form, even on Windows) and are
/// returned sorted for deterministic refresh order. `-z` keeps paths with
/// spaces or unusual characters intact (git would otherwise quote them).
pub fn list_tracked_files(repo_root: &Path, matcher: &PathMatcher) -> Result<Vec<String>> {
    let output = Command::new("git")
        .arg("-C")
        .arg(repo_root)
        .arg("ls-files")
        .arg("-z")
        .output()?;

    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr).trim().to_string();
        return Err(MemhubError::ExternalCommand {
            command: format!("git -C {} ls-files", repo_root.display()),
            stderr: if stderr.is_empty() {
                "unknown git error".to_string()
            } else {
                stderr
            },
        });
    }

    // `-z` delimits each path with a trailing NUL and emits raw bytes, so
    // splitting on NUL is the whole parse: do NOT trim, or paths whose
    // names begin or end with whitespace get silently corrupted. The split
    // yields a trailing empty element after the final NUL, dropped here.
    let mut paths: Vec<String> = String::from_utf8_lossy(&output.stdout)
        .split('\0')
        .filter(|p| !p.is_empty())
        .filter(|p| !matcher.is_denied(p))
        .map(str::to_string)
        .collect();
    paths.sort();
    paths.dedup();
    Ok(paths)
}

/// The current `HEAD` commit sha, or `None` when it cannot be resolved
/// (e.g. a repo with no commits yet). Stamped into `index_meta` so
/// `code status` can report the indexed HEAD; never load-bearing for
/// staleness, which is decided per-file.
pub fn current_head(repo_root: &Path) -> Option<String> {
    let output = Command::new("git")
        .arg("-C")
        .arg(repo_root)
        .arg("rev-parse")
        .arg("HEAD")
        .output()
        .ok()?;
    if !output.status.success() {
        return None;
    }
    let sha = String::from_utf8_lossy(&output.stdout).trim().to_string();
    if sha.is_empty() { None } else { Some(sha) }
}

//! `memhub audit md` (Wave 2 C5, issue #32 / decisions Q25 + Q29): a
//! read-only linter over the repo's root memory files that turns
//! CLAUDE.md/AGENTS.md drift and bloat — today caught only by chance in
//! review — into detectable, reported findings.
//!
//! **Exit-code contract (deliberately unlike `doctor`):** default exit
//! is always `0`, findings are printed either way; `--strict` exits `1`
//! iff at least one finding fired, regardless of its severity. Unlike
//! `doctor`'s `Status` (`Ok`/`Warn`/`Error`/`Skipped`, where severity
//! itself gates the exit code), `Severity` here (`Warn`/`Error`) is
//! purely a display label — every entry in `findings` is already a
//! problem, so there is no `Ok`/`Skipped` case to report. This is a CLI
//! surface only — no MCP tool, no DB open, no DB writes; it reads
//! `CLAUDE.md` / `AGENTS.md` / (opt-in) a user-global orientation file
//! straight off disk.
//!
//! Reuses rather than reimplements: [`crate::agents_md::generate_agents_md`]
//! (issue #30) for the drift check, [`crate::managed_block::parse_managed_block`]
//! (issue #31) for the managed-block check, and the same
//! [`CLAUDE_KEYSTONE_PHRASES`] set `tests/skill_parity.rs` asserts against
//! (issue #30) — that test now imports this const rather than keeping its
//! own copy, so the two can never silently drift from each other.

use std::fs;
use std::path::Path;

use crate::Result;
use crate::agents_md::{CLAUDE_TITLE, generate_agents_md, split_trailing_managed_block};
use crate::commands::sync::expand_home;
use crate::config::ProjectConfig;
use crate::db;
use crate::managed_block::{self, parse_managed_block};
use crate::metrics::tokenizer::tokens_of;

const CLAUDE_MD_FILENAME: &str = "CLAUDE.md";
const AGENTS_MD_FILENAME: &str = "AGENTS.md";

/// Target token budget for `CLAUDE.md` (issue #30 / decision Q22).
pub const CLAUDE_MD_TARGET_TOKENS: usize = 2_500;
/// Hard ceiling before a size finding is `error` rather than `warn`
/// (issue #30 acceptance criteria: "CLAUDE.md <= 2,600 cl100k tokens").
pub const CLAUDE_MD_HARD_CEILING_TOKENS: usize = 2_600;

/// N4 keystone phrases (issue #30) that must survive the CLAUDE.md token
/// diet — each is a safety gate, an identity line, or a guardrail an
/// agent must see inline. This is the single source of truth: both this
/// audit's keystone check and `tests/skill_parity.rs`'s
/// `claude_md_keeps_keystone_phrases` import this same const, so the two
/// can never drift apart.
pub const CLAUDE_KEYSTONE_PHRASES: &[&str] = &[
    "stale_embeddings",
    "sync_adopt",
    "Agents are untrusted writers",
    "memhub-primary",
    "Local-first",
];

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Severity {
    Warn,
    Error,
}

impl Severity {
    pub fn as_str(&self) -> &'static str {
        match self {
            Severity::Warn => "warn",
            Severity::Error => "error",
        }
    }
}

#[derive(Debug, Clone)]
pub struct Finding {
    pub id: &'static str,
    pub severity: Severity,
    pub message: String,
    pub detail: Option<String>,
}

impl Finding {
    fn new(id: &'static str, severity: Severity, message: impl Into<String>) -> Self {
        Self {
            id,
            severity,
            message: message.into(),
            detail: None,
        }
    }

    fn with_detail(mut self, detail: impl Into<String>) -> Self {
        self.detail = Some(detail.into());
        self
    }
}

#[derive(Debug, Clone)]
pub struct AuditMdReport {
    pub findings: Vec<Finding>,
    pub exit_code: i32,
}

/// Run every check against the repo discovered from `start` (same
/// `.memhub`-upward walk every other subcommand uses) and build the
/// report. Read-only: at most a config-file read, never a DB open.
pub fn run(start: &Path, strict: bool) -> Result<AuditMdReport> {
    let paths = db::discover_paths(start)?;
    let config = ProjectConfig::load(&paths.config_path)
        .unwrap_or_else(|_| ProjectConfig::default_for_repo_name(repo_name(&paths.repo_root)));

    let mut findings = Vec::new();

    let claude_path = paths.repo_root.join(CLAUDE_MD_FILENAME);
    match fs::read_to_string(&claude_path) {
        Ok(claude_md) => {
            findings.extend(check_size("claude_md_size", CLAUDE_MD_FILENAME, &claude_md));
            findings.extend(check_agents_md_drift(&paths.repo_root, &claude_md));
            findings.extend(check_managed_block(&claude_md));
            findings.extend(check_keystones(&claude_md));
        }
        Err(e) => {
            findings.push(Finding::new(
                "claude_md_missing",
                Severity::Error,
                format!("cannot read {}: {e}", claude_path.display()),
            ));
        }
    }

    if !config.audit.user_md_path.trim().is_empty() {
        findings.extend(check_user_md(&config.audit.user_md_path));
    }

    Ok(build_report(findings, strict))
}

fn repo_name(repo_root: &Path) -> &str {
    repo_root
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or("memhub")
}

fn build_report(findings: Vec<Finding>, strict: bool) -> AuditMdReport {
    let exit_code = if strict && !findings.is_empty() { 1 } else { 0 };
    AuditMdReport {
        findings,
        exit_code,
    }
}

// ---------------------------------------------------------------------
// Size (target ~2,500 tokens, hard ceiling 2,600 — issue #30)
// ---------------------------------------------------------------------

/// Pure boundary classification, split out from [`check_size`] so the
/// target/ceiling edges can be unit-tested with exact integers instead
/// of a hand-crafted string whose real cl100k count is fragile to pin.
fn classify_size(tokens: usize, target: usize, ceiling: usize) -> Option<Severity> {
    if tokens > ceiling {
        Some(Severity::Error)
    } else if tokens > target {
        Some(Severity::Warn)
    } else {
        None
    }
}

fn check_size(id: &'static str, label: &str, content: &str) -> Option<Finding> {
    let tokens = tokens_of(content);
    let severity = classify_size(
        tokens,
        CLAUDE_MD_TARGET_TOKENS,
        CLAUDE_MD_HARD_CEILING_TOKENS,
    )?;
    let message = match severity {
        Severity::Error => format!(
            "{label} is {tokens} cl100k tokens — over the {CLAUDE_MD_HARD_CEILING_TOKENS} hard \
             ceiling (target ~{CLAUDE_MD_TARGET_TOKENS})"
        ),
        Severity::Warn => format!(
            "{label} is {tokens} cl100k tokens — over the ~{CLAUDE_MD_TARGET_TOKENS} target \
             (hard ceiling {CLAUDE_MD_HARD_CEILING_TOKENS})"
        ),
    };
    Some(Finding::new(id, severity, message))
}

// ---------------------------------------------------------------------
// AGENTS.md drift (issue #30's generate_agents_md)
// ---------------------------------------------------------------------

/// Mirrors the two preconditions `generate_agents_md` itself `assert!`s
/// on (first line == [`CLAUDE_TITLE`]; a `## ` section exists) without
/// duplicating the transform logic — just enough to call it safely.
/// `generate_agents_md` is frozen/reused as-is (issue #30), so a
/// malformed `CLAUDE.md` must be caught *before* calling it rather than
/// letting a read-only linter crash the CLI on a programmer-error-style
/// `assert!`.
///
/// Checks the *stripped* text — after a trailing Orch-managed block is
/// split off via [`split_trailing_managed_block`] — because that's what
/// `generate_agents_md` actually runs its `## ` search against (its own
/// step 0 does the same split). Checking the raw file here previously let
/// a `CLAUDE.md` whose only `## ` heading lived inside that managed block
/// pass this precondition and then panic inside `generate_agents_md`,
/// where the block (and its heading) had already been stripped off
/// (issue #148 / audit C3).
fn generate_agents_md_preconditions_met(claude_md: &str) -> bool {
    let (claude, _) = split_trailing_managed_block(claude_md);
    let Some((first_line, rest)) = claude.split_once('\n') else {
        return false;
    };
    first_line == CLAUDE_TITLE && (rest.starts_with("## ") || rest.contains("\n## "))
}

fn normalize_newlines(s: &str) -> String {
    s.replace("\r\n", "\n")
}

fn check_agents_md_drift(repo_root: &Path, claude_md: &str) -> Option<Finding> {
    if !generate_agents_md_preconditions_met(claude_md) {
        return Some(Finding::new(
            "claude_md_malformed",
            Severity::Error,
            format!(
                "{CLAUDE_MD_FILENAME} does not start with the `{CLAUDE_TITLE}` H1 title or has \
                 no `## ` section — cannot generate/verify {AGENTS_MD_FILENAME}"
            ),
        ));
    }

    let generated = generate_agents_md(claude_md);
    let agents_path = repo_root.join(AGENTS_MD_FILENAME);
    let agents_md = match fs::read_to_string(&agents_path) {
        Ok(s) => s,
        Err(_) => {
            return Some(Finding::new(
                "agents_md_drift",
                Severity::Error,
                format!(
                    "{AGENTS_MD_FILENAME} not found at {} — generate it with MEMHUB_REGEN=1 \
                     cargo test skill_parity",
                    agents_path.display()
                ),
            ));
        }
    };

    if normalize_newlines(&agents_md) == normalize_newlines(&generated) {
        None
    } else {
        Some(Finding::new(
            "agents_md_drift",
            Severity::Error,
            format!(
                "{AGENTS_MD_FILENAME} does not match generate_agents_md({CLAUDE_MD_FILENAME}) — \
                 regenerate with MEMHUB_REGEN=1 cargo test skill_parity and commit \
                 {AGENTS_MD_FILENAME}"
            ),
        ))
    }
}

// ---------------------------------------------------------------------
// Managed block (issue #31's parse_managed_block)
// ---------------------------------------------------------------------

fn check_managed_block(claude_md: &str) -> Option<Finding> {
    match parse_managed_block(claude_md) {
        None => Some(Finding::new(
            "managed_block_missing",
            Severity::Warn,
            format!("no memhub:managed-block found in {CLAUDE_MD_FILENAME}"),
        )),
        Some(block) if block.version < managed_block::MANAGED_BLOCK_VERSION => Some(Finding::new(
            "managed_block_version",
            Severity::Warn,
            format!(
                "managed block is v{} — this build expects v{}",
                block.version,
                managed_block::MANAGED_BLOCK_VERSION
            ),
        )),
        Some(_) => None,
    }
}

// ---------------------------------------------------------------------
// Keystone phrases (issue #30's N4 set)
// ---------------------------------------------------------------------

fn check_keystones(claude_md: &str) -> Option<Finding> {
    let missing: Vec<&str> = CLAUDE_KEYSTONE_PHRASES
        .iter()
        .filter(|phrase| !claude_md.contains(**phrase))
        .copied()
        .collect();
    if missing.is_empty() {
        None
    } else {
        Some(
            Finding::new(
                "keystone_phrases",
                Severity::Error,
                format!(
                    "{} keystone phrase(s) missing from {CLAUDE_MD_FILENAME}",
                    missing.len()
                ),
            )
            .with_detail(missing.join(", ")),
        )
    }
}

// ---------------------------------------------------------------------
// User-global orientation file (opt-in, decision Q25)
// ---------------------------------------------------------------------

fn check_user_md(configured_path: &str) -> Option<Finding> {
    let expanded = match expand_home(configured_path) {
        Ok(p) => p,
        Err(e) => {
            return Some(Finding::new(
                "user_md_unreadable",
                Severity::Warn,
                format!("[audit] user_md_path {configured_path:?} could not be resolved: {e}"),
            ));
        }
    };
    match fs::read_to_string(&expanded) {
        Ok(content) => check_size("user_md_size", &expanded.display().to_string(), &content),
        Err(e) => Some(Finding::new(
            "user_md_unreadable",
            Severity::Warn,
            format!(
                "[audit] user_md_path {} could not be read: {e}",
                expanded.display()
            ),
        )),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::tempdir;

    // -- classify_size / check_size ----------------------------------

    #[test]
    fn classify_size_boundaries() {
        assert_eq!(classify_size(0, 2_500, 2_600), None);
        assert_eq!(
            classify_size(2_500, 2_500, 2_600),
            None,
            "at target: not over"
        );
        assert_eq!(classify_size(2_501, 2_500, 2_600), Some(Severity::Warn));
        assert_eq!(
            classify_size(2_600, 2_500, 2_600),
            Some(Severity::Warn),
            "at ceiling: not over yet"
        );
        assert_eq!(classify_size(2_601, 2_500, 2_600), Some(Severity::Error));
    }

    #[test]
    fn check_size_none_for_short_content() {
        assert!(check_size("x", "label", "short content").is_none());
    }

    #[test]
    fn check_size_fires_and_reports_tokens_in_message() {
        // Comfortably over the 2,500-token target. Whether this exact
        // repeat count lands in the warn or error band depends on the
        // real tokenizer's tokens-per-word ratio and is not this test's
        // concern — `classify_size_boundaries` above already pins the
        // warn/error edges with exact integers. This just proves
        // `check_size` wires `tokens_of`'s real count into the message.
        let content = "word ".repeat(2_600);
        let finding = check_size("claude_md_size", "CLAUDE.md", &content).expect("finding");
        assert!(finding.message.contains("cl100k tokens"));
        assert!(finding.message.contains("CLAUDE.md"));
    }

    // -- generate_agents_md_preconditions_met / check_agents_md_drift --

    const VALID_CLAUDE_MD: &str = "# memhub\n\nIntro.\n\n## Session Continuity\n\nBody.\n";

    #[test]
    fn preconditions_met_for_well_formed_claude_md() {
        assert!(generate_agents_md_preconditions_met(VALID_CLAUDE_MD));
    }

    #[test]
    fn preconditions_fail_without_the_h1_title() {
        assert!(!generate_agents_md_preconditions_met(
            "# something else\n\n## Section\n"
        ));
