/// Outcome of a decision supersession — the demoted old decision and the one
/// it now points to, with titles for a friendly CLI echo.
#[derive(Debug)]
pub struct DecisionSupersedeOutcome {
    pub old_id: i64,
    pub old_title: String,
    pub new_id: i64,
    pub new_title: String,
}

/// Look up a decision by numeric id, returning its title. Decisions have no
/// natural key (unlike facts), so supersession resolves them by id alone.
fn resolve_decision(tx: &Transaction<'_>, id: i64) -> Result<Option<String>> {
    tx.query_row(
        "SELECT title FROM decisions WHERE project_id = 1 AND id = ?1",
        params![id],
        |r| r.get::<_, String>(0),
    )
    .optional()
    .map_err(Into::into)
}

/// Retire `old_id`'s decision by supersession (Wave 3 L3): set its status to
/// 'superseded' and link it to `new_id`. Demote-with-link, no-loss — the row
/// is NOT deleted; it stays present (annotated in render, penalized in
/// recall, and dropped from the active-decisions list). Q2 ruling: decisions
/// retire by supersession, not by age. Title/rationale/summary are unchanged,
/// so no re-embed or FTS/chunk resync is required. Errors if either id is
/// missing or if a decision would supersede itself.
pub fn supersede_in_tx(
    tx: &Transaction<'_>,
    old_id: i64,
    new_id: i64,
    actor: &str,
) -> Result<DecisionSupersedeOutcome> {
    let old_title = resolve_decision(tx, old_id)?
        .ok_or_else(|| crate::MemhubError::InvalidInput(format!("no decision with id {old_id}")))?;
    let new_title = resolve_decision(tx, new_id)?
        .ok_or_else(|| crate::MemhubError::InvalidInput(format!("no decision with id {new_id}")))?;
    if old_id == new_id {
        return Err(crate::MemhubError::InvalidInput(
            "a decision cannot supersede itself".to_string(),
        ));
    }

    tx.execute(
        "UPDATE decisions SET status = 'superseded', superseded_by = ?1
         WHERE project_id = 1 AND id = ?2",
        params![new_id, old_id],
    )?;

    db::log_write(
        tx,
        actor,
        "decisions",
        Some(old_id),
        "supersede",
        &format!("decision supersede {old_id} by {new_id}"),
    )?;

    Ok(DecisionSupersedeOutcome {
        old_id,
        old_title,
        new_id,
        new_title,
    })
}

/// CLI wrapper around [`supersede_in_tx`]: open the project and run the
/// supersession in one transaction.
pub fn supersede(
    start: &Path,
    old_id: i64,
    new_id: i64,
    actor: &str,
) -> Result<DecisionSupersedeOutcome> {
    let mut ctx = db::open_project(start)?;
    let tx = ctx.conn.transaction()?;
    let outcome = supersede_in_tx(&tx, old_id, new_id, actor)?;
    tx.commit()?;
    Ok(outcome)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::commands::init;
    use tempfile::tempdir;

    // Wave 3 L3 / Q2 — decisions retire by supersession, not age. The old
    // decision flips to status 'superseded', links to its replacement, and
    // stays present (demote-with-link) but drops out of the active list.
    #[test]
    fn supersede_sets_status_link_and_leaves_active_list() {
        let temp = tempdir().expect("tempdir");
        init::run(temp.path()).expect("init");
        let old_id = add(
            temp.path(),
            "Use JSON logs",
            "chosen for tooling",
            "user",
            "cli:user",
        )
        .expect("old");
        let new_id = add(
            temp.path(),
            "Use structured tracing",
            "replaces JSON logging",
            "user",
            "cli:user",
        )
        .expect("new");

        let outcome = supersede(temp.path(), old_id, new_id, "cli:user").expect("supersede");
        assert_eq!(outcome.old_id, old_id);
        assert_eq!(outcome.new_id, new_id);

        let all = list(temp.path()).expect("list");
        let old = all
            .iter()
            .find(|d| d.id == old_id)
            .expect("superseded decision must still be present (no-loss)");
        assert_eq!(old.status, "superseded");
        assert_eq!(old.superseded_by, Some(new_id));

        let active = list_active_recent(temp.path(), 10).expect("active");
        assert!(
            !active.iter().any(|d| d.id == old_id),
            "superseded decision must leave the active-recent list"
        );
        assert!(
            active.iter().any(|d| d.id == new_id),
            "the replacement stays active"
        );
    }

    #[test]
    fn supersede_rejects_self_and_missing_decision() {
        let temp = tempdir().expect("tempdir");
        init::run(temp.path()).expect("init");
        let id = add(temp.path(), "Only", "r", "user", "cli:user").expect("decision");

        assert!(matches!(
            supersede(temp.path(), id, id, "cli:user").expect_err("self must fail"),
            crate::MemhubError::InvalidInput(_)
        ));
        assert!(matches!(
            supersede(temp.path(), id, 9999, "cli:user").expect_err("missing must fail"),
            crate::MemhubError::InvalidInput(_)
        ));
        // Untouched by the failed ops.
        let d = list(temp.path()).expect("list");
        let row = d.iter().find(|d| d.id == id).unwrap();
        assert_eq!(row.status, "active");
        assert_eq!(row.superseded_by, None);
    }
}

//! `memhub doc` command surface: ingest external reference documents
//! into the per-repo store, RAG-searchable through the same hybrid
//! recall path as facts/decisions/tasks.
//!
//! Documents are deliberately OPT-IN to recall — `doc_chunk` is never in
//! the default source-type set. They are user-initiated reference
//! material (a design spec, an API contract), not durable project
//! knowledge and not an agent claim, so ingestion writes directly with
//! `source = 'user'` and no review gate.
//!
//! Trigger invariant: SQLite `recursive_triggers` is OFF (see
//! `db::open_project`), so a foreign-key cascade delete of `doc_chunks`
//! does NOT fire `doc_chunks_delete_embeddings` / `doc_chunks_fts_ad`.
//! Every code path that drops a document's chunks therefore deletes the
//! `doc_chunks` rows EXPLICITLY first (which fires those AFTER-DELETE
//! triggers) and only then touches the parent `documents` row. The
//! `ON DELETE CASCADE` FK stays as a row-integrity backstop.

use std::fs;
use std::path::Path;

use rusqlite::{Connection, OptionalExtension, Transaction, params};

use crate::Result;
use crate::db;
use crate::models::{DocChunk, Document};
use crate::retrieval::util::sha256_hex;

/// Largest chunk body (in chars) before a section is soft-split on
/// paragraph boundaries. Generous enough that well-structured docs chunk
/// at their natural section headings; the split only guards against a
/// pathologically long heading-free section.
const MAX_CHUNK_CHARS: usize = 2000;

#[derive(Debug, PartialEq, Eq)]
pub enum IngestStatus {
    Created,
    Updated,
    Unchanged,
}

#[derive(Debug)]
pub struct DocAddOutcome {
    pub doc_id: i64,
    pub title: String,
    pub path: String,
    pub chunk_count: usize,
    pub status: IngestStatus,
    /// True when this call flipped `[retrieval] include_docs_in_default`
    /// on for the repo (first successful doc add). The CLI surfaces a
    /// one-line notice so the behavior change is visible, not silent.
    pub enabled_default_recall: bool,
    /// True only for `add_global` when this call created
    /// `~/.memhub/global.sqlite` (first global write on the machine).
    /// Always false for the repo path.
    pub store_created: bool,
}

struct PreparedDoc {
    content: String,
    path_str: String,
    byte_len: i64,
    content_hash: String,
    resolved_title: String,
}

fn prepare_doc(file: &Path, title: Option<&str>) -> Result<PreparedDoc> {
    let content = fs::read_to_string(file).map_err(|e| {
        crate::MemhubError::InvalidInput(format!("cannot read {}: {e}", file.display()))
    })?;
    let canonical = fs::canonicalize(file).unwrap_or_else(|_| file.to_path_buf());
    let path_str = canonical.to_string_lossy().into_owned();
    let byte_len = content.len() as i64;
    let content_hash = sha256_hex(content.as_bytes());
    let resolved_title = title
        .map(str::to_string)
        .filter(|t| !t.trim().is_empty())
        .unwrap_or_else(|| derive_title(&content, &canonical));
    Ok(PreparedDoc {
        content,
        path_str,
        byte_len,
        content_hash,
        resolved_title,
    })
}

struct IngestResult {
    doc_id: i64,
    status: IngestStatus,
    chunk_count: usize,
    /// `documents` table was empty before this ingest. Connection-agnostic,
    /// so in the global DB this is the store's own emptiness (true once,
    /// for whichever repo happens to add the very first global doc on the
    /// machine), NOT "first global doc for this repo". `add` (repo-scoped)
    /// uses it as its config-flip trigger, since there the `documents`
    /// table it queries genuinely is scoped to the calling repo. `add_global`
    /// must NOT use it for that purpose — it gates its config flip on the
    /// calling repo's own config state instead (see
    /// `maybe_enable_global_default_doc_recall`).
    was_first_doc: bool,
}

/// Connection-agnostic ingest core. Operates entirely on `tx`, so the
/// caller chooses repo vs. global DB. Does NOT commit — the caller
/// commits and then applies its target-specific config flip / sync.
fn ingest_in_tx(
    tx: &Transaction<'_>,
    doc: &PreparedDoc,
    actor: &str,
    mode: crate::config::RetrievalMode,
) -> Result<IngestResult> {
    let was_first_doc: bool = tx.query_row(
        "SELECT COUNT(*) FROM documents WHERE project_id = 1",
        [],
        |r| r.get::<_, i64>(0),
    )? == 0;

    let existing: Option<(i64, String)> = tx
        .query_row(
            "SELECT id, content_hash FROM documents WHERE project_id = 1 AND path = ?1",
            params![doc.path_str],
            |r| Ok((r.get(0)?, r.get(1)?)),
        )
        .optional()?;

    let (doc_id, status) = match existing {
        Some((id, old_hash)) if old_hash == doc.content_hash => {
            let chunk_count: i64 = tx.query_row(
                "SELECT COUNT(*) FROM doc_chunks WHERE doc_id = ?1",
                params![id],
                |r| r.get(0),
            )?;
            return Ok(IngestResult {
                doc_id: id,
                status: IngestStatus::Unchanged,
                chunk_count: chunk_count.max(0) as usize,
                was_first_doc,
            });
        }
        Some((id, _)) => {
            // Explicit chunk delete first so the AFTER-DELETE triggers
            // clear embeddings + FTS (recursive_triggers is OFF).
            tx.execute("DELETE FROM doc_chunks WHERE doc_id = ?1", params![id])?;
            tx.execute(
                "UPDATE documents
                 SET title = ?1, content_hash = ?2, byte_len = ?3,
                     ingested_at = CURRENT_TIMESTAMP
                 WHERE id = ?4",
                params![doc.resolved_title, doc.content_hash, doc.byte_len, id],
            )?;
            (id, IngestStatus::Updated)
        }
        None => {
            tx.execute(
                "INSERT INTO documents(project_id, path, title, content_hash, byte_len, source)
                 VALUES (1, ?1, ?2, ?3, ?4, 'user')",
                params![
                    doc.path_str,
                    doc.resolved_title,
                    doc.content_hash,
                    doc.byte_len
                ],
            )?;
            (tx.last_insert_rowid(), IngestStatus::Created)
        }
    };

    let chunks = chunk_markdown(&doc.content);
    insert_chunks(tx, doc_id, &chunks, mode)?;

    db::log_write(
        tx,
        actor,
        "documents",
        Some(doc_id),
        if status == IngestStatus::Created {
            "insert"
        } else {
            "update"
        },
        &format!("doc add: {} ({} chunks)", doc.path_str, chunks.len()),
    )?;

    Ok(IngestResult {
        doc_id,
        status,
        chunk_count: chunks.len(),
        was_first_doc,
    })
}

/// Ingest (or re-ingest) a markdown file into this repo's store.
/// Unchanged content (same SHA-256) is a no-op. Changed content
/// replaces every chunk.
pub fn add(start: &Path, file: &Path, title: Option<&str>, actor: &str) -> Result<DocAddOutcome> {
    let doc = prepare_doc(file, title)?;

    let mut ctx = db::open_project(start)?;
    let mode = ctx.config.retrieval.mode;
    let tx = ctx.conn.transaction()?;
    let r = ingest_in_tx(&tx, &doc, actor, mode)?;
    tx.commit()?;

    let enabled_default_recall = r.was_first_doc && maybe_enable_default_doc_recall(&mut ctx)?;

    Ok(DocAddOutcome {
        doc_id: r.doc_id,
        title: doc.resolved_title,
        path: doc.path_str,
        chunk_count: r.chunk_count,
        status: r.status,
        enabled_default_recall,
        store_created: false,
    })
}

/// Ingest a markdown file into the machine-global store (M9). A
/// global doc is a broadly-applicable guide visible to every repo
/// that has opted in. Requires `memhub global enable` in this repo.
/// This repo's *first* global doc add flips `[global]
/// include_docs_in_default` in this repo's config (mirrors the
/// repo-scoped behavior) — gated on THIS REPO's own config state (see
/// `maybe_enable_global_default_doc_recall`), never on whether the
/// shared global store itself was empty. The global `documents` table
/// spans every repo on the machine that has opted in, so a second repo
/// adding to an already-populated global store must still flip its own
/// config on its own first add.
pub fn add_global(
    start: &Path,
    file: &Path,
    title: Option<&str>,
    actor: &str,
) -> Result<DocAddOutcome> {
    let doc = prepare_doc(file, title)?;

    let mut repo = db::open_project(start)?;
    crate::commands::global::ensure_enabled(&repo.config)?;
    let mode = repo.config.retrieval.mode;
    let store_created = !db::global_store_exists()?;

    let mut g = db::open_global()?;
    let tx = g.conn.transaction()?;
    let r = ingest_in_tx(&tx, &doc, actor, mode)?;
    tx.commit()?;

    let enabled_default_recall = maybe_enable_global_default_doc_recall(&mut repo)?;

    Ok(DocAddOutcome {
        doc_id: r.doc_id,
        title: doc.resolved_title,
        path: doc.path_str,
        chunk_count: r.chunk_count,
        status: r.status,
        enabled_default_recall,
        store_created,
    })
}

/// Flip `[retrieval] include_docs_in_default` on (decision 90). Only
/// called when `was_first_doc` held — i.e. the documents table was
/// empty before this ingest — so the user-pointed write that
/// establishes the very first doc also wires up retrieval, while a
/// later `false` set by the user is never silently re-flipped by a
/// re-add or a second doc. Returns whether it changed the config.
fn maybe_enable_default_doc_recall(ctx: &mut db::ProjectContext) -> Result<bool> {
    if ctx.config.retrieval.include_docs_in_default {
        return Ok(false);
    }
    ctx.config.retrieval.include_docs_in_default = true;
    ctx.config.save(&ctx.paths.config_path)?;
    Ok(true)
}

/// Flip `[global] include_docs_in_default` on for THIS repo (mirrors
/// `maybe_enable_default_doc_recall`, but for the `add_global` path).
///
/// Gated purely on this repo's own config state — not on
/// `was_first_doc`, which for the global store reflects whether the
/// shared `documents` table (spanning every opted-in repo on the
/// machine) was empty, not whether *this repo* has flipped its mirror
/// yet. Using `was_first_doc` here was the bug (issue #123): repo A's
/// first `doc add --global` flips A's config and consumes the store's
/// only "empty" moment, so repo B's own later first global add saw
/// `was_first_doc == false` and never flipped B's config — no notice,
/// and B's ingested global doc silently never joined B's default
/// recall. Checking this repo's own current flag instead is also a
/// no-op (no rewrite, no duplicate notice) when it is already enabled.
///
/// Cross-machine gap (untouched by this fix): `config.toml` is never
/// part of a Drive-sync snapshot (only the DB travels — see
/// "Cross-machine Drive sync" in docs/reference/operations.md), so a
/// machine that `sync adopt`s a snapshot containing global docs does
/// not gain this flag locally; run `doc add --global` (or set the flag
/// by hand) on each machine that should see them in default recall.
fn maybe_enable_global_default_doc_recall(repo: &mut db::ProjectContext) -> Result<bool> {
    if repo.config.global.include_docs_in_default {
        return Ok(false);
    }
    repo.config.global.include_docs_in_default = true;
    repo.config.save(&repo.paths.config_path)?;
    Ok(true)
}

fn insert_chunks(
    tx: &Transaction<'_>,
    doc_id: i64,
    chunks: &[(String, String)],
    mode: crate::config::RetrievalMode,
) -> Result<()> {
    // Insert every chunk row first, collecting (chunk_id, embed_text) pairs,
    // then hand the whole batch to eager_embed_batch_in_tx so the embedding
    // model runs once for the document instead of once per chunk (issue
    // #66) — same pattern as index::rebuild's per-source-type batching.
    let mut embed_rows: Vec<(i64, String)> = Vec::with_capacity(chunks.len());
    for (ord, (heading_path, body)) in chunks.iter().enumerate() {
        tx.execute(
            "INSERT INTO doc_chunks(project_id, doc_id, ord, heading_path, body)
             VALUES (1, ?1, ?2, ?3, ?4)",
            params![doc_id, ord as i64, heading_path, body],
        )?;
        let chunk_id = tx.last_insert_rowid();
        embed_rows.push((
            chunk_id,
            crate::retrieval::doc_chunk_embed_text(heading_path, body),
        ));
    }
    crate::retrieval::eager_embed_batch_in_tx(
        tx,
        mode,
        crate::retrieval::SourceType::DocChunk,
        embed_rows,
    )
}

fn list_in_conn(conn: &Connection) -> Result<Vec<Document>> {
    let mut stmt = conn.prepare(
        "SELECT d.id, d.path, d.title, d.content_hash, d.byte_len, d.source,
                d.ingested_at,
                (SELECT COUNT(*) FROM doc_chunks c WHERE c.doc_id = d.id) AS chunk_count
         FROM documents d
         ORDER BY d.ingested_at DESC, d.id DESC",
    )?;
    let rows = stmt.query_map([], |r| {
        Ok(Document {
            id: r.get(0)?,
            path: r.get(1)?,
            title: r.get(2)?,
            content_hash: r.get(3)?,
            byte_len: r.get(4)?,
            source: r.get(5)?,
            ingested_at: r.get(6)?,
            chunk_count: r.get(7)?,
        })
    })?;
    rows.collect::<std::result::Result<Vec<_>, _>>()
        .map_err(Into::into)
}

pub fn list(start: &Path) -> Result<Vec<Document>> {
    let ctx = db::open_project(start)?;
    list_in_conn(&ctx.conn)
}

/// List documents in the machine-global store (M9). Requires this repo
/// to have opted in (`memhub global enable`), mirroring the gate on
/// `doc add --global`. Returns empty when the store does not yet exist
/// — a read never creates it.
pub fn list_global(start: &Path) -> Result<Vec<Document>> {
    let repo = db::open_project(start)?;
    crate::commands::global::ensure_enabled(&repo.config)?;
    match db::open_global_if_exists()? {
        Some(g) => list_in_conn(&g.conn),
        None => Ok(Vec::new()),
    }
}

/// Resolve a document by numeric id or by exact/canonical path.
fn resolve_doc_id(tx: &Transaction<'_>, ident: &str) -> Result<Option<i64>> {
    if let Ok(id) = ident.parse::<i64>() {
        let found: Option<i64> = tx
            .query_row("SELECT id FROM documents WHERE id = ?1", params![id], |r| {
                r.get(0)
            })
            .optional()?;
        if found.is_some() {
            return Ok(found);
        }
    }
    let canonical = fs::canonicalize(ident)
        .map(|p| p.to_string_lossy().into_owned())
        .unwrap_or_else(|_| ident.to_string());
    let by_path: Option<i64> = tx
        .query_row(
            "SELECT id FROM documents WHERE path = ?1 OR path = ?2",
            params![ident, canonical],
            |r| r.get(0),
        )
        .optional()?;
    Ok(by_path)
}

/// Resolve + delete a document and its chunks/embeddings within `tx`.
/// Connection-agnostic so the caller picks repo vs. global DB. Returns
/// false (leaving `tx` to roll back) when nothing matched `ident`.
fn remove_in_tx(tx: &Transaction<'_>, ident: &str, actor: &str) -> Result<bool> {
    let Some(doc_id) = resolve_doc_id(tx, ident)? else {
        return Ok(false);
    };
    // Explicit chunk delete first (recursive_triggers OFF) so embeddings
    // + FTS are cleaned; then the parent row.
    tx.execute("DELETE FROM doc_chunks WHERE doc_id = ?1", params![doc_id])?;
    tx.execute("DELETE FROM documents WHERE id = ?1", params![doc_id])?;
    db::log_write(
        tx,
        actor,
        "documents",
        Some(doc_id),
        "delete",
        &format!("doc rm: {ident}"),
    )?;
    Ok(true)
}

/// Remove a document and all its chunks/embeddings. Returns false when
/// no document matched `ident`.
pub fn remove(start: &Path, ident: &str, actor: &str) -> Result<bool> {
    let mut ctx = db::open_project(start)?;
    let tx = ctx.conn.transaction()?;
    if !remove_in_tx(&tx, ident, actor)? {
        return Ok(false);
    }
    tx.commit()?;
    Ok(true)
}

/// Remove a document from the machine-global store (M9). Requires this
/// repo opted in, mirroring `doc add --global`. Returns false when the
/// store does not exist or nothing matched `ident`. No markdown sync —
/// the global store has no rendered view.
pub fn remove_global(start: &Path, ident: &str, actor: &str) -> Result<bool> {
    let repo = db::open_project(start)?;
    crate::commands::global::ensure_enabled(&repo.config)?;
    let Some(mut g) = db::open_global_if_exists()? else {
        return Ok(false);
    };
    let tx = g.conn.transaction()?;
    if !remove_in_tx(&tx, ident, actor)? {
        return Ok(false);
    }
    tx.commit()?;
    Ok(true)
}

fn show_in_conn(conn: &Connection, ident: &str) -> Result<Option<(Document, Vec<DocChunk>)>> {
    let docs = list_in_conn(conn)?;
    let parsed_id = ident.parse::<i64>().ok();
    let canonical = fs::canonicalize(ident)
        .map(|p| p.to_string_lossy().into_owned())
        .unwrap_or_else(|_| ident.to_string());
    let Some(doc) = docs
        .into_iter()
        .find(|d| parsed_id == Some(d.id) || d.path == ident || d.path == canonical)
    else {
        return Ok(None);
    };

    let mut stmt = conn.prepare(
        "SELECT id, doc_id, ord, heading_path, body, created_at
         FROM doc_chunks WHERE doc_id = ?1 ORDER BY ord",
    )?;
    let chunks = stmt
        .query_map(params![doc.id], |r| {
            Ok(DocChunk {
                id: r.get(0)?,
                doc_id: r.get(1)?,
                ord: r.get(2)?,
                heading_path: r.get(3)?,
                body: r.get(4)?,
                created_at: r.get(5)?,
            })
        })?
        .collect::<std::result::Result<Vec<_>, _>>()?;
    Ok(Some((doc, chunks)))
}

pub fn show(start: &Path, ident: &str) -> Result<Option<(Document, Vec<DocChunk>)>> {
    let ctx = db::open_project(start)?;
    show_in_conn(&ctx.conn, ident)
}

/// Show a document from the machine-global store (M9). Requires this
/// repo opted in, mirroring `doc add --global`. Returns None when the
/// store does not exist or nothing matched `ident`.
pub fn show_global(start: &Path, ident: &str) -> Result<Option<(Document, Vec<DocChunk>)>> {
    let repo = db::open_project(start)?;
    crate::commands::global::ensure_enabled(&repo.config)?;
    match db::open_global_if_exists()? {
        Some(g) => show_in_conn(&g.conn, ident),
        None => Ok(None),
    }
}

/// Count of ingested documents (for `status` / dashboards).
pub fn count(start: &Path) -> Result<i64> {
    let ctx = db::open_project(start)?;
    let n: i64 = ctx
        .conn
        .query_row("SELECT COUNT(*) FROM documents", [], |r| r.get(0))?;
    Ok(n)
}

fn derive_title(content: &str, path: &Path) -> String {
    for (heading_path, _) in chunk_markdown(content) {
        if !heading_path.trim().is_empty() {
            // First heading's leaf is the most document-like title.
            return heading_path
                .rsplit(" > ")
                .next()
                .unwrap_or(&heading_path)
                .to_string();
        }
    }
    path.file_name()
        .map(|n| n.to_string_lossy().into_owned())
        .unwrap_or_else(|| "untitled".to_string())
}

/// Split markdown into retrievable chunks.
///
/// One chunk per ATX heading section; the heading line is kept in the
/// body so the chunk is self-describing, and `heading_path` carries the
/// ancestor breadcrumb (e.g. `Components > Buttons`). Content before the
/// first heading (including YAML front matter) becomes a leading chunk
/// with an empty `heading_path`. Fenced code blocks (``` or ~~~) are
/// never split: a `#` inside a fence is body text, not a heading, and a
/// soft-split for over-long sections only breaks on blank lines outside
/// a fence.
///
/// Returns `(heading_path, body)` pairs in document order.
pub fn chunk_markdown(content: &str) -> Vec<(String, String)> {
    let mut sections: Vec<(String, Vec<String>)> = Vec::new();
    let mut stack: Vec<(usize, String)> = Vec::new();
    let mut current_path = String::new();
    let mut current_body: Vec<String> = Vec::new();
    let mut fence: Option<String> = None;

    let flush = |path: &str, body: &Vec<String>, out: &mut Vec<(String, Vec<String>)>| {
        if body.iter().any(|l| !l.trim().is_empty()) {
            out.push((path.to_string(), body.clone()));
        }
    };

    for line in content.lines() {
        let trimmed = line.trim_start();
        if let Some(open) = fence.clone() {
            current_body.push(line.to_string());
            if is_fence_token(trimmed, Some(&open)) {
                fence = None;
            }
            continue;
        }
        if is_fence_token(trimmed, None) {
            fence = Some(fence_marker(trimmed));
            current_body.push(line.to_string());
            continue;
        }
        if let Some((level, text)) = parse_heading(trimmed) {
            flush(&current_path, &current_body, &mut sections);
            current_body = vec![line.to_string()];
            while stack.last().is_some_and(|(l, _)| *l >= level) {
                stack.pop();
            }
            stack.push((level, text));
            current_path = stack
                .iter()
                .map(|(_, t)| t.as_str())
                .collect::<Vec<_>>()
                .join(" > ");
        } else {
            current_body.push(line.to_string());
        }
    }
    flush(&current_path, &current_body, &mut sections);

    let mut out = Vec::new();
    for (path, body_lines) in sections {
        let body = body_lines.join("\n");
        let trimmed_body = body.trim();
        if trimmed_body.is_empty() {
            continue;
        }
        if body.chars().count() <= MAX_CHUNK_CHARS {
            out.push((path, trimmed_body.to_string()));
        } else {
            for piece in soft_split(&body) {
                out.push((path.clone(), piece));
            }
        }
    }
    out
}

/// Greedily pack paragraphs (blank-line separated, never breaking inside
/// a fence) into pieces of at most `MAX_CHUNK_CHARS`.
fn soft_split(body: &str) -> Vec<String> {
    let mut blocks: Vec<String> = Vec::new();
    let mut cur: Vec<String> = Vec::new();
    let mut fence: Option<String> = None;
    for line in body.lines() {
        let trimmed = line.trim_start();
        if let Some(open) = fence.clone() {
            cur.push(line.to_string());
            if is_fence_token(trimmed, Some(&open)) {
                fence = None;
            }
            continue;
        }
        if is_fence_token(trimmed, None) {
            fence = Some(fence_marker(trimmed));
            cur.push(line.to_string());
            continue;
        }
        if line.trim().is_empty() {
            if !cur.is_empty() {
                blocks.push(std::mem::take(&mut cur).join("\n"));
            }
        } else {
            cur.push(line.to_string());
        }
    }
    if !cur.is_empty() {
        blocks.push(cur.join("\n"));
    }

    let mut pieces: Vec<String> = Vec::new();
    let mut acc = String::new();
    for block in blocks {
        let candidate_len = acc.chars().count() + block.chars().count() + 2;
        if !acc.is_empty() && candidate_len > MAX_CHUNK_CHARS {
            pieces.push(std::mem::take(&mut acc));
        }
        if !acc.is_empty() {
            acc.push_str("\n\n");
        }
        acc.push_str(&block);
    }
    if !acc.trim().is_empty() {
        pieces.push(acc);
    }
    pieces
}

fn parse_heading(trimmed: &str) -> Option<(usize, String)> {
    if !trimmed.starts_with('#') {
        return None;
    }
    let level = trimmed.chars().take_while(|c| *c == '#').count();
    if level == 0 || level > 6 {
        return None;
    }
    let rest = &trimmed[level..];
    // ATX requires a space after the hashes ("#foo" is not a heading).
    if !rest.starts_with(char::is_whitespace) {
        return None;
    }
    let text = rest.trim().trim_end_matches('#').trim();
    if text.is_empty() {
        return None;
    }
    Some((level, text.to_string()))
}

/// A fence token is 3+ backticks or 3+ tildes at the start of a
/// (trimmed) line. When `open` is set, only the matching marker family
/// closes the fence.
fn is_fence_token(trimmed: &str, open: Option<&str>) -> bool {
    let matches = |ch: char| trimmed.chars().take_while(|c| *c == ch).count() >= 3;
    match open {
        Some(marker) => {
            let ch = marker.chars().next().unwrap_or('`');
            matches(ch)
        }
        None => matches('`') || matches('~'),
    }
}

fn fence_marker(trimmed: &str) -> String {
    if trimmed.starts_with('~') {
        "~~~"
    } else {
        "```"
    }
    .to_string()
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::commands::init;
    use tempfile::tempdir;

    #[test]
    fn chunker_splits_on_headings_with_breadcrumb() {
        let md =
            "# Top\n\nintro\n\n## Alpha\n\nbody a\n\n### Nested\n\ndeep\n\n## Beta\n\nbody b\n";
        let chunks = chunk_markdown(md);
        let paths: Vec<&str> = chunks.iter().map(|(p, _)| p.as_str()).collect();
        assert_eq!(
            paths,
            vec!["Top", "Top > Alpha", "Top > Alpha > Nested", "Top > Beta"]
        );
        assert!(chunks[1].1.contains("body a"));
    }

    #[test]
    fn chunker_does_not_split_inside_fences() {
        let md = "## Code\n\n```yaml\n# this is not a heading\nkey: value\n```\n\nafter\n";
        let chunks = chunk_markdown(md);
        assert_eq!(chunks.len(), 1, "fenced # must not start a new chunk");
        assert!(chunks[0].1.contains("# this is not a heading"));
        assert!(chunks[0].1.contains("after"));
    }

    #[test]
    fn chunker_keeps_preamble_as_leading_chunk() {
        let md = "---\nname: spec\n---\n\nlead prose\n\n# First\n\nbody\n";
        let chunks = chunk_markdown(md);
        assert_eq!(chunks[0].0, "", "preamble has empty heading_path");
        assert!(chunks[0].1.contains("name: spec"));
        assert_eq!(chunks[1].0, "First");
    }

    #[test]
    fn add_then_show_roundtrips_and_reingest_is_noop() {
        let temp = tempdir().expect("tempdir");
        init::run(temp.path()).expect("init");
        let doc = temp.path().join("spec.md");
        fs::write(&doc, "# Title\n\n## A\n\nalpha\n\n## B\n\nbeta\n").expect("write");

        let first = add(temp.path(), &doc, None, "cli:user").expect("add");
        assert_eq!(first.status, IngestStatus::Created);
        assert!(first.chunk_count >= 3);

        let again = add(temp.path(), &doc, None, "cli:user").expect("re-add");
        assert_eq!(again.status, IngestStatus::Unchanged);
        assert_eq!(again.doc_id, first.doc_id);

        fs::write(&doc, "# Title\n\n## A\n\nalpha edited\n").expect("rewrite");
        let updated = add(temp.path(), &doc, None, "cli:user").expect("update");
        assert_eq!(updated.status, IngestStatus::Updated);

        let (meta, chunks) = show(temp.path(), &first.doc_id.to_string())
            .expect("show")
            .expect("present");
        assert_eq!(meta.id, first.doc_id);
        assert!(chunks.iter().any(|c| c.body.contains("alpha edited")));
        assert!(
            !chunks.iter().any(|c| c.body.contains("beta")),
            "stale chunk from prior ingest must be gone"
        );
    }

    #[test]
    fn hybrid_reingest_and_remove_leave_no_orphan_embeddings() {
        // The load-bearing invariant: recursive_triggers is OFF, so a
        // doc's chunks (and their embeddings + FTS rows) only get
        // cleaned because the writer deletes doc_chunks EXPLICITLY
        // before the parent. This must hold in hybrid mode, where
        // eager_embed_in_tx actually writes embedding rows. FTS-mode
        // tests can't catch a regression here.
        let temp = tempdir().expect("tempdir");
        init::run(temp.path()).expect("init");
        let cfg_path = temp.path().join(".memhub/config.toml");
        let mut cfg = crate::config::ProjectConfig::load(&cfg_path).expect("load cfg");
        cfg.retrieval.mode = crate::config::RetrievalMode::Hybrid;
        cfg.save(&cfg_path).expect("save cfg");

        let counts = |label: &str| -> (i64, i64) {
            let ctx = db::open_project(temp.path()).expect("open");
            let chunks: i64 = ctx
                .conn
                .query_row("SELECT COUNT(*) FROM doc_chunks", [], |r| r.get(0))
                .expect(label);
            let embs: i64 = ctx
                .conn
                .query_row(
                    "SELECT COUNT(*) FROM embeddings WHERE source_type = 'doc_chunk'",
                    [],
                    |r| r.get(0),
                )
                .expect(label);
            (chunks, embs)
        };

        let doc = temp.path().join("spec.md");
        fs::write(
            &doc,
            "# Spec\n\n## A\n\nalpha\n\n## B\n\nbeta\n\n## C\n\ngamma\n",
        )
        .expect("write");
        let first = add(temp.path(), &doc, None, "cli:user").expect("add");
        let (c1, e1) = counts("after add");
        assert!(c1 >= 3);
        assert_eq!(c1, e1, "every chunk must have exactly one embedding");
        assert_eq!(e1 as usize, first.chunk_count);

        // Edit + re-ingest: stale chunks AND their embeddings must go.
        fs::write(&doc, "# Spec\n\n## A\n\nalpha edited\n").expect("rewrite");
        let updated = add(temp.path(), &doc, None, "cli:user").expect("re-add");
        assert_eq!(updated.status, IngestStatus::Updated);
        let (c2, e2) = counts("after re-add");
        assert_eq!(c2, e2, "no orphan embeddings after re-ingest");
        assert_eq!(e2 as usize, updated.chunk_count);
        assert!(c2 < c1, "shrunk doc has fewer chunks");

        // Remove: everything for the doc is gone.
        assert!(remove(temp.path(), &first.doc_id.to_string(), "cli:user").expect("rm"));
        let (c3, e3) = counts("after rm");
        assert_eq!((c3, e3), (0, 0), "remove clears chunks and embeddings");
    }

    #[test]
    fn remove_clears_document_and_chunks() {
        let temp = tempdir().expect("tempdir");
        init::run(temp.path()).expect("init");
        let doc = temp.path().join("d.md");
        fs::write(&doc, "# T\n\n## S\n\nbody\n").expect("write");
        let added = add(temp.path(), &doc, None, "cli:user").expect("add");

        assert!(remove(temp.path(), &added.doc_id.to_string(), "cli:user").expect("rm"));
        assert!(list(temp.path()).expect("list").is_empty());
        assert!(
            !remove(temp.path(), &added.doc_id.to_string(), "cli:user").expect("rm again"),
            "second remove finds nothing"
        );
    }

    #[test]
    fn batched_chunk_embeddings_match_solo_embed_and_stay_in_order() {
        // Issue #66: insert_chunks now embeds every chunk of a document in
        // one embed_batch call instead of one embed_one call per chunk.
        // hybrid_reingest_and_remove_leave_no_orphan_embeddings already
        // proves the *count* of embeddings matches the chunk count; this
        // test proves the *values* are unchanged and correctly associated
        // per chunk (not swapped/shuffled by the batch pass), by comparing
        // each stored vector against an independent solo embed_one() of
        // that same chunk's text.
        let temp = tempdir().expect("tempdir");
        init::run(temp.path()).expect("init");
        let cfg_path = temp.path().join(".memhub/config.toml");
        let mut cfg = crate::config::ProjectConfig::load(&cfg_path).expect("load cfg");
        cfg.retrieval.mode = crate::config::RetrievalMode::Hybrid;
        cfg.save(&cfg_path).expect("save cfg");

        let doc = temp.path().join("spec.md");
        fs::write(
            &doc,
            "# Spec\n\n## Alpha\n\nfirst distinct chunk body\n\n\
             ## Beta\n\nsecond distinct chunk body\n\n\
             ## Gamma\n\nthird distinct chunk body\n",
        )
        .expect("write");
        let added = add(temp.path(), &doc, None, "cli:user").expect("add");
        assert!(added.chunk_count >= 3);

        let ctx = db::open_project(temp.path()).expect("open");
        let mut stmt = ctx
            .conn
            .prepare(
                "SELECT id, heading_path, body FROM doc_chunks
                 WHERE doc_id = ?1 ORDER BY ord",
            )
            .expect("prepare");
        let chunks: Vec<(i64, String, String)> = stmt
            .query_map(params![added.doc_id], |r| {
                Ok((r.get(0)?, r.get(1)?, r.get(2)?))
            })
            .expect("query")
            .collect::<std::result::Result<Vec<_>, _>>()
            .expect("collect");
        assert!(chunks.len() >= 3);

        for (chunk_id, heading_path, body) in &chunks {
            let blob: Vec<u8> = ctx
                .conn
                .query_row(
                    "SELECT vector FROM embeddings
                     WHERE source_type = 'doc_chunk' AND source_id = ?1",
                    params![chunk_id],
                    |r| r.get(0),
                )
                .expect("stored embedding");
            let stored: Vec<f32> = blob
                .chunks_exact(4)
                .map(|b| f32::from_le_bytes([b[0], b[1], b[2], b[3]]))
                .collect();

            let expected = crate::retrieval::embed_one(&crate::retrieval::doc_chunk_embed_text(
                heading_path,
                body,
            ))
            .expect("solo embed");

            assert_eq!(stored.len(), expected.len());
            let max_delta = stored
                .iter()
                .zip(&expected)
                .map(|(a, b)| (a - b).abs())
                .fold(0.0_f32, f32::max);
            assert!(
                max_delta < 1e-3,
                "batched embedding for chunk {chunk_id} ({heading_path}) diverged \
                 from solo embed (max delta {max_delta})"
            );
        }
    }
}

//! `memhub doctor` (Wave 1·A, issue #21): one read-only health command
//! that turns memhub's comment-enforced invariants and scattered health
//! signals into detectable, reported states. Absorbs `/check-init`,
//! adds config validation, the D1 integrity surface, the X4 metrics
//! health line, and probes P1 (per-CLI MCP registration) and P4 (sync
//! freshness).
//!
//! **Contract frozen by the main thread — do not redesign:** exit `0`
//! unless an `error`-level check fires (`1` otherwise); `--strict`
//! additionally fails on any `warn`. CLI-only, no MCP tool. Read-only —
//! checks are `SELECT`/`PRAGMA`, except the FTS5 integrity check, which
//! runs the special `INSERT INTO {fts}({fts}) VALUES('integrity-check')`
//! command; that is FTS5's consistency-scan syntax, not a row write —
//! nothing here persists new data.
//!
//! Each check is a reusable, side-effect-free function returning a
//! [`Check`] (plain data, no printing) so `commands::status`'s own
//! refresh (a separate issue) can reuse a subset without pulling in any
//! rendering. Rendering (human text / `--json`) lives in
//! `src/cli/output.rs`.

use std::fs;
use std::path::{Path, PathBuf};

use rusqlite::{Connection, params};

use crate::Result;
use crate::commands::{index, sync};
use crate::config::{ProjectConfig, RetrievalMode};
use crate::db;

/// Ordered worst-to-best so `overall` is `checks.iter().map(|c|
/// c.status).max()`. Declaration order is the derive order:
/// `Skipped < Ok < Warn < Error`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum Status {
    Skipped,
    Ok,
    Warn,
    Error,
}

impl Status {
    pub fn as_str(&self) -> &'static str {
        match self {
            Status::Skipped => "skipped",
            Status::Ok => "ok",
            Status::Warn => "warn",
            Status::Error => "error",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Group {
    Project,
    Config,
    Integrity,
    RetrievalMetrics,
    Integrations,
}

impl Group {
    pub fn as_str(&self) -> &'static str {
        match self {
            Group::Project => "project",
            Group::Config => "config",
            Group::Integrity => "integrity",
            Group::RetrievalMetrics => "retrieval_metrics",
            Group::Integrations => "integrations",
        }
    }
}

#[derive(Debug, Clone)]
pub struct Check {
    pub id: &'static str,
    pub group: Group,
    pub status: Status,
    pub message: String,
    pub detail: Option<String>,
}

impl Check {
    fn new(id: &'static str, group: Group, status: Status, message: impl Into<String>) -> Self {
        Self {
            id,
            group,
            status,
            message: message.into(),
            detail: None,
        }
    }

    fn with_detail(mut self, detail: impl Into<String>) -> Self {
        self.detail = Some(detail.into());
        self
    }
}

#[derive(Debug, Clone, Default)]
pub struct DoctorCounts {
    pub ok: usize,
    pub warn: usize,
    pub error: usize,
    pub skipped: usize,
}

#[derive(Debug, Clone)]
pub struct DoctorReport {
    pub project: String,
    pub overall: Status,
    pub exit_code: i32,
    pub counts: DoctorCounts,
    pub checks: Vec<Check>,
}

pub fn run(start: &Path, strict: bool) -> Result<DoctorReport> {
    run_with_home(start, strict, db::home_dir().ok())
}

/// Core orchestration. `home` is injected (rather than resolved inline)
/// so the P1 MCP-registration checks are hermetically testable — they
/// must never depend on the ambient state of the machine running
/// `cargo test`.
fn run_with_home(start: &Path, strict: bool, home: Option<PathBuf>) -> Result<DoctorReport> {
    let ctx = db::open_project(start)?;
    // Project (absorbs /check-init).
    let mut checks = vec![
        check_schema(&ctx.conn),
        check_render_freshness(&ctx.conn, &ctx.paths.repo_root, &ctx.config),
        check_writes_log_recency(&ctx.conn),
    ];

    // Config.
    checks.extend(check_config(&ctx.paths.config_path, &ctx.paths.memhub_dir));

    // Integrity (D1).
    checks.extend(check_integrity(&ctx.conn));

    // Retrieval / Metrics (X4).
    checks.push(check_retrieval_mode(&ctx.config));
    checks.push(check_embeddings_freshness(start, &ctx.config));
    checks.push(check_metrics_health(&ctx.conn, &ctx.config));

    // Integrations (P1 report-only, P4).
    checks.push(check_mcp_claude(&ctx.paths.repo_root, home.as_deref()));
    checks.push(check_mcp_codex(home.as_deref()));
    checks.push(check_mcp_opencode(&ctx.paths.repo_root, home.as_deref()));
    checks.push(check_sync_freshness(start, &ctx.config));

    Ok(build_report(&ctx.config.project_name, checks, strict))
}

fn build_report(project_name: &str, checks: Vec<Check>, strict: bool) -> DoctorReport {
    let mut counts = DoctorCounts::default();
    for c in &checks {
        match c.status {
            Status::Ok => counts.ok += 1,
            Status::Warn => counts.warn += 1,
            Status::Error => counts.error += 1,
            Status::Skipped => counts.skipped += 1,
        }
    }

    let overall = checks
        .iter()
        .map(|c| c.status)
        .filter(|s| *s != Status::Skipped)
        .max()
        .unwrap_or(Status::Ok);

    let exit_code = if counts.error > 0 || (strict && counts.warn > 0) {
        1
    } else {
        0
    };

    DoctorReport {
        project: project_name.to_string(),
        overall,
        exit_code,
        counts,
        checks,
    }
}

// ---------------------------------------------------------------------
// Project group
// ---------------------------------------------------------------------

// Visibility note (issue #22, Wave 1·C): the functions below are
// `pub(crate)` rather than private specifically so `commands::status`
// can call them directly instead of duplicating their logic. Only the
// signature/visibility line changes — bodies are untouched so this
// stays a clean merge alongside any later change to a check's
// internals (e.g. `check_sync_freshness`).
pub(crate) fn check_schema(conn: &Connection) -> Check {
    let applied: String = conn
        .query_row(
            "SELECT schema_version FROM projects WHERE id = 1",
            [],
            |r| r.get(0),
        )
        .unwrap_or_default();
    let head = db::latest_schema_version();

    if applied == head {
        Check::new(
            "schema",
            Group::Project,
            Status::Ok,
            format!("at head ({head})"),
        )
    } else {
        // Not reachable through `db::open_project` today (it migrates
        // forward on every connect, or refuses outright if the DB is
        // newer than this binary) — kept as a defensive, cheap
        // confirmation rather than removed, since `status`'s refresh
        // (a separate issue) reuses this same function.
        Check::new(
            "schema",
            Group::Project,
            Status::Error,
            format!("schema {applied} is behind head {head} — run `memhub upgrade`"),
        )
    }
}

const RENDER_TABLE_NAME: &str = "render";
const PROJECT_MD_FILENAME: &str = "PROJECT.md";

pub(crate) fn check_render_freshness(
    conn: &Connection,
    repo_root: &Path,
    config: &ProjectConfig,
) -> Check {
    let output_dir = repo_root.join(&config.render.output_dir);
    let exists = output_dir.join(PROJECT_MD_FILENAME).is_file();

    // Ordered by `id`, not `at`: `writes_log.at` is `CURRENT_TIMESTAMP`
    // (one-second resolution), so a write logged in the same wall-clock
    // second as the render marker would be indistinguishable from it —
    // or worse, invisible to a `>` comparison — under a timestamp
    // comparison. `id` is a strictly monotonic autoincrement, so it
    // orders correctly regardless of timing.
    let last_render_id: Option<i64> = conn
        .query_row(
            "SELECT MAX(id) FROM writes_log WHERE table_name = ?1",
            params![RENDER_TABLE_NAME],
            |r| r.get(0),
        )
        .unwrap_or(None);

    let writes_since: i64 = match last_render_id {
        Some(id) => conn
            .query_row(
                "SELECT COUNT(*) FROM writes_log WHERE id > ?1 AND table_name != ?2",
                params![id, RENDER_TABLE_NAME],
                |r| r.get(0),
            )
            .unwrap_or(0),
        None => conn
            .query_row(
                "SELECT COUNT(*) FROM writes_log WHERE table_name != ?1",
                params![RENDER_TABLE_NAME],
                |r| r.get(0),
            )
            .unwrap_or(0),
    };

    match (exists, last_render_id.is_some(), writes_since) {
        (true, true, 0) => Check::new(
            "render_freshness",
            Group::Project,
            Status::Ok,
            "rendered output is current",
        ),
        (true, true, n) => Check::new(
            "render_freshness",
            Group::Project,
            Status::Warn,
            format!("{n} durable write(s) since last render — run `memhub render`"),
        ),
        (_, false, _) => Check::new(
            "render_freshness",
            Group::Project,
            Status::Warn,
            "never rendered — run `memhub render`",
        ),
        (false, true, n) => Check::new(
            "render_freshness",
            Group::Project,
            Status::Warn,
            format!(
                "{PROJECT_MD_FILENAME} missing despite a recorded render \
                 ({n} write(s) since) — run `memhub render`"
            ),
        ),
    }
}

fn check_writes_log_recency(conn: &Connection) -> Check {
    let total: i64 = conn
        .query_row("SELECT COUNT(*) FROM writes_log", [], |r| r.get(0))
        .unwrap_or(0);
    if total == 0 {
        return Check::new(
            "writes_log_recency",
            Group::Project,
            Status::Ok,
            "no writes recorded yet",
        );
    }

    let last_at: Option<String> = conn
        .query_row("SELECT MAX(at) FROM writes_log", [], |r| r.get(0))
        .unwrap_or(None);
    match last_at {
        Some(ts) => Check::new(
            "writes_log_recency",
            Group::Project,
            Status::Ok,
            format!("{total} write(s) logged; last write at {ts}"),
        ),
        None => Check::new(
            "writes_log_recency",
            Group::Project,
            Status::Ok,
            format!("{total} write(s) logged"),
        ),
    }
}

