                    Some("embed_one"),
                    0.4,
                    None,
                ),
                locate_hit(
                    2,
                    "src/code_index/locate.rs",
                    Some("cosine_similarity"),
                    0.38,
                    None,
                ),
            ],
        );
        let outcome = evaluate_locate_query(&q, &resp, 3, false, None);
        assert!(outcome.passed, "{:?}", outcome.failure_reason);
        assert_eq!(outcome.matched_rank, Some(2));
        assert!(!outcome.passed_at_1);
    }

    #[test]
    fn locate_match_fails_when_path_outside_top_k() {
        let q = match_query("x", &["src/code_index/locate.rs"], None);
        let resp = fake_locate_response(
            "q",
            vec![
                locate_hit(1, "AGENTS.md", None, 0.4, None),
                locate_hit(2, "docs/reference/spec.md", None, 0.39, None),
                locate_hit(3, "src/mcp/mod.rs", Some("locate"), 0.38, None),
            ],
        );
        let outcome = evaluate_locate_query(&q, &resp, 3, false, None);
        assert!(!outcome.passed);
        assert!(outcome.failure_reason.unwrap().contains("no top-3"));
    }

    #[test]
    fn locate_symbol_contains_gates_the_match() {
        // Right file, wrong symbol → no match.
        let q = match_query("x", &["src/code_index/locate.rs"], Some("cosine"));
        let resp = fake_locate_response(
            "q",
            vec![locate_hit(
                1,
                "src/code_index/locate.rs",
                Some("read_snippet"),
                0.4,
                None,
            )],
        );
        let outcome = evaluate_locate_query(&q, &resp, 3, false, None);
        assert!(!outcome.passed);
    }

    #[test]
    fn locate_passed_at_1_when_first_hit_matches() {
        let q = match_query("x", &["src/code_index/mod.rs"], Some("refresh"));
        let resp = fake_locate_response(
            "q",
            vec![locate_hit(
                1,
                "src/code_index/mod.rs",
                Some("refresh"),
                0.8,
                None,
            )],
        );
        let outcome = evaluate_locate_query(&q, &resp, 3, false, None);
        assert!(outcome.passed);
        assert!(outcome.passed_at_1);
        assert_eq!(outcome.matched_rank, Some(1));
    }

    #[test]
    fn locate_floor_drops_hits_below_threshold_when_reranking() {
        let q = match_query("x", &["src/code_index/locate.rs"], None);
        // The matching hit is rank 1 but its logit is below the floor, so it
        // is filtered out and the query fails.
        let resp = fake_locate_response(
            "q",
            vec![
                locate_hit(
                    1,
                    "src/code_index/locate.rs",
                    Some("cosine"),
                    0.4,
                    Some(-3.0),
                ),
                locate_hit(2, "src/other.rs", None, 0.3, Some(-4.0)),
            ],
        );
        let outcome = evaluate_locate_query(&q, &resp, 3, true, Some(0.0));
        assert!(!outcome.passed);
        assert_eq!(outcome.returned_count, 0);
    }

    #[test]
    fn locate_floor_ignored_when_reranker_off() {
        let q = match_query("x", &["src/code_index/locate.rs"], None);
        let resp = fake_locate_response(
            "q",
            vec![locate_hit(1, "src/code_index/locate.rs", None, 0.4, None)],
        );
        // Floor given, but reranker off → floor is a no-op, hit survives.
        let outcome = evaluate_locate_query(&q, &resp, 3, false, Some(99.0));
        assert!(outcome.passed);
        assert_eq!(outcome.returned_count, 1);
    }

    #[test]
    fn locate_empty_passes_only_when_floor_clears_all_hits() {
        let q = LocateGoldenQuery {
            id: "neg".into(),
            query: "zxqv".into(),
            kind: GoldenKind::Empty,
            path_contains: vec![],
            symbol_contains: None,
            notes: String::new(),
        };
        let resp = fake_locate_response(
            "zxqv",
            vec![locate_hit(1, "Cargo.lock", None, 0.2, Some(-6.0))],
        );
        // Without a floor the nonsense hit leaks → fail.
        let leaked = evaluate_locate_query(&q, &resp, 3, true, None);
        assert!(!leaked.passed);
        // With a floor above the logit the bundle clears → pass.
        let cleared = evaluate_locate_query(&q, &resp, 3, true, Some(0.0));
        assert!(cleared.passed);
        assert_eq!(cleared.returned_count, 0);
    }

    #[test]
    fn load_locate_golden_rejects_match_without_matchers() {
        use std::io::Write;
        let dir = tempfile::tempdir().expect("tempdir");
        let path = dir.path().join("code_golden.json");
        let mut f = std::fs::File::create(&path).expect("create");
        writeln!(
            f,
            r#"{{ "version": 1, "queries": [ {{ "id": "x", "query": "q", "kind": "match" }} ] }}"#
        )
        .expect("write");
        let err = load_locate_golden(&path).expect_err("no matchers");
        assert!(matches!(err, MemhubError::InvalidInput(_)));
    }

    #[test]
    fn summarize_locate_computes_recall_at_1_and_k() {
        let outcomes = vec![
            // passes at 1 and k
            LocateQueryOutcome {
                id: "a".into(),
                query: "q".into(),
                kind: GoldenKind::Match,
                passed: true,
                passed_at_1: true,
                matched_rank: Some(1),
                matched_score: Some(0.9),
                matched_rerank: None,
                returned_count: 3,
                failure_reason: None,
            },
            // passes at k only (rank 3)
            LocateQueryOutcome {
                id: "b".into(),
                query: "q".into(),
                kind: GoldenKind::Match,
                passed: true,
                passed_at_1: false,
                matched_rank: Some(3),
                matched_score: Some(0.5),
                matched_rerank: None,
                returned_count: 3,
                failure_reason: None,
            },
            // empty probe that leaked
            LocateQueryOutcome {
                id: "n".into(),
                query: "q".into(),
                kind: GoldenKind::Empty,
                passed: false,
                passed_at_1: false,
                matched_rank: None,
                matched_score: None,
                matched_rerank: None,
                returned_count: 2,
                failure_reason: Some("leaked".into()),
            },
        ];
        let golden = LocateGoldenFile {
            version: 1,
            description: String::new(),
            queries: vec![
                match_query("a", &["x"], None),
                match_query("b", &["x"], None),
                LocateGoldenQuery {
                    id: "n".into(),
                    query: "q".into(),
                    kind: GoldenKind::Empty,
                    path_contains: vec![],
                    symbol_contains: None,
                    notes: String::new(),
                },
            ],
        };
        let opts = LocateEvalOptions {
            golden_path: PathBuf::from("code.json"),
            k: 3,
            use_reranker: false,
            min_rerank_score: None,
        };
        let summary = summarize_locate(
            &golden,
            RetrievalMode::Hybrid,
            opts,
            outcomes,
            Instant::now(),
        );
        assert_eq!(summary.match_queries, 2);
        assert_eq!(summary.match_passes_at_1, 1);
        assert_eq!(summary.match_passes_at_k, 2);
        assert_eq!(summary.safety_failures, 1);
        assert!((summary.recall_at_1 - 0.5).abs() < 1e-9);
        assert!((summary.recall_at_k - 1.0).abs() < 1e-9);
    }
}

use std::fs;
use std::path::{Path, PathBuf};

use rusqlite::Connection;

use crate::Result;
use crate::db;
use crate::export::{EXPORT_VERSION, Export, v1};
use crate::render::temp_path_for;

pub struct ExportSummary {
    pub destination: PathBuf,
    pub facts: usize,
    pub decisions: usize,
    pub tasks: usize,
    pub commands: usize,
    pub pending_writes: usize,
    pub writes_log: usize,
    pub session_notes: usize,
    pub project_state: usize,
    pub project_arch: usize,
}

pub fn run(start: &Path, destination: &Path) -> Result<ExportSummary> {
    let ctx = db::open_project(start)?;
    let conn = &ctx.conn;

    let (root_path_at_export, project_created_at, source_schema_version) = read_project_meta(conn)?;
    let exported_at: String = conn.query_row("SELECT CURRENT_TIMESTAMP", [], |row| row.get(0))?;

    let facts = read_facts(conn)?;
    let decisions = read_decisions(conn)?;
    let tasks = read_tasks(conn)?;
    let commands = read_commands(conn)?;
    let pending_writes = read_pending_writes(conn)?;
    let writes_log = read_writes_log(conn)?;
    let session_notes = read_session_notes(conn)?;
    let project_state = read_narrative(conn, "project_state")?;
    let project_arch = read_narrative(conn, "project_arch")?;

    let summary = ExportSummary {
        destination: destination.to_path_buf(),
        facts: facts.len(),
        decisions: decisions.len(),
        tasks: tasks.len(),
        commands: commands.len(),
        pending_writes: pending_writes.len(),
        writes_log: writes_log.len(),
        session_notes: session_notes.len(),
        project_state: project_state.len(),
        project_arch: project_arch.len(),
    };

    let payload = Export {
        memhub_export_version: EXPORT_VERSION,
        exported_at,
        exported_by: format!("memhub {}", env!("CARGO_PKG_VERSION")),
        source_schema_version,
        project: v1::ProjectMeta {
            root_path_at_export,
            created_at: project_created_at,
        },
        facts,
        decisions,
        tasks,
        commands,
        pending_writes,
        writes_log,
        session_notes,
        project_state,
        project_arch,
    };

    if let Some(parent) = destination.parent()
        && !parent.as_os_str().is_empty()
    {
        fs::create_dir_all(parent)?;
    }

    let json = serde_json::to_string_pretty(&payload)?;

    // Temp file + atomic rename (the same discipline `render` uses, see
    // `crate::render::temp_path_for`): a crash mid-write can now only ever
    // leave a stray `.tmp` file behind, never a truncated `destination`
    // over a previous good export (issue #148 / audit C3).
    let temp_path = temp_path_for(destination)?;
    if let Err(err) = fs::write(&temp_path, &json) {
        let _ = fs::remove_file(&temp_path);
        return Err(err.into());
    }
    if let Err(err) = fs::rename(&temp_path, destination) {
        let _ = fs::remove_file(&temp_path);
        return Err(err.into());
    }

    Ok(summary)
}

fn read_project_meta(conn: &Connection) -> Result<(String, String, String)> {
    Ok(conn.query_row(
        "SELECT root_path, created_at, schema_version FROM projects WHERE id = 1",
        [],
        |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
    )?)
}

fn read_facts(conn: &Connection) -> Result<Vec<v1::Fact>> {
    let mut stmt = conn.prepare(
        "SELECT id, key, value, confidence, source, verified_at, created_at, superseded_by, kind
         FROM facts
         WHERE project_id = 1
         ORDER BY id",
    )?;
    let rows = stmt.query_map([], |row| {
        Ok(v1::Fact {
            id: row.get(0)?,
            key: row.get(1)?,
            value: row.get(2)?,
            confidence: row.get(3)?,
            source: row.get(4)?,
            verified_at: row.get(5)?,
            created_at: row.get(6)?,
            superseded_by: row.get(7)?,
            kind: row.get(8)?,
        })
    })?;
    rows.collect::<std::result::Result<Vec<_>, _>>()
        .map_err(Into::into)
}

