                      datetime('now','-1 hour'), 10, 10, 200, 200)",
                    [],
                )
                .expect("sessions");
        }

        let ctx = db::open_project(temp.path()).expect("reopen");
        let t = query_period_totals(&ctx.conn, 7).expect("totals");

