        for item in &report.items {
            assert!(
                !item.verb.trim().is_empty(),
                "every stale item must name a verb: {item:?}"
            );
            assert!(
                item.verb.starts_with("memhub "),
                "verb should be a runnable memhub invocation: {item:?}"
            );
        }
    }

    #[test]
    fn stale_is_strictly_read_only() {
        use crate::commands::init;
        let temp = tempfile::tempdir().expect("tempdir");
        init::run(temp.path()).expect("init");
        seed_one_of_each_category(temp.path());

        fn snapshot(path: &std::path::Path) -> (i64, i64, i64, i64, i64, i64) {
            let ctx = db::open_project(path).expect("open");
            let count =
                |sql: &str| -> i64 { ctx.conn.query_row(sql, [], |r| r.get(0)).expect("count") };
            (
                count("SELECT COUNT(*) FROM facts"),
                count("SELECT COUNT(*) FROM tasks"),
                count("SELECT COUNT(*) FROM pending_writes"),
                count("SELECT COUNT(*) FROM documents"),
                count("SELECT COUNT(*) FROM writes_log"),
                count("SELECT IFNULL(MAX(id), 0) FROM writes_log"),
            )
        }

        let before = snapshot(temp.path());
        let report = super::stale(temp.path()).expect("stale");
        let after = snapshot(temp.path());

        assert_eq!(
            before, after,
            "review stale must not add/remove rows or writes_log entries"
        );
        assert_eq!(report.counts.total(), 4, "{:#?}", report.items);
    }

    #[test]
    fn count_stale_queue_matches_stale_report_total() {
        use crate::commands::init;
        let temp = tempfile::tempdir().expect("tempdir");
        init::run(temp.path()).expect("init");
        seed_one_of_each_category(temp.path());

        let total = super::count_stale_queue(temp.path()).expect("count");
        let report = super::stale(temp.path()).expect("stale");
        assert_eq!(total, report.counts.total() as i64);
        assert_eq!(total, 4);
    }
}

use std::path::Path;

use rusqlite::{Connection, params};

use crate::Result;
use crate::config::PathMatcher;
use crate::db;
use crate::errors::MemhubError;
use crate::models::{DecisionSearchHit, FileHistoryHit, SearchResponse, SearchResult};

pub fn run(start: &Path, query: &str, limit: usize) -> Result<SearchResponse> {
    let query = query.trim();
    if query.is_empty() {
        return Err(MemhubError::InvalidInput(
            "search query cannot be empty".to_string(),
        ));
    }

    if limit == 0 {
        return Err(MemhubError::InvalidInput(
            "search limit must be greater than zero".to_string(),
        ));
    }

    let ctx = db::open_project(start)?;
    let matcher = PathMatcher::from_patterns(&ctx.config.deny_list.patterns)?;
    sync_decision_chunks(&ctx.conn)?;

    if let Some(path_query) = strip_file_prefix(query) {
        let normalized = normalize_path(path_query);
        let results = if matcher.is_denied(&normalized) {
            Vec::new()
        } else {
            filter_denied_paths(
                search_file_history(&ctx.conn, &normalized, limit)?,
                &matcher,
            )
        };
        return Ok(SearchResponse {
            matcher: "exact:file-history".to_string(),
            query: normalized,
            results: results.into_iter().map(SearchResult::FileHistory).collect(),
        });
    }

    if looks_like_path(query) && file_exists(&ctx.conn, &normalize_path(query))? {
        let normalized = normalize_path(query);
        let results = if matcher.is_denied(&normalized) {
            Vec::new()
        } else {
            filter_denied_paths(
                search_file_history(&ctx.conn, &normalized, limit)?,
                &matcher,
            )
        };
        return Ok(SearchResponse {
            matcher: "exact:file-history".to_string(),
            query: normalized,
            results: results.into_iter().map(SearchResult::FileHistory).collect(),
        });
    }

    let decision_query = strip_decision_prefix(query).unwrap_or(query);
    let results = search_decisions(&ctx.conn, decision_query, limit)?;
    Ok(SearchResponse {
        matcher: if strip_decision_prefix(query).is_some() {
            "fts:decision".to_string()
        } else {
            "fts:decision-fallback".to_string()
        },
        query: decision_query.to_string(),
        results: results.into_iter().map(SearchResult::Decision).collect(),
    })
}

pub fn sync_decision_chunks(conn: &Connection) -> Result<()> {
    conn.execute(
        "INSERT INTO chunks(project_id, source_type, source_id, text)
         SELECT
             d.project_id,
             'decision',
             CAST(d.id AS TEXT),
             d.title || char(10) || d.rationale
         FROM decisions d
         WHERE 1 = 1
         ON CONFLICT(project_id, source_type, source_id) DO UPDATE SET
             text = excluded.text",
        [],
    )?;

    Ok(())
}

fn filter_denied_paths(hits: Vec<FileHistoryHit>, matcher: &PathMatcher) -> Vec<FileHistoryHit> {
    hits.into_iter()
        .filter(|hit| !matcher.is_denied(&hit.path))
        .collect()
}

fn search_file_history(conn: &Connection, path: &str, limit: usize) -> Result<Vec<FileHistoryHit>> {
    let mut stmt = conn.prepare(
        "SELECT
             f.path,
             c.sha,
             c.author,
             c.committed_at,
             c.message,
             cf.change_type
         FROM files f
         JOIN commit_files cf ON cf.file_id = f.id
         JOIN commits c ON c.sha = cf.commit_sha
         WHERE f.project_id = 1 AND f.path = ?1
         ORDER BY c.committed_at DESC
         LIMIT ?2",
    )?;

    let rows = stmt.query_map(params![path, limit as i64], |row| {
        Ok(FileHistoryHit {
            path: row.get(0)?,
            commit_sha: row.get(1)?,
            author: row.get(2)?,
            committed_at: row.get(3)?,
            message: row.get(4)?,
            change_type: row.get(5)?,
        })
    })?;

    rows.collect::<std::result::Result<Vec<_>, _>>()
        .map_err(Into::into)
}

fn search_decisions(
    conn: &Connection,
    query: &str,
    limit: usize,
) -> Result<Vec<DecisionSearchHit>> {
    let match_query = build_fts_query(query)?;
    let mut stmt = conn.prepare(
        "SELECT
             d.id,
             d.title,
             d.rationale,
             d.decided_at,
             bm25(chunk_fts) AS score
         FROM chunk_fts
         JOIN chunks ch ON ch.id = chunk_fts.rowid
         JOIN decisions d
             ON d.id = CAST(ch.source_id AS INTEGER)
            AND d.project_id = ch.project_id
         WHERE chunk_fts MATCH ?1
           AND ch.source_type = 'decision'
         ORDER BY score ASC, d.decided_at DESC
         LIMIT ?2",
    )?;

    let rows = stmt.query_map(params![match_query, limit as i64], |row| {
        Ok(DecisionSearchHit {
            decision_id: row.get(0)?,
            title: row.get(1)?,
            rationale: row.get(2)?,
            decided_at: row.get(3)?,
            score: row.get(4)?,
        })
    })?;

    rows.collect::<std::result::Result<Vec<_>, _>>()
        .map_err(Into::into)
}

fn build_fts_query(query: &str) -> Result<String> {
    let tokens = query
        .split_whitespace()
        .map(|token| token.trim_matches(|c: char| matches!(c, '"' | '\'' | ',' | '.' | ':' | ';')))
        .filter(|token| !token.is_empty())
        .map(|token| format!("\"{}\"", token.replace('"', "\"\"")))
        .collect::<Vec<_>>();

    if tokens.is_empty() {
        return Err(MemhubError::InvalidInput(
            "search query must include at least one searchable token".to_string(),
        ));
    }

    Ok(tokens.join(" AND "))
}

fn strip_file_prefix(query: &str) -> Option<&str> {
    query.strip_prefix("file:").map(str::trim)
}

fn strip_decision_prefix(query: &str) -> Option<&str> {
    [
        "find decisions about ",
        "decisions about ",
        "decision about ",
        "decision: ",
        "decisions: ",
        "decision ",
        "decisions ",
    ]
    .into_iter()
    .find_map(|prefix| query.strip_prefix(prefix))
    .map(str::trim)
}

fn file_exists(conn: &Connection, path: &str) -> Result<bool> {
    conn.query_row(
        "SELECT EXISTS(
             SELECT 1 FROM files
             WHERE project_id = 1 AND path = ?1
         )",
        [path],
        |row| row.get(0),
    )
    .map_err(Into::into)
}

fn looks_like_path(query: &str) -> bool {
    query.contains('/') || query.contains('\\') || query.contains('.')
}

fn normalize_path(path: &str) -> String {
    path.trim().replace('\\', "/")
}

use std::path::Path;

use rusqlite::params;

use crate::MemhubError;
use crate::Result;
use crate::db;
use crate::models::SessionNote;

pub const DEFAULT_LIST_LIMIT: usize = 25;
pub const MAX_TEXT_LEN: usize = 4096;

pub fn add(start: &Path, text: &str, actor: &str, actor_raw: &str) -> Result<SessionNote> {
    let trimmed_text = text.trim();
    if trimmed_text.is_empty() {
        return Err(MemhubError::InvalidInput(
            "session note text must not be empty".to_string(),
        ));
    }
    if trimmed_text.chars().count() > MAX_TEXT_LEN {
        return Err(MemhubError::InvalidInput(format!(
            "session note text must be {MAX_TEXT_LEN} characters or fewer"
        )));
    }
    if actor.trim().is_empty() {
        return Err(MemhubError::InvalidInput(
            "session note actor must not be empty".to_string(),
        ));
    }

    let mut ctx = db::open_project(start)?;
    let mode = ctx.config.retrieval.mode;
    let tx = ctx.conn.transaction()?;

    tx.execute(
        "INSERT INTO session_notes(project_id, actor, actor_raw, text)
         VALUES (1, ?1, ?2, ?3)",
        params![actor, actor_raw, trimmed_text],
    )?;
    let row_id = tx.last_insert_rowid();

    db::log_write(
        &tx,
        actor,
        "session_notes",
        Some(row_id),
        "insert",
        "mcp log_session_note",
    )?;

    let embed_text = crate::retrieval::note_embed_text(trimmed_text);
    crate::retrieval::eager_embed_in_tx(
        &tx,
        mode,
        crate::retrieval::SourceType::Note,
        row_id,
        &embed_text,
    )?;

    let note = tx.query_row(
        "SELECT id, actor, actor_raw, text, created_at
         FROM session_notes WHERE id = ?1",
        params![row_id],
        row_to_note,
    )?;

    tx.commit()?;
    Ok(note)
}

pub fn list(
    start: &Path,
    limit: usize,
    actor_filter: Option<&str>,
    since_days: Option<i64>,
) -> Result<Vec<SessionNote>> {
    if limit == 0 {
        return Err(MemhubError::InvalidInput(
            "session note list limit must be greater than zero".to_string(),
        ));
    }
    if let Some(days) = since_days
        && days < 0
    {
        return Err(MemhubError::InvalidInput(
            "session note --since-days must not be negative".to_string(),
        ));
    }

    let ctx = db::open_project(start)?;
    let conn = &ctx.conn;

    let mut sql = String::from(
        "SELECT id, actor, actor_raw, text, created_at
         FROM session_notes
         WHERE project_id = 1",
    );
    if actor_filter.is_some() {
        sql.push_str(" AND actor = ?2");
    }
    if let Some(days) = since_days {
        sql.push_str(&format!(
            " AND created_at >= datetime('now', '-{days} days')"
        ));
    }
    sql.push_str(" ORDER BY created_at DESC, id DESC LIMIT ?1");

    let mut stmt = conn.prepare(&sql)?;
    let rows = match actor_filter {
        Some(actor) => stmt
            .query_map(params![limit as i64, actor], row_to_note)?
            .collect::<std::result::Result<Vec<_>, _>>()?,
        None => stmt
            .query_map(params![limit as i64], row_to_note)?
            .collect::<std::result::Result<Vec<_>, _>>()?,
    };
    Ok(rows)
}

fn row_to_note(row: &rusqlite::Row<'_>) -> rusqlite::Result<SessionNote> {
    Ok(SessionNote {
        id: row.get(0)?,
        actor: row.get(1)?,
        actor_raw: row.get(2)?,
        text: row.get(3)?,
        created_at: row.get(4)?,
    })
}

use std::path::Path;

use rusqlite::{Connection, params};

use crate::Result;
use crate::commands::fact;
use crate::db;
use crate::models::{
    CountByLabel, FACT_STALE_AFTER_DAYS, RecentFactKey, StatsSummary, TopCommandKind,
};

pub const TOP_N: usize = 5;
pub const DEFAULT_WINDOW_DAYS: i64 = 30;

#[derive(Debug, Clone, Copy)]
pub enum StatsWindow {
    Days(i64),
    All,
}

impl StatsWindow {
    pub fn label(&self) -> String {
        match self {
            StatsWindow::Days(d) => format!("last {d} days"),
            StatsWindow::All => "all time".to_string(),
        }
    }

    pub fn days(&self) -> Option<i64> {
        match self {
            StatsWindow::Days(d) => Some(*d),
            StatsWindow::All => None,
        }
    }
}

pub fn run(start: &Path, window: StatsWindow) -> Result<StatsSummary> {
    let ctx = db::open_project(start)?;
    let conn = &ctx.conn;

    let facts: i64 = conn.query_row("SELECT COUNT(*) FROM facts", [], |row| row.get(0))?;
    let stale_facts = fact::count_stale(start)?;
    let stale_ratio = if facts > 0 {
        Some(stale_facts as f64 / facts as f64)
    } else {
        None
    };
    let decisions: i64 = conn.query_row("SELECT COUNT(*) FROM decisions", [], |row| row.get(0))?;
    let tasks_total: i64 = conn.query_row("SELECT COUNT(*) FROM tasks", [], |row| row.get(0))?;
    let tasks_open: i64 = conn.query_row(
        "SELECT COUNT(*) FROM tasks WHERE status = 'open'",
        [],
        |row| row.get(0),
    )?;
    let commands: i64 = conn.query_row("SELECT COUNT(*) FROM commands", [], |row| row.get(0))?;
    let commits: i64 = conn.query_row("SELECT COUNT(*) FROM commits", [], |row| row.get(0))?;
    let files: i64 = conn.query_row("SELECT COUNT(*) FROM files", [], |row| row.get(0))?;
    let chunks: i64 = conn.query_row("SELECT COUNT(*) FROM chunks", [], |row| row.get(0))?;
    let pending_writes_now: i64 = conn.query_row(
        "SELECT COUNT(*) FROM pending_writes WHERE status = 'pending'",
        [],
        |row| row.get(0),
    )?;
    let writes_logged_total: i64 =
        conn.query_row("SELECT COUNT(*) FROM writes_log", [], |row| row.get(0))?;

    let writes_in_window = count_writes_in_window(conn, window)?;
    let writes_by_actor = top_writes_grouped(conn, window, "actor", TOP_N)?;
    let writes_by_table = top_writes_grouped(conn, window, "table_name", TOP_N)?;

    let pending_created_in_window = count_pending_created(conn, window)?;
    let pending_reviewed_in_window = count_pending_reviewed(conn, window)?;
    let review_rate = if pending_created_in_window > 0 {
        Some(pending_reviewed_in_window as f64 / pending_created_in_window as f64)
    } else {
        None
    };
    let pending_by_status = pending_status_counts(conn)?;

    let top_command_kinds = top_command_kinds(conn, TOP_N)?;
    let recent_facts = recent_facts(conn, TOP_N)?;

    Ok(StatsSummary {
        project_name: ctx.config.project_name,
        repo_root: ctx.paths.repo_root,
        window_label: window.label(),
        window_days: window.days(),
        facts,
        stale_facts,
        stale_ratio,
        decisions,
        tasks_total,
        tasks_open,
        commands,
        commits,
        files,
        chunks,
        pending_writes_now,
        writes_logged_total,
        writes_in_window,
        writes_by_actor,
        writes_by_table,
        pending_created_in_window,
        pending_reviewed_in_window,
        review_rate,
        pending_by_status,
        top_command_kinds,
        recent_facts,
    })
}

fn count_writes_in_window(conn: &Connection, window: StatsWindow) -> Result<i64> {
    Ok(match window {
        StatsWindow::All => {
            conn.query_row("SELECT COUNT(*) FROM writes_log", [], |row| row.get(0))?
        }
        StatsWindow::Days(d) => conn.query_row(
            &format!("SELECT COUNT(*) FROM writes_log WHERE at >= datetime('now', '-{d} days')"),
            [],
            |row| row.get(0),
        )?,
    })
}

fn top_writes_grouped(
    conn: &Connection,
    window: StatsWindow,
    column: &str,
    limit: usize,
) -> Result<Vec<CountByLabel>> {
    let where_clause = match window {
        StatsWindow::All => String::new(),
        StatsWindow::Days(d) => format!("WHERE at >= datetime('now', '-{d} days')"),
    };
    let sql = format!(
        "SELECT {column} AS label, COUNT(*) AS c
         FROM writes_log
         {where_clause}
         GROUP BY {column}
         ORDER BY c DESC, label ASC
         LIMIT ?1"
    );
    let mut stmt = conn.prepare(&sql)?;
    let rows = stmt
        .query_map(params![limit as i64], |row| {
            Ok(CountByLabel {
                label: row.get::<_, String>(0)?,
                count: row.get::<_, i64>(1)?,
            })
        })?
        .collect::<std::result::Result<Vec<_>, _>>()?;
    Ok(rows)
}

fn count_pending_created(conn: &Connection, window: StatsWindow) -> Result<i64> {
    Ok(match window {
        StatsWindow::All => conn.query_row(
            "SELECT COUNT(*) FROM pending_writes",
            [],
            |row| row.get(0),
        )?,
        StatsWindow::Days(d) => conn.query_row(
            &format!(
                "SELECT COUNT(*) FROM pending_writes WHERE created_at >= datetime('now', '-{d} days')"
            ),
            [],
            |row| row.get(0),
        )?,
    })
}

fn count_pending_reviewed(conn: &Connection, window: StatsWindow) -> Result<i64> {
    Ok(match window {
        StatsWindow::All => conn.query_row(
            "SELECT COUNT(*) FROM pending_writes WHERE status != 'pending'",
            [],
            |row| row.get(0),
        )?,
        StatsWindow::Days(d) => conn.query_row(
            &format!(
                "SELECT COUNT(*) FROM pending_writes
                 WHERE status != 'pending'
                   AND reviewed_at IS NOT NULL
                   AND reviewed_at >= datetime('now', '-{d} days')"
            ),
            [],
            |row| row.get(0),
        )?,
    })
}

fn pending_status_counts(conn: &Connection) -> Result<Vec<CountByLabel>> {
    let mut stmt = conn.prepare(
        "SELECT status, COUNT(*) AS c
         FROM pending_writes
         GROUP BY status
         ORDER BY status ASC",
    )?;
    let rows = stmt
        .query_map([], |row| {
            Ok(CountByLabel {
                label: row.get::<_, String>(0)?,
                count: row.get::<_, i64>(1)?,
            })
        })?
        .collect::<std::result::Result<Vec<_>, _>>()?;
    Ok(rows)
}

fn top_command_kinds(conn: &Connection, limit: usize) -> Result<Vec<TopCommandKind>> {
    let mut stmt = conn.prepare(
        "SELECT kind, cmdline, success_count, fail_count, last_run_at
         FROM commands
         ORDER BY (success_count + fail_count) DESC, last_run_at DESC NULLS LAST
         LIMIT ?1",
    )?;
    let rows = stmt
        .query_map(params![limit as i64], |row| {
            let success: i64 = row.get(2)?;
            let fail: i64 = row.get(3)?;
            let total = success + fail;
            let confidence = if total > 0 {
                Some(success as f64 / total as f64)
            } else {
                None
            };
            Ok(TopCommandKind {
                kind: row.get(0)?,
                cmdline: row.get(1)?,
                success_count: success,
                fail_count: fail,
                confidence,
                last_run_at: row.get(4)?,
            })
        })?
        .collect::<std::result::Result<Vec<_>, _>>()?;
    Ok(rows)
}

fn recent_facts(conn: &Connection, limit: usize) -> Result<Vec<RecentFactKey>> {
    let mut stmt = conn.prepare(&format!(
        "SELECT key, verified_at,
                CASE
                    WHEN verified_at IS NULL THEN 1
                    WHEN julianday('now') - julianday(verified_at) > {FACT_STALE_AFTER_DAYS} THEN 1
                    ELSE 0
                END AS is_stale
         FROM facts
         ORDER BY verified_at DESC NULLS LAST, id DESC
         LIMIT ?1"
    ))?;
    let rows = stmt
        .query_map(params![limit as i64], |row| {
            let stale_flag: i64 = row.get(2)?;
            Ok(RecentFactKey {
                key: row.get(0)?,
                verified_at: row.get(1)?,
                is_stale: stale_flag != 0,
            })
        })?
        .collect::<std::result::Result<Vec<_>, _>>()?;
    Ok(rows)
}

use std::path::Path;

use crate::Result;
use crate::commands::doctor;
use crate::commands::fact;
use crate::commands::review;
use crate::db;
use crate::models::StatusSummary;

pub fn run(start: &Path) -> Result<StatusSummary> {
    let ctx = db::open_project(start)?;
    let conn = &ctx.conn;

    let schema_version: String = conn.query_row(
        "SELECT schema_version FROM projects WHERE id = 1",
        [],
        |row| row.get(0),
    )?;
    let facts: i64 = conn.query_row("SELECT COUNT(*) FROM facts", [], |row| row.get(0))?;
    let stale_facts = fact::count_stale(start)?;
    let decisions: i64 = conn.query_row("SELECT COUNT(*) FROM decisions", [], |row| row.get(0))?;
    let tasks_total: i64 = conn.query_row("SELECT COUNT(*) FROM tasks", [], |row| row.get(0))?;
    let tasks_open: i64 = conn.query_row(
        "SELECT COUNT(*) FROM tasks WHERE status = 'open'",
        [],
        |row| row.get(0),
    )?;
    let commands: i64 = conn.query_row("SELECT COUNT(*) FROM commands", [], |row| row.get(0))?;
    let commits: i64 = conn.query_row("SELECT COUNT(*) FROM commits", [], |row| row.get(0))?;
    let files: i64 = conn.query_row("SELECT COUNT(*) FROM files", [], |row| row.get(0))?;
    let chunks: i64 = conn.query_row("SELECT COUNT(*) FROM chunks", [], |row| row.get(0))?;
    let pending_writes: i64 = conn.query_row(
        "SELECT COUNT(*) FROM pending_writes WHERE status = 'pending'",
        [],
        |row| row.get(0),
    )?;
    let writes_logged: i64 =
        conn.query_row("SELECT COUNT(*) FROM writes_log", [], |row| row.get(0))?;
    // Wave 3 L4 (issue #47): one-line visibility into the read-only
    // `memhub review stale` audit queue. Reuses that command's exact
    // computation (`review::count_stale_queue`) rather than a second
    // implementation, so the two counts can never silently disagree.
    let stale_queue = review::count_stale_queue(start)?;

    let deny_patterns = ctx.config.deny_list.patterns.len();
    let project_name = ctx.config.project_name;
    let repo_root = ctx.paths.repo_root;
    let db_path = ctx.paths.db_path;
    let config_path = ctx.paths.config_path;

    Ok(StatusSummary {
        project_name,
        repo_root,
        db_path,
        config_path,
        schema_version,
        facts,
        stale_facts,
        decisions,
        tasks_open,
        tasks_total,
        commands,
        commits,
        files,
        chunks,
        pending_writes,
        writes_logged,
        deny_patterns,
        stale_queue,
    })
}

/// Cheap, always-relevant subsystem-state checks for `status`'s fast
/// path (Wave 1·C, issue #22): a curated subset of `doctor`'s own
/// checks (issue #21), reused by calling them directly instead of
/// duplicating their logic. Deliberately excludes doctor's heavy
/// integrity PRAGMAs, config validation, and MCP-registration probes —
/// those stay `doctor`-only; `status` stays the quick overview.
///
/// Order mirrors `doctor::run`'s own ordering for the same checks, so
/// a user who runs both commands sees the same relative placement.
pub fn checks(start: &Path) -> Result<Vec<doctor::Check>> {
    let ctx = db::open_project(start)?;
    Ok(vec![
        doctor::check_schema(&ctx.conn),
        doctor::check_render_freshness(&ctx.conn, &ctx.paths.repo_root, &ctx.config),
        doctor::check_retrieval_mode(&ctx.config),
        doctor::check_embeddings_freshness(start, &ctx.config),
        doctor::check_metrics_health(&ctx.conn, &ctx.config),
        doctor::check_sync_freshness(start, &ctx.config),
    ])
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::commands::init;
    use tempfile::tempdir;

    #[test]
    fn checks_reuses_the_documented_subsystem_subset_in_order() {
        let temp = tempdir().expect("tempdir");
        init::run(temp.path()).expect("init");

        let result = checks(temp.path()).expect("status checks");
        let ids: Vec<&str> = result.iter().map(|c| c.id).collect();
        assert_eq!(
            ids,
            vec![
                "schema",
                "render_freshness",
                "retrieval_mode",
                "embeddings_freshness",
                "metrics_health",
                "sync_freshness",
            ]
        );
    }

    // Wave 3 L4 (issue #47): `status` gains a one-line stale-queue count,
    // reusing `review::count_stale_queue` rather than a second tally.
    #[test]
    fn run_reports_zero_stale_queue_on_a_clean_repo() {
        let temp = tempdir().expect("tempdir");
        init::run(temp.path()).expect("init");

        let summary = run(temp.path()).expect("status");
        assert_eq!(summary.stale_queue, 0);
    }

    #[test]
    fn run_stale_queue_matches_review_count_stale_queue() {
        use crate::commands::{fact, review};
        let temp = tempdir().expect("tempdir");
        init::run(temp.path()).expect("init");

        let (id, _) = fact::add(temp.path(), "k", "v", "user", "cli:user").expect("fact");
        let ctx = db::open_project(temp.path()).expect("open");
        ctx.conn
            .execute(
                "UPDATE facts SET verified_at = datetime('now', '-400 days') WHERE id = ?1",
                rusqlite::params![id],
            )
            .expect("backdate");
        drop(ctx);

        let summary = run(temp.path()).expect("status");
        let direct = review::count_stale_queue(temp.path()).expect("count");
        assert_eq!(summary.stale_queue, direct);
        assert_eq!(summary.stale_queue, 1);
    }
}

//! Cross-machine Drive sync (M10). memhub stays **offline** — every
//! function here reads or writes only local files. The agent's Drive
//! access is the transport; these commands are the brain it drives.
//!
//! Design anchor:
//! `docs/reference/memhub-prd-addendum-m10-drive-sync.md`.
//!
//! Command surface (all local-file, all offline):
//! - `enable` / `disable` / `enablement_status` — per-repo opt-in.
//! - `snapshot` — clean single-file DB copy + manifest for upload.
//! - `check` — fast-forward verdict of local vs a downloaded snapshot.
//! - `adopt` — gated replace of the local DB with a snapshot.
//! - `commit` — record the post-push baseline in the marker.

use std::fs::{self, File};
use std::io::{Read, Write};
use std::path::{Path, PathBuf};
use std::process::Command;
use std::time::Duration;

use rusqlite::backup::{Backup, StepResult};
use rusqlite::{Connection, OpenFlags, params};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};

use crate::config::SyncConfig;
use crate::db;
use crate::{MemhubError, Result};

/// File names inside a `<project-id>` Drive folder.
///
/// `SNAPSHOT_FILENAME` is the **legacy** bare snapshot name. New pushes
/// write an immutable, content-addressed `project-<sha256>.sqlite`
/// (see [`versioned_snapshot_filename`]) so publishing a new snapshot
/// never overwrites the one the current manifest still points at. The
/// bare name survives only as the read-side fallback for a Drive folder
/// last written by a pre-versioning binary — a manifest without a
/// `snapshot_filename` field resolves to it (see [`resolve_snapshot_file`]).
pub const SNAPSHOT_FILENAME: &str = "project.sqlite";
pub const MANIFEST_FILENAME: &str = "manifest.json";

/// Immutable, content-addressed snapshot filename: `project-<sha256>.sqlite`.
/// Keying the name on the file's own hash makes every distinct snapshot a
/// distinct file, so a new publication is a *new* file rather than an
/// in-place overwrite of the snapshot the live manifest still references —
/// the previous snapshot+manifest pair stays adoptable right up until the
/// manifest rename swings the pointer to the new one.
fn versioned_snapshot_filename(file_sha256: &str) -> String {
    format!("project-{file_sha256}.sqlite")
}

/// Whether `name` looks like one of memhub's own snapshot DB files — the
/// legacy bare `project.sqlite` or a versioned `project-<hash>.sqlite`.
/// Used by publication GC to find snapshots the current manifest no
/// longer references, without touching files other tools may keep in a
/// shared folder.
fn is_snapshot_filename(name: &str) -> bool {
    name == SNAPSHOT_FILENAME || (name.starts_with("project-") && name.ends_with(".sqlite"))
}

/// Sub-namespace inside `[sync] drive_subpath` so memhub owns its own
/// folder even when the synced directory is shared with other tools.
/// The canonical layout is `<drive_subpath>/memhub/<project_id>/`.
pub const DRIVE_NAMESPACE: &str = "memhub";

/// Bumped only on an incompatible manifest shape change. Additive
/// fields ride on `#[serde(default)]` like the export format.
pub const MANIFEST_VERSION: u32 = 1;

/// Logical content version of a memhub DB. Divergence is decided from
/// this, **never** from file bytes — SQLite files are not byte-stable
/// for identical content (page reordering, `VACUUM`), so a file hash
/// would report "changed" on every comparison.
///
/// `writes_log` is appended to by every durable mutation, so its
/// `max_id` / `count` are a cheap monotonic human signal. But equality
/// hinges on `digest` — a hash of the **durable content tables**
/// themselves, not the log. The log records *that* a fact was added,
/// not the fact's key/value; two repos that each added one fact log
/// near-identical rows (differing only by a second-granularity
/// timestamp), so a log-based digest gives dangerous false "equal"
/// verdicts. Hashing the content tables means only genuinely identical
/// content — e.g. one side adopted the other's snapshot byte-for-byte
/// — compares equal, regardless of timing or page layout.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct LogicalVersion {
    pub writes_log_max_id: i64,
    pub writes_log_count: i64,
    pub digest: String,
}

/// Durable content tables and the columns that define their content.
/// Order is fixed so the digest is deterministic.
///
/// This is the authoritative list of what divergence the sync check
/// gates on. It is a **superset** of `memhub export` — a whole-DB sync
/// snapshot (`VACUUM INTO`) carries every table, including `documents` /
/// `doc_chunks`, which `export` deliberately omits — so the digest must
/// cover them too or two machines that each ingest a different doc would
/// compare EQUAL over real divergence (audit finding F2).
///
/// Coverage is hand-maintained but drift-proofed: the
/// `content_tables_cover_the_live_schema` test asserts every live table
/// and column is either digested here or on an explicit exemption list
/// with a stated reason. Adding a durable table/column without updating
/// one of the two lists turns that test red.
///
/// `project_id` is intentionally never digested (it is the constant
/// singleton partition key, always 1, and the digest already filters
/// `WHERE project_id = 1`). `documents` / `doc_chunks` also omit their
/// surrogate `id` and local ingest timestamp so two machines that
/// independently ingest the *same* document at the same path converge to
/// an equal digest; their content identity is the natural
/// (path/title/hash/…) and (doc_id/ord/heading/body) columns. Both
/// exemptions are recorded in `column_exempt` alongside their reasons.
const CONTENT_TABLES: &[(&str, &[&str])] = &[
    (
        "facts",
        &[
            "id",
            "key",
            "value",
            "confidence",
            "source",
            "verified_at",
            "created_at",
            "kind",
            "superseded_by",
        ],
    ),
    (
        "decisions",
        &[
            "id",
            "title",
            "rationale",
            "status",
            "decided_at",
            "superseded_by",
            "source",
            "summary",
        ],
    ),
    (
        "tasks",
        &["id", "title", "status", "notes", "created_at", "updated_at"],
    ),
    (
        "commands",
        &[
            "id",
            "kind",
            "cmdline",
            "last_exit_code",
            "last_run_at",
            "success_count",
            "fail_count",
        ],
    ),
    (
        "pending_writes",
        &[
            "id",
            "kind",
            "payload_json",
            "rationale",
            "status",
            "actor",
            "actor_raw",
            "created_at",
            "provenance_json",
            "reviewed_at",
        ],
    ),
    (
        "session_notes",
        &["id", "actor", "actor_raw", "text", "created_at"],
    ),
    (
        "project_state",
        &["id", "body", "actor", "actor_raw", "created_at"],
    ),
    (
        "project_arch",
        &["id", "body", "actor", "actor_raw", "created_at"],
    ),
    (
        "documents",
        &["path", "title", "content_hash", "byte_len", "source"],
    ),
    ("doc_chunks", &["doc_id", "ord", "heading_path", "body"]),
];

impl LogicalVersion {
    pub fn read(conn: &Connection) -> Result<Self> {
        let (max_id, count): (Option<i64>, i64) = conn.query_row(
            "SELECT MAX(id), COUNT(*) FROM writes_log WHERE project_id = 1",
            [],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )?;

        // Self-describing, length-prefixed encoding (F2). The old scheme
        // COALESCE'd NULL to '' (so NULL and empty string collided) and
        // joined columns with 0x1f/0x1e/0x1d separators that can occur
        // inside TEXT (so embedded separator bytes could blur row/column
        // boundaries). Here every value carries its own length and a
        // NULL/TEXT tag, and rows and tables are framed with control
        // bytes, so the byte stream is a prefix-free encoding of the
        // content — two DBs hash equal iff their digested content is
        // byte-for-byte identical, and NULL ≠ '' ≠ any other value.
        let mut hasher = Sha256::new();
        for (table, cols) in CONTENT_TABLES {
            // Length-framed table name so no table's bytes can bleed into
            // the next.
            hash_len_prefixed(&mut hasher, table.as_bytes());
            // Each column is CAST to TEXT individually (NULL stays NULL —
            // it is not coalesced), so integer/real columns render
            // deterministically while NULL remains distinguishable.
            let select_list = cols
                .iter()
                .map(|c| format!("CAST({c} AS TEXT)"))
                .collect::<Vec<_>>()
                .join(", ");
            let sql = format!("SELECT {select_list} FROM {table} WHERE project_id = 1 ORDER BY id");
            let mut stmt = conn.prepare(&sql)?;
            let mut rows = stmt.query([])?;
            while let Some(row) = rows.next()? {
                // 0x01 = "a row follows"; distinguished from the 0x00
                // end-of-table marker below. The column count is fixed per
                // table, so the parse of the framed values is unambiguous.
                hasher.update([ROW_PRESENT]);
                for i in 0..cols.len() {
                    match row.get::<_, Option<String>>(i)? {
                        // 0x00 tag, no length: a NULL, distinct from an
                        // empty string (0x01 tag + length 0).
                        None => hasher.update([VALUE_NULL]),
                        Some(s) => {
                            hasher.update([VALUE_TEXT]);
                            hash_len_prefixed(&mut hasher, s.as_bytes());
                        }
                    }
                }
            }
            // 0x00 closes the table's row stream.
            hasher.update([TABLE_END]);
        }
        let digest = hasher
            .finalize()
            .iter()
            .map(|b| format!("{b:02x}"))
            .collect();

        Ok(Self {
            writes_log_max_id: max_id.unwrap_or(0),
            writes_log_count: count,
            digest,
        })
    }
}

/// Control bytes for the digest's prefix-free row/value framing (see
/// [`LogicalVersion::read`]). Kept distinct so a row-boundary marker can
/// never be confused with a value's NULL/TEXT tag during the (conceptual)
/// parse that makes the encoding injective.
const ROW_PRESENT: u8 = 0x01;
const TABLE_END: u8 = 0x00;
const VALUE_NULL: u8 = 0x00;
const VALUE_TEXT: u8 = 0x01;

/// Feed `bytes` into `hasher` prefixed by its length as 8 little-endian
/// bytes, so an arbitrary byte payload cannot blur into whatever follows
/// it — the length says exactly where it ends regardless of its content.
fn hash_len_prefixed(hasher: &mut Sha256, bytes: &[u8]) {
    hasher.update((bytes.len() as u64).to_le_bytes());
    hasher.update(bytes);
}

/// Compact, human-readable one-line summary of a [`LogicalVersion`] for
/// error messages: the writes-log signal plus a short digest prefix.
/// Not a stable format — diagnostics only.
fn describe_logical(v: &LogicalVersion) -> String {
    let short: String = v.digest.chars().take(12).collect();
    format!(
        "writes {}/{}, digest {}…",
        v.writes_log_max_id, v.writes_log_count, short
    )
}

/// Sidecar written next to a snapshot in the Drive folder. Carries the
/// logical version (divergence), schema version (the §6 upgrade
/// guard), and the file checksum (integrity against a torn download).
/// The checksum is **of the snapshot file**, so the manifest never
/// includes itself.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Manifest {
    pub manifest_version: u32,
    pub project_id: String,
    pub schema_version: String,
    pub logical_version: LogicalVersion,
    pub file_sha256: String,
    /// The snapshot file this manifest references, relative to the manifest's
    /// own directory. Additive (`#[serde(default)]`): a manifest written by a
    /// pre-versioning binary omits it, and the reader falls back to the
    /// legacy bare `SNAPSHOT_FILENAME` — so old Drive layouts stay readable
    /// and an older binary reading a new manifest simply ignores the field.
    /// Always a plain filename (validated on read in [`resolve_snapshot_file`]).
    #[serde(default)]
    pub snapshot_filename: String,
    pub machine_id: String,
    pub created_at: String,
    pub memhub_version: String,
}

impl Manifest {
    pub fn load(path: &Path) -> Result<Self> {
        let raw = fs::read_to_string(path)?;
        Ok(serde_json::from_str(&raw)?)
    }
}

#[derive(Debug)]
pub struct SnapshotSummary {
    pub out_dir: PathBuf,
    pub snapshot_path: PathBuf,
    pub manifest_path: PathBuf,
    pub project_id: String,
    pub schema_version: String,
    pub logical_version: LogicalVersion,
    pub file_sha256: String,
    pub bytes: u64,
}

/// Produce a consistent single-file snapshot of the repo DB plus its
/// `manifest.json` under `out_dir`. Uses SQLite `VACUUM INTO` so a
/// live WAL'd DB is captured cleanly (never a raw byte copy — §7).
pub fn snapshot(start: &Path, out_dir: &Path, force: bool) -> Result<SnapshotSummary> {
    // Push-side clobber gate (F12). Writing the snapshot into the synced
    // folder *is* the push and overwrites whatever is already there. Refuse
    // to stomp a remote that is ahead of or diverged from local unless
    // explicitly forced — the "lossy case is operator-gated" guarantee has
    // to hold on push, not only on pull (adopt). A first push (no remote
    // yet) reports `no-remote` and proceeds.
    if !force {
        let report = check(start, out_dir)?;
        if matches!(
            report.verdict,
            SyncVerdict::DriveAhead | SyncVerdict::Diverged
        ) {
            return Err(MemhubError::InvalidInput(format!(
                "refusing to overwrite the remote: it is {} relative to local. \
                 Pull first (`memhub sync check`, then `sync adopt`), or pass \
                 --force to overwrite the remote with this machine's state.",
                report.verdict.as_str()
            )));
        }
    }

    let ctx = db::open_project(start)?;
    require_enabled(&ctx.config.sync)?;

    let project_id = resolve_project_id(&ctx.paths.repo_root, &ctx.config.sync)?;
    let schema_version: String = ctx.conn.query_row(
        "SELECT schema_version FROM projects WHERE id = 1",
        [],
        |row| row.get(0),
    )?;
    let logical_version = LogicalVersion::read(&ctx.conn)?;
    let created_at: String = ctx
        .conn
        .query_row("SELECT CURRENT_TIMESTAMP", [], |row| row.get(0))?;

    fs::create_dir_all(out_dir)?;

    // ── Publish atomically (audit F6/X5) ─────────────────────────────
    // The previous scheme deleted the old remote `project.sqlite` before
    // `VACUUM INTO` wrote the new one and then overwrote `manifest.json`
    // in place, so a crash mid-sequence could lose the last valid remote
    // copy or pair new bytes with a stale manifest. Instead:
    //   1. `VACUUM INTO` a same-dir temp (VACUUM refuses to overwrite).
    //   2. Rename it to an immutable content-addressed name — a *new*
    //      file that never overwrites the snapshot the live manifest
    //      still points at.
    //   3. Write `manifest.json` via same-dir temp + atomic rename LAST:
    //      that single rename is the publication point that swings the
    //      pointer to the new snapshot.
    //   4. GC snapshots the freshly-published manifest no longer names.
    // At every boundary the remote holds a valid, adoptable snapshot +
    // manifest pair — the previous one until step 3's rename lands.
    let tmp_snapshot = out_dir.join(format!(".{SNAPSHOT_FILENAME}.{}.tmp", std::process::id()));
    if tmp_snapshot.exists() {
        fs::remove_file(&tmp_snapshot)?;
    }
    vacuum_into(&ctx.conn, &tmp_snapshot)?;

    let file_sha256 = sha256_file(&tmp_snapshot)?;
    let snapshot_filename = versioned_snapshot_filename(&file_sha256);
    let snapshot_path = out_dir.join(&snapshot_filename);
    // A byte-identical prior snapshot would already carry this exact name;
    // replace it (same content) so the rename below always succeeds.
    if snapshot_path.exists() {
        fs::remove_file(&snapshot_path)?;
    }
    fs::rename(&tmp_snapshot, &snapshot_path)?;
    let bytes = fs::metadata(&snapshot_path)?.len();

    let manifest = Manifest {
        manifest_version: MANIFEST_VERSION,
        project_id: project_id.clone(),
        schema_version: schema_version.clone(),
        logical_version: logical_version.clone(),
        file_sha256: file_sha256.clone(),
        snapshot_filename: snapshot_filename.clone(),
        machine_id: machine_id(),
        created_at,
        memhub_version: env!("CARGO_PKG_VERSION").to_string(),
    };
    let manifest_path = out_dir.join(MANIFEST_FILENAME);
    // The atomic rename here is the publication point. Until it lands, the
    // prior manifest (and the snapshot it names) is what any reader sees.
    write_atomic(
        &manifest_path,
        serde_json::to_string_pretty(&manifest)?.as_bytes(),
    )?;

    // Publication succeeded: reclaim snapshots (and interrupted temps) the
    // new manifest no longer references. Best-effort — an orphan left by a
    // failed delete is harmless, and the push itself has already committed.
    gc_unreferenced_snapshots(out_dir, &snapshot_filename);

    // A snapshot written into the repo's *canonical* remote dir just
    // pushed the DB to the shared destination -- record the same
    // baseline `commit()` would, so a push is atomic with its own
    // marker instead of leaving a stale one until a required second
    // step. A snapshot to anywhere else (an inspection copy, a test
    // fixture dir) must never touch the marker: stamping a baseline for
    // a push that never reached the real remote would let a later
    // check() report a false DriveAhead/UpToDate over a true Diverged.
    if is_canonical_remote_dir(&ctx.paths.repo_root, &ctx.config.sync, out_dir) {
        save_marker(
            &ctx.paths.memhub_dir,
            &SyncMarker {
                project_id: manifest.project_id.clone(),
                baseline: manifest.logical_version.clone(),
                baseline_file_sha256: manifest.file_sha256.clone(),
                synced_at: manifest.created_at.clone(),
                last_action: "push".into(),
            },
        )?;
    }

    Ok(SnapshotSummary {
        out_dir: out_dir.to_path_buf(),
        snapshot_path,
        manifest_path,
        project_id,
        schema_version,
        logical_version,
        file_sha256,
        bytes,
    })
}

/// Whether `out_dir` is this repo's canonical remote dir (`<drive_subpath>
/// /memhub/<project_id>`, per `resolve_remote_dir`) -- used to decide
/// whether `snapshot()` should record the push baseline automatically.
/// Paths are compared via `fs::canonicalize` (the caller only reaches
/// here after `create_dir_all(out_dir)`, so it's guaranteed to exist) so
/// a `\\?\`-prefixed or differently-cased spelling of the same directory
/// on Windows doesn't produce a false negative.
///
/// Any failure -- `resolve_remote_dir` erroring (no `drive_subpath`
/// configured, the case for every existing unit test's bare
/// `enable_sync` fixture) or either side failing to canonicalize -- is
/// treated as "not canonical". That fails toward the pre-existing
/// behavior (no automatic marker write, `commit()` still required) and
/// is the safe direction: it never risks stamping a baseline for a
/// snapshot that did not actually land at the real remote.
fn is_canonical_remote_dir(repo_root: &Path, cfg: &SyncConfig, out_dir: &Path) -> bool {
    let Ok(remote_dir) = resolve_remote_dir(repo_root, cfg) else {
        return false;
    };
    match (fs::canonicalize(&remote_dir), fs::canonicalize(out_dir)) {
        (Ok(a), Ok(b)) => a == b,
        _ => false,
    }
}

/// Per-machine last-sync marker, stored at `.memhub/sync_marker.json`
/// (gitignored). Records the logical version the two sides agreed on at
/// the last successful sync. Only **one** version is needed: a sync
/// (pull or push) leaves local and Drive byte-identical, so they share
/// a single baseline. Divergence is then "did local move off the
/// baseline?" and "did Drive move off the baseline?", computed
/// independently.
pub const MARKER_FILENAME: &str = "sync_marker.json";

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SyncMarker {
    pub project_id: String,
    /// Logical version both sides shared at last sync.
    pub baseline: LogicalVersion,
    /// sha256 of the snapshot at last sync (identity/integrity aid).
    #[serde(default)]
    pub baseline_file_sha256: String,
    pub synced_at: String,
    /// `"pull"` or `"push"` — informational.
    #[serde(default)]
    pub last_action: String,
}

pub fn marker_path(memhub_dir: &Path) -> PathBuf {
    memhub_dir.join(MARKER_FILENAME)
}

pub fn load_marker(memhub_dir: &Path) -> Result<Option<SyncMarker>> {
    let path = marker_path(memhub_dir);
    if !path.exists() {
        return Ok(None);
    }
    // An IO error (permissions, a mid-read vanish) still fails loudly: the
    // caller cannot know the sync baseline, so it must not proceed blind.
    let raw = fs::read_to_string(&path)?;
    // A *parse* failure degrades instead of blocking every sync op (X5). A
    // torn/truncated marker — a crash mid-write before the temp+rename in
    // `save_marker` existed, or an externally corrupted file — must not
    // wedge sync. We warn and treat it as "no baseline" (None); the next
    // successful sync rewrites it atomically. A missing marker is already
    // None above, and a valid one parses to Some.
    match serde_json::from_str(&raw) {
        Ok(marker) => Ok(Some(marker)),
        Err(err) => {
            log::warn!(
                "sync marker at {} is unreadable ({err}); ignoring it and treating this as no \
                 baseline. Sync stays usable — the next successful sync rewrites the marker.",
                path.display()
            );
            Ok(None)
        }
    }
}

pub fn save_marker(memhub_dir: &Path, marker: &SyncMarker) -> Result<()> {
    // Same-dir temp + atomic rename (X5): a crash mid-write can never leave
    // a half-written marker that `load_marker` would then have to degrade —
    // a reader sees either the previous marker or the fully-written new one.
    write_atomic(
        &marker_path(memhub_dir),
        serde_json::to_string_pretty(marker)?.as_bytes(),
    )
}

/// Write `bytes` to `path` atomically: write a sibling temp file in the
/// **same directory**, fsync it, then rename it over `path`. `std::fs::rename`
/// replaces an existing destination on both Windows (`MoveFileEx` with
/// `REPLACE_EXISTING`) and POSIX, so the swap is atomic — a concurrent
/// reader observes either the old file or the new one, never a torn write.
/// Same-dir keeps the rename a metadata-only move on one filesystem (a
/// cross-device rename would fail). The temp name carries the pid so two
/// writers don't fight over one temp before their renames.
fn write_atomic(path: &Path, bytes: &[u8]) -> Result<()> {
    let dir = path.parent().ok_or_else(|| {
        MemhubError::InvalidInput(format!(
            "cannot atomically write {}: it has no parent directory",
            path.display()
        ))
    })?;
    let stem = path.file_name().and_then(|n| n.to_str()).unwrap_or("write");
    let tmp = dir.join(format!(".{stem}.{}.tmp", std::process::id()));
    {
        let mut f = File::create(&tmp)?;
        f.write_all(bytes)?;
        f.sync_all()?;
    }
    if let Err(e) = fs::rename(&tmp, path) {
        // Don't leave the temp behind on a failed swap.
        let _ = fs::remove_file(&tmp);
        return Err(e.into());
    }
    Ok(())
}

/// After a successful publication, delete snapshot files the current
/// manifest no longer references — previous versioned snapshots, a legacy
/// bare `project.sqlite`, and any leftover `.tmp` artifacts from an
/// interrupted run. Never touches `keep` (the just-published snapshot) or
/// `manifest.json`. Best-effort and infallible by contract: the push has
/// already committed at the manifest rename, so a failed cleanup leaves
/// only a harmless orphan and must not turn a successful push into an
/// error. Per-file and whole-directory failures are logged, not raised.
fn gc_unreferenced_snapshots(out_dir: &Path, keep: &str) {
    let entries = match fs::read_dir(out_dir) {
        Ok(e) => e,
        Err(err) => {
            log::warn!(
                "sync publication GC: could not scan {} ({err}); leaving orphan snapshots in place",
                out_dir.display()
            );
            return;
        }
    };
    for entry in entries.flatten() {
        let name = entry.file_name();
        let Some(name) = name.to_str() else { continue };
        if name == keep || name == MANIFEST_FILENAME {
            continue;
        }
        // Only reclaim our own artifacts: an unreferenced snapshot DB, or a
        // stray temp from an interrupted snapshot/manifest write. The temp
        // match is scoped to memhub's own `.<stem>.<pid>.tmp` names so a
        // shared folder's unrelated `.tmp` files are never touched.
        let is_own_temp = name.ends_with(".tmp")
            && (name.starts_with(&format!(".{SNAPSHOT_FILENAME}."))
                || name.starts_with(&format!(".{MANIFEST_FILENAME}.")));
        if !is_snapshot_filename(name) && !is_own_temp {
            continue;
        }
        if !entry.file_type().map(|t| t.is_file()).unwrap_or(false) {
            continue;
        }
        if let Err(err) = fs::remove_file(entry.path()) {
            log::warn!(
                "sync publication GC: could not remove orphan {} ({err}); it is harmless and \
                 will be retried on the next push",
                entry.path().display()
            );
        }
    }
}

/// Fast-forward verdict of the local DB against a Drive snapshot, by
/// exact analogy to git. `NoRemote` = nothing at the given path;
/// `Diverged` with `baseline_present == false` = first sync, no
/// baseline to fast-forward from (the skill phrases that gently).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum SyncVerdict {
    UpToDate,
    LocalAhead,
    DriveAhead,
    Diverged,
    NoRemote,
}

impl SyncVerdict {
    pub fn as_str(&self) -> &'static str {
        match self {
            SyncVerdict::UpToDate => "up-to-date",
            SyncVerdict::LocalAhead => "local-ahead",
            SyncVerdict::DriveAhead => "drive-ahead",
            SyncVerdict::Diverged => "diverged",
            SyncVerdict::NoRemote => "no-remote",
        }
    }
}

#[derive(Debug, Clone, Serialize)]
pub struct CheckReport {
    pub verdict: SyncVerdict,
    pub baseline_present: bool,
    pub project_id: String,
    pub local_logical: LogicalVersion,
    pub remote_logical: Option<LogicalVersion>,
    pub local_schema: String,
    pub remote_schema: Option<String>,
    /// True when the remote snapshot's schema is newer than this
    /// binary can open — adopt must be refused; run `memhub upgrade`.
    pub schema_blocks_adopt: bool,
    /// Set when the remote manifest's project_id does not match this
    /// repo's — a wrong-folder snapshot the caller must not adopt.
    pub project_id_mismatch: Option<String>,
    pub remote_machine_id: Option<String>,
    pub remote_created_at: Option<String>,
}

/// Compare the local DB against the snapshot at `remote_dir` (a
/// directory holding `project.sqlite` + `manifest.json`, or a path to a
/// `manifest.json` directly). Reads only the manifest — never the
/// multi-MB snapshot — so status is cheap.
pub fn check(start: &Path, remote: &Path) -> Result<CheckReport> {
    let ctx = db::open_project(start)?;
    require_enabled(&ctx.config.sync)?;
    let project_id = resolve_project_id(&ctx.paths.repo_root, &ctx.config.sync)?;
    let local_logical = LogicalVersion::read(&ctx.conn)?;
    let local_schema: String = ctx.conn.query_row(
        "SELECT schema_version FROM projects WHERE id = 1",
        [],
        |row| row.get(0),
    )?;
    let marker = load_marker(&ctx.paths.memhub_dir)?;
    let baseline_present = marker.is_some();

    let manifest = read_remote_manifest(remote)?;
    let Some(manifest) = manifest else {
        return Ok(CheckReport {
            verdict: SyncVerdict::NoRemote,
            baseline_present,
            project_id,
            local_logical,
            remote_logical: None,
            local_schema,
            remote_schema: None,
            schema_blocks_adopt: false,
            project_id_mismatch: None,
            remote_machine_id: None,
            remote_created_at: None,
        });
    };

    let project_id_mismatch =
        (manifest.project_id != project_id).then(|| manifest.project_id.clone());
    // The local schema always parses (it is written by our own
    // migrations); a remote schema that does not parse can never be
    // adopted (adopt hard-refuses it), so `check` reports it as blocking
    // rather than as a spurious "older, safe to adopt".
    let local_ordinal = schema_ordinal(&local_schema)?;
    let schema_blocks_adopt = match schema_ordinal(&manifest.schema_version) {
        Ok(remote_ordinal) => remote_ordinal > local_ordinal,
        Err(_) => true,
    };

    // Did each side move off the shared baseline? With no baseline this
    // is the first sync: equal logical → already in step, else the
    // operator must choose (Diverged, baseline_present=false).
    let verdict = match &marker {
        None => {
            if manifest.logical_version == local_logical {
                SyncVerdict::UpToDate
            } else {
                SyncVerdict::Diverged
            }
        }
        Some(m) => {
            // Local and remote already hold identical content, regardless
            // of what the stored baseline says. This self-heals a marker
            // that fell behind a real sync (e.g. a push that skipped
            // `commit()` before this baseline-on-push fix existed) so a
            // historically-missed commit doesn't keep reporting a stale
            // verdict forever.
            if manifest.logical_version == local_logical {
                SyncVerdict::UpToDate
            } else {
                let local_changed = local_logical != m.baseline;
                let drive_changed = manifest.logical_version != m.baseline;
                match (local_changed, drive_changed) {
                    (false, false) => SyncVerdict::UpToDate,
                    (true, false) => SyncVerdict::LocalAhead,
                    (false, true) => SyncVerdict::DriveAhead,
                    (true, true) => SyncVerdict::Diverged,
                }
            }
        }
    };

    Ok(CheckReport {
        verdict,
        baseline_present,
        project_id,
        local_logical,
        remote_logical: Some(manifest.logical_version),
        local_schema,
        remote_schema: Some(manifest.schema_version),
        schema_blocks_adopt,
        project_id_mismatch,
        remote_machine_id: Some(manifest.machine_id),
        remote_created_at: Some(manifest.created_at),
    })
}

/// Resolve `remote` to its manifest. Accepts a directory (looks for
/// `manifest.json` inside) or a manifest file path directly. `None`
/// when no manifest is present — the `NoRemote` case.
fn read_remote_manifest(remote: &Path) -> Result<Option<Manifest>> {
    let manifest_path = if remote.is_dir() {
        remote.join(MANIFEST_FILENAME)
    } else {
        remote.to_path_buf()
    };
    if !manifest_path.exists() {
        return Ok(None);
    }
    Ok(Some(Manifest::load(&manifest_path)?))
}

/// Numeric prefix of a migration-style schema version (`"0016_x"` →
/// 16). Schema versions are zero-padded ordinals, so comparing the
/// leading number orders them.
///
/// **Fail-closed** (F4/X6): an empty or non-numeric prefix is an error,
/// never a silent `0`. Collapsing an unparseable version to "oldest"
/// would let a garbage or hostile manifest `schema_version` slip *under*
/// the newer-schema refusal in [`adopt`] and get installed by a binary
/// that may not understand it — the exact hole this hardening closes.
/// This mirrors the upward-only `MAX(schema_version)` ratchet in
/// `db::upsert_project`, which likewise refuses to let an unknown/newer
/// schema be treated as safe.
fn schema_ordinal(schema_version: &str) -> Result<u32> {
    schema_version
        .split('_')
        .next()
        .and_then(|n| n.parse().ok())
        .ok_or_else(|| {
            MemhubError::InvalidInput(format!(
                "schema_version '{schema_version}' is not a parseable migration ordinal \
                 (expected a zero-padded 'NNNN_name')"
            ))
        })
}

/// The snapshot file a `manifest` references, resolved against `remote`
/// (a directory holding the manifest, or a `manifest.json` path itself).
/// The name comes from the manifest's `snapshot_filename`; a manifest
/// written by a pre-versioning binary omits it, so we fall back to the
/// legacy bare `SNAPSHOT_FILENAME` and old Drive layouts stay readable.
///
/// The filename is **untrusted** (it rides in a manifest on shared Drive
/// storage), so it must be a single plain path component: a value with a
/// separator or `..` is refused rather than joined, so a hostile manifest
/// cannot steer `adopt` at a file outside the remote folder.
fn resolve_snapshot_file(remote: &Path, manifest: &Manifest) -> Result<PathBuf> {
    let dir = if remote.is_dir() {
        remote.to_path_buf()
    } else {
        remote.parent().map(Path::to_path_buf).unwrap_or_default()
    };
    let candidate = manifest.snapshot_filename.trim();
    if candidate.is_empty() {
        return Ok(dir.join(SNAPSHOT_FILENAME));
    }
    let is_plain = Path::new(candidate)
        .file_name()
        .and_then(|f| f.to_str())
        .map(|f| f == candidate)
        .unwrap_or(false);
    if !is_plain {
        return Err(MemhubError::InvalidInput(format!(
            "manifest 'snapshot_filename' = '{candidate}' is not a plain filename; refusing to \
             resolve a snapshot path outside the remote folder"
        )));
    }
    Ok(dir.join(candidate))
}

/// Tables whose `writes_log` rows carry enough identity in the table
/// itself (a `key`/`title` column) to be worth surfacing individually in
/// a [`diff`] — the durable, human-authored content types. Every other
/// `table_name` that shows up in `writes_log` (documents, pending_writes,
/// config, …) still gets its added/updated counts, just no per-row list.
fn title_column(table: &str) -> Option<&'static str> {
    match table {
        "facts" => Some("key"),
        "decisions" => Some("title"),
        "tasks" => Some("title"),
        _ => None,
    }
}

/// Per-table divergence detail for one side (local or remote) since a
/// shared baseline `writes_log` id — see [`diff`].
#[derive(Debug, Clone, Serialize)]
pub struct TableDelta {
    pub table: String,
    /// Rows whose `writes_log` action was `"insert"`.
    pub added: i64,
    /// Rows whose `writes_log` action was anything else (`update`,
    /// `promote`, `verify`, `supersede`, `delete`, …).
    pub updated: i64,
    /// For `facts`/`decisions`/`tasks`: the current key/title of each
    /// distinct row touched since the baseline, in the order first
    /// touched. Falls back to the `writes_log` reason when the row no
    /// longer exists in the current table (e.g. later superseded). Empty
    /// for every other table.
    pub changed: Vec<String>,
}

/// One side's (local or remote) divergence detail since the baseline.
#[derive(Debug, Clone, Serialize)]
pub struct SideDiff {
    pub writes_since_baseline: i64,
    pub tables: Vec<TableDelta>,
}

/// Per-table divergence detail for both sides since the last agreed sync
/// baseline — the `--diff` detail behind `memhub sync check --diff`
/// (tracker X1). `local`/`remote` are `None` exactly when
/// `unavailable_reason` explains why no diff could be computed: no
/// baseline recorded yet (first sync), no remote snapshot, or a remote
/// schema this binary cannot open.
#[derive(Debug, Clone, Serialize)]
pub struct DiffReport {
    pub baseline_writes_log_max_id: Option<i64>,
    pub local: Option<SideDiff>,
    pub remote: Option<SideDiff>,
    pub unavailable_reason: Option<String>,
}

fn diff_unavailable(baseline: Option<i64>, reason: impl Into<String>) -> DiffReport {
    DiffReport {
        baseline_writes_log_max_id: baseline,
        local: None,
        remote: None,
        unavailable_reason: Some(reason.into()),
    }
}

/// Per-table added/updated counts and changed fact/decision/task titles
/// on both sides since the common sync baseline (tracker X1). Strictly
/// read-only: the local DB is only ever `SELECT`ed from (the same
/// `db::open_project` every other read command uses), and the remote
/// snapshot is opened with `SQLITE_OPEN_READ_ONLY` — never through
/// `db::open_project`, which migrates/upserts on open. Nothing here
/// writes to the local DB, the sync marker, or the remote dir.
///
/// `writes_log` rows are appended by every durable mutation (see
/// [`db::log_write`]), so `WHERE id > baseline` on each side's own copy
/// gives that side's writes since the fork — both sides' `writes_log`
/// share the same id numbering up to the baseline because a sync
/// (`adopt`/`snapshot`+`commit`) leaves the two byte-identical at that
/// point, and each side's `AUTOINCREMENT` counter continues from there
/// independently.
pub fn diff(start: &Path, remote: &Path) -> Result<DiffReport> {
    let ctx = db::open_project(start)?;
    require_enabled(&ctx.config.sync)?;

    let marker = load_marker(&ctx.paths.memhub_dir)?;
    let Some(marker) = marker else {
        return Ok(diff_unavailable(
            None,
            "no common sync baseline recorded yet (first sync) — a per-table diff needs a \
             shared starting point. Reconcile first (`sync adopt` to take the remote, or \
             `sync snapshot` + `sync commit` to push local), then retry `sync check --diff`.",
        ));
    };
    let baseline_id = marker.baseline.writes_log_max_id;

    let manifest = read_remote_manifest(remote)?;
    let Some(manifest) = manifest else {
        return Ok(diff_unavailable(
            Some(baseline_id),
            format!("no remote snapshot manifest found at {}", remote.display()),
        ));
    };

    let local_schema: String = ctx.conn.query_row(
        "SELECT schema_version FROM projects WHERE id = 1",
        [],
        |row| row.get(0),
    )?;
    let local_ordinal = schema_ordinal(&local_schema)?;
    let schema_blocks = match schema_ordinal(&manifest.schema_version) {
        Ok(remote_ordinal) => remote_ordinal > local_ordinal,
        Err(_) => true,
    };
    if schema_blocks {
        return Ok(diff_unavailable(
            Some(baseline_id),
            format!(
                "remote snapshot schema '{}' is newer than this binary understands ('{}'); \
                 run `memhub upgrade` before diffing",
                manifest.schema_version, local_schema
            ),
        ));
    }

    let snapshot_file = resolve_snapshot_file(remote, &manifest)?;
    if !snapshot_file.exists() {
        return Ok(diff_unavailable(
            Some(baseline_id),
            format!(
                "manifest present but its snapshot is missing at {}",
                snapshot_file.display()
            ),
        ));
    }

    let local = side_diff_since(&ctx.conn, baseline_id)?;

    // Read-only: never opened via `db::open_project` (would migrate/upsert
    // the remote file), and `SQLITE_OPEN_READ_ONLY` refuses any write SQLite
    // itself might otherwise attempt (e.g. journal creation).
    let remote_conn =
        Connection::open_with_flags(&snapshot_file, OpenFlags::SQLITE_OPEN_READ_ONLY)?;
    let remote_side = side_diff_since(&remote_conn, baseline_id)?;

    Ok(DiffReport {
        baseline_writes_log_max_id: Some(baseline_id),
        local: Some(local),
        remote: Some(remote_side),
        unavailable_reason: None,
    })
}

/// One side's [`SideDiff`]: every `writes_log` row past `baseline_id`,
/// aggregated per table. Read-only — a single `SELECT` over `writes_log`
/// plus, for `facts`/`decisions`/`tasks`, one lookup per distinct row
/// touched to resolve its current title/key.
fn side_diff_since(conn: &Connection, baseline_id: i64) -> Result<SideDiff> {
    use std::collections::BTreeMap;

    struct Agg {
        added: i64,
        updated: i64,
        // Distinct row ids touched, in first-seen order, each paired with
        // the most recent writes_log reason (the identifier fallback).
        rows: Vec<(i64, String)>,
    }

    let mut per_table: BTreeMap<String, Agg> = BTreeMap::new();
    let mut writes_since_baseline = 0i64;

    let mut stmt = conn.prepare(
        "SELECT table_name, action, row_id, reason FROM writes_log \
         WHERE project_id = 1 AND id > ?1 ORDER BY id",
    )?;
    let mut rows = stmt.query(params![baseline_id])?;
    while let Some(row) = rows.next()? {
        writes_since_baseline += 1;
        let table: String = row.get(0)?;
        let action: String = row.get(1)?;
        let row_id: Option<i64> = row.get(2)?;
        let reason: Option<String> = row.get(3)?;

        let agg = per_table.entry(table).or_insert(Agg {
            added: 0,
            updated: 0,
            rows: Vec::new(),
        });
        if action == "insert" {
            agg.added += 1;
        } else {
            agg.updated += 1;
        }
        if let Some(rid) = row_id {
            let reason = reason.unwrap_or_default();
            match agg.rows.iter_mut().find(|(id, _)| *id == rid) {
                Some(existing) => existing.1 = reason,
                None => agg.rows.push((rid, reason)),
            }
        }
    }

    let mut tables = Vec::with_capacity(per_table.len());
    for (table, agg) in per_table {
        let changed = match title_column(&table) {
            Some(col) => changed_titles(conn, &table, col, &agg.rows)?,
            None => Vec::new(),
        };
        tables.push(TableDelta {
            table,
            added: agg.added,
            updated: agg.updated,
            changed,
        });
    }

    Ok(SideDiff {
        writes_since_baseline,
        tables,
    })
}

/// Current key/title of each `(row_id, fallback_reason)` in `table`,
/// falling back to the `writes_log` reason (the fallback identifier)
/// when the row no longer exists there — e.g. it was later removed.
fn changed_titles(
    conn: &Connection,
    table: &str,
    title_col: &str,
    rows: &[(i64, String)],
) -> Result<Vec<String>> {
    use rusqlite::OptionalExtension;
    let sql = format!("SELECT {title_col} FROM {table} WHERE project_id = 1 AND id = ?1");
    let mut stmt = conn.prepare(&sql)?;
    let mut out = Vec::with_capacity(rows.len());
    for (row_id, reason) in rows {
        let title: Option<String> = stmt
            .query_row(params![row_id], |row| row.get(0))
            .optional()?;
        out.push(title.unwrap_or_else(|| {
            if reason.is_empty() {
                format!("{table} id {row_id} (no longer present)")
            } else {
                reason.clone()
            }
        }));
    }
    Ok(out)
}

/// Name of the local staging copy `adopt` writes before hashing and
/// installing. Sits inside `.memhub/` (same filesystem as the live DB),
/// never in the Drive folder, so the bytes we hash are the bytes we
/// install — Drive cannot rewrite it between the two.
const INCOMING_FILENAME: &str = "project.sqlite.incoming";

/// Bound on how long the online-backup restore waits for a live external
/// writer to release the destination DB before refusing. SQLite's backup
/// step reports BUSY/LOCKED **without writing anything** when it cannot
/// lock the destination, so a bounded retry that then errors out leaves
/// the original DB fully intact — never a torn, half-restored file.
/// ~2 s worst case (20 × 100 ms), comfortably longer than memhub's own
/// millisecond-scale writes yet still a prompt, deterministic give-up.
const RESTORE_BUSY_RETRIES: u32 = 20;
const RESTORE_BUSY_PAUSE: Duration = Duration::from_millis(100);

/// Restore the pages of the staged snapshot into the live DB **in place**
/// via SQLite's online-backup API, instead of deleting/renaming the DB
/// file out from under any process that holds it open. This is the
/// cross-process-safe swap (F4/X6):
///
/// * **Windows:** a DB file another `memhub` process (a CLI invocation or
///   the long-lived MCP server) holds open cannot be renamed or deleted —
///   the OS raises a sharing violation, so the old delete-`-wal`/`-shm`
///   + `rename` swap would fail outright. The backup API instead writes
///     *through* SQLite's own file locking, so a concurrent process is
///     serialized against and always sees a coherent DB.
/// * **POSIX:** renaming over an open DB there does *not* error; it
///   silently orphans the other process onto the old (now-unlinked)
///   inode, and unlinking `-wal`/`-shm` beside a live connection lets it
///   keep writing to a WAL that no longer matches the DB — a silent
///   divergence. Writing through the backup API avoids both.
///
/// A single `step(-1)` copies every page in one operation, holding the
/// destination's write lock for its duration, so other connections
/// observe either the pre- or post-restore DB, never a partial mix. If
/// the destination is locked, `step` copies nothing and reports BUSY; we
/// retry a bounded number of times and then refuse cleanly, leaving the
/// original DB untouched.
fn restore_into_live_db(staged: &Path, dest_path: &Path) -> Result<()> {
    // Source read-only: the backup only reads it, and read-only opening
    // avoids leaving a stray rollback journal beside the staged file.
    let src = Connection::open_with_flags(staged, OpenFlags::SQLITE_OPEN_READ_ONLY)?;
    // Destination opened plain (default `busy_timeout` = 0) so each locked
    // step returns BUSY immediately and our own bounded loop — not an
    // unbounded internal wait — governs the retry budget.
    let mut dest = Connection::open(dest_path)?;

    let backup = Backup::new(&src, &mut dest)?;
    let mut attempts = 0u32;
    loop {
        // `-1` copies all remaining pages in a single locked step.
        match backup.step(-1)? {
            StepResult::Done => break,
            // Cannot occur for `step(-1)`, but treat it as "keep copying"
            // rather than assume completion.
            StepResult::More => continue,
            StepResult::Busy | StepResult::Locked => {
                attempts += 1;
                if attempts >= RESTORE_BUSY_RETRIES {
                    return Err(MemhubError::InvalidInput(format!(
                        "the local DB at {} is held open by another memhub process; adopt \
                         retried {RESTORE_BUSY_RETRIES} times without writing anything and \
                         gave up. The DB is unchanged — close other memhub processes and \
                         retry `sync adopt`.",
                        dest_path.display()
                    )));
                }
                std::thread::sleep(RESTORE_BUSY_PAUSE);
            }
            // `StepResult` is `#[non_exhaustive]`; a future rusqlite variant
            // we do not understand must fail loudly rather than be treated
            // as success — the DB may be in an unknown state, so refuse.
            other => {
                return Err(MemhubError::InvalidInput(format!(
                    "online-backup restore returned an unrecognized step result ({other:?}); \
                     refusing to treat it as a completed adopt"
                )));
            }
        }
    }
    Ok(())
}

#[derive(Debug)]
pub struct AdoptSummary {
    pub project_id: String,
    pub adopted_from_machine: String,
    pub previous_schema: String,
    pub new_schema: String,
    pub baseline: LogicalVersion,
    pub backup_path: PathBuf,
}

/// Replace the local DB with the Drive-synced snapshot. Destructive,
/// so it **requires `force`** (the CLI `--yes`); the pull skill
/// (`/catch-up`) only reaches here after the operator confirms a
/// `status` verdict.
///
/// Three checks are **hard refusals `force` cannot override**: a
/// project-id mismatch (wrong Drive folder), a snapshot schema newer
/// than — or unparseable by — this binary (run `memhub upgrade` first —
/// §6), and a sha256 that disagrees with the manifest (torn/partial
/// sync). The manifest-only refusals run first; the checksum is verified
/// against a **local staged copy** (see below), so a snapshot Drive
/// rewrites between hashing and install cannot be installed unverified
/// (TOCTOU, F4/X6).
///
/// Install sequence, ordered so a failure at any stage leaves the
/// original DB intact:
/// 1. stage the remote snapshot into `.memhub/project.sqlite.incoming`;
/// 2. hash the *staged* copy and verify it against the manifest;
/// 3. take a pre-adopt safety copy of the current DB to
///    `.memhub/backups/sync/last-replaced.sqlite` via `VACUUM INTO`, so
///    it captures committed WAL state (a raw file copy could miss it);
/// 4. restore the staged snapshot's pages into the live DB through
///    SQLite's online-backup API (see [`restore_into_live_db`]) — no DB
///    file is ever deleted or renamed under a process that may hold it
///    open, and concurrent memhub processes serialize through SQLite's
///    own locking.
pub fn adopt(start: &Path, remote: &Path, force: bool) -> Result<AdoptSummary> {
    let manifest = read_remote_manifest(remote)?.ok_or_else(|| {
        MemhubError::InvalidInput("no snapshot manifest found at the given path".into())
    })?;
    let snapshot_file = resolve_snapshot_file(remote, &manifest)?;
    if !snapshot_file.exists() {
        return Err(MemhubError::InvalidInput(format!(
            "manifest present but its snapshot {} is missing at {}",
            snapshot_file
                .file_name()
                .and_then(|n| n.to_str())
                .unwrap_or(SNAPSHOT_FILENAME),
            snapshot_file.display()
        )));
    }

    let ctx = db::open_project(start)?;
    require_enabled(&ctx.config.sync)?;
    let project_id = resolve_project_id(&ctx.paths.repo_root, &ctx.config.sync)?;
    let previous_schema: String = ctx.conn.query_row(
        "SELECT schema_version FROM projects WHERE id = 1",
        [],
        |row| row.get(0),
    )?;
    let memhub_dir = ctx.paths.memhub_dir.clone();
    let db_path = ctx.paths.db_path.clone();
    let repo_root = ctx.paths.repo_root.clone();

    // ── Manifest-only hard refusals (independent of `force`, evaluated
    //    before any local file is touched) ───────────────────────────
    if manifest.project_id != project_id {
        return Err(MemhubError::InvalidInput(format!(
            "snapshot is for project '{}', not this repo's '{}'; refusing to adopt a \
             wrong-folder snapshot",
            manifest.project_id, project_id
        )));
    }
    // Fail closed on an unreadable manifest schema version: it must
    // hard-refuse here, before any local mutation, naming the field —
    // never collapse to ordinal 0 and slip under the newer-schema guard.
    let snapshot_ordinal = schema_ordinal(&manifest.schema_version).map_err(|_| {
        MemhubError::InvalidInput(format!(
            "snapshot manifest field 'schema_version' = '{}' is not a parseable migration \
             ordinal (expected 'NNNN_name'); refusing to adopt a snapshot whose schema \
             version cannot be read",
            manifest.schema_version
        ))
    })?;
    if snapshot_ordinal > schema_ordinal(&previous_schema)? {
        return Err(MemhubError::InvalidInput(format!(
            "snapshot schema {} is newer than this binary ({}); run `memhub upgrade` first, \
             then retry",
            manifest.schema_version, previous_schema
        )));
    }

    // ── Confirmation gate (before the multi-MB staging copy) ─────────
    if !force {
        return Err(MemhubError::InvalidInput(
            "adopt overwrites the local DB with the Drive snapshot; pass --yes to confirm".into(),
        ));
    }

    // ── Stage the incoming snapshot locally, then hash THAT copy ─────
    // Everything from here reads/writes only the staged local copy and
    // the destination; Drive can rewrite `snapshot_file` freely without
    // affecting what we install.
    let incoming = memhub_dir.join(INCOMING_FILENAME);
    if incoming.exists() {
        fs::remove_file(&incoming)?;
    }
    fs::copy(&snapshot_file, &incoming)?;

    let staged_sha = sha256_file(&incoming)?;
    if staged_sha != manifest.file_sha256 {
        // Torn/partial download, or a snapshot that changed on Drive
        // between manifest-write and now: the staged bytes we would
        // install do not match the manifest. Refuse and drop the stage —
        // no local DB state has been touched.
        let _ = fs::remove_file(&incoming);
        return Err(MemhubError::InvalidInput(
            "snapshot sha256 does not match its manifest (corrupt or partial download); \
             not adopting"
                .into(),
        ));
    }

    // ── Pre-adopt safety copy of the DB being replaced ───────────────
    // `VACUUM INTO` from the still-open connection captures committed WAL
    // state that a raw `fs::copy` of `project.sqlite` alone could miss.
    let backup_dir = memhub_dir.join("backups").join("sync");
    fs::create_dir_all(&backup_dir)?;
    let backup_path = backup_dir.join("last-replaced.sqlite");
    // `VACUUM INTO` refuses to overwrite; clear the single prior slot.
    if backup_path.exists() {
        fs::remove_file(&backup_path)?;
    }
    if let Err(e) = vacuum_into(&ctx.conn, &backup_path) {
        let _ = fs::remove_file(&incoming);
        return Err(e);
    }

    // Close our own connection so the in-place restore serializes only
    // against *other* processes, not this one.
    drop(ctx);

    // ── Restore the staged snapshot into the live DB in place ────────
    // Never deletes or renames the DB/-wal/-shm; writes through SQLite's
    // locking so a concurrent process cannot observe a torn DB. On a
    // busy/locked destination this refuses cleanly with the original DB
    // (and the WAL-inclusive backup above) intact.
    let restore_result = restore_into_live_db(&incoming, &db_path);
    // The stage is transient either way.
    let _ = fs::remove_file(&incoming);
    restore_result?;

    // Reopen: `open_project` migrates forward if the snapshot was older.
    let ctx = db::open_project(&repo_root)?;
    let new_schema: String = ctx.conn.query_row(
        "SELECT schema_version FROM projects WHERE id = 1",
        [],
        |row| row.get(0),
    )?;

    // F3 hygiene: a whole-DB snapshot carries the source machine's
    // `session_metrics`, including any that were open (`ended_at IS NULL`)
    // when it was taken. On this machine those are foreign zombies — close
    // them to their own start so they can neither capture local recalls
    // (belt to the reconciler's window cap) nor linger un-prunable (the
    // pruner only deletes ended sessions). Best-effort, never fatal.
    let _ = ctx.conn.execute(
        "UPDATE session_metrics SET ended_at = started_at WHERE ended_at IS NULL",
        [],
    );
    let synced_at: String = ctx
        .conn
        .query_row("SELECT CURRENT_TIMESTAMP", [], |row| row.get(0))?;
    drop(ctx);

    // The agreed baseline is the snapshot's logical version (local now
    // holds exactly that content; a forward migration changes schema,
    // not `writes_log`).
    save_marker(
        &memhub_dir,
        &SyncMarker {
            project_id: project_id.clone(),
            baseline: manifest.logical_version.clone(),
            baseline_file_sha256: manifest.file_sha256.clone(),
            synced_at,
            last_action: "pull".into(),
        },
    )?;

    Ok(AdoptSummary {
        project_id,
        adopted_from_machine: manifest.machine_id,
        previous_schema,
        new_schema,
        baseline: manifest.logical_version,
        backup_path,
    })
}

#[derive(Debug)]
pub struct CommitSummary {
    pub project_id: String,
    pub baseline: LogicalVersion,
}

/// Record that the local DB now equals the snapshot at `remote` — call
/// after a successful push so the next `status` reads `up-to-date`. The
/// snapshot's manifest is authoritative for what was pushed.
pub fn commit(start: &Path, remote: &Path) -> Result<CommitSummary> {
    let manifest = read_remote_manifest(remote)?.ok_or_else(|| {
        MemhubError::InvalidInput("no snapshot manifest found at the given path".into())
    })?;
    let ctx = db::open_project(start)?;
    require_enabled(&ctx.config.sync)?;
    let project_id = resolve_project_id(&ctx.paths.repo_root, &ctx.config.sync)?;
    if manifest.project_id != project_id {
        return Err(MemhubError::InvalidInput(format!(
            "snapshot project '{}' does not match this repo's '{}'",
            manifest.project_id, project_id
        )));
    }

    // commit() records "local now EQUALS what the remote holds" — so it
    // MUST verify that equality (Claude-sweep finding). Without this check
    // commit() would stamp the remote's logical version as the baseline
    // even when local has diverged from it; a subsequent plain
    // `sync snapshot` would then read LocalAhead and sail through the
    // push-side clobber gate, silently overwriting another machine's push
    // that this machine never adopted. Refuse instead: the operator must
    // reconcile (adopt to take the remote, or re-push to publish local)
    // before a baseline can be recorded. (Decision 161: this local==manifest
    // check IS the fix — no confirm gate is added.)
    let local_logical = LogicalVersion::read(&ctx.conn)?;
    if local_logical != manifest.logical_version {
        return Err(MemhubError::InvalidInput(format!(
            "refusing to record a push baseline: local state does not match the remote manifest. \
             commit() records that local EQUALS the pushed snapshot, but local is [{}] and the \
             manifest is [{}]. The remote has moved on (another machine pushed) or local changed \
             since the push — run `memhub sync check` and reconcile (adopt to take the remote, or \
             `sync snapshot` to re-push local) before committing.",
            describe_logical(&local_logical),
            describe_logical(&manifest.logical_version),
        )));
    }

    let synced_at: String = ctx
        .conn
        .query_row("SELECT CURRENT_TIMESTAMP", [], |row| row.get(0))?;
    save_marker(
        &ctx.paths.memhub_dir,
        &SyncMarker {
            project_id: project_id.clone(),
            baseline: manifest.logical_version.clone(),
            baseline_file_sha256: manifest.file_sha256.clone(),
            synced_at,
            last_action: "push".into(),
        },
    )?;
    Ok(CommitSummary {
        project_id,
        baseline: manifest.logical_version,
    })
}

const SYNC_ACTOR: &str = "cli:user";

#[derive(Debug)]
pub struct EnableResult {
    pub already_enabled: bool,
    /// The resolved Drive-folder id, or the resolution error message
    /// (e.g. "no git remote") so `enable` can guide a no-remote repo to
    /// set `[sync] project_id` without itself failing.
    pub project_id: std::result::Result<String, String>,
}

/// Opt this repo into cross-machine sync (`[sync] enabled = true`).
/// Mirrors `memhub global enable`: idempotent, logs the config change.
pub fn enable(start: &Path) -> Result<EnableResult> {
    let ctx = db::open_project(start)?;
    let already_enabled = ctx.config.sync.enabled;
    let project_id =
        resolve_project_id(&ctx.paths.repo_root, &ctx.config.sync).map_err(|e| e.to_string());

    let mut new_config = ctx.config.clone();
    new_config.sync.enabled = true;
    new_config.save(&ctx.paths.config_path)?;
    db::log_write(
        &ctx.conn,
        SYNC_ACTOR,
        "config",
        None,
        "update",
        "sync enable",
    )?;

    Ok(EnableResult {
        already_enabled,
        project_id,
    })
}

/// Opt this repo back out. Non-destructive: the marker and any local
/// backups stay; the `sync` commands simply refuse again.
pub fn disable(start: &Path) -> Result<()> {
    let ctx = db::open_project(start)?;
    let mut new_config = ctx.config.clone();
    new_config.sync.enabled = false;
    new_config.save(&ctx.paths.config_path)?;
    db::log_write(
        &ctx.conn,
        SYNC_ACTOR,
        "config",
        None,
        "update",
        "sync disable",
    )?;
    Ok(())
}

#[derive(Debug)]
pub struct SyncStatus {
    pub enabled: bool,
    pub project_id: std::result::Result<String, String>,
    pub drive_subpath: String,
    /// Canonical `<drive_subpath>/memhub/<project_id>` push/pull dir, or
    /// the resolution-error message when `drive_subpath` is unset or the
    /// project id cannot be derived.
    pub remote_dir: std::result::Result<String, String>,
    pub local_logical: LogicalVersion,
    pub local_schema: String,
    pub marker: Option<SyncMarker>,
}

/// Enablement + identity view (no Drive comparison). Mirrors
/// `memhub global status`; works whether or not sync is enabled.
pub fn enablement_status(start: &Path) -> Result<SyncStatus> {
    let ctx = db::open_project(start)?;
    let project_id =
        resolve_project_id(&ctx.paths.repo_root, &ctx.config.sync).map_err(|e| e.to_string());
    let local_logical = LogicalVersion::read(&ctx.conn)?;
    let local_schema: String = ctx.conn.query_row(
        "SELECT schema_version FROM projects WHERE id = 1",
        [],
        |row| row.get(0),
    )?;
    let marker = load_marker(&ctx.paths.memhub_dir)?;
    let remote_dir = resolve_remote_dir(&ctx.paths.repo_root, &ctx.config.sync)
        .map(|p| p.display().to_string())
        .map_err(|e| e.to_string());
    Ok(SyncStatus {
        enabled: ctx.config.sync.enabled,
        project_id,
        drive_subpath: ctx.config.sync.drive_subpath.clone(),
        remote_dir,
        local_logical,
        local_schema,
        marker,
    })
}

/// `[sync] enabled = false` → refuse with an actionable hint. Mirrors
/// how the global-store commands gate on `[global] enabled`.
pub fn require_enabled(cfg: &SyncConfig) -> Result<()> {
    if cfg.enabled {
        Ok(())
    } else {
        Err(MemhubError::InvalidInput(
            "cross-machine sync is disabled for this repo; run `memhub sync enable` first".into(),
        ))
    }
}

/// The Drive-folder identity for this repo. Prefers an explicit
/// `[sync] project_id` override (the no-remote escape hatch); otherwise
/// derives a stable id from the git remote URL, which both machines
/// share. Errors with a clear instruction when neither is available.
pub fn resolve_project_id(repo_root: &Path, cfg: &SyncConfig) -> Result<String> {
    let override_id = cfg.project_id.trim();
    if !override_id.is_empty() {
        return Ok(override_id.to_string());
    }
    match git_remote_url(repo_root) {
        Some(url) => Ok(remote_to_id(&url)),
        None => Err(MemhubError::InvalidInput(
            "no git remote to derive a sync project id from; set `[sync] project_id` in \
             .memhub/config.toml to pin one"
                .into(),
        )),
    }
}

/// Canonical Drive snapshot directory for this repo:
/// `<drive_subpath>/memhub/<project_id>`. This is the single source of
/// truth for the layout the skills used to hand-concatenate in prose.
/// Errors when `[sync] drive_subpath` is unset or the project id cannot
/// be resolved (no git remote and no `[sync] project_id` override).
pub fn resolve_remote_dir(repo_root: &Path, cfg: &SyncConfig) -> Result<PathBuf> {
    let subpath = cfg.drive_subpath.trim();
    if subpath.is_empty() {
        return Err(MemhubError::InvalidInput(
            "no `[sync] drive_subpath` set in .memhub/config.toml; set it to the absolute \
             path of the synced Drive folder (e.g. your Google Drive for Desktop mount) \
             before syncing"
                .into(),
        ));
    }
    let base = expand_home(subpath)?;
    let project_id = resolve_project_id(repo_root, cfg)?;
    Ok(base.join(DRIVE_NAMESPACE).join(project_id))
}

/// Expand a leading `~` / `~/` (or `~\` on Windows) in `drive_subpath`
/// to the machine home directory. rclone mounts on Linux commonly live
/// under `~` (e.g. `~/gdrive/memhub-sync`), and the config example
/// itself advertises a `~/Library/CloudStorage/...` macOS path — but
/// `Path::join` treats a literal `~` as a directory named `~`, so an
/// un-expanded tilde silently writes the snapshot into a bogus `./~`
/// tree. Only a leading `~` is expanded (no `~user` form); any other
/// path is returned verbatim, so absolute paths are unaffected.
///
/// `pub(crate)` (rather than private) so `commands::audit_md` can reuse
/// it for `[audit] user_md_path` (issue #32) instead of duplicating
/// this logic — same reuse rationale as the `pub(crate)` doctor checks.
pub(crate) fn expand_home(subpath: &str) -> Result<PathBuf> {
    if subpath == "~" {
        return db::home_dir();
    }
    if let Some(rest) = subpath
        .strip_prefix("~/")
        .or_else(|| subpath.strip_prefix("~\\"))
    {
        return Ok(db::home_dir()?.join(rest));
    }
    Ok(PathBuf::from(subpath))
}

/// Open the project and resolve its canonical remote dir from config.
/// Used by the CLI no-arg default and the MCP `sync_*` tools so neither
/// has to reconstruct `<drive_subpath>/memhub/<project_id>` by hand.
pub fn default_remote_dir(start: &Path) -> Result<PathBuf> {
    let ctx = db::open_project(start)?;
    resolve_remote_dir(&ctx.paths.repo_root, &ctx.config.sync)
}

/// `git -C <root> remote get-url origin`, trimmed. `None` when there is
/// no remote or git is unavailable — the caller turns that into the
/// "set project_id" instruction. OS-agnostic: relies only on `git` on
/// PATH, which both supported platforms have.
fn git_remote_url(repo_root: &Path) -> Option<String> {
    let output = Command::new("git")
        .arg("-C")
        .arg(repo_root)
        .args(["remote", "get-url", "origin"])
        .output()
        .ok()?;
    if !output.status.success() {
        return None;
    }
    let url = String::from_utf8_lossy(&output.stdout).trim().to_string();
    if url.is_empty() { None } else { Some(url) }
}

/// `<repo-slug>-<8 hex of sha256(normalized url)>`. Human-legible in a
/// Drive listing while still collision-resistant. Normalization folds
/// the trivial spellings of the same remote (trailing `.git`, trailing
/// slash, case) so the two machines agree.
fn remote_to_id(url: &str) -> String {
    let normalized = normalize_remote(url);
    let mut hasher = Sha256::new();
    hasher.update(normalized.as_bytes());
    let hash = hasher.finalize();
    let short: String = hash.iter().take(4).map(|b| format!("{b:02x}")).collect();
    format!("{}-{}", repo_slug(&normalized), short)
}

/// Canonicalize a git remote to `host/owner/repo` so that the SSH,
/// HTTPS, and `scheme://` spellings of one repo — plus trailing `.git`,
/// trailing slash, and case — all fold to the same id. Without this, a
/// Mac cloned over HTTPS and a Windows cloned over SSH would point at
/// different Drive folders and silently never sync.
fn normalize_remote(url: &str) -> String {
    let mut s = url.trim().to_ascii_lowercase();
    s = s.trim_end_matches('/').to_string();
    s = s.strip_suffix(".git").unwrap_or(&s).to_string();

    // Drop any URL scheme (`https://`, `ssh://`, `git://`, …).
    if let Some((_, rest)) = s.split_once("://") {
        s = rest.to_string();
    }
    // Drop userinfo (`git@host…`), keeping only what's after the `@`
    // that precedes the host.
    if let Some(at) = s.find('@') {
        let before_slash = s.find('/').map(|i| at < i).unwrap_or(true);
        if before_slash {
            s = s[at + 1..].to_string();
        }
    }
    // SCP-style `host:owner/repo` → `host/owner/repo`. Only the first
    // colon (the host/path separator) is rewritten.
    if let Some(colon) = s.find(':') {
        let is_path_sep = !s[..colon].contains('/');
        if is_path_sep {
            s.replace_range(colon..colon + 1, "/");
        }
    }
    s
}

/// Last path-ish segment of the remote, reduced to `[a-z0-9-]`, capped.
/// Falls back to `repo` when nothing usable remains.
fn repo_slug(normalized_url: &str) -> String {
    let tail = normalized_url
        .rsplit(['/', ':'])
        .find(|s| !s.is_empty())
        .unwrap_or("repo");
    let slug: String = tail
        .chars()
        .map(|c| if c.is_ascii_alphanumeric() { c } else { '-' })
        .collect();
    let slug = slug.trim_matches('-');
    if slug.is_empty() {
        "repo".to_string()
    } else {
        slug.chars().take(32).collect()
    }
}

/// Best-effort, OS-agnostic host label for "who pushed this". Not a
/// security boundary — just human context in the manifest.
///
/// Prefers the `hostname` binary, which exists on macOS, Linux, and
/// Windows; the per-platform env var is a fallback. (On macOS+zsh
/// `HOSTNAME` is a *shell* variable, not an environment one, so the
/// env path alone reports nothing in a non-interactive shell.)
/// `unknown-host` when all paths fail.
fn machine_id() -> String {
    if let Ok(out) = Command::new("hostname").output()
        && out.status.success()
    {
        let name = String::from_utf8_lossy(&out.stdout).trim().to_string();
        if !name.is_empty() {
            return name;
        }
    }
    let env_var = if cfg!(windows) {
        "COMPUTERNAME"
    } else {
        "HOSTNAME"
    };
    std::env::var(env_var)
        .ok()
        .map(|s| s.trim().to_string())
        .filter(|s| !s.is_empty())
        .unwrap_or_else(|| "unknown-host".to_string())
}

/// `VACUUM INTO '<path>'`. SQLite parses the destination as a string
/// expression; we interpolate an escaped literal (double any single
/// quote) rather than bind, since `VACUUM` is not a prepared-parameter
/// statement. The path is memhub-internal, never user SQL.
fn vacuum_into(conn: &Connection, dest: &Path) -> Result<()> {
    let dest = dest
        .to_str()
        .ok_or_else(|| MemhubError::InvalidInput("snapshot path is not valid UTF-8".into()))?;
    let escaped = dest.replace('\'', "''");
    conn.execute_batch(&format!("VACUUM INTO '{escaped}';"))?;
    Ok(())
}

pub fn sha256_file(path: &Path) -> Result<String> {
    let mut file = File::open(path)?;
    let mut hasher = Sha256::new();
    let mut buf = [0u8; 64 * 1024];
    loop {
        let n = file.read(&mut buf)?;
        if n == 0 {
            break;
        }
        hasher.update(&buf[..n]);
    }
    Ok(hasher
        .finalize()
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect())
}

#[cfg(test)]
mod tests {
