            "restore must not corrupt the prior binary's contents"
        );
        // No abandoned `.old-*` file left behind either.
        let leftovers = sweep_stale_old_exes(&cargo_bin);
        assert!(
            leftovers.is_empty(),
            "restore must not leave a renamed-aside file behind: {leftovers:?}"
