            );
            assert!(
                text.contains("memhub command verify") && text.contains("record_command"),
                "level {level:?} missing Q11 routing to command verify/record_command: {text}"
            );
            assert!(text.contains("go-forward only"), "level {level:?}: {text}");
        }
