        let tasks =
            commands::task::list_by_status(&self.start, &status, limit).map_err(map_tool_error)?;
        Ok(Json(ListTasksToolResponse {
            status,
            tasks: tasks.into_iter().map(TaskToolRecord::from).collect(),
        }))
    }

