            .expect("fact count");
        let durable_decision_count: i64 = ctx
            .conn
            .query_row("SELECT COUNT(*) FROM decisions", [], |row| row.get(0))
            .expect("decision count");
        let summary = status::run(temp.path()).expect("status");

