            .expect("count old-1");
        assert_eq!(old_1_gone, 0, "first call must prune the long-dead session");

        // New work arrives inside the debounce window: another
        // unattributed recall and another long-dead session.
        conn.execute(
            "INSERT INTO recall_metrics \
                (ts, session_id, query_hash, bundle_tokens, ledger_tokens, \
                 rerank_used, result_count) \
             VALUES (datetime('now'), NULL, 'q2', 10, 100, 0, 3)",
            [],
        )
        .expect("seed recall 2");
        conn.execute(
            "INSERT INTO session_metrics (session_id, agent, started_at, ended_at) \
             VALUES ('old-2', 'claude-code', datetime('now','-999 days'), \
                     datetime('now','-999 days'))",
            [],
        )
        .expect("seed old-2");

        // Second call, immediately after: must be debounced, so neither
        // the new recall nor the new dead session is touched.
        run_if_enabled(conn, &cfg);
        let unattributed: i64 = conn
            .query_row(
                "SELECT COUNT(*) FROM recall_metrics WHERE session_id IS NULL",
                [],
                |r| r.get(0),
            )
            .expect("count unattributed");
        assert_eq!(
            unattributed, 1,
            "immediate second call must be debounced and skip reconcile"
        );
        let old_2_present: i64 = conn
            .query_row(
                "SELECT COUNT(*) FROM session_metrics WHERE session_id = 'old-2'",
                [],
                |r| r.get(0),
            )
            .expect("count old-2");
        assert_eq!(
            old_2_present, 1,
            "immediate second call must be debounced and skip prune"
        );

        // Backdate the marker past the debounce window (simulate an
        // hour passing) and call a third time: must run again and clear
        // both the pending recall and the newly-dead session.
        conn.execute(
            "UPDATE projects SET metrics_maintenance_last_run_at = \
                datetime('now', '-2 hours') WHERE id = 1",
            [],
        )
        .expect("backdate marker");
        run_if_enabled(conn, &cfg);
        let unattributed_after: i64 = conn
            .query_row(
                "SELECT COUNT(*) FROM recall_metrics WHERE session_id IS NULL",
                [],
                |r| r.get(0),
            )
            .expect("count unattributed after");
        assert_eq!(
            unattributed_after, 0,
            "once stale, the third call must reconcile the pending recall"
        );
        let old_2_gone: i64 = conn
            .query_row(
                "SELECT COUNT(*) FROM session_metrics WHERE session_id = 'old-2'",
                [],
                |r| r.get(0),
            )
            .expect("count old-2 after");
        assert_eq!(
            old_2_gone, 0,
            "once stale, the third call must prune the newly-dead session"
        );
    }
}

//! Opt-in token-accounting subsystem (decision 74).
//!
//! Off by default; users enable it per-machine via
//! `memhub metrics enable`. Two independent components live here:
//!
//! - **Component A — recall proxy**: every `memhub recall` call
//!   appends a row to `recall_metrics` with the bundle size and the
//!   ledger-equivalent baseline so the dashboard can report
//!   "context offset vs full-ledger baseline". Local arithmetic only;
//!   cannot break across Claude Code updates.
//! - **Component B — session accounting**: scrapes agent transcript
//!   JSONL for real `usage.input_tokens` / `usage.output_tokens` /
//!   cache totals. Kept behind its own kill switch in case the
//!   transcript shape shifts.
//!
//! Both share `tokenizer::tokens_of` for size estimates so any
//! ratio between bundle size and ledger size uses the same yardstick.
//!
//! `maintenance` is the shared post-scrape upkeep both components feed:
//! it attributes recall rows to a session by timestamp window and
//! prunes rows past the retention horizon. It runs opportunistically
//! from `db::open_project`, gated by the master switch alone.

#[cfg(feature = "metrics")]
pub mod calibrate;
#[cfg(feature = "metrics")]
pub mod formatter;
#[cfg(feature = "metrics")]
pub mod maintenance;
#[cfg(feature = "metrics")]
pub mod recall_proxy;
#[cfg(feature = "metrics")]
pub mod session_scraper;
// Generic token estimation is also used by `audit md`, so it remains in
// normal builds without activating any metrics collection or surface.
pub mod tokenizer;

//! Component A of the token-accounting subsystem (decision 74,
//! task #28).
//!
//! Logs one row to `recall_metrics` per `memhub recall` call when the
//! user has opted in via `metrics.enabled && metrics.recall_proxy`.
//! No-op otherwise. Local arithmetic only — no external file reads
//! outside the rendered ledger — so this component cannot break
//! across Claude Code updates.

use std::fs;
use std::path::{Path, PathBuf};
use std::sync::{Mutex, OnceLock};
use std::time::{Instant, SystemTime};

use rusqlite::{Connection, params};

use crate::Result;
use crate::config::MetricsConfig;
use crate::metrics::tokenizer::{set_calibration_factor, tokens_of};
use crate::retrieval::util::sha256_hex;
use crate::retrieval::{RecallResponse, RecallSurface};

/// Process-wide ledger token cache. CLI one-shots build it once per
/// invocation; the MCP server amortizes the read across calls.
struct LedgerCacheEntry {
    path: PathBuf,
    mtime: SystemTime,
    tokens: usize,
    cached_at: Instant,
}

static LEDGER_CACHE: OnceLock<Mutex<Option<LedgerCacheEntry>>> = OnceLock::new();

const LEDGER_CACHE_TTL_SECS: u64 = 60;
const LEDGER_FILENAME: &str = "PROJECT_LEDGER.md";

/// Log one `recall_metrics` row for the call that just produced
/// `response`. Honors the `metrics.enabled` master switch and the
/// `metrics.recall_proxy` sub-switch; when either is off this is a
/// zero-cost no-op (one bool check + return). Errors are not
/// propagated to the caller — losing a metrics row must never fail
/// an otherwise-successful recall.
pub fn log_recall(
    conn: &Connection,
    cfg: &MetricsConfig,
    project_root: &Path,
    render_output_dir: &str,
    query: &str,
    response: &RecallResponse,
    surface: Option<RecallSurface>,
) {
    if !cfg.enabled || !cfg.recall_proxy {
        return;
    }
    // Apply the machine's stored tokenizer calibration (task 63) so the
    // bundle/ledger counts written below approximate Anthropic's real
    // tokenizer. Default 1.0 is an exact passthrough, so an uncalibrated
    // install logs identical numbers to a pre-calibration build.
    set_calibration_factor(cfg.calibration_factor);
    if let Err(err) = try_log_recall(
        conn,
        project_root,
        render_output_dir,
        query,
        response,
        surface,
    ) {
        log::warn!("recall_metrics insert failed: {err}");
    }
}

fn try_log_recall(
    conn: &Connection,
    project_root: &Path,
    render_output_dir: &str,
    query: &str,
    response: &RecallResponse,
    surface: Option<RecallSurface>,
) -> Result<()> {
    let query_hash = sha256_hex(query.as_bytes());
    let bundle_tokens = bundle_token_estimate(response);
    let ledger_tokens = ledger_token_estimate(project_root, render_output_dir);
    let rerank_used = if response.matcher == "recall:hybrid+rerank" {
        1
    } else {
        0
    };
    let result_count = response.results.len() as i64;
    // NULL for internal callers (eval sweeps, dashboard inspector, upgrade
    // smoke check) — none of them reach here anyway since they all pass
    // `log_metrics: false`. 'cli' / 'mcp' for the two agent-facing entry
    // points (issue #70 / Wave 4 gate Q17).
    let surface_str = surface.map(RecallSurface::as_str);

    conn.execute(
        "INSERT INTO recall_metrics \
            (ts, session_id, query_hash, bundle_tokens, ledger_tokens, rerank_used, \
             result_count, surface) \
         VALUES (CURRENT_TIMESTAMP, NULL, ?1, ?2, ?3, ?4, ?5, ?6)",
        params![
            query_hash,
            bundle_tokens as i64,
            ledger_tokens as i64,
            rerank_used,
            result_count,
            surface_str,
        ],
    )?;
    Ok(())
}

fn bundle_token_estimate(response: &RecallResponse) -> usize {
    // Sum tokens over what the agent actually reads from each hit:
    // the title and body. Per-hit metadata (score, source, ts) is
    // small constant overhead that doesn't move the ratio against
    // ledger_tokens; counting only title+body keeps the proxy stable
    // even if RecallHit grows new metadata fields later.
    response
        .results
        .iter()
        .map(|hit| tokens_of(&format!("{}\n{}", hit.title, hit.body)))
        .sum()
}

fn ledger_token_estimate(project_root: &Path, render_output_dir: &str) -> usize {
    let path = project_root.join(render_output_dir).join(LEDGER_FILENAME);
    let mtime = match fs::metadata(&path).and_then(|m| m.modified()) {
        Ok(m) => m,
        Err(_) => return 0,
    };

    let cache = LEDGER_CACHE.get_or_init(|| Mutex::new(None));
    if let Ok(guard) = cache.lock()
        && let Some(entry) = guard.as_ref()
        && entry.path == path
        && entry.mtime == mtime
        && entry.cached_at.elapsed().as_secs() < LEDGER_CACHE_TTL_SECS
    {
        return entry.tokens;
    }

    let body = match fs::read_to_string(&path) {
        Ok(s) => s,
        Err(_) => return 0,
    };
    let tokens = tokens_of(&body);

    if let Ok(mut guard) = cache.lock() {
        *guard = Some(LedgerCacheEntry {
            path,
            mtime,
            tokens,
            cached_at: Instant::now(),
        });
    }
    tokens
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::config::{ProjectConfig, RetrievalMode};

    /// A minimal, result-free `RecallResponse` — `log_recall` only reads
    /// `results` (for `bundle_token_estimate`) and `matcher`, so an empty
    /// bundle is enough to exercise the INSERT itself without dragging in
    /// a full recall fixture.
    fn empty_response(query: &str) -> RecallResponse {
        RecallResponse {
            query: query.to_string(),
            mode: RetrievalMode::Fts,
            results: Vec::new(),
            candidate_count: 0,
            returned_count: 0,
            warnings: Vec::new(),
            matcher: "recall:fts".to_string(),
            elapsed_ms: 0,
            available_docs: 0,
        }
    }

    /// Issue #70 / Wave 4 gate Q17: `log_recall`'s `surface` argument must
    /// land verbatim as the `recall_metrics.surface` column — `'cli'` /
    /// `'mcp'` — so a follow-up can split latency by calling surface.
    #[test]
    fn log_recall_writes_the_calling_surface() {
        let temp = tempfile::tempdir().expect("tempdir");
        crate::commands::init::run(temp.path()).expect("init");
        let cfg_path = temp.path().join(".memhub/config.toml");
        let mut cfg = ProjectConfig::load(&cfg_path).expect("load");
        cfg.metrics.enabled = true;
        cfg.metrics.recall_proxy = true;
        cfg.save(&cfg_path).expect("save");

        let ctx = crate::db::open_project(temp.path()).expect("open");

        log_recall(
            &ctx.conn,
            &ctx.config.metrics,
            &ctx.paths.repo_root,
            &ctx.config.render.output_dir,
            "cli query",
            &empty_response("cli query"),
            Some(RecallSurface::Cli),
        );
        log_recall(
            &ctx.conn,
            &ctx.config.metrics,
            &ctx.paths.repo_root,
            &ctx.config.render.output_dir,
            "mcp query",
            &empty_response("mcp query"),
            Some(RecallSurface::Mcp),
        );

        let mut stmt = ctx
            .conn
            .prepare("SELECT surface FROM recall_metrics ORDER BY id")
            .expect("prepare");
        let rows: Vec<Option<String>> = stmt
            .query_map([], |r| r.get(0))
            .expect("query")
            .collect::<std::result::Result<Vec<_>, _>>()
            .expect("collect");

        assert_eq!(
            rows,
            vec![Some("cli".to_string()), Some("mcp".to_string())],
            "surface column must record each call's actual calling surface"
        );
    }

    #[test]
    fn sha256_is_deterministic_and_hex() {
        let a = sha256_hex("memhub recall".as_bytes());
        let b = sha256_hex("memhub recall".as_bytes());
        assert_eq!(a, b);
        assert_eq!(a.len(), 64);
        assert!(a.chars().all(|c| c.is_ascii_hexdigit()));
    }
}

//! Component B of the token-accounting subsystem (decision 74,
//! task #29).
//!
//! Scrapes Claude Code transcript JSONL for the *real*
//! `usage.input_tokens` / `usage.output_tokens` / cache totals an
//! agent burned, and UPSERTs them into `session_metrics`. Unlike
//! Component A (local arithmetic, cannot break), this component reads
//! an external file format owned by Claude Code, so it lives behind
//! its own `metrics.session_accounting` kill switch and is written
//! defensively: a shape mismatch logs and continues, it never fails
//! the host `memhub` command.
//!
//! ## Cadence
//!
//! `scrape_if_enabled` is called once from `db::open_project`, so it
//! runs opportunistically on every `memhub` invocation — no daemon,
//! no cron (decision 74). Repeated calls within one process (e.g. an
//! eval sweep that recalls many times) are cheap: a session whose
//! file length already equals its recorded `last_scanned_offset` is
//! skipped without opening the file.
//!
//! ## Incremental resume
//!
//! Claude Code writes one append-only `<session-id>.jsonl` per
//! session. We seek to the session's `last_scanned_offset`, read only
//! complete newline-terminated lines, accumulate token deltas, and
//! advance the offset to the byte after the last `\n`. A trailing
//! partial line (the session is still being written) is left
//! unconsumed for the next pass, so no turn is double-counted and no
//! half-written JSON line is parsed.
//!
//! Token counters accumulate (`+= excluded`) rather than replace,
//! because each pass only ever reads the bytes appended since the
//! last pass. `started_at` is pinned to the earliest line seen;
//! `ended_at` advances to the latest. `recall_calls` is deliberately
//! left untouched here — the reconciler (task #30) owns it.
//!
//! ## Deviation from the task wording
//!
//! Task #29 step 2 says "skip files whose mtime <= max(last_scan_ts)".
//! Migration 0012 has no `last_scan_ts` column, and an mtime/clock
//! comparison is fragile (a `touch` or clock skew defeats it).
//! Instead we skip when `file_len == last_scanned_offset`: exact,
//! schema-native, and immune to clock issues. A file shorter than its
//! recorded offset is treated as rotated/rewritten and re-scanned
//! from zero after zeroing that session's counters.

use std::fs::{self, File};
use std::io::{BufRead, BufReader, Seek, SeekFrom};
use std::path::Path;

use rusqlite::{Connection, OptionalExtension, params};
use serde_json::Value;

use crate::Result;
use crate::config::MetricsConfig;
use crate::db::log_write;
pub use crate::transcript_files::{
    claude_session_id_from_path, codex_session_id_from_path, find_claude_transcript,
    find_codex_transcript,
};

const CLAUDE_AGENT: &str = "claude-code";
const SCRAPER_ACTOR: &str = "metrics:claude-scraper";
const CODEX_AGENT: &str = "codex";
const CODEX_SCRAPER_ACTOR: &str = "metrics:codex-scraper";

/// Opportunistic entry point. Gated by the `metrics.enabled` master
/// switch and the `metrics.session_accounting` sub-switch; both off by
/// default, so this is a zero-cost early return on a non-opted-in
/// install. Errors are swallowed (logged, never propagated) — losing a
/// metrics scrape must never fail an otherwise-successful command.
///
/// `repo_root` is used to filter Codex sessions: Codex writes all
/// projects' sessions to `~/.codex/sessions/`, so each file is checked
/// against `session_meta.payload.cwd` before any rows are written
/// (decision 77).
pub fn scrape_if_enabled(conn: &Connection, cfg: &MetricsConfig, repo_root: &Path) {
    if !cfg.enabled || !cfg.session_accounting {
        return;
    }

    if !cfg.claude_transcripts_dir.is_empty() {
        let dir = Path::new(&cfg.claude_transcripts_dir);
        if let Err(err) = scrape_claude_dir(conn, dir) {
            log::warn!("session_metrics scrape of {} failed: {err}", dir.display());
        }
    }

    if !cfg.codex_transcripts_dir.is_empty() {
        let dir = Path::new(&cfg.codex_transcripts_dir);
        if let Err(err) = scrape_codex_dir(conn, dir, repo_root) {
            log::warn!(
                "session_metrics codex scrape of {} failed: {err}",
                dir.display()
            );
        }
    }
}

/// Scrape every `*.jsonl` directly under `dir`. A missing directory is
/// not an error (the user enabled metrics but the path hasn't produced
/// transcripts yet); other directory-read failures propagate.
fn scrape_claude_dir(conn: &Connection, dir: &Path) -> Result<()> {
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(err) if err.kind() == std::io::ErrorKind::NotFound => return Ok(()),
        Err(err) => return Err(err.into()),
    };

    for entry in entries {
        let path = match entry {
            Ok(e) => e.path(),
            Err(err) => {
                log::debug!("metrics: skipping unreadable dir entry: {err}");
                continue;
            }
        };
        if path.extension().and_then(|e| e.to_str()) != Some("jsonl") {
            continue;
        }
        // One bad file must not stop the others.
        if let Err(err) = scrape_claude_file(conn, &path) {
            log::warn!("metrics: skipping session file {}: {err}", path.display());
        }
    }
    Ok(())
}

/// Scrape the Codex sessions tree: `~/.codex/sessions/YYYY/MM/DD/*.jsonl`.
/// The tree is global (all projects share it), so each file is filtered by
/// `session_meta.payload.cwd` before rows are written (decision 77).
fn scrape_codex_dir(conn: &Connection, dir: &Path, repo_root: &Path) -> Result<()> {
    let l1_entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(err) if err.kind() == std::io::ErrorKind::NotFound => return Ok(()),
        Err(err) => return Err(err.into()),
    };
    let canonical_root = repo_root
        .canonicalize()
        .unwrap_or_else(|_| repo_root.to_path_buf());
    for l1 in l1_entries {
        let l1 = match l1 {
            Ok(e) => e,
            Err(_) => continue,
        };
        if !l1.file_type().map(|t| t.is_dir()).unwrap_or(false) {
            continue;
        }
        let l2_entries = match fs::read_dir(l1.path()) {
            Ok(e) => e,
            Err(_) => continue,
        };
        for l2 in l2_entries {
            let l2 = match l2 {
                Ok(e) => e,
                Err(_) => continue,
            };
            if !l2.file_type().map(|t| t.is_dir()).unwrap_or(false) {
                continue;
            }
            let l3_entries = match fs::read_dir(l2.path()) {
                Ok(e) => e,
                Err(_) => continue,
            };
            for l3 in l3_entries {
                let l3 = match l3 {
                    Ok(e) => e,
                    Err(_) => continue,
                };
                if !l3.file_type().map(|t| t.is_dir()).unwrap_or(false) {
                    continue;
                }
                let file_entries = match fs::read_dir(l3.path()) {
                    Ok(e) => e,
                    Err(_) => continue,
                };
                for entry in file_entries {
                    let path = match entry {
                        Ok(e) => e.path(),
                        Err(_) => continue,
                    };
                    if path.extension().and_then(|e| e.to_str()) != Some("jsonl") {
                        continue;
                    }
                    if let Err(err) = scrape_codex_file(conn, &path, &canonical_root) {
                        log::warn!(
                            "metrics: skipping codex session file {}: {err}",
                            path.display()
                        );
                    }
                }
            }
        }
    }
    Ok(())
}

/// Scrape one Codex session file.
///
/// Codex session IDs are prefixed with `codex:` to prevent any PK
/// collision with Claude session UUIDs (decision 77).
///
/// Token mapping (decision 77):
///   `last_token_usage.input_tokens`            → input_tokens
///   `last_token_usage.cached_input_tokens`      → cache_read_tokens
///   `last_token_usage.output_tokens`            → output_tokens (base)
///   `last_token_usage.reasoning_output_tokens`  → rolled into output_tokens
///   cache_creation_tokens                       → always 0 (no Codex equivalent)
fn scrape_codex_file(conn: &Connection, path: &Path, canonical_root: &Path) -> Result<()> {
    // Session id: `codex:<UUID>` where the UUID is the last 5
    // hyphen-delimited groups of the stem (shared with the archiver).
    let session_id = match codex_session_id_from_path(path) {
        Some(id) => id,
        None => {
            log::debug!(
                "metrics: codex stem has too few hyphen parts, skipping: {}",
                path.display()
            );
            return Ok(());
        }
    };

    let file_len = fs::metadata(path)?.len();

    let existing_offset: Option<i64> = conn
        .query_row(
            "SELECT last_scanned_offset FROM session_metrics WHERE session_id = ?1",
            params![session_id],
            |row| row.get(0),
        )
        .optional()?
        .flatten();

    let mut offset = existing_offset.unwrap_or(0).max(0) as u64;

    if existing_offset.is_some() && file_len == offset {
        return Ok(());
    }

    if file_len < offset {
        conn.execute(
            "UPDATE session_metrics SET \
                input_tokens = 0, output_tokens = 0, \
                cache_read_tokens = 0, cache_creation_tokens = 0, \
                last_scanned_offset = 0 \
             WHERE session_id = ?1",
            params![session_id],
        )?;
        conn.execute(
            "DELETE FROM session_turn_metrics WHERE session_id = ?1",
            params![session_id],
        )?;
        let _ = log_write(
            conn,
            CODEX_SCRAPER_ACTOR,
            "session_metrics",
            None,
            "scrape_reset",
            &format!(
                "{} shrank ({} < {}); rescanning from 0",
                path.display(),
                file_len,
                offset
            ),
        );
        offset = 0;
    }

    // CWD filter: only needed for sessions we haven't seen before.
    // On a resume (existing_offset.is_some()) the project already matched.
    if existing_offset.is_none() && !codex_session_matches_project(path, canonical_root) {
        return Ok(());
    }

    let mut file = File::open(path)?;
    file.seek(SeekFrom::Start(offset))?;
    let mut reader = BufReader::new(file);

    let mut d = Delta::default();
    let mut buf = Vec::new();
    loop {
        buf.clear();
        let n = reader.read_until(b'\n', &mut buf)?;
        if n == 0 {
            break;
        }
        if buf.last() != Some(&b'\n') {
            break;
        }
        d.consumed += n as u64;
        ingest_codex_line(&String::from_utf8_lossy(&buf), &mut d);
    }

    if d.consumed == 0 {
        return Ok(());
    }

    let new_offset = (offset + d.consumed) as i64;

    conn.execute(
        "INSERT INTO session_metrics \
            (session_id, agent, started_at, ended_at, \
             input_tokens, output_tokens, cache_read_tokens, \
             cache_creation_tokens, recall_calls, last_scanned_offset, \
             baseline_input_tokens) \
         VALUES (?1, ?2, COALESCE(?3, CURRENT_TIMESTAMP), ?4, \
                 ?5, ?6, ?7, 0, 0, ?8, ?9) \
         ON CONFLICT(session_id) DO UPDATE SET \
            input_tokens          = input_tokens          + excluded.input_tokens, \
            output_tokens         = output_tokens         + excluded.output_tokens, \
            cache_read_tokens     = cache_read_tokens     + excluded.cache_read_tokens, \
            cache_creation_tokens = cache_creation_tokens + excluded.cache_creation_tokens, \
            ended_at              = COALESCE(excluded.ended_at, session_metrics.ended_at), \
            last_scanned_offset   = excluded.last_scanned_offset, \
            baseline_input_tokens = COALESCE(session_metrics.baseline_input_tokens, \
                                             excluded.baseline_input_tokens)",
        params![
            session_id,
            CODEX_AGENT,
            d.min_ts,
            d.max_ts,
            d.input,
            d.output,
            d.cache_read,
            new_offset,
            d.baseline(),
        ],
    )?;

    if !d.turns.is_empty() {
        let mut stmt = conn.prepare(
            "INSERT INTO session_turn_metrics \
                (session_id, ts, input_tokens, output_tokens, \
                 cache_read_tokens, cache_creation_tokens) \
             VALUES (?1, ?2, ?3, ?4, ?5, ?6)",
        )?;
        for turn in &d.turns {
            stmt.execute(params![
                session_id,
                turn.ts,
                turn.input,
                turn.output,
                turn.cache_read,
                turn.cache_creation,
            ])?;
        }
    }

    if d.parse_skips > 0 {
        let _ = log_write(
            conn,
            CODEX_SCRAPER_ACTOR,
            "session_metrics",
            None,
            "scrape_skip",
            &format!(
                "{}: {} unparseable/foreign line(s) skipped, {} token_count line(s) counted",
                path.display(),
                d.parse_skips,
                d.lines_with_usage
            ),
        );
    }

    Ok(())
}

/// Read the first line of a Codex session file and return true when
/// `session_meta.payload.cwd` matches `canonical_root`.
fn codex_session_matches_project(path: &Path, canonical_root: &Path) -> bool {
    let file = match File::open(path) {
        Ok(f) => f,
        Err(_) => return false,
    };
    let mut reader = BufReader::new(file);
    let mut line = String::new();
    if reader.read_line(&mut line).is_err() {
        return false;
    }
    let v: Value = match serde_json::from_str(line.trim()) {
        Ok(v) => v,
        Err(_) => return false,
    };
    if v.get("type").and_then(Value::as_str) != Some("session_meta") {
        return false;
    }
    let cwd = match v
        .get("payload")
        .and_then(|p| p.get("cwd"))
        .and_then(Value::as_str)
    {
        Some(c) => c,
        None => return false,
    };
    let cwd_path = std::path::Path::new(cwd);
    let canonical_cwd = cwd_path
        .canonicalize()
        .unwrap_or_else(|_| cwd_path.to_path_buf());
    canonical_cwd == canonical_root
}

/// Parse one Codex `event_msg / token_count` line and fold its
/// `last_token_usage` into `d`. Any other event type is silently
/// ignored (not a skip). `reasoning_output_tokens` is rolled into
/// `output_tokens`; `cache_creation_tokens` is always 0.
fn ingest_codex_line(line: &str, d: &mut Delta) {
    let line = line.trim();
    if line.is_empty() {
        return;
    }

    let v: Value = match serde_json::from_str(line) {
        Ok(v) => v,
        Err(_) => {
            d.parse_skips += 1;
            return;
        }
    };

    let line_ts: Option<String> = v
        .get("timestamp")
        .and_then(Value::as_str)
        .map(str::to_string);
    if let Some(ts) = line_ts.clone() {
        if d.min_ts.as_ref().is_none_or(|m| ts < *m) {
            d.min_ts = Some(ts.clone());
        }
        if d.max_ts.as_ref().is_none_or(|m| ts > *m) {
            d.max_ts = Some(ts);
        }
    }

    if v.get("type").and_then(Value::as_str) != Some("event_msg") {
        return;
    }
    let payload = match v.get("payload") {
        Some(p) => p,
        None => return,
    };
    if payload.get("type").and_then(Value::as_str) != Some("token_count") {
        return;
    }
    let info = match payload.get("info") {
        Some(i) if !i.is_null() => i,
        _ => return,
    };
    let last = match info.get("last_token_usage") {
        Some(l) if !l.is_null() => l,
        _ => return,
    };

    let n = |key: &str| -> i64 { last.get(key).and_then(Value::as_i64).unwrap_or(0) };

    let input = n("input_tokens");
    let cache_read = n("cached_input_tokens");
    let output = n("output_tokens") + n("reasoning_output_tokens");

    d.input += input;
    d.output += output;
    d.cache_read += cache_read;
    d.lines_with_usage += 1;
    d.turns.push(TurnRecord {
        ts: line_ts,
        input,
        output,
        cache_read,
        cache_creation: 0,
    });
}

/// One usage-bearing assistant line, captured verbatim for the
/// per-turn (`session_turn_metrics`) curve. The session-level
/// aggregate still comes from the summed `Delta` fields below; this is
/// purely additional granularity, not a replacement.
#[derive(Default)]
struct TurnRecord {
    ts: Option<String>,
    input: i64,
    output: i64,
    cache_read: i64,
    cache_creation: i64,
}

/// Accumulated token deltas + timestamp bounds for a single scrape
/// pass over one file's newly appended bytes.
#[derive(Default)]
struct Delta {
    input: i64,
    output: i64,
    cache_read: i64,
    cache_creation: i64,
    min_ts: Option<String>,
    max_ts: Option<String>,
    consumed: u64,
    parse_skips: u64,
    lines_with_usage: u64,
    /// One entry per usage-bearing line, in transcript (consume) order.
    turns: Vec<TurnRecord>,
}

impl Delta {
    /// Full prompt size of this pass's FIRST usage turn — input plus both
    /// cache fields (task 64, decision 109). On a session's first pass
    /// (offset 0) that turn is the session's true first usage line, so the
    /// sum approximates everything loaded at session start (system prompt +
    /// CLAUDE.md + PROJECT.md + any handoff md). Under prompt caching most
    /// of that is billed as cache_read/cache_creation rather than
    /// input_tokens, so all three are summed. `None` when the pass consumed
    /// no usage line; the UPSERT then leaves `baseline_input_tokens` NULL
    /// for a later pass to fill.
    fn baseline(&self) -> Option<i64> {
        self.turns
            .first()
            .map(|t| t.input + t.cache_read + t.cache_creation)
    }
}

fn scrape_claude_file(conn: &Connection, path: &Path) -> Result<()> {
    // Claude Code names the file `<session-id>.jsonl`; the stem is the
    // stable per-session key (the in-line `sessionId` is expected to
    // match and is treated as a cross-check, not the key, so we can
    // resolve the resume offset before reading a single byte). Shared
    // with the archiver via `claude_session_id_from_path`.
    let session_id = match claude_session_id_from_path(path) {
        Some(id) => id,
        None => {
            log::debug!(
                "metrics: session file with no usable stem: {}",
                path.display()
            );
            return Ok(());
        }
    };

    let file_len = fs::metadata(path)?.len();

    let existing_offset: Option<i64> = conn
        .query_row(
            "SELECT last_scanned_offset FROM session_metrics WHERE session_id = ?1",
            params![session_id],
            |row| row.get(0),
        )
        .optional()?
        .flatten();

    let mut offset = existing_offset.unwrap_or(0).max(0) as u64;

    if existing_offset.is_some() && file_len == offset {
        // No bytes appended since the last pass — the cheap skip.
        return Ok(());
    }

    if file_len < offset {
        // Shorter than what we already consumed: the session file was
        // rotated or rewritten. Re-scan from zero, but first zero the
        // accumulators so the additive UPSERT doesn't double-count the
        // surviving prefix. recall_calls is left alone (task #30).
        conn.execute(
            "UPDATE session_metrics SET \
                input_tokens = 0, output_tokens = 0, \
                cache_read_tokens = 0, cache_creation_tokens = 0, \
                last_scanned_offset = 0 \
             WHERE session_id = ?1",
            params![session_id],
        )?;
        // The per-turn rows mirror the consumed prefix; a from-zero
        // re-scan would re-insert all of them, so drop this session's
        // turn history too. The session_metrics row is kept (zeroed)
        // because its recall_calls is owned by the reconciler.
        conn.execute(
            "DELETE FROM session_turn_metrics WHERE session_id = ?1",
            params![session_id],
        )?;
        let _ = log_write(
            conn,
            SCRAPER_ACTOR,
            "session_metrics",
            None,
            "scrape_reset",
            &format!(
                "{} shrank ({} < {}); rescanning from 0",
                path.display(),
                file_len,
                offset
            ),
        );
        offset = 0;
    }

    let mut file = File::open(path)?;
    file.seek(SeekFrom::Start(offset))?;
    let mut reader = BufReader::new(file);

    let mut d = Delta::default();
    let mut buf = Vec::new();
    loop {
        buf.clear();
        let n = reader.read_until(b'\n', &mut buf)?;
        if n == 0 {
            break; // EOF
        }
        if buf.last() != Some(&b'\n') {
            // Trailing partial line: the session is still being
            // written. Leave it unconsumed for the next pass.
            break;
        }
        d.consumed += n as u64;
        ingest_line(&String::from_utf8_lossy(&buf), &mut d);
    }

    if d.consumed == 0 {
        // Only a partial line (or nothing) past the offset. Don't
        // create or touch a row; don't advance the offset.
        return Ok(());
    }

    let new_offset = (offset + d.consumed) as i64;

    // Additive UPSERT. started_at is NOT NULL: fall back to
    // CURRENT_TIMESTAMP when the consumed lines carried no parseable
    // timestamp. On conflict, started_at is intentionally not updated
    // (keep the earliest) and ended_at only moves forward.
    conn.execute(
        "INSERT INTO session_metrics \
            (session_id, agent, started_at, ended_at, \
             input_tokens, output_tokens, cache_read_tokens, \
             cache_creation_tokens, recall_calls, last_scanned_offset, \
             baseline_input_tokens) \
         VALUES (?1, ?2, COALESCE(?3, CURRENT_TIMESTAMP), ?4, \
                 ?5, ?6, ?7, ?8, 0, ?9, ?10) \
         ON CONFLICT(session_id) DO UPDATE SET \
            input_tokens          = input_tokens          + excluded.input_tokens, \
            output_tokens         = output_tokens         + excluded.output_tokens, \
            cache_read_tokens     = cache_read_tokens     + excluded.cache_read_tokens, \
            cache_creation_tokens = cache_creation_tokens + excluded.cache_creation_tokens, \
            ended_at              = COALESCE(excluded.ended_at, session_metrics.ended_at), \
            last_scanned_offset   = excluded.last_scanned_offset, \
            baseline_input_tokens = COALESCE(session_metrics.baseline_input_tokens, \
                                             excluded.baseline_input_tokens)",
        params![
            session_id,
            CLAUDE_AGENT,
            d.min_ts,
            d.max_ts,
            d.input,
            d.output,
            d.cache_read,
            d.cache_creation,
            new_offset,
            d.baseline(),
        ],
    )?;

    // Per-turn granularity (migration 0013). Done AFTER the
    // offset-advancing UPSERT on purpose: if these inserts fail the
    // offset has already moved, so the pass under-counts the curve by
    // a few turns rather than re-reading the bytes next pass and
    // double-inserting. Under-count is the conservative direction for
    // an advisory subsystem, matching this module's "never fatal".
    // Each consumed usage line maps to exactly one row (rows are never
    // updated), so plain INSERTs stay idempotent across resumes.
    if !d.turns.is_empty() {
        let mut stmt = conn.prepare(
            "INSERT INTO session_turn_metrics \
                (session_id, ts, input_tokens, output_tokens, \
                 cache_read_tokens, cache_creation_tokens) \
             VALUES (?1, ?2, ?3, ?4, ?5, ?6)",
        )?;
        for turn in &d.turns {
            stmt.execute(params![
                session_id,
                turn.ts,
                turn.input,
                turn.output,
                turn.cache_read,
                turn.cache_creation,
            ])?;
        }
    }

    if d.parse_skips > 0 {
        // One summary row per file per pass — never one per bad line,
        // which could flood writes_log on a foreign-format file.
        let _ = log_write(
            conn,
            SCRAPER_ACTOR,
            "session_metrics",
            None,
            "scrape_skip",
            &format!(
                "{}: {} unparseable/foreign line(s) skipped, {} usage line(s) counted",
                path.display(),
                d.parse_skips,
                d.lines_with_usage
            ),
        );
    }

    Ok(())
}

/// Parse one JSONL line and fold its usage into `d`. Defensive: any
/// line that isn't a JSON object, isn't an assistant turn, or lacks a
/// `usage` block is counted as a skip and ignored. A line is never
/// allowed to abort the scrape.
fn ingest_line(line: &str, d: &mut Delta) {
    let line = line.trim();
    if line.is_empty() {
        return; // blank line: not a skip, just nothing
    }

    let v: Value = match serde_json::from_str(line) {
        Ok(v) => v,
        Err(_) => {
            d.parse_skips += 1;
            return;
        }
    };

    // Timestamp bounds track *every* line (user + assistant), so a
    // session with only user turns so far still gets a sane window.
    // The same value is later pinned onto this line's TurnRecord.
    let line_ts: Option<String> = v
        .get("timestamp")
        .and_then(Value::as_str)
        .map(str::to_string);
    if let Some(ts) = line_ts.clone() {
        if d.min_ts.as_ref().is_none_or(|m| ts < *m) {
            d.min_ts = Some(ts.clone());
        }
        if d.max_ts.as_ref().is_none_or(|m| ts > *m) {
            d.max_ts = Some(ts);
        }
    }

    // Usage lives on assistant turns under message.usage in the Claude
    // Code shape; tolerate a top-level `usage` too in case the shape
    // shifts. A line without usage isn't an error (user turns, tool
    // results, summaries) — only count it as a skip if it also failed
    // to look like a known event at all.
    let usage = v
        .get("message")
        .and_then(|m| m.get("usage"))
        .or_else(|| v.get("usage"));

    let usage = match usage {
        Some(u) => u,
        None => return, // non-usage event: silently ignored
    };

    let n = |key: &str| -> i64 { usage.get(key).and_then(Value::as_i64).unwrap_or(0) };

    let input = n("input_tokens");
    let output = n("output_tokens");
    let cache_read = n("cache_read_input_tokens");
    let cache_creation = n("cache_creation_input_tokens");

    d.input += input;
    d.output += output;
    d.cache_read += cache_read;
    d.cache_creation += cache_creation;
    d.lines_with_usage += 1;
    d.turns.push(TurnRecord {
        ts: line_ts,
        input,
        output,
        cache_read,
        cache_creation,
    });
}

#[cfg(test)]
mod tests {
    use super::*;

    fn d_after(lines: &[&str]) -> Delta {
        let mut d = Delta::default();
        for l in lines {
            ingest_line(l, &mut d);
        }
        d
    }

    #[test]
    fn sums_usage_across_assistant_turns_in_claude_shape() {
        let d = d_after(&[
            r#"{"type":"user","timestamp":"2026-05-15T09:00:00.000Z","message":{"role":"user"}}"#,
            r#"{"type":"assistant","timestamp":"2026-05-15T09:00:05.000Z","message":{"role":"assistant","usage":{"input_tokens":120,"output_tokens":40,"cache_read_input_tokens":900,"cache_creation_input_tokens":50}}}"#,
            r#"{"type":"assistant","timestamp":"2026-05-15T09:01:00.000Z","message":{"role":"assistant","usage":{"input_tokens":200,"output_tokens":60}}}"#,
        ]);
        assert_eq!(d.input, 320);
        assert_eq!(d.output, 100);
        assert_eq!(d.cache_read, 900);
        assert_eq!(d.cache_creation, 50);
        assert_eq!(d.lines_with_usage, 2);
        assert_eq!(d.parse_skips, 0);
        assert_eq!(d.min_ts.as_deref(), Some("2026-05-15T09:00:00.000Z"));
        assert_eq!(d.max_ts.as_deref(), Some("2026-05-15T09:01:00.000Z"));
    }

    #[test]
    fn malformed_json_is_a_counted_skip_not_a_failure() {
        let d = d_after(&[
            r#"{not json"#,
            r#"{"type":"assistant","message":{"usage":{"input_tokens":10}}}"#,
            "",
        ]);
        assert_eq!(d.parse_skips, 1);
        assert_eq!(d.input, 10);
        assert_eq!(d.lines_with_usage, 1);
    }

    #[test]
    fn non_usage_events_are_ignored_without_skip_inflation() {
        let d = d_after(&[
            r#"{"type":"user","message":{"role":"user","content":"hi"}}"#,
            r#"{"type":"summary","summary":"..."}"#,
        ]);
        assert_eq!(d.parse_skips, 0);
        assert_eq!(d.lines_with_usage, 0);
        assert_eq!(d.input, 0);
    }

    #[test]
    fn tolerates_top_level_usage_shape_drift() {
        let d = d_after(&[r#"{"type":"assistant","usage":{"input_tokens":7,"output_tokens":3}}"#]);
        assert_eq!(d.input, 7);
        assert_eq!(d.output, 3);
    }

    #[test]
    fn captures_one_turn_record_per_usage_line_with_its_own_ts() {
        let d = d_after(&[
            r#"{"type":"user","timestamp":"2026-05-15T09:00:00.000Z","message":{"role":"user"}}"#,
            r#"{"type":"assistant","timestamp":"2026-05-15T09:00:05.000Z","message":{"role":"assistant","usage":{"input_tokens":120,"output_tokens":40}}}"#,
            r#"{"type":"assistant","timestamp":"2026-05-15T09:01:00.000Z","message":{"role":"assistant","usage":{"input_tokens":200,"output_tokens":60,"cache_read_input_tokens":10}}}"#,
        ]);
        // Per-turn rows: one per usage line, NOT one per transcript line.
        assert_eq!(d.turns.len(), 2);
        assert_eq!(d.turns[0].ts.as_deref(), Some("2026-05-15T09:00:05.000Z"));
        assert_eq!(d.turns[0].input, 120);
        assert_eq!(d.turns[0].output, 40);
        assert_eq!(d.turns[1].ts.as_deref(), Some("2026-05-15T09:01:00.000Z"));
        assert_eq!(d.turns[1].cache_read, 10);
        // Aggregate is still the sum — per-turn is purely additive.
        assert_eq!(d.input, 320);
        assert_eq!(d.output, 100);
    }

    #[test]
    fn non_usage_and_malformed_lines_produce_no_turn_records() {
        let d = d_after(&[
            r#"{"type":"user","message":{"role":"user","content":"hi"}}"#,
            r#"{not json"#,
            r#"{"type":"summary","summary":"..."}"#,
        ]);
        assert!(d.turns.is_empty());
    }

    fn write(path: &std::path::Path, lines: &[&str]) {
        let mut body = lines.join("\n");
        body.push('\n');
        std::fs::write(path, body).expect("write transcript");
    }

    #[test]
    fn scrape_persists_per_turn_rows_alongside_session_aggregate() {
        let temp = tempfile::tempdir().expect("tempdir");
        crate::commands::init::run(temp.path()).expect("init");
        let ctx = crate::db::open_project(temp.path()).expect("open");
        let conn = &ctx.conn;

        let file = temp.path().join("sess-A.jsonl");
        write(
            &file,
            &[
                r#"{"type":"user","timestamp":"2026-05-15T10:00:00.000Z","message":{"role":"user"}}"#,
                r#"{"type":"assistant","timestamp":"2026-05-15T10:00:01.000Z","message":{"usage":{"input_tokens":100,"output_tokens":20}}}"#,
                r#"{"type":"assistant","timestamp":"2026-05-15T10:00:09.000Z","message":{"usage":{"input_tokens":300,"output_tokens":40}}}"#,
            ],
        );
        scrape_claude_file(conn, &file).expect("scrape");

        let (turns, sum_in, sum_out): (i64, i64, i64) = conn
            .query_row(
                "SELECT COUNT(*), COALESCE(SUM(input_tokens),0), \
                        COALESCE(SUM(output_tokens),0) \
                 FROM session_turn_metrics WHERE session_id = 'sess-A'",
                [],
                |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?)),
            )
            .expect("turn query");
        assert_eq!(turns, 2, "one row per usage line");
        assert_eq!(sum_in, 400);
        assert_eq!(sum_out, 60);

        // The aggregate session row must match the per-turn sum.
        let (agg_in, agg_out): (i64, i64) = conn
            .query_row(
                "SELECT input_tokens, output_tokens FROM session_metrics \
                 WHERE session_id = 'sess-A'",
                [],
                |r| Ok((r.get(0)?, r.get(1)?)),
            )
            .expect("session query");
        assert_eq!(agg_in, 400);
        assert_eq!(agg_out, 60);
    }

    #[test]
    fn baseline_is_first_turn_full_prompt_and_not_overwritten_on_resume() {
        let temp = tempfile::tempdir().expect("tempdir");
        crate::commands::init::run(temp.path()).expect("init");
        let ctx = crate::db::open_project(temp.path()).expect("open");
        let conn = &ctx.conn;
        let file = temp.path().join("sess-base.jsonl");

        // First usage line: full startup prompt is split across input +
        // cache_read + cache_creation under caching → baseline = 2615 + 9209
        // + 13702 = 25526 (the real-data shape from the DB).
        write(
            &file,
            &[
                r#"{"type":"user","timestamp":"2026-05-15T10:00:00.000Z","message":{"role":"user"}}"#,
                r#"{"type":"assistant","timestamp":"2026-05-15T10:00:01.000Z","message":{"usage":{"input_tokens":2615,"output_tokens":40,"cache_read_input_tokens":9209,"cache_creation_input_tokens":13702}}}"#,
            ],
        );
        scrape_claude_file(conn, &file).expect("scrape 1");

