| Key | Value | Source | Verified | Stale | Superseded |
|-----|-------|--------|----------|-------|------------|
| build-command | cargo build | user | 2026-01-01T00:00:00Z | no | no |

";
        assert!(
            ledger.contains(expected_block),
            "untagged facts block must render byte-identically to pre-#97:\n{ledger}"
        );
        assert!(
            !ledger.contains("Kind"),
            "no fact is tagged, so the Kind column must not appear at all:\n{ledger}"
        );
    }

    /// A tagged corpus adds the "Kind" column; the tag surfaces in its row.
    #[test]
    fn ledger_facts_block_adds_kind_column_when_tagged() {
        let snapshot = minimal_snapshot(vec![fact(
            1,
            "build-command",
            "cargo build",
            Some("command"),
        )]);
        let ledger = format_ledger_md(&snapshot);

        let expected_block = "\
## Facts

_1 fact(s), 0 stale._

| Key | Value | Source | Verified | Stale | Superseded | Kind |
|-----|-------|--------|----------|-------|------------|------|
| build-command | cargo build | user | 2026-01-01T00:00:00Z | no | no | command |

";
        assert!(
            ledger.contains(expected_block),
            "tagged facts block must render the Kind column byte-for-byte:\n{ledger}"
        );
    }

    /// Mixed corpus: the Kind column appears (one fact is tagged) but the
    /// untagged sibling's cell renders blank rather than "no fact" text.
    #[test]
    fn ledger_facts_block_blanks_kind_cell_for_untagged_row_in_mixed_corpus() {
        let snapshot = minimal_snapshot(vec![
            fact(1, "build-command", "cargo build", Some("command")),
            fact(2, "other-fact", "some value", None),
        ]);
        let ledger = format_ledger_md(&snapshot);

        assert!(
            ledger.contains(
                "| build-command | cargo build | user | 2026-01-01T00:00:00Z | no | no | command |\n"
            ),
            "tagged row must show its kind:\n{ledger}"
        );
        assert!(
            ledger.contains(
                "| other-fact | some value | user | 2026-01-01T00:00:00Z | no | no |  |\n"
            ),
            "untagged row must render a blank Kind cell, not be dropped:\n{ledger}"
        );
    }
}

//! BGE-small-en-v1.5 embedding wrapper.
//!
//! The ONNX model and tokenizer files are bundled into the memhub binary at
//! build time by `build.rs`. The first call to [`embed_one`] or
//! [`embed_batch`] constructs the fastembed [`TextEmbedding`] handle; all
//! subsequent calls reuse it.

use std::sync::{Mutex, OnceLock};

use fastembed::{
    InitOptionsUserDefined, Pooling, TextEmbedding, TokenizerFiles, UserDefinedEmbeddingModel,
};

use crate::{MemhubError, Result};

pub const EMBEDDING_MODEL_NAME: &str = "bge-small-en-v1.5";
pub const EMBEDDING_DIMENSION: usize = 384;

/// Per-inference batch size handed to fastembed. fastembed's default (256)
/// pads every chunk in a batch to the longest sequence and allocates the
/// transformer's activation tensors for the whole batch at once; for long
/// inputs (code chunks carry whole function/type bodies) that peaks at
/// several GB and OOM-kills memory-constrained hosts — e.g. backfilling a
/// ~600-chunk code index hit ~6.8 GB RSS on an 8 GB Raspberry Pi 5. A modest
/// cap bounds peak memory roughly linearly (16 vs 256 ≈ 16× less) at a
/// negligible throughput cost, since the model is already resident. Output
/// vectors are unaffected — batch size only governs how many texts share one
/// forward pass, and fastembed preserves input order across batches.
const EMBED_BATCH_SIZE: usize = 16;

const MODEL_ONNX: &[u8] = include_bytes!(concat!(env!("OUT_DIR"), "/bge-small-en-v1.5/model.onnx"));
const TOKENIZER_JSON: &[u8] = include_bytes!(concat!(
    env!("OUT_DIR"),
    "/bge-small-en-v1.5/tokenizer.json"
));
const CONFIG_JSON: &[u8] =
    include_bytes!(concat!(env!("OUT_DIR"), "/bge-small-en-v1.5/config.json"));
const SPECIAL_TOKENS_JSON: &[u8] = include_bytes!(concat!(
    env!("OUT_DIR"),
    "/bge-small-en-v1.5/special_tokens_map.json"
));
const TOKENIZER_CONFIG_JSON: &[u8] = include_bytes!(concat!(
    env!("OUT_DIR"),
    "/bge-small-en-v1.5/tokenizer_config.json"
));

static MODEL: OnceLock<Mutex<TextEmbedding>> = OnceLock::new();

fn shared() -> Result<&'static Mutex<TextEmbedding>> {
    if let Some(m) = MODEL.get() {
        return Ok(m);
    }
    let tokenizer_files = TokenizerFiles {
        tokenizer_file: TOKENIZER_JSON.to_vec(),
        config_file: CONFIG_JSON.to_vec(),
        special_tokens_map_file: SPECIAL_TOKENS_JSON.to_vec(),
        tokenizer_config_file: TOKENIZER_CONFIG_JSON.to_vec(),
    };
    let user_model = UserDefinedEmbeddingModel::new(MODEL_ONNX.to_vec(), tokenizer_files)
        .with_pooling(Pooling::Cls);
    let model = TextEmbedding::try_new_from_user_defined(user_model, InitOptionsUserDefined::new())
        .map_err(|e| {
            MemhubError::Embedding(format!("failed to load {EMBEDDING_MODEL_NAME}: {e}"))
        })?;
    // If another thread won the race, drop ours and return the winner.
    Ok(MODEL.get_or_init(|| Mutex::new(model)))
}

/// Embed a single text into a 384-dim vector.
pub fn embed_one(text: &str) -> Result<Vec<f32>> {
    let mut out = embed_batch(&[text])?;
    out.pop()
        .ok_or_else(|| MemhubError::Embedding("empty embedding output".to_string()))
}

/// Embed a batch of texts. Each output is a 384-dim vector in the same order.
///
/// Inference is split into [`EMBED_BATCH_SIZE`]-text passes to bound peak
/// memory on small hosts; fastembed preserves input order across passes, so
/// callers can pass an arbitrarily large slice without exhausting RAM.
pub fn embed_batch<S: AsRef<str> + Send + Sync>(texts: &[S]) -> Result<Vec<Vec<f32>>> {
    if texts.is_empty() {
        return Ok(Vec::new());
    }
    let cell = shared()?;
    let mut model = cell
        .lock()
        .map_err(|e| MemhubError::Embedding(format!("model mutex poisoned: {e}")))?;
    let documents: Vec<&str> = texts.iter().map(AsRef::as_ref).collect();
    model
        .embed(documents, Some(EMBED_BATCH_SIZE))
        .map_err(|e| MemhubError::Embedding(format!("embed failed: {e}")))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn smoke_embed_dimension_and_finite() {
        let v = embed_one("memhub local-first project memory").expect("embed_one");
        assert_eq!(v.len(), EMBEDDING_DIMENSION, "expected 384-dim vector");
        assert!(
            v.iter().all(|f| f.is_finite()),
            "embedding contained non-finite values"
        );
        let norm: f32 = v.iter().map(|f| f * f).sum::<f32>().sqrt();
        // BGE outputs are L2-normalized by fastembed; allow some float slack.
        assert!(
            (0.5..=1.5).contains(&norm),
            "embedding norm {norm} is unexpectedly far from 1.0"
        );
    }

    #[test]
    fn smoke_embed_batch_preserves_order_and_length() {
        let texts = vec!["alpha", "beta", "gamma"];
        let vecs = embed_batch(&texts).expect("embed_batch");
        assert_eq!(vecs.len(), 3);
        assert!(vecs.iter().all(|v| v.len() == EMBEDDING_DIMENSION));
        // alpha and beta should not be identical vectors.
        assert!(vecs[0] != vecs[1]);
    }

    #[test]
    fn embed_batch_spanning_multiple_passes_preserves_order_and_count() {
        // More texts than EMBED_BATCH_SIZE so fastembed must run several
        // forward passes; the result must still be one vector per input, in
        // input order, with no cross-pass shuffling. Guards the batch cap
        // (memory fix) against silently dropping or reordering rows.
        let texts: Vec<String> = (0..EMBED_BATCH_SIZE * 2 + 3)
            .map(|i| format!("distinct embedding probe number {i}"))
            .collect();
        let refs: Vec<&str> = texts.iter().map(String::as_str).collect();
        let vecs = embed_batch(&refs).expect("embed_batch");
        assert_eq!(vecs.len(), refs.len());
        assert!(vecs.iter().all(|v| v.len() == EMBEDDING_DIMENSION));
        // A single-text embed of one input must match its slot in the batch,
        // proving order is preserved across the pass boundary.
        let probe_idx = EMBED_BATCH_SIZE + 1;
        let solo = embed_one(refs[probe_idx]).expect("embed_one");
        let max_delta = solo
            .iter()
            .zip(&vecs[probe_idx])
            .map(|(a, b)| (a - b).abs())
            .fold(0.0_f32, f32::max);
        assert!(
            max_delta < 1e-3,
            "batched vector diverged from solo embed (max delta {max_delta})"
        );
    }
}

//! Retrieval layer for memhub M8 (SQL+RAG hybrid recall).
//!
//! Owns the bundled embedding model and (as of task #21) the bundled
//! cross-encoder re-ranker. The hybrid scoring path lives in `recall`;
//! `rerank` is the optional post-blend reordering step gated by
//! `[retrieval] use_reranker` in project config.

pub mod embeddings;
pub mod persist;
pub mod recall;
pub mod rerank;
pub mod util;

pub use embeddings::{EMBEDDING_DIMENSION, EMBEDDING_MODEL_NAME, embed_batch, embed_one};
pub use persist::{
    SourceType, decision_embed_text, doc_chunk_embed_text, eager_embed_batch_in_tx,
    eager_embed_in_tx, fact_embed_text, note_embed_text, task_embed_text,
};
pub use recall::{RecallHit, RecallOptions, RecallResponse, RecallSurface, RecallWarning, recall};
pub use rerank::RERANKER_MODEL_NAME;

//! Eager-embed write path for retrieval (M8 PR3).
//!
//! Fact/decision/task writers call into this module inside the same DB
//! transaction as the source-row write. Per addendum §5 the flow is:
//!   1. Compute a stable content_hash over the embed text.
//!   2. Look up the existing embedding row for (source_type, source_id,
//!      active model).
//!   3. If the hash matches, no-op (the embedding is already current).
//!   4. Otherwise run the embedding model and UPSERT the row inside the
//!      same transaction.
//!
//! When [`RetrievalMode::Fts`] is configured the whole path is a no-op:
//! the embedding model never loads and the embeddings table stays empty.
//! Switching to [`RetrievalMode::Hybrid`] on an existing repo will need
//! a one-shot backfill (`memhub index rebuild` — not yet shipped) before
//! the embeddings table is fully populated.

use rusqlite::{OptionalExtension, Transaction, params};

use crate::config::RetrievalMode;
use crate::retrieval::embeddings::{
    EMBEDDING_DIMENSION, EMBEDDING_MODEL_NAME, embed_batch, embed_one,
};
use crate::retrieval::util::{sha256_hex, vector_to_le_bytes};
use crate::{MemhubError, Result};

/// Source row kind that an embedding refers back to.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum SourceType {
    Fact,
    Decision,
    Task,
    DocChunk,
    Note,
}

impl SourceType {
    pub fn as_str(self) -> &'static str {
        match self {
            SourceType::Fact => "fact",
            SourceType::Decision => "decision",
            SourceType::Task => "task",
            SourceType::DocChunk => "doc_chunk",
            SourceType::Note => "note",
        }
    }
}

/// Build the embed text for a fact. Embeds key + value so the model sees
/// the label and the body in one short sentence-like string.
pub fn fact_embed_text(key: &str, value: &str) -> String {
    format!("{key}: {value}")
}

/// Build the embed text for a decision. When `summary` is present and
/// non-empty, it is prepended so the bi-encoder picks up the natural-
/// language framing in addition to the (often jargon-heavy) title. Title
/// and rationale are separated by a blank line so the tokenizer sees
/// them as distinct segments. See decision 72 / task #23.
pub fn decision_embed_text(title: &str, rationale: &str, summary: Option<&str>) -> String {
    match summary {
        Some(s) if !s.trim().is_empty() => format!("{s}\n\n{title}\n\n{rationale}"),
        _ => format!("{title}\n\n{rationale}"),
    }
}

/// Build the embed text for a task. Notes are optional; when present they
/// follow the title separated by a blank line.
pub fn task_embed_text(title: &str, notes: Option<&str>) -> String {
    match notes {
        Some(n) if !n.is_empty() => format!("{title}\n\n{n}"),
        _ => title.to_string(),
    }
}

/// Build the embed text for a doc chunk. The heading-path breadcrumb
/// (e.g. `Components > Buttons`) acts as the title-analog so the
/// bi-encoder and cross-encoder both see the section context, not just
/// the prose body. Mirrors the `title\n\nbody` shape used for tasks.
pub fn doc_chunk_embed_text(heading_path: &str, body: &str) -> String {
    if heading_path.trim().is_empty() {
        body.to_string()
    } else {
        format!("{heading_path}\n\n{body}")
    }
}

/// Build the embed text for a session note. Notes carry only free-form
/// `text` — no title-analog field like a doc chunk's heading_path or a
/// fact's key — and `actor` is provenance (like `source` on facts/
/// decisions), not content, so it stays out of the embed text the same
/// way `source` does. The body is embedded verbatim.
pub fn note_embed_text(text: &str) -> String {
    text.to_string()
}

/// Eager-embed entry point. No-op when mode != Hybrid.
pub fn eager_embed_in_tx(
    tx: &Transaction<'_>,
    mode: RetrievalMode,
    source_type: SourceType,
    source_id: i64,
    embed_text: &str,
) -> Result<()> {
    if mode != RetrievalMode::Hybrid {
        return Ok(());
    }

    let content_hash = sha256_hex(embed_text.as_bytes());
    let source_type_str = source_type.as_str();

    let existing_hash: Option<String> = tx
        .query_row(
            "SELECT content_hash FROM embeddings
             WHERE source_type = ?1 AND source_id = ?2 AND model_name = ?3",
            params![source_type_str, source_id, EMBEDDING_MODEL_NAME],
            |row| row.get(0),
        )
        .optional()?;

    if existing_hash.as_deref() == Some(content_hash.as_str()) {
        return Ok(());
    }

    let vector = embed_one(embed_text)?;
    if vector.len() != EMBEDDING_DIMENSION {
        return Err(MemhubError::Embedding(format!(
            "expected {EMBEDDING_DIMENSION}-dim vector, got {}",
            vector.len()
        )));
    }
    let blob = vector_to_le_bytes(&vector);

    tx.execute(
        "DELETE FROM embeddings
         WHERE source_type = ?1 AND source_id = ?2 AND model_name = ?3",
        params![source_type_str, source_id, EMBEDDING_MODEL_NAME],
    )?;
    tx.execute(
        "INSERT INTO embeddings(
            project_id, source_type, source_id, model_name,
            dimension, vector, content_hash
        ) VALUES (1, ?1, ?2, ?3, ?4, ?5, ?6)",
        params![
            source_type_str,
            source_id,
            EMBEDDING_MODEL_NAME,
            EMBEDDING_DIMENSION as i64,
            blob,
            content_hash,
        ],
    )?;

    Ok(())
}

/// Batched counterpart to [`eager_embed_in_tx`] for callers that insert many
/// rows of the same `source_type` in one transaction (currently doc-chunk
/// ingest, see `commands::doc::insert_chunks`). Same semantics row for
/// row — mode-gated no-op, unchanged-content-hash rows skipped, DELETE then
/// INSERT the vector — but every row still needing an embedding is sent to
/// the model in a single [`embed_batch`] call instead of one model call per
/// row, which is where the per-chunk cost actually lives (batching amortizes
/// ONNX inference overhead; the SQLite hash-check stays per-row because it's
/// cheap and lets an unchanged row skip embedding entirely).
pub fn eager_embed_batch_in_tx(
    tx: &Transaction<'_>,
    mode: RetrievalMode,
    source_type: SourceType,
    rows: Vec<(i64, String)>,
) -> Result<()> {
    if mode != RetrievalMode::Hybrid || rows.is_empty() {
        return Ok(());
    }

    let source_type_str = source_type.as_str();

    // Same skip-if-unchanged check as the single-row path, run up front so
    // only rows that actually need a new vector go into the batch call.
    let mut pending: Vec<(i64, String, String)> = Vec::with_capacity(rows.len());
    for (source_id, embed_text) in rows {
        let content_hash = sha256_hex(embed_text.as_bytes());
        let existing_hash: Option<String> = tx
            .query_row(
                "SELECT content_hash FROM embeddings
                 WHERE source_type = ?1 AND source_id = ?2 AND model_name = ?3",
                params![source_type_str, source_id, EMBEDDING_MODEL_NAME],
                |row| row.get(0),
            )
            .optional()?;
        if existing_hash.as_deref() == Some(content_hash.as_str()) {
            continue;
        }
        pending.push((source_id, embed_text, content_hash));
    }

    if pending.is_empty() {
        return Ok(());
    }

    let texts: Vec<&str> = pending.iter().map(|(_, t, _)| t.as_str()).collect();
    let vectors = embed_batch(&texts)?;

    for ((source_id, _, content_hash), vector) in pending.iter().zip(vectors) {
        if vector.len() != EMBEDDING_DIMENSION {
            return Err(MemhubError::Embedding(format!(
                "expected {EMBEDDING_DIMENSION}-dim vector, got {}",
                vector.len()
            )));
        }
        let blob = vector_to_le_bytes(&vector);

        tx.execute(
            "DELETE FROM embeddings
             WHERE source_type = ?1 AND source_id = ?2 AND model_name = ?3",
            params![source_type_str, source_id, EMBEDDING_MODEL_NAME],
        )?;
        tx.execute(
            "INSERT INTO embeddings(
                project_id, source_type, source_id, model_name,
                dimension, vector, content_hash
            ) VALUES (1, ?1, ?2, ?3, ?4, ?5, ?6)",
            params![
                source_type_str,
                source_id,
                EMBEDDING_MODEL_NAME,
                EMBEDDING_DIMENSION as i64,
                blob,
                content_hash,
            ],
        )?;
    }

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn decision_embed_text_without_summary_matches_legacy_format() {
        let out = decision_embed_text("Title", "Rationale body", None);
        assert_eq!(out, "Title\n\nRationale body");
    }

    #[test]
    fn decision_embed_text_with_summary_prepends_it() {
        let out = decision_embed_text(
            "content_hash drift detection per embedding",
            "Store a hash of source body alongside each vector.",
            Some("How does memhub know when an embedding has gone stale?"),
        );
        assert_eq!(
            out,
            "How does memhub know when an embedding has gone stale?\n\n\
             content_hash drift detection per embedding\n\n\
             Store a hash of source body alongside each vector."
        );
    }

    #[test]
    fn decision_embed_text_treats_empty_or_whitespace_summary_as_absent() {
        // Empty and whitespace-only summaries must not pollute the embed
        // text with a leading blank, which would change content_hash and
        // force a spurious re-embed across every machine.
        assert_eq!(decision_embed_text("T", "R", Some("")), "T\n\nR");
        assert_eq!(decision_embed_text("T", "R", Some("   \n  ")), "T\n\nR");
    }

    // eager_embed_batch_in_tx has no real FK on embeddings.source_id (see
    // migration 0014's comment — the key is the polymorphic (source_type,
    // source_id) pair), so these unit tests exercise it directly against
    // synthetic source_ids rather than needing real doc_chunks rows.

    #[test]
    fn eager_embed_batch_in_tx_is_noop_outside_hybrid_mode() {
        let temp = tempfile::tempdir().expect("tempdir");
        crate::commands::init::run(temp.path()).expect("init");
        let mut ctx = crate::db::open_project(temp.path()).expect("open");
        let tx = ctx.conn.transaction().expect("tx");

        eager_embed_batch_in_tx(
            &tx,
            RetrievalMode::Fts,
            SourceType::DocChunk,
            vec![(1, "some text".to_string())],
        )
        .expect("noop");

        let count: i64 = tx
            .query_row("SELECT COUNT(*) FROM embeddings", [], |r| r.get(0))
            .expect("count");
        assert_eq!(count, 0, "Fts mode must never write an embedding row");
    }

    #[test]
    fn eager_embed_batch_in_tx_skips_unchanged_and_reembeds_changed() {
        let temp = tempfile::tempdir().expect("tempdir");
        crate::commands::init::run(temp.path()).expect("init");
        let mut ctx = crate::db::open_project(temp.path()).expect("open");
        let tx = ctx.conn.transaction().expect("tx");

        eager_embed_batch_in_tx(
            &tx,
            RetrievalMode::Hybrid,
            SourceType::DocChunk,
            vec![(1, "alpha text".to_string()), (2, "beta text".to_string())],
        )
        .expect("first batch");
        let count: i64 = tx
            .query_row("SELECT COUNT(*) FROM embeddings", [], |r| r.get(0))
            .expect("count after first batch");
        assert_eq!(count, 2);
        let hash1: String = tx
            .query_row(
                "SELECT content_hash FROM embeddings
                 WHERE source_type = 'doc_chunk' AND source_id = 1",
                [],
                |r| r.get(0),
            )
            .expect("hash1");

        // Row 1 unchanged, row 2 changed, plus a brand new row 3 in the
        // same batch call — must skip 1, re-embed 2, insert 3.
        eager_embed_batch_in_tx(
            &tx,
            RetrievalMode::Hybrid,
            SourceType::DocChunk,
            vec![
                (1, "alpha text".to_string()),
                (2, "beta text CHANGED".to_string()),
                (3, "gamma text".to_string()),
            ],
        )
        .expect("second batch");

        let count: i64 = tx
            .query_row("SELECT COUNT(*) FROM embeddings", [], |r| r.get(0))
            .expect("count after second batch");
        assert_eq!(
            count, 3,
            "row 1 skip + row 2 update + row 3 insert => 3 total rows"
        );

        let hash1_again: String = tx
            .query_row(
                "SELECT content_hash FROM embeddings
                 WHERE source_type = 'doc_chunk' AND source_id = 1",
                [],
                |r| r.get(0),
            )
            .expect("hash1 again");
        assert_eq!(
            hash1, hash1_again,
            "unchanged row must be skipped, not re-embedded"
        );

        let hash2: String = tx
            .query_row(
                "SELECT content_hash FROM embeddings
                 WHERE source_type = 'doc_chunk' AND source_id = 2",
                [],
                |r| r.get(0),
            )
            .expect("hash2");
        assert_eq!(hash2, sha256_hex("beta text CHANGED".as_bytes()));
    }
}

//! Hybrid SQL+RAG recall surface (M8 PR4).
//!
//! Reads from durable facts/decisions/tasks tables, ranks them with a
//! blend of FTS5 BM25 (per-source-type) and brute-force cosine similarity
//! over the per-row embeddings (hybrid mode only), and returns a ranked
//! evidence bundle to the caller. The shape mirrors the addendum's
//! §8 specification of `memhub.recall`.
//!
//! Stays read-only: never writes to durable tables, never writes to
//! pending_writes, never records to `writes_log`.

use std::collections::{HashMap, HashSet};
use std::path::Path;
use std::time::Instant;

use rusqlite::{Connection, Row, params};

use crate::config::{RetrievalMode, RetrievalScoringConfig};
use crate::db;
use crate::retrieval::embeddings::{EMBEDDING_DIMENSION, EMBEDDING_MODEL_NAME, embed_one};
use crate::retrieval::persist::{
    SourceType, decision_embed_text, doc_chunk_embed_text, fact_embed_text, note_embed_text,
    task_embed_text,
};
use crate::retrieval::rerank;
use crate::retrieval::util::{
    build_fts_match, bytes_to_vector, cosine_similarity, normalize_fts, sha256_hex,
};
use crate::{MemhubError, Result};

const PER_SOURCE_FTS_LIMIT: i64 = 50;

/// Which agent-facing surface issued a recall — the CLI process or the
/// MCP server's `recall` tool (issue #70, Wave 4 gate Q17 / decision
/// 148). Threaded into `RecallOptions` purely so `recall_proxy::log_recall`
/// can tag the `recall_metrics.surface` column; nothing else reads it.
/// Q17 asks whether CLI-issued recalls feel slower than MCP-issued ones,
/// and this is the signal a follow-up analysis needs to split by caller.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RecallSurface {
    Cli,
    Mcp,
}

impl RecallSurface {
    pub fn as_str(self) -> &'static str {
        match self {
            RecallSurface::Cli => "cli",
            RecallSurface::Mcp => "mcp",
        }
    }
}

/// Caller-supplied recall request.
#[derive(Debug, Clone)]
pub struct RecallOptions {
    pub query: String,
    /// Optional override of `[retrieval] mode`. None = use project config.
    pub mode: Option<RetrievalMode>,
    /// 0 means "use config default".
    pub max_results: usize,
    /// Empty = all source types allowed.
    pub source_types: Vec<SourceType>,
    /// Override of `include_stale_by_default`.
    pub include_stale: Option<bool>,
    /// Override of `accepted_only_by_default`.
    pub accepted_only: Option<bool>,
    /// Override of `[retrieval] use_reranker`. None = use project config.
    /// Ignored when mode resolves to fts (re-ranker only runs on hybrid).
    pub use_reranker: Option<bool>,
    /// Override of `[retrieval.scoring] min_rerank_score`. None = use
    /// project config. Ignored when mode resolves to fts or when the
    /// re-ranker is disabled (the floor only applies to rerank scores).
    /// Exists primarily to support `memhub eval retrieval
    /// --min-rerank-score` calibration sweeps (decisions 70, 71).
    pub min_rerank_score: Option<f32>,
    /// Append a `recall_metrics` row for this call (component A of
    /// decision 74's token-accounting subsystem). The agent-facing
    /// call sites — CLI and MCP server — set this to `true`. Eval
    /// sweeps and the viz dashboard's recall inspector pass `false`
    /// because calibration runs and human inspection are not the
    /// "real usage" the dashboard reports on. The `metrics.enabled`
    /// master switch gates the actual insert separately, so setting
    /// this `true` on a non-opted-in install is still a no-op.
    pub log_metrics: bool,
    /// Which surface issued this call — `Some(Cli)` / `Some(Mcp)` at the
    /// two agent-facing entry points, `None` everywhere else (eval
    /// sweeps, the dashboard's recall inspector, the upgrade smoke
    /// check, and unit tests that never log a row). Only consulted when
    /// `log_metrics` is true; `None` there is accurate, not a gap, since
    /// those callers never write to `recall_metrics` at all.
    pub surface: Option<RecallSurface>,
}

/// Corpus a recall hit came from. Repo-local always; `"global"` only
/// when the repo opted into machine-global memory and the store had a
/// match (M9). Precedence is provenance-tag-only: recall never drops a
/// hit for being global — the agent applies repo-overrides-global.
pub const SCOPE_REPO: &str = "repo";
pub const SCOPE_GLOBAL: &str = "global";

#[derive(Debug, Clone)]
pub struct RecallHit {
    pub rank: usize,
    pub source_type: String,
    /// `"repo"` or `"global"` (M9 provenance). Sibling to
    /// `source_type`; surfaced in CLI JSON and the MCP recall bundle.
    pub scope: String,
    pub source_id: i64,
    pub title: String,
    pub body: String,
    pub score: f64,
    pub fts_score: f64,
    pub vector_score: f64,
    pub stale: bool,
    /// `Some(new_id)` when this hit was superseded by another row of the
    /// same source type (Wave 3 L3). The hit is kept and demoted (via
    /// `scoring.superseded_penalty`), not excluded — this tag lets the
    /// caller see the replacement id. Only facts/decisions can carry it.
    pub superseded_by: Option<i64>,
    pub source: String,
    pub created_at: String,
    /// Cross-encoder relevance score. Some(score) when the re-ranker ran
    /// for this query (hybrid mode + `use_reranker`), None otherwise.
    /// Positive = relevant; nonsense candidates score negative and are
    /// dropped by `[retrieval.scoring] min_rerank_score` before this
    /// hit ever surfaces (decisions 70, 71).
    pub rerank_score: Option<f32>,
    /// Optional, unenforced classifier tag (Wave 6 W4, migration 0021).
    /// Fact-only -- always `None` for decisions, tasks, and doc chunks.
    /// A pure passthrough: never read by `score()`, so its presence never
    /// perturbs ranking (see `score_is_byte_identical_regardless_of_kind`).
    /// `None` for an untagged fact, which is every fact recall ever
    /// returned before this field existed.
    pub kind: Option<String>,
}

#[derive(Debug, Clone)]
pub struct RecallWarning {
    pub kind: String,
    pub stale_count: usize,
    pub total_count: usize,
    pub reason: String,
    pub fix: String,
}

#[derive(Debug, Clone)]
pub struct RecallResponse {
    pub query: String,
    pub mode: RetrievalMode,
    pub results: Vec<RecallHit>,
    pub candidate_count: usize,
    pub returned_count: usize,
    pub warnings: Vec<RecallWarning>,
    pub matcher: String,
    pub elapsed_ms: u128,
    /// Count of ingested doc chunks that exist in this repo but were NOT
    /// surfaced in `results` on this call. Zero when the caller explicitly
    /// scoped to docs (`--source-type doc`), when none are ingested, or
    /// when every ingested chunk made the returned bundle. A non-zero
    /// value is a cheap cue for the agent to decide whether a follow-up
    /// doc-scoped recall is worthwhile. Doc chunks join the *default*
    /// bundle (no explicit `source_types`) only when `[retrieval]
    /// include_docs_in_default` is set — auto-enabled by the first `doc
    /// add` / `doc add --global` (decision 90) — and even then only past
    /// the `doc_min_rerank_score` relevance floor (decisions 90/91), so
    /// most ingested chunks still don't surface and this count stays
    /// meaningfully non-zero.
    pub available_docs: usize,
}

/// Top-level entry: resolves config, gathers scored candidates from
/// the repo store and (when this repo opted into machine-global memory
/// and the store exists) the global store, merges them with `scope`
/// provenance, then runs one rerank pass over the unified pool.
///
/// The global corpus is consulted only when `[global] enabled` AND
/// `~/.memhub/global.sqlite` exists; otherwise this is byte-identical
/// to the pre-M9 single-corpus path (the eval-regression guarantee).
pub fn recall(start: &Path, options: RecallOptions) -> Result<RecallResponse> {
    let ctx = db::open_project(start)?;
    let resolved = ResolvedOptions::from(&options, &ctx.config.retrieval)?;
    let scoring = &ctx.config.retrieval.scoring;
    let started = Instant::now();

    // Embed the query once and reuse it for every corpus gather so the
    // cross-corpus blended scores are computed on the same basis.
    let query_vec: Option<Vec<f32>> = if resolved.mode == RetrievalMode::Hybrid {
        let v = embed_one(&resolved.query)?;
        if v.len() != EMBEDDING_DIMENSION {
            return Err(MemhubError::Embedding(format!(
                "query embedding produced {}-dim vector, expected {EMBEDDING_DIMENSION}",
                v.len()
            )));
        }
        Some(v)
    } else {
        None
    };

    let mut repo = gather_scored(&ctx.conn, &resolved, scoring, query_vec.as_deref())?;
    for h in &mut repo.scored {
        h.scope = SCOPE_REPO.to_string();
    }

    let mut merged = repo.scored;
    let mut candidate_count = repo.candidate_count;
    let mut warnings = repo.warnings;
    let mut doc_chunk_total = repo.doc_chunk_total;
    let mut demoted_stale_count = repo.demoted_stale_count;

    if ctx.config.global.enabled
        && let Some(gctx) = db::open_global_if_exists()?
    {
        let mut g = gather_scored(&gctx.conn, &resolved, scoring, query_vec.as_deref())?;
        for h in &mut g.scored {
            h.scope = SCOPE_GLOBAL.to_string();
        }
        merged.extend(g.scored);
        candidate_count += g.candidate_count;
        warnings.extend(g.warnings);
        doc_chunk_total += g.doc_chunk_total;
        demoted_stale_count += g.demoted_stale_count;
    }

    // Un-silence staleness (Q1 / decision 145): when stale facts were kept
    // and demoted rather than excluded, tell the caller how many. This is
    // the demoted-count that replaced the old silent drop — a peer of the
    // `stale_embeddings` warning, surfaced identically in CLI/JSON/MCP.
    if demoted_stale_count > 0 {
        warnings.push(RecallWarning {
            kind: "stale_facts_demoted".to_string(),
            stale_count: demoted_stale_count,
            total_count: candidate_count,
            reason: format!(
                "{demoted_stale_count} stale fact(s) past the {}-day \
                 fact_stale_after_days horizon were kept but demoted \
                 (stale: true) instead of excluded",
                resolved.fact_stale_after_days,
            ),
            fix: "Re-verify current facts (`memhub fact verify <key>`), or set \
                  [retrieval] include_stale_by_default = false to exclude stale facts."
                .to_string(),
        });
    }

    // Re-sort the unified pool by blended score before the rerank
    // truncation so the top `rerank_candidate_pool` is drawn from both
    // corpora, not just whichever gathered first.
    merged.sort_by(|a, b| {
        b.score
            .partial_cmp(&a.score)
            .unwrap_or(std::cmp::Ordering::Equal)
            .then_with(|| a.source_type.as_str().cmp(b.source_type.as_str()))
            .then_with(|| a.scope.cmp(&b.scope))
            .then_with(|| a.source_id.cmp(&b.source_id))
    });

    let response = finalize(
        &resolved,
        merged,
        candidate_count,
        warnings,
        doc_chunk_total,
        started,
    )?;

    #[cfg(feature = "metrics")]
    if options.log_metrics {
        crate::metrics::recall_proxy::log_recall(
            &ctx.conn,
            &ctx.config.metrics,
            &ctx.paths.repo_root,
            &ctx.config.render.output_dir,
            &resolved.query,
            &response,
            options.surface,
        );
    }
    Ok(response)
}

#[derive(Debug)]
struct ResolvedOptions {
    query: String,
    mode: RetrievalMode,
    max_results: usize,
    source_types: Vec<SourceType>,
    include_stale: bool,
    /// Fact-staleness horizon in days (`[retrieval] fact_stale_after_days`).
    /// A fact never verified, or last verified more than this many days ago,
    /// is stale — kept and demoted when `include_stale`, else excluded.
    fact_stale_after_days: i64,
    accepted_only: bool,
    /// Effective rerank toggle; honored only when mode = hybrid.
    use_reranker: bool,
    /// Effective candidate pool size for the cross-encoder when active.
    rerank_candidate_pool: usize,
    /// Effective cross-encoder score floor; honored only when mode =
    /// hybrid and the re-ranker actually runs. Replaces the prior
    /// `min_vector_score` floor (D70, D71): MiniLM gives positive logits
    /// to relevant docs and negative logits to nonsense, so a single
    /// rerank-score cutoff cleanly separates the two without the
    /// cosine-band overlap that doomed the vector-path floor.
    min_rerank_score: f32,
    /// True only when doc chunks entered the pool implicitly via
    /// `[retrieval] include_docs_in_default` (caller passed no
    /// `source_types`). Explicit `--source-type doc` keeps this false
    /// so that path behaves exactly as before. Gates the stricter
    /// doc floor and the "drop unvetted docs" safety rule below.
    docs_via_default: bool,
    /// Rerank floor applied to doc chunks that entered via
    /// `docs_via_default`, from `[retrieval.scoring]
    /// doc_min_rerank_score`. Defaults to the cross-encoder's
    /// relevant/irrelevant sign boundary (0.0): on-topic doc chunks
    /// rerank just above it, off-topic ones far below, so docs route
    /// by task without displacing project memory.
    doc_min_rerank_score: f32,
}

impl ResolvedOptions {
    fn from(opts: &RecallOptions, cfg: &crate::config::RetrievalConfig) -> Result<Self> {
        let query = opts.query.trim();
        if query.is_empty() {
            return Err(MemhubError::InvalidInput(
                "recall query cannot be empty".to_string(),
            ));
        }
        let max_results = if opts.max_results == 0 {
            cfg.default_max_results
        } else {
            opts.max_results
        };
        if max_results == 0 {
            return Err(MemhubError::InvalidInput(
                "max_results must be greater than zero".to_string(),
            ));
        }
        // Docs join the *default* pool only when the caller passed no
        // explicit scope AND the repo opted in. Explicit scopes
        // (including `--source-type doc`) bypass this entirely and
        // keep the legacy floor.
        let docs_via_default = opts.source_types.is_empty() && cfg.include_docs_in_default;
        let source_types = if opts.source_types.is_empty() {
            let mut base = vec![SourceType::Fact, SourceType::Decision, SourceType::Task];
            if docs_via_default {
                base.push(SourceType::DocChunk);
            }
            base
        } else {
            let mut deduped = Vec::with_capacity(opts.source_types.len());
            for st in &opts.source_types {
                if !deduped.contains(st) {
                    deduped.push(*st);
                }
            }
            deduped
        };
        Ok(Self {
            query: query.to_string(),
            mode: opts.mode.unwrap_or(cfg.mode),
            max_results,
            source_types,
            include_stale: opts.include_stale.unwrap_or(cfg.include_stale_by_default),
            fact_stale_after_days: cfg.fact_stale_after_days,
            accepted_only: opts.accepted_only.unwrap_or(cfg.accepted_only_by_default),
            use_reranker: opts.use_reranker.unwrap_or(cfg.use_reranker),
            rerank_candidate_pool: cfg.rerank_candidate_pool.max(max_results),
            min_rerank_score: opts
                .min_rerank_score
                .unwrap_or(cfg.scoring.min_rerank_score),
            docs_via_default,
            doc_min_rerank_score: cfg.scoring.doc_min_rerank_score,
        })
    }
}

struct GatherResult {
    /// Blended-scored, sorted candidates for this single corpus
    /// (pre-rerank). `scope` is left empty here; the orchestrator
    /// tags it before the merged rerank pass.
    scored: Vec<ScoredHit>,
    candidate_count: usize,
    warnings: Vec<RecallWarning>,
    /// Stale facts that survived the filter (i.e. were kept and demoted
    /// rather than excluded) in this corpus. Summed across corpora by the
    /// orchestrator to surface the `stale_facts_demoted` warning. Always 0
    /// when `include_stale` is off, since stale rows are filtered out then.
    demoted_stale_count: usize,
    /// `COUNT(*)` of `doc_chunks` in this corpus, summed across
    /// corpora by the orchestrator for the `available_docs` cue.
    doc_chunk_total: i64,
}

/// Connection-scoped candidate gather: FTS + (hybrid) vector + stale
/// detection + hydrate + filter + blended score + sort. Connection-
/// agnostic so the orchestrator can run it once per corpus. The query
/// embedding is computed once by the caller and passed in so both the
/// repo and global gathers score on the same vector.
fn gather_scored(
    conn: &Connection,
    opts: &ResolvedOptions,
    scoring: &RetrievalScoringConfig,
    query_vec: Option<&[f32]>,
) -> Result<GatherResult> {
    let mut candidates: HashMap<(SourceType, i64), CandidateRow> = HashMap::new();

    let fts_match = build_fts_match(&opts.query);
    let fts_results: Vec<(SourceType, i64, f64)> = if let Some(match_expr) = fts_match.as_ref() {
        let mut acc = Vec::new();
        for st in &opts.source_types {
            let hits = fts_lookup(conn, *st, match_expr)?;
            acc.extend(hits.into_iter().map(|(id, score)| (*st, id, score)));
        }
        acc
    } else {
        Vec::new()
    };

    // Hydrate source rows for every FTS hit so we can apply filters and
    // assemble the response.
    for (st, id, fts_raw) in &fts_results {
        let entry = candidates
            .entry((*st, *id))
            .or_insert_with(|| CandidateRow::empty(*st, *id));
        entry.fts_raw = Some(*fts_raw);
    }

    // Vector path (hybrid only). The query embedding is supplied by the
    // orchestrator (computed once, reused across corpora).
    let mut warnings: Vec<RecallWarning> = Vec::new();
    if opts.mode == RetrievalMode::Hybrid {
        let query_vec = query_vec.ok_or_else(|| {
            MemhubError::Embedding("hybrid gather requires a precomputed query embedding".into())
        })?;
        // No vector-path floor — D70/D71 retired `min_vector_score` after
        // the MiniLM bundle landed. Nonsense rejection now lives in the
        // rerank-score filter applied below.
        let (vector_hits, corrupt_vectors) = vector_lookup(conn, &opts.source_types, query_vec)?;
        for hit in &vector_hits {
            let entry = candidates
                .entry((hit.source_type, hit.source_id))
                .or_insert_with(|| CandidateRow::empty(hit.source_type, hit.source_id));
            entry.vector_score = Some(hit.cosine);
        }

        // Stale-embedding detection: across the candidate set, count rows
        // that are missing an embedding, whose content_hash doesn't match
        // the current body, or whose stored vector blob is the wrong
        // length (a corrupt/truncated write that `content_hash` alone
        // can't catch, since the hash covers the source text, not the
        // vector bytes — `vector_lookup` skips these for scoring but
        // reports them here rather than silently degrading to FTS-only).
        let stale = detect_stale_candidates(conn, &candidates, &corrupt_vectors)?;
        if stale.stale_count > 0 {
            warnings.push(RecallWarning {
                kind: "stale_embeddings".to_string(),
                stale_count: stale.stale_count,
                total_count: stale.total_count,
                reason: stale.reason,
                fix: "Run /reindex (memhub index rebuild) to refresh.".to_string(),
            });
        }
    }

    // Hydrate source rows for every candidate. The staleness horizon is
    // config-driven (`[retrieval] fact_stale_after_days`) so the caller can
    // widen or tighten the window without a rebuild.
    hydrate_sources(conn, &mut candidates, opts.fact_stale_after_days)?;

    // Apply filters (per §4 of the addendum, filters apply before scoring).
    // Stale handling is the Q1 currency ruling (decision 145): by default
    // (`include_stale`) keep aged facts and let `score()` demote them
    // (`stale_penalty`) with `stale: true`, rather than silently dropping
    // them. `include_stale = false` restores the old hard exclusion.
    let surviving: Vec<CandidateRow> = candidates
        .into_values()
        .filter(|c| c.has_source_row())
        .filter(|c| {
            if opts.include_stale {
                true
            } else {
                !c.is_stale
            }
        })
        .filter(|c| {
            if opts.accepted_only {
                is_accepted_source(&c.source)
            } else {
                true
            }
        })
        .collect();

    let candidate_count = surviving.len();
    // Stale survivors are the demoted rows (only nonzero when include_stale
    // kept them). Reported to the caller as `stale_facts_demoted`.
    let demoted_stale_count = surviving.iter().filter(|c| c.is_stale).count();

    let mut scored: Vec<ScoredHit> = score(&surviving, scoring);
    scored.sort_by(|a, b| {
        b.score
            .partial_cmp(&a.score)
            .unwrap_or(std::cmp::Ordering::Equal)
            .then_with(|| a.source_type.as_str().cmp(b.source_type.as_str()))
            .then_with(|| a.source_id.cmp(&b.source_id))
    });

    let doc_chunk_total = conn
        .query_row(
            "SELECT COUNT(*) FROM doc_chunks WHERE project_id = 1",
            [],
            |r| r.get::<_, i64>(0),
        )
        .optional_row()?
        .unwrap_or(0)
        .max(0);

    Ok(GatherResult {
        scored,
        candidate_count,
        warnings,
        demoted_stale_count,
        doc_chunk_total,
    })
}

/// Merged-pool finalize: one cross-encoder rerank pass over the unified
/// (repo + global) candidate set, the doc-safety rule, truncation, and
/// `RecallResponse` assembly with `scope` provenance carried through.
fn finalize(
    opts: &ResolvedOptions,
    mut scored: Vec<ScoredHit>,
    candidate_count: usize,
    warnings: Vec<RecallWarning>,
    doc_chunk_total: i64,
    started: Instant,
) -> Result<RecallResponse> {
    // Optional cross-encoder re-rank pass (decision 68). Only runs on
    // hybrid mode and only when the operator hasn't opted out. Takes the
    // top `rerank_candidate_pool` by blended score, reorders them by the
    // cross-encoder, drops anything below `min_rerank_score` (D71 — the
    // nonsense-rejection floor that replaced `min_vector_score`), then
    // truncates to `max_results`. fts-only callers and trivially short
    // candidate sets bypass entirely.
    let reranked = opts.mode == RetrievalMode::Hybrid && opts.use_reranker && scored.len() > 1;
    if reranked {
        scored.truncate(opts.rerank_candidate_pool);
        // Cross-encoder input mirrors the bi-encoder's embed text shape:
        // prepend the row's natural-language summary when present so the
        // re-ranker can score paraphrase matches, not just title+body
        // surface tokens (decision 72 / task #23).
        let docs: Vec<String> = scored
            .iter()
            .map(|h| match h.summary.as_deref() {
                Some(s) if !s.trim().is_empty() => {
                    format!("{}\n\n{}\n\n{}", s, h.title, h.body)
                }
                _ => format!("{}\n\n{}", h.title, h.body),
            })
            .collect();
        let scored_order = rerank::rerank(&opts.query, &docs)?;
        let mut reshuffled: Vec<ScoredHit> = Vec::with_capacity(scored.len());
        for (idx, score) in scored_order {
            if let Some(hit) = scored.get(idx) {
                // Doc chunks that joined via the default-inclusion
                // path must clear the stricter doc floor; everything
                // else (and explicitly doc-scoped recall) uses the
                // normal floor.
                let floor = if opts.docs_via_default && hit.source_type == SourceType::DocChunk {
                    opts.doc_min_rerank_score
                } else {
                    opts.min_rerank_score
                };
                if score < floor {
                    continue;
                }
                let mut hit = hit.clone();
                hit.rerank_score = Some(score);
                reshuffled.push(hit);
            }
        }
        scored = reshuffled;
    }
    // Safety invariant: a doc may enter the *default* bundle only when
    // the cross-encoder actually vetted it. If the re-rank pass did
    // not run (fts mode, use_reranker = false, or a trivially short
    // candidate set), drop default-included docs entirely rather than
    // letting unscored chunks displace project memory. Explicit
    // `--source-type doc` (docs_via_default = false) is unaffected.
    if opts.docs_via_default && !reranked {
        scored.retain(|h| h.source_type != SourceType::DocChunk);
    }
    scored.truncate(opts.max_results);

    let mut results = Vec::with_capacity(scored.len());
    for (idx, hit) in scored.into_iter().enumerate() {
        results.push(RecallHit {
            rank: idx + 1,
            source_type: hit.source_type.as_str().to_string(),
            scope: if hit.scope.is_empty() {
                SCOPE_REPO.to_string()
            } else {
                hit.scope
            },
            source_id: hit.source_id,
            title: hit.title,
            body: hit.body,
            score: hit.score,
            fts_score: hit.fts_score,
            vector_score: hit.vector_score,
            stale: hit.stale,
            superseded_by: hit.superseded_by,
            source: hit.source,
            created_at: hit.created_at,
            rerank_score: hit.rerank_score,
            kind: hit.kind,
        });
    }

    let returned_count = results.len();
    let matcher = match opts.mode {
        RetrievalMode::Fts => "recall:fts".to_string(),
        RetrievalMode::Hybrid => {
            if reranked {
                "recall:hybrid+rerank".to_string()
            } else {
                "recall:hybrid".to_string()
            }
        }
    };

    // Cheap awareness signal. Three states:
    //  - explicit `--source-type doc`: 0, the caller already has docs.
    //  - docs_via_default: docs are in the pool but most won't fit the
    //    bundle, so report how many chunks did NOT surface here — the
    //    agent still benefits from knowing a doc-scoped follow-up
    //    exists for the long tail.
    //  - flag off / docs not pooled: total chunks skipped (legacy).
    let explicitly_doc_scoped =
        !opts.docs_via_default && opts.source_types.contains(&SourceType::DocChunk);
    let available_docs: usize = if explicitly_doc_scoped {
        0
    } else {
        // Repo + global doc-chunk count, summed by the orchestrator.
        let total = doc_chunk_total.max(0) as usize;
        if opts.docs_via_default {
            let surfaced = results
                .iter()
                .filter(|r| r.source_type == SourceType::DocChunk.as_str())
                .count();
            total.saturating_sub(surfaced)
        } else {
            total
        }
    };

    Ok(RecallResponse {
        query: opts.query.clone(),
        mode: opts.mode,
        results,
        candidate_count,
        returned_count,
        warnings,
        matcher,
        elapsed_ms: started.elapsed().as_millis(),
        available_docs,
    })
}

#[derive(Debug)]
struct CandidateRow {
    source_type: SourceType,
    source_id: i64,
    fts_raw: Option<f64>,
    vector_score: Option<f64>,
    title: String,
    body: String,
    /// Optional augmenting paraphrase. When `Some`, the cross-encoder
    /// rerank input is built as `summary\n\ntitle\n\nbody`; otherwise
    /// the existing `title\n\nbody` shape is preserved. Today only
    /// populated for decisions (migration 0011 / decision 72).
    summary: Option<String>,
    source: String,
    is_stale: bool,
    /// `Some(new_id)` once hydrated for a superseded fact/decision (Wave 3
    /// L3). Drives the `superseded_penalty` demotion in `score()` and the
    /// `superseded_by` tag on the returned hit.
    superseded_by: Option<i64>,
    created_at: String,
    /// Decay-eligible age in days (Wave 3 L6): `julianday('now') -
    /// julianday(verified_at)` for facts, `... - julianday(updated_at)` for
    /// *done* tasks. `None` for decisions, doc chunks, open/blocked tasks,
    /// and never-verified facts — rows that carry no age and so never decay.
    /// Drives the `age_half_life_days` multiplier in `score()`.
    age_days: Option<f64>,
    /// Optional, unenforced classifier tag (Wave 6 W4, migration 0021),
    /// fact-only. Carried straight through to the returned `RecallHit`;
    /// `score()` never reads it.
    kind: Option<String>,
    hydrated: bool,
}

impl CandidateRow {
    fn empty(source_type: SourceType, source_id: i64) -> Self {
        Self {
            source_type,
            source_id,
            fts_raw: None,
            vector_score: None,
            title: String::new(),
            body: String::new(),
            summary: None,
            source: String::new(),
            is_stale: false,
            superseded_by: None,
            created_at: String::new(),
            age_days: None,
            kind: None,
            hydrated: false,
        }
    }

    fn has_source_row(&self) -> bool {
        self.hydrated
    }
}

#[derive(Clone)]
struct ScoredHit {
    source_type: SourceType,
    /// Provenance tag, assigned by the orchestrator after a per-corpus
    /// gather (`SCOPE_REPO` / `SCOPE_GLOBAL`). `score()` leaves it
    /// empty; it is filled before the merged rerank pass.
    scope: String,
    source_id: i64,
    title: String,
    body: String,
    /// Carried forward from the candidate row so the cross-encoder
    /// rerank input can be built as `summary\n\ntitle\n\nbody` when
    /// present (decision 72). Not exposed on the public RecallHit
    /// shape — callers see only title/body/score/etc.
    summary: Option<String>,
    score: f64,
    fts_score: f64,
    vector_score: f64,
    stale: bool,
    /// Carried from the candidate row so the returned hit can be tagged
    /// `superseded_by: N` (Wave 3 L3). `score()` also uses it to apply
    /// `superseded_penalty`.
    superseded_by: Option<i64>,
    source: String,
    created_at: String,
    /// Cross-encoder relevance score, populated only when the re-ranker
    /// ran (hybrid mode + use_reranker + non-trivial candidate set).
    /// Used both as the final ordering key and as the nonsense-rejection
    /// floor (`min_rerank_score`). See decisions 68, 70, 71.
    rerank_score: Option<f32>,
    /// Carried from the candidate row so the returned hit can be tagged
    /// with its fact `kind` (Wave 6 W4, migration 0021). `score()` never
    /// reads this -- it is a pure passthrough, unlike `superseded_by`.
    kind: Option<String>,
}

fn fts_lookup(
    conn: &Connection,
    source_type: SourceType,
    match_expr: &str,
) -> Result<Vec<(i64, f64)>> {
    let sql = match source_type {
        SourceType::Fact => {
            "SELECT facts_fts.rowid, bm25(facts_fts) AS score \
             FROM facts_fts \
             WHERE facts_fts MATCH ?1 \
             ORDER BY score ASC \
             LIMIT ?2"
        }
        SourceType::Decision => {
            "SELECT decisions_fts.rowid, bm25(decisions_fts) AS score \
             FROM decisions_fts \
             WHERE decisions_fts MATCH ?1 \
             ORDER BY score ASC \
             LIMIT ?2"
        }
        SourceType::Task => {
            "SELECT tasks_fts.rowid, bm25(tasks_fts) AS score \
             FROM tasks_fts \
             WHERE tasks_fts MATCH ?1 \
             ORDER BY score ASC \
             LIMIT ?2"
        }
        SourceType::DocChunk => {
            "SELECT doc_chunks_fts.rowid, bm25(doc_chunks_fts) AS score \
             FROM doc_chunks_fts \
             WHERE doc_chunks_fts MATCH ?1 \
             ORDER BY score ASC \
             LIMIT ?2"
        }
        SourceType::Note => {
            "SELECT session_notes_fts.rowid, bm25(session_notes_fts) AS score \
             FROM session_notes_fts \
             WHERE session_notes_fts MATCH ?1 \
             ORDER BY score ASC \
             LIMIT ?2"
        }
    };
    let mut stmt = conn.prepare(sql)?;
    let rows = stmt.query_map(params![match_expr, PER_SOURCE_FTS_LIMIT], |row| {
        Ok((row.get::<_, i64>(0)?, row.get::<_, f64>(1)?))
    })?;
    rows.collect::<std::result::Result<Vec<_>, _>>()
        .map_err(Into::into)
}

#[derive(Debug)]
struct VectorHit {
    source_type: SourceType,
    source_id: i64,
    cosine: f64,
}

/// `(matching vector hits, source keys whose stored vector was corrupt)`.
type VectorLookupResult = (Vec<VectorHit>, HashSet<(SourceType, i64)>);

fn vector_lookup(
    conn: &Connection,
    source_types: &[SourceType],
    query_vec: &[f32],
) -> Result<VectorLookupResult> {
    let mut stmt = conn.prepare(
        "SELECT source_type, source_id, vector \
         FROM embeddings \
         WHERE model_name = ?1 AND dimension = ?2",
    )?;
    let allowed: Vec<&'static str> = source_types.iter().map(|st| st.as_str()).collect();
    let rows = stmt.query_map(
        params![EMBEDDING_MODEL_NAME, EMBEDDING_DIMENSION as i64],
        |row| {
            let st: String = row.get(0)?;
            let id: i64 = row.get(1)?;
            let blob: Vec<u8> = row.get(2)?;
            Ok((st, id, blob))
        },
    )?;

    let mut out = Vec::new();
    // Rows whose stored vector blob is the wrong byte length for
    // `EMBEDDING_DIMENSION` -- a corrupt or truncated write. These are
    // skipped for scoring (there's nothing to compute cosine similarity
    // against) but the caller folds them into the `stale_embeddings`
    // warning rather than letting them vanish silently.
    let mut corrupt = HashSet::new();
    for row in rows {
        let (st, id, blob) = row?;
        if !allowed.contains(&st.as_str()) {
            continue;
        }
        let source_type = match parse_source_type(&st) {
            Some(t) => t,
            None => continue,
        };
        if blob.len() != EMBEDDING_DIMENSION * 4 {
            corrupt.insert((source_type, id));
            continue;
        }
        let candidate_vec = bytes_to_vector(&blob);
        let cosine = cosine_similarity(query_vec, &candidate_vec);
        // The only caller always passed 0.0 here (see the call site's
        // comment) — D70/D71 retired the configurable floor, leaving a
        // parameter that never varied. Issue #69 inlines that dead
        // plumbing; a negative-cosine candidate still never enters the
        // vector path, unchanged from before.
        if cosine < 0.0 {
            continue;
        }
        out.push(VectorHit {
            source_type,
            source_id: id,
            cosine,
        });
    }
    Ok((out, corrupt))
}

struct StaleSummary {
    stale_count: usize,
    total_count: usize,
    reason: String,
}

fn detect_stale_candidates(
    conn: &Connection,
    candidates: &HashMap<(SourceType, i64), CandidateRow>,
    corrupt_vectors: &HashSet<(SourceType, i64)>,
) -> Result<StaleSummary> {
    // Union of this query's candidates with any corrupt-length embedding
    // rows `vector_lookup` found in the requested source types -- the
    // latter may include rows this query never matched via FTS, since
    // that scan covers every embedding row in scope, not just the
    // candidate set.
    let mut keys: HashSet<(SourceType, i64)> = candidates.keys().copied().collect();
    keys.extend(corrupt_vectors.iter().copied());
    if keys.is_empty() {
        return Ok(StaleSummary {
            stale_count: 0,
            total_count: 0,
            reason: String::new(),
        });
    }

    let mut stale_count = 0;
    let total_count = keys.len();
    let mut reason_missing = false;
    let mut reason_drift = false;
    let mut reason_corrupt = false;

    let mut stmt = conn.prepare(
        "SELECT content_hash FROM embeddings \
         WHERE source_type = ?1 AND source_id = ?2 AND model_name = ?3",
    )?;

    for key in &keys {
        if corrupt_vectors.contains(key) {
            // A length-mismatched blob is decisively stale regardless of
            // what content_hash says -- the hash covers the source text,
            // not the vector bytes, so it can't detect this corruption.
            stale_count += 1;
            reason_corrupt = true;
            continue;
        }
        let current_text = match current_embed_text(conn, key.0, key.1)? {
            Some(t) => t,
            None => continue,
        };
        let current_hash = sha256_hex(current_text.as_bytes());
        let existing: Option<String> = stmt
            .query_row(
                params![key.0.as_str(), key.1, EMBEDDING_MODEL_NAME],
                |row| row.get(0),
            )
            .optional_row()?;
        match existing {
            None => {
                stale_count += 1;
                reason_missing = true;
            }
            Some(hash) if hash != current_hash => {
                stale_count += 1;
                reason_drift = true;
            }
            _ => {}
        }
    }

    let reason = match (reason_missing, reason_drift, reason_corrupt) {
        (false, false, false) => String::new(),
        (true, false, false) => "missing_embeddings".to_string(),
        (false, true, false) => "content_drift".to_string(),
        (false, false, true) => "corrupt_length_mismatch".to_string(),
        (true, true, false) => "missing_or_drift".to_string(),
        (true, false, true) => "missing_or_corrupt".to_string(),
        (false, true, true) => "drift_or_corrupt".to_string(),
        (true, true, true) => "missing_drift_or_corrupt".to_string(),
    };

    Ok(StaleSummary {
        stale_count,
        total_count,
        reason,
    })
}

trait OptionalRowExt<T> {
    fn optional_row(self) -> std::result::Result<Option<T>, rusqlite::Error>;
}

impl<T> OptionalRowExt<T> for std::result::Result<T, rusqlite::Error> {
    fn optional_row(self) -> std::result::Result<Option<T>, rusqlite::Error> {
        match self {
            Ok(v) => Ok(Some(v)),
            Err(rusqlite::Error::QueryReturnedNoRows) => Ok(None),
            Err(e) => Err(e),
        }
    }
}

fn current_embed_text(
    conn: &Connection,
    source_type: SourceType,
    source_id: i64,
) -> Result<Option<String>> {
    match source_type {
        SourceType::Fact => {
            let row: std::result::Result<(String, String), rusqlite::Error> = conn.query_row(
                "SELECT key, value FROM facts WHERE id = ?1",
                params![source_id],
                |row| Ok((row.get(0)?, row.get(1)?)),
            );
            match row.optional_row()? {
                Some((k, v)) => Ok(Some(fact_embed_text(&k, &v))),
                None => Ok(None),
            }
        }
        SourceType::Decision => {
            let row: std::result::Result<(String, String, Option<String>), rusqlite::Error> = conn
                .query_row(
                    "SELECT title, rationale, summary FROM decisions WHERE id = ?1",
                    params![source_id],
                    |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
                );
            match row.optional_row()? {
                Some((t, r, s)) => Ok(Some(decision_embed_text(&t, &r, s.as_deref()))),
                None => Ok(None),
            }
        }
        SourceType::Task => {
            let row: std::result::Result<(String, Option<String>), rusqlite::Error> = conn
                .query_row(
                    "SELECT title, notes FROM tasks WHERE id = ?1",
                    params![source_id],
                    |row| Ok((row.get(0)?, row.get(1)?)),
                );
            match row.optional_row()? {
                Some((t, n)) => Ok(Some(task_embed_text(&t, n.as_deref()))),
                None => Ok(None),
            }
        }
        SourceType::DocChunk => {
            let row: std::result::Result<(String, String), rusqlite::Error> = conn.query_row(
                "SELECT heading_path, body FROM doc_chunks WHERE id = ?1",
                params![source_id],
                |row| Ok((row.get(0)?, row.get(1)?)),
            );
            match row.optional_row()? {
                Some((h, b)) => Ok(Some(doc_chunk_embed_text(&h, &b))),
                None => Ok(None),
            }
        }
        SourceType::Note => {
            let row: std::result::Result<String, rusqlite::Error> = conn.query_row(
                "SELECT text FROM session_notes WHERE id = ?1",
                params![source_id],
                |row| row.get(0),
            );
            match row.optional_row()? {
                Some(t) => Ok(Some(note_embed_text(&t))),
                None => Ok(None),
            }
        }
    }
}

fn hydrate_sources(
    conn: &Connection,
    candidates: &mut HashMap<(SourceType, i64), CandidateRow>,
    fact_stale_after_days: i64,
) -> Result<()> {
    // Group by source type to minimize prepared statements.
    let mut by_type: HashMap<SourceType, Vec<i64>> = HashMap::new();
    for key in candidates.keys() {
        by_type.entry(key.0).or_default().push(key.1);
    }

    for (st, ids) in by_type {
        for id in ids {
            if let Some(row) = load_source_row(conn, st, id, fact_stale_after_days)?
                && let Some(entry) = candidates.get_mut(&(st, id))
            {
                entry.title = row.title;
                entry.body = row.body;
                entry.summary = row.summary;
                entry.source = row.source;
                entry.is_stale = row.is_stale;
                entry.superseded_by = row.superseded_by;
                entry.created_at = row.created_at;
                entry.age_days = row.age_days;
                entry.kind = row.kind;
                entry.hydrated = true;
            }
        }
    }
    Ok(())
}

struct HydratedSource {
    title: String,
    body: String,
    /// Only populated for decisions (migration 0011 / decision 72).
    summary: Option<String>,
    source: String,
    is_stale: bool,
    /// `Some(new_id)` for a superseded fact/decision (Wave 3 L3); always
    /// `None` for tasks and doc chunks, which cannot be superseded.
    superseded_by: Option<i64>,
    created_at: String,
    /// Decay-eligible age in days (Wave 3 L6): `Some` only for facts (from
    /// `verified_at`) and *done* tasks (from `updated_at`); `None` for
    /// decisions, doc chunks, open/blocked tasks, and never-verified facts.
    age_days: Option<f64>,
    /// Optional, unenforced classifier tag (Wave 6 W4, migration 0021).
    /// `Some` only for a tagged fact; always `None` for decisions, tasks,
    /// and doc chunks, which have no `kind` column.
    kind: Option<String>,
}

fn load_source_row(
    conn: &Connection,
    source_type: SourceType,
    source_id: i64,
    fact_stale_after_days: i64,
) -> Result<Option<HydratedSource>> {
    match source_type {
        SourceType::Fact => {
            let mut stmt = conn.prepare(
                "SELECT key, value, source, verified_at, created_at, \
                    CASE \
                        WHEN verified_at IS NULL THEN 1 \
                        WHEN (julianday('now') - julianday(verified_at)) > ?2 THEN 1 \
                        ELSE 0 \
                    END AS is_stale, \
                    superseded_by, \
                    julianday('now') - julianday(verified_at) AS age_days, \
                    kind \
                FROM facts WHERE id = ?1",
            )?;
            let row: std::result::Result<HydratedSource, rusqlite::Error> =
                stmt.query_row(params![source_id, fact_stale_after_days], |r: &Row<'_>| {
                    let key: String = r.get(0)?;
                    let value: String = r.get(1)?;
                    let source: String = r.get(2)?;
                    let created_at: String = r.get(4)?;
                    let stale_int: i64 = r.get(5)?;
                    let superseded_by: Option<i64> = r.get(6)?;
                    // `NULL` (never-verified fact) => julianday() is NULL =>
                    // `None` => no decay (already flagged stale + demoted).
                    let age_days: Option<f64> = r.get(7)?;
                    let kind: Option<String> = r.get(8)?;
                    Ok(HydratedSource {
                        title: key,
                        body: value,
                        summary: None,
                        source,
                        is_stale: stale_int != 0,
                        superseded_by,
                        created_at,
                        age_days,
                        kind,
                    })
                });
            row.optional_row().map_err(Into::into)
        }
        SourceType::Decision => {
            let mut stmt = conn.prepare(
                "SELECT title, rationale, source, decided_at, summary, superseded_by \
                 FROM decisions WHERE id = ?1",
            )?;
            let row: std::result::Result<HydratedSource, rusqlite::Error> =
                stmt.query_row(params![source_id], |r: &Row<'_>| {
                    let title: String = r.get(0)?;
                    let rationale: String = r.get(1)?;
                    let source: String = r.get(2)?;
                    let decided_at: String = r.get(3)?;
                    let summary: Option<String> = r.get(4)?;
                    let superseded_by: Option<i64> = r.get(5)?;
                    Ok(HydratedSource {
                        title,
                        body: rationale,
                        summary,
                        source,
                        is_stale: false,
                        superseded_by,
                        created_at: decided_at,
                        // Decisions are excluded from age decay entirely (Q2 /
                        // decision 145): standing policy retires by
                        // supersession, not age.
                        age_days: None,
                        // `kind` (migration 0021) is a facts-only column.
                        kind: None,
                    })
                });
            row.optional_row().map_err(Into::into)
        }
        SourceType::Task => {
            // Age decay keys on `updated_at` for *done* tasks only (Wave 3
            // L6); open/blocked tasks are live work and carry no decay age
            // (`NULL` => `None`).
            let mut stmt = conn.prepare(
                "SELECT title, notes, created_at, \
                    CASE WHEN status = 'done' \
                         THEN julianday('now') - julianday(updated_at) \
                         ELSE NULL END AS age_days \
                 FROM tasks WHERE id = ?1",
            )?;
            let row: std::result::Result<HydratedSource, rusqlite::Error> =
                stmt.query_row(params![source_id], |r: &Row<'_>| {
                    let title: String = r.get(0)?;
                    let notes: Option<String> = r.get(1)?;
                    let created_at: String = r.get(2)?;
                    let age_days: Option<f64> = r.get(3)?;
                    Ok(HydratedSource {
                        title,
                        body: notes.unwrap_or_default(),
                        summary: None,
                        source: String::new(),
                        is_stale: false,
                        superseded_by: None,
                        created_at,
                        age_days,
                        // `kind` (migration 0021) is a facts-only column.
                        kind: None,
                    })
                });
            row.optional_row().map_err(Into::into)
        }
        SourceType::DocChunk => {
            // Title shows the document title plus the section breadcrumb
            // so a recalled chunk is self-describing about its origin.
            let mut stmt = conn.prepare(
                "SELECT d.title, c.heading_path, c.body, d.source, c.created_at \
                 FROM doc_chunks c JOIN documents d ON d.id = c.doc_id \
                 WHERE c.id = ?1",
            )?;
            let row: std::result::Result<HydratedSource, rusqlite::Error> =
                stmt.query_row(params![source_id], |r: &Row<'_>| {
                    let doc_title: String = r.get(0)?;
                    let heading_path: String = r.get(1)?;
                    let body: String = r.get(2)?;
                    let source: String = r.get(3)?;
                    let created_at: String = r.get(4)?;
                    let title = if heading_path.trim().is_empty() {
                        doc_title
                    } else {
                        format!("{doc_title} — {heading_path}")
                    };
                    Ok(HydratedSource {
                        title,
                        body,
                        summary: None,
                        source,
                        is_stale: false,
                        superseded_by: None,
                        created_at,
                        // Doc chunks are excluded from age decay (Wave 3 L6).
                        age_days: None,
                        // `kind` (migration 0021) is a facts-only column.
                        kind: None,
                    })
                });
            row.optional_row().map_err(Into::into)
        }
        SourceType::Note => {
            // No title-analog column exists for a note (unlike a fact's
            // key or a doc chunk's heading_path), so `actor` — the
            // provenance tag — doubles as the short scannable label;
            // `text` is the full body.
            let mut stmt =
                conn.prepare("SELECT actor, text, created_at FROM session_notes WHERE id = ?1")?;
            let row: std::result::Result<HydratedSource, rusqlite::Error> =
                stmt.query_row(params![source_id], |r: &Row<'_>| {
                    let actor: String = r.get(0)?;
                    let text: String = r.get(1)?;
                    let created_at: String = r.get(2)?;
                    Ok(HydratedSource {
                        title: actor,
                        body: text,
                        summary: None,
                        // No source-vocabulary column on session_notes
                        // (mirrors tasks, which also carry no `source`) —
                        // `accepted_only` therefore excludes notes just
                        // like it does tasks, since neither is a vetted
                        // claim in the fact/decision sense.
                        source: String::new(),
                        is_stale: false,
                        superseded_by: None,
                        created_at,
                        // Notes carry no decay-eligible age (Wave 3 L6
                        // scope): write-only scratch, not a durable claim
                        // that ages toward staleness.
                        age_days: None,
                        // `kind` (migration 0021) is a facts-only column.
                        kind: None,
                    })
                });
            row.optional_row().map_err(Into::into)
        }
    }
}

fn is_accepted_source(source: &str) -> bool {
    source == "user" || source.starts_with("user+agent:")
}

fn parse_source_type(raw: &str) -> Option<SourceType> {
    match raw {
        "fact" => Some(SourceType::Fact),
        "decision" => Some(SourceType::Decision),
        "task" => Some(SourceType::Task),
        "doc_chunk" => Some(SourceType::DocChunk),
        "note" => Some(SourceType::Note),
        _ => None,
    }
}

fn score(rows: &[CandidateRow], scoring: &RetrievalScoringConfig) -> Vec<ScoredHit> {
    let (fts_min, fts_max) = rows
        .iter()
        .fold((f64::INFINITY, f64::NEG_INFINITY), |acc, c| {
            match c.fts_raw {
                Some(raw) => {
                    let pos = -raw; // BM25 is "lower is better"; invert so higher is better.
                    (acc.0.min(pos), acc.1.max(pos))
                }
                None => acc,
            }
        });

    rows.iter()
        .map(|c| {
            let fts_score = match c.fts_raw {
                Some(raw) => normalize_fts(-raw, fts_min, fts_max),
                None => 0.0,
            };
            let vector_score = c.vector_score.unwrap_or(0.0).clamp(0.0, 1.0);
            let stale_penalty = if c.is_stale {
                scoring.stale_penalty
            } else {
                0.0
            };
            // Second, independent demotion signal (Wave 3 L3): a superseded
            // row is kept and tagged but pushed down. Stacks additively with
            // the stale penalty — a row that is both aged and replaced sinks
            // furthest — and never excludes (demote-with-link, decision 145).
            let superseded_penalty = if c.superseded_by.is_some() {
                scoring.superseded_penalty
            } else {
                0.0
            };
            // Optional continuous age decay (Wave 3 L6). OFF by default
            // (`age_half_life_days = 0` => multiplier is exactly 1.0, an
            // IEEE-754 no-op) so an untouched install scores byte-identically
            // to pre-L6 memhub. When enabled, the blended relevance is scaled
            // by an exponential half-life keyed on `verified_at` (facts) /
            // `updated_at` (done tasks); decisions and doc chunks carry no
            // `age_days` and are never decayed (Q2 / decision 145 — decisions
            // retire by supersession, not age). Applied as a multiplier on
            // the positive relevance term *before* the additive penalties so
            // decay never flips the sign of a penalized score. Under the
            // cross-encoder re-ranker this mostly shifts which candidates
            // enter the rerank pool rather than the final reranked order
            // (`finalize`).
            let age_decay = age_decay_multiplier(c.age_days, scoring.age_half_life_days);
            let relevance = scoring.fts_weight * fts_score + scoring.vector_weight * vector_score;
            let score = relevance * age_decay - stale_penalty - superseded_penalty;
            ScoredHit {
                source_type: c.source_type,
                scope: String::new(),
                source_id: c.source_id,
                title: c.title.clone(),
                body: c.body.clone(),
                summary: c.summary.clone(),
                score,
                fts_score,
                vector_score,
                stale: c.is_stale,
                superseded_by: c.superseded_by,
                source: c.source.clone(),
                created_at: c.created_at.clone(),
                rerank_score: None,
                kind: c.kind.clone(),
            }
        })
        .collect()
}

/// Continuous age-decay multiplier for a candidate's blended relevance
/// (Wave 3 L6). Returns a value in `(0, 1]`.
///
/// `half_life_days <= 0` is the OFF state (the default, `age_half_life_days
/// = 0`) and returns **exactly** `1.0` — multiplying the blended relevance
/// by `1.0` is a bit-for-bit IEEE-754 no-op, which is what makes an
/// untouched install score byte-identically to pre-L6 memhub.
///
/// When enabled (`> 0`), a row whose decay-eligible age is `days` old is
/// scaled by `2^(-days / half_life)`, i.e. it halves every `half_life_days`.
/// `age_days == None` (decisions, doc chunks, open/blocked tasks, or a fact
/// never verified) and non-positive ages both return `1.0`: decay only ever
/// demotes an aged row, it never boosts a fresh or timestamp-less one.
fn age_decay_multiplier(age_days: Option<f64>, half_life_days: i64) -> f64 {
    if half_life_days <= 0 {
        return 1.0;
    }
    match age_days {
        Some(days) if days > 0.0 => {
            // 2^(-days / half_life) == exp(-ln2 * days / half_life).
            (-days * std::f64::consts::LN_2 / half_life_days as f64).exp()
        }
        _ => 1.0,
    }
}

