//! ms-marco-MiniLM-L-6-v2 cross-encoder re-ranker.
//!
//! The ONNX model and tokenizer files are bundled into the memhub binary
//! at build time by `build.rs`. The first call to [`rerank`] constructs
//! the fastembed [`TextRerank`] handle (~1–2 s ONNX session init); all
//! subsequent calls reuse it.
//!
//! Selected over BGE-reranker-v2-m3 in the cross-encoder bake-off
//! (decisions 68–70): +17.7pp Recall@1 over baseline, ~15× faster, no
//! keyword-query regressions. Bundled unconditionally; the `[retrieval]
//! use_reranker` config knob gates whether `recall::run` actually calls
//! into this module.

use std::sync::{Mutex, OnceLock};

use fastembed::{
    OnnxSource, RerankInitOptionsUserDefined, TextRerank, TokenizerFiles, UserDefinedRerankingModel,
};

use crate::{MemhubError, Result};

pub const RERANKER_MODEL_NAME: &str = "ms-marco-MiniLM-L-6-v2";

const MODEL_ONNX: &[u8] = include_bytes!(concat!(
    env!("OUT_DIR"),
    "/ms-marco-MiniLM-L-6-v2/model.onnx"
));
const TOKENIZER_JSON: &[u8] = include_bytes!(concat!(
    env!("OUT_DIR"),
    "/ms-marco-MiniLM-L-6-v2/tokenizer.json"
));
const CONFIG_JSON: &[u8] = include_bytes!(concat!(
    env!("OUT_DIR"),
    "/ms-marco-MiniLM-L-6-v2/config.json"
));
const SPECIAL_TOKENS_JSON: &[u8] = include_bytes!(concat!(
    env!("OUT_DIR"),
    "/ms-marco-MiniLM-L-6-v2/special_tokens_map.json"
));
const TOKENIZER_CONFIG_JSON: &[u8] = include_bytes!(concat!(
    env!("OUT_DIR"),
    "/ms-marco-MiniLM-L-6-v2/tokenizer_config.json"
));

static MODEL: OnceLock<Mutex<TextRerank>> = OnceLock::new();

fn shared() -> Result<&'static Mutex<TextRerank>> {
    if let Some(m) = MODEL.get() {
        return Ok(m);
    }
    let tokenizer_files = TokenizerFiles {
        tokenizer_file: TOKENIZER_JSON.to_vec(),
        config_file: CONFIG_JSON.to_vec(),
        special_tokens_map_file: SPECIAL_TOKENS_JSON.to_vec(),
        tokenizer_config_file: TOKENIZER_CONFIG_JSON.to_vec(),
    };
    let user_model =
        UserDefinedRerankingModel::new(OnnxSource::Memory(MODEL_ONNX.to_vec()), tokenizer_files);
    let model =
        TextRerank::try_new_from_user_defined(user_model, RerankInitOptionsUserDefined::default())
            .map_err(|e| {
                MemhubError::Rerank(format!("failed to load {RERANKER_MODEL_NAME}: {e}"))
            })?;
    Ok(MODEL.get_or_init(|| Mutex::new(model)))
}

/// Score (query, doc) pairs with the bundled cross-encoder and return
/// `(input_index, score)` pairs sorted by descending relevance.
///
/// `docs[i]` is the document originally at input position `i`. The
/// returned `input_index` tells the caller how to reorder them; the
/// `score` is the cross-encoder relevance logit (positive = relevant,
/// negative = irrelevant — see decision 70 follow-up on rerank-score-
/// based nonsense rejection). Empty input returns an empty Vec without
/// loading the model.
pub fn rerank(query: &str, docs: &[String]) -> Result<Vec<(usize, f32)>> {
    if docs.is_empty() {
        return Ok(Vec::new());
    }
    let cell = shared()?;
    let mut model = cell
        .lock()
        .map_err(|e| MemhubError::Rerank(format!("rerank mutex poisoned: {e}")))?;
    let doc_refs: Vec<&str> = docs.iter().map(String::as_str).collect();
    let results = model
        .rerank(query, &doc_refs, false, None)
        .map_err(|e| MemhubError::Rerank(format!("rerank failed: {e}")))?;
    Ok(results.into_iter().map(|r| (r.index, r.score)).collect())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn rerank_empty_input_returns_empty_without_loading_model() {
        // Important: this must not trigger MODEL init. If it did, the test
        // would pay ~1–2 s of ONNX session setup. The early-return for
        // empty docs guards that.
        let out = rerank("anything", &[]).expect("empty rerank");
        assert!(out.is_empty());
    }

    #[test]
    fn rerank_returns_permutation_of_input_indices() {
        let docs = vec![
            "Rust is a systems programming language with strong memory safety".to_string(),
            "Cats are domesticated felines kept as household pets".to_string(),
            "The borrow checker enforces ownership rules at compile time".to_string(),
        ];
        let scored = rerank("how does rust prevent memory bugs", &docs).expect("rerank");
        assert_eq!(scored.len(), docs.len());
        let mut indices: Vec<usize> = scored.iter().map(|(i, _)| *i).collect();
        indices.sort();
        assert_eq!(indices, vec![0, 1, 2], "must be a permutation");
        // The cat doc (index 1) is clearly unrelated; it should not rank #1.
        assert_ne!(scored[0].0, 1, "off-topic doc should not be top-ranked");
        // Scores must be sorted descending — the top is the highest-relevance.
        for w in scored.windows(2) {
            assert!(w[0].1 >= w[1].1, "rerank scores must be descending");
        }
    }
}

//! Shared low-level helpers for the retrieval fusion paths.
//!
//! [`crate::retrieval::recall`] (project recall) and
//! [`crate::code_index::locate`] (the code locator) each implement the
//! same FTS5-match-building, min-max-normalization, and cosine-similarity
//! logic over their own tables; the embedding write paths
//! ([`crate::retrieval::persist`], `commands::index`, `commands::doc`,
//! `commands::review`, `metrics::recall_proxy`) and the code index
//! ([`crate::code_index`]) each hand-rolled their own content-hash and/or
//! vector<->bytes codec. Every copy was byte-identical (same algorithm,
//! same output for the same input) at the time of consolidation (issue
//! #69 / R9) — this module is a pure relocation, not a behavior change.

use sha2::{Digest, Sha256};

/// Hex-encode the SHA-256 digest of `bytes` (lowercase, no separators).
/// Used as a stable content-hash to detect whether a source row's embed
/// text — or, for the code index, a file's raw on-disk bytes — has
/// changed since the last embed/ingest. Takes `&[u8]` rather than `&str`
/// so the code-index caller can hash raw (not-necessarily-UTF-8) file
/// bytes directly; `&str` callers pass `.as_bytes()`.
pub(crate) fn sha256_hex(bytes: &[u8]) -> String {
    let mut hasher = Sha256::new();
    hasher.update(bytes);
    let digest = hasher.finalize();
    const HEX: &[u8; 16] = b"0123456789abcdef";
    let mut out = String::with_capacity(digest.len() * 2);
    for b in digest {
        out.push(HEX[(b >> 4) as usize] as char);
        out.push(HEX[(b & 0x0f) as usize] as char);
    }
    out
}

/// Tokenize a free-text query into a quoted FTS5 `AND` of terms. Returns
/// `None` when the query has no usable tokens (so the caller skips FTS).
pub(crate) fn build_fts_match(query: &str) -> Option<String> {
    let tokens: Vec<String> = query
        .split_whitespace()
        .map(|token| token.trim_matches(|c: char| matches!(c, '"' | '\'' | ',' | '.' | ':' | ';')))
        .filter(|t| !t.is_empty())
        .map(|token| format!("\"{}\"", token.replace('"', "\"\"")))
        .collect();
    if tokens.is_empty() {
        None
    } else {
        Some(tokens.join(" AND "))
    }
}

/// Min-max normalize an FTS bm25 score into `[0, 1]` against the
/// candidate pool's `[min, max]` range. A degenerate range (single hit,
/// or a tie across the whole pool) is treated as full strength (`1.0`)
/// rather than dividing by zero.
pub(crate) fn normalize_fts(value: f64, min: f64, max: f64) -> f64 {
    if !value.is_finite() || !min.is_finite() || !max.is_finite() {
        return 0.0;
    }
    if (max - min).abs() < f64::EPSILON {
        // Single FTS hit (or ties): treat as full strength.
        return 1.0;
    }
    ((value - min) / (max - min)).clamp(0.0, 1.0)
}

/// Cosine similarity between two equal-length embedding vectors. Returns
/// `0.0` for length mismatches or (near-)zero-norm vectors rather than
/// dividing by zero / producing NaN.
pub(crate) fn cosine_similarity(a: &[f32], b: &[f32]) -> f64 {
    if a.len() != b.len() {
        return 0.0;
    }
    let mut dot: f64 = 0.0;
    let mut na: f64 = 0.0;
    let mut nb: f64 = 0.0;
    for (x, y) in a.iter().zip(b.iter()) {
        let xf = *x as f64;
        let yf = *y as f64;
        dot += xf * yf;
        na += xf * xf;
        nb += yf * yf;
    }
    if na <= f64::EPSILON || nb <= f64::EPSILON {
        return 0.0;
    }
    dot / (na.sqrt() * nb.sqrt())
}

/// Pack a vector as little-endian f32 bytes for storage in the
/// `embeddings` / `code_embeddings` BLOB column.
pub(crate) fn vector_to_le_bytes(v: &[f32]) -> Vec<u8> {
    let mut out = Vec::with_capacity(v.len() * 4);
    for f in v {
        out.extend_from_slice(&f.to_le_bytes());
    }
    out
}

/// Unpack little-endian f32 bytes back into a vector. A trailing partial
/// chunk (corrupt blob) is ignored rather than panicking.
pub(crate) fn bytes_to_vector(blob: &[u8]) -> Vec<f32> {
    blob.chunks_exact(4)
        .map(|b| f32::from_le_bytes([b[0], b[1], b[2], b[3]]))
        .collect()
}

//! Agent transcript path and session-id conventions shared by the optional
//! metrics scraper and the always-available transcript archiver.
//!
//! This module deliberately lives outside `metrics`: hibernating token
//! accounting must not disable archival, and the two callers must still use
//! one definition of each agent's on-disk layout.

use std::fs;
use std::path::{Path, PathBuf};

pub(crate) fn detect_codex_sessions_dir() -> Option<PathBuf> {
    let home = crate::db::home_dir().ok()?;
    let candidate = home.join(".codex/sessions");
    candidate.is_dir().then_some(candidate)
}

pub(crate) fn detect_claude_transcripts_dir(repo_root: &Path) -> Option<PathBuf> {
    let home = crate::db::home_dir().ok()?;
    let abs = repo_root.canonicalize().ok()?;
    let candidate = home
        .join(".claude/projects")
        .join(encode_claude_project_dir(&abs));
    candidate.is_dir().then_some(candidate)
}

pub(crate) fn encode_claude_project_dir(abs: &Path) -> String {
    let path_str = abs.to_string_lossy();
    let stripped = path_str.strip_prefix(r"\\?\").unwrap_or(path_str.as_ref());
    stripped.replace(['/', '\\', ':'], "-")
}

pub fn claude_session_id_from_path(path: &Path) -> Option<String> {
    path.file_stem()
        .and_then(|s| s.to_str())
        .filter(|s| !s.is_empty())
        .map(str::to_string)
}

pub fn codex_session_id_from_path(path: &Path) -> Option<String> {
    let stem = path
        .file_stem()
        .and_then(|s| s.to_str())
        .filter(|s| !s.is_empty())?;
    let parts: Vec<&str> = stem.split('-').collect();
    if parts.len() < 5 {
        return None;
    }
    let uuid = parts[parts.len() - 5..].join("-");
    Some(format!("codex:{uuid}"))
}

pub fn find_claude_transcript(dir: &Path, session_id: &str) -> Option<PathBuf> {
    let candidate = dir.join(format!("{session_id}.jsonl"));
    candidate.is_file().then_some(candidate)
}

pub fn find_codex_transcript(dir: &Path, session_id: &str) -> Option<PathBuf> {
    for l1 in read_subdirs(dir) {
        for l2 in read_subdirs(&l1) {
            for l3 in read_subdirs(&l2) {
                let files = match fs::read_dir(&l3) {
                    Ok(entries) => entries,
                    Err(_) => continue,
                };
                for entry in files.flatten() {
                    let path = entry.path();
                    if path.extension().and_then(|e| e.to_str()) == Some("jsonl")
                        && codex_session_id_from_path(&path).as_deref() == Some(session_id)
                    {
                        return Some(path);
                    }
                }
            }
        }
    }
    None
}

fn read_subdirs(dir: &Path) -> Vec<PathBuf> {
    let mut out = Vec::new();
    if let Ok(entries) = fs::read_dir(dir) {
        for entry in entries.flatten() {
            if entry.file_type().map(|t| t.is_dir()).unwrap_or(false) {
                out.push(entry.path());
            }
        }
    }
    out
}

