#[test]
fn export_import_round_trips_pending_writes_reviewed_at() {
    let source = tempdir().expect("source tempdir");
    init::run(source.path()).expect("source init");

    let pending_id = pending_write::propose_fact(
        source.path(),
        "deploy-command",
        "./deploy.sh",
        "Looks risky.",
        "codex",
        "openai-codex",
        "{\"source\":\"mcp\"}",
    )
    .expect("propose fact");
    review::reject(
