        "cli:user",
    )
    .expect("second decision");

    let ctx = memhub::db::open_project(source.path()).expect("open source");
    ctx.conn
        .execute(
            "UPDATE decisions SET status = 'superseded', superseded_by = ?1 WHERE id = ?2",
