//! End-to-end MCP protocol smoke tests.
//!
//! Spawns `memhub serve` as a subprocess and runs the JSON-RPC handshake
//! over stdio. Exists because the `#[tool_handler]` attribute on the
//! `ServerHandler` impl is load-bearing — if it's ever removed, the
//! server still initializes and identifies itself, but `tools/list`
//! silently returns an empty array. The in-process unit tests don't
//! catch that; only a real handshake does.

use std::io::{BufRead, BufReader, Write};
use std::process::{Command, Stdio};
use std::time::Duration;

use memhub::commands::{decision, fact, init};
use serde_json::{Value, json};
use tempfile::tempdir;

fn memhub_bin() -> &'static str {
    env!("CARGO_BIN_EXE_memhub")
}

fn send_handshake(repo: &std::path::Path) -> Vec<Value> {
    let mut child = Command::new(memhub_bin())
        .arg("serve")
        .current_dir(repo)
        .env("MEMHUB_LOG", "off")
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::null())
        .spawn()
        .expect("spawn memhub serve");

    let stdin = child.stdin.as_mut().expect("stdin");
    let initialize = json!({
        "jsonrpc": "2.0",
        "id": 1,
        "method": "initialize",
        "params": {
            "protocolVersion": "2025-06-18",
            "capabilities": {},
            "clientInfo": {"name": "codex", "version": "test"}
        }
    });
    let initialized = json!({
        "jsonrpc": "2.0",
        "method": "notifications/initialized",
        "params": {}
    });
    let list_tools = json!({
        "jsonrpc": "2.0",
        "id": 2,
        "method": "tools/list",
        "params": {}
    });
    let call_recall = json!({
        "jsonrpc": "2.0",
        "id": 3,
        "method": "tools/call",
        "params": {
            "name": "recall",
            "arguments": {"query": "stage agent writes", "max_results": 2}
        }
    });

    for msg in [&initialize, &initialized, &list_tools, &call_recall] {
        writeln!(stdin, "{msg}").expect("write json-rpc");
    }
    // Close stdin so the server exits cleanly after responding.
    drop(child.stdin.take());

    let stdout = child.stdout.take().expect("stdout");
    let mut responses = Vec::new();
    let reader = BufReader::new(stdout);
    for line in reader.lines() {
        let line = line.expect("read line");
        if line.trim().is_empty() {
            continue;
        }
        match serde_json::from_str::<Value>(&line) {
            Ok(v) => responses.push(v),
            Err(_) => continue,
        }
        // We expect exactly 3 responses (init, tools/list, tools/call).
        if responses.len() >= 3 {
            break;
        }
    }

    // Give the child a moment to exit on its own, then kill if needed.
    let _ = child.wait_timeout(Duration::from_secs(2));
    let _ = child.kill();
    let _ = child.wait();

    responses
}

#[test]
fn tools_list_exposes_full_tool_surface() {
    let temp = tempdir().expect("tempdir");
    init::run(temp.path()).expect("init");

    let responses = send_handshake(temp.path());
    let list = responses
        .iter()
        .find(|r| r["id"] == json!(2))
        .expect("tools/list response");
    let tools = list["result"]["tools"].as_array().expect("tools array");

    let names: std::collections::HashSet<String> = tools
        .iter()
        .filter_map(|t| t["name"].as_str().map(str::to_string))
        .collect();

    // The MCP surface per addendum §8 and PR4. If any of these go
    // missing the server is silently broken — symptom is an empty
    // tools array even though the server initializes fine.
    let required = [
        "status",
        "search",
        "recall",
        "list_tasks",
        "list_decisions",
        "list_facts",
        "list_pending_writes",
        "get_command",
        "task_add",
        "task_done",
        "record_command",
        "log_session_note",
        "render",
        "propose_fact",
        "propose_decision",
        "archive_transcript",
    ];
    for name in required {
        assert!(
            names.contains(name),
            "tools/list missing `{name}`; got {names:?}",
        );
    }

    if cfg!(feature = "metrics") {
        assert!(
            names.contains("metrics"),
            "reactivated build omitted metrics"
        );
    } else {
        assert!(
            !names.contains("metrics"),
            "hibernated build exposed metrics: {names:?}"
        );
    }
}

#[test]
fn recall_tool_call_round_trips_through_mcp() {
    let temp = tempdir().expect("tempdir");
    init::run(temp.path()).expect("init");
    fact::add(temp.path(), "build", "cargo build", "user", "cli:user").expect("fact");
    decision::add(
        temp.path(),
        "Stage agent writes before promotion",
        "Agents may propose facts and decisions but durable rows require human review.",
        "user+agent:claude-code",
        "cli:user",
    )
    .expect("decision");

    let responses = send_handshake(temp.path());
    let call = responses
        .iter()
        .find(|r| r["id"] == json!(3))
        .expect("tools/call response");
    let body = &call["result"]["structuredContent"];
    let results = body["results"]
        .as_array()
        .expect("results array in structuredContent");

    assert!(!results.is_empty(), "expected at least one recall hit");
    let top = &results[0];
    assert_eq!(top["source_type"], "decision");
    assert!(
        top["title"]
            .as_str()
            .unwrap_or("")
            .to_lowercase()
            .contains("stage"),
        "unexpected top hit: {top}",
    );

    // R6 (issue #72): the MCP recall bundle is a trimmed subset of the
    // CLI's diagnostic `--json` shape. `rank`/`score`/`fts_score`/
    // `vector_score`/`confidence` must never appear on the wire here;
    // `rerank_score` must — present (even as `null` when the re-ranker
    // didn't run, as in this fts-mode call) rather than omitted, so
    // callers can rely on the key existing.
    let hit_obj = top.as_object().expect("recall hit is a JSON object");
    for dropped in ["rank", "score", "fts_score", "vector_score", "confidence"] {
        assert!(
            !hit_obj.contains_key(dropped),
            "MCP recall hit still carries dropped field `{dropped}`: {top}",
        );
    }
    assert!(
        hit_obj.contains_key("rerank_score"),
        "MCP recall hit is missing `rerank_score`: {top}",
    );
}

// Tiny helper to keep the spawn loop terminating on timeout. Avoid pulling
// in the `wait_timeout` crate; do it with a manual poll loop.
trait WaitTimeoutExt {
    fn wait_timeout(&mut self, dur: Duration) -> std::io::Result<Option<std::process::ExitStatus>>;
}

impl WaitTimeoutExt for std::process::Child {
    fn wait_timeout(&mut self, dur: Duration) -> std::io::Result<Option<std::process::ExitStatus>> {
        let start = std::time::Instant::now();
        loop {
            if let Some(status) = self.try_wait()? {
                return Ok(Some(status));
            }
            if start.elapsed() >= dur {
                return Ok(None);
            }
            std::thread::sleep(Duration::from_millis(50));
        }
    }
}

//! Integration coverage for the token-accounting maintenance pass
//! (decision 74, task #30): the recall→session reconciler and the
//! retention pruner.
//!
//! Each test bootstraps a real temp project, crafts `recall_metrics` /
//! `session_metrics` rows with deliberately mixed timestamp formats
//! (SQLite `CURRENT_TIMESTAMP` space form vs Claude Code's ISO-`T`-`Z`
//! form), then exercises the public `maintenance` API directly. One
//! test drives it through the gated `db::open_project` path to prove
//! the master switch wiring.

use std::path::Path;

use memhub::commands::init;
use memhub::config::ProjectConfig;
use memhub::db;
use memhub::metrics::maintenance;
use rusqlite::{Connection, params};
use tempfile::tempdir;

/// Insert a `session_metrics` row. `ended_at = None` models an open
/// (still-running) session.
fn insert_session(
    conn: &Connection,
    session_id: &str,
    agent: &str,
    started_at: &str,
    ended_at: Option<&str>,
) {
    conn.execute(
        "INSERT INTO session_metrics \
            (session_id, agent, started_at, ended_at) \
         VALUES (?1, ?2, ?3, ?4)",
        params![session_id, agent, started_at, ended_at],
    )
    .expect("insert session_metrics");
}

/// Insert a `recall_metrics` row with an explicit `ts` and a NULL
/// `session_id` (the state the recall path always writes).
fn insert_recall(conn: &Connection, ts: &str) {
    conn.execute(
        "INSERT INTO recall_metrics \
            (ts, session_id, query_hash, bundle_tokens, ledger_tokens, \
             rerank_used, result_count) \
         VALUES (?1, NULL, 'hash', 10, 1000, 1, 3)",
        params![ts],
    )
    .expect("insert recall_metrics");
}

fn session_id_of_recall(conn: &Connection, ts: &str) -> Option<String> {
    conn.query_row(
        "SELECT session_id FROM recall_metrics WHERE ts = ?1",
        params![ts],
        |r| r.get(0),
    )
    .expect("query recall row")
}

fn recall_calls(conn: &Connection, session_id: &str) -> i64 {
    conn.query_row(
        "SELECT recall_calls FROM session_metrics WHERE session_id = ?1",
        params![session_id],
        |r| r.get(0),
    )
    .expect("query recall_calls")
}

fn count(conn: &Connection, table: &str) -> i64 {
    conn.query_row(&format!("SELECT COUNT(*) FROM {table}"), [], |r| r.get(0))
        .expect("count")
}

fn open(repo: &Path) -> db::ProjectContext {
    db::open_project(repo).expect("open_project")
}

/// The core correctness case: the recall `ts` is in SQLite
/// `CURRENT_TIMESTAMP` form (space separator) while the session bounds
/// are in Claude Code's ISO `T`/`Z` form. A naive string compare would
/// never match these; the `datetime()` normalization must.
#[test]
fn reconciles_across_mixed_timestamp_formats() {
    let temp = tempdir().expect("tempdir");
    init::run(temp.path()).expect("init");
    let ctx = open(temp.path());

    insert_session(
        &ctx.conn,
        "sess-1",
        "claude-code",
        "2026-05-15T09:00:00.000Z",
        Some("2026-05-15T09:10:00.000Z"),
    );
    insert_recall(&ctx.conn, "2026-05-15 09:05:00");

    let n = maintenance::reconcile(&ctx.conn).expect("reconcile");

    assert_eq!(n, 1, "the one in-window recall is attributed");
    assert_eq!(
        session_id_of_recall(&ctx.conn, "2026-05-15 09:05:00").as_deref(),
        Some("sess-1")
    );
    assert_eq!(recall_calls(&ctx.conn, "sess-1"), 1);
}

/// A recall outside every session window stays NULL and is not counted.
#[test]
fn recall_outside_any_window_is_left_unattributed() {
    let temp = tempdir().expect("tempdir");
    init::run(temp.path()).expect("init");
    let ctx = open(temp.path());

    insert_session(
        &ctx.conn,
        "sess-1",
        "claude-code",
        "2026-05-15T09:00:00.000Z",
        Some("2026-05-15T09:10:00.000Z"),
    );
    insert_recall(&ctx.conn, "2026-05-15 12:00:00"); // hours later

    let n = maintenance::reconcile(&ctx.conn).expect("reconcile");

    assert_eq!(n, 0);
    assert_eq!(session_id_of_recall(&ctx.conn, "2026-05-15 12:00:00"), None);
    assert_eq!(
        recall_calls(&ctx.conn, "sess-1"),
        0,
        "untouched session keeps its default 0"
    );
}

/// A *live* open session (NULL `ended_at`, started within the cap) still
/// attributes a recall inside its window — the common case must keep
/// working.
#[test]
fn live_open_session_attributes_within_cap() {
    let temp = tempdir().expect("tempdir");
    init::run(temp.path()).expect("init");
    let ctx = open(temp.path());

    ctx.conn
        .execute(
            "INSERT INTO session_metrics (session_id, agent, started_at, ended_at) \
             VALUES ('sess-live', 'claude-code', datetime('now','-1 hour'), NULL)",
            [],
        )
        .expect("insert session");
    // CURRENT_TIMESTAMP-form "now-ish" value, comfortably inside the cap.
    ctx.conn
        .execute(
            "INSERT INTO recall_metrics \
                (ts, session_id, query_hash, bundle_tokens, ledger_tokens, \
                 rerank_used, result_count) \
             VALUES (datetime('now', '-1 minute'), NULL, 'h', 1, 2, 0, 1)",
            [],
        )
        .expect("insert recall");

    let n = maintenance::reconcile(&ctx.conn).expect("reconcile");
    assert_eq!(n, 1);
    assert_eq!(recall_calls(&ctx.conn, "sess-live"), 1);
}

/// A *stale* open session (NULL `ended_at`, started long ago) must NOT
/// swallow a much-later recall: its window is capped at `started_at + N h`
/// rather than extending to "now". This is the shape a whole-DB sync
/// adopt imports from another machine — the F3 zombie.
#[test]
fn stale_open_session_window_is_capped_not_unbounded() {
    let temp = tempdir().expect("tempdir");
    init::run(temp.path()).expect("init");
    let ctx = open(temp.path());

    insert_session(
        &ctx.conn,
        "sess-zombie",
        "claude-code",
        "2020-01-01T00:00:00.000Z",
        None,
    );
    ctx.conn
        .execute(
            "INSERT INTO recall_metrics \
                (ts, session_id, query_hash, bundle_tokens, ledger_tokens, \
                 rerank_used, result_count) \
             VALUES (datetime('now', '-1 minute'), NULL, 'h', 1, 2, 0, 1)",
            [],
        )
        .expect("insert recall");

    let n = maintenance::reconcile(&ctx.conn).expect("reconcile");
    assert_eq!(n, 0, "a years-old open zombie must not capture the recall");
    assert_eq!(recall_calls(&ctx.conn, "sess-zombie"), 0);
}

/// Overlapping windows: the recall lands in the overlap and must go to
/// the most-recently-started containing session (documented lossy
/// behavior).
#[test]
fn overlapping_windows_assign_to_latest_started_session() {
    let temp = tempdir().expect("tempdir");
    init::run(temp.path()).expect("init");
    let ctx = open(temp.path());

    insert_session(
        &ctx.conn,
        "sess-early",
        "claude-code",
        "2026-05-15T09:00:00.000Z",
        Some("2026-05-15T09:20:00.000Z"),
    );
    insert_session(
        &ctx.conn,
        "sess-late",
        "codex",
        "2026-05-15T09:10:00.000Z",
        Some("2026-05-15T09:30:00.000Z"),
    );
    insert_recall(&ctx.conn, "2026-05-15 09:15:00"); // in both windows

    maintenance::reconcile(&ctx.conn).expect("reconcile");

    assert_eq!(
        session_id_of_recall(&ctx.conn, "2026-05-15 09:15:00").as_deref(),
        Some("sess-late"),
        "later started_at wins the overlap"
    );
    assert_eq!(recall_calls(&ctx.conn, "sess-late"), 1);
    assert_eq!(recall_calls(&ctx.conn, "sess-early"), 0);
}

/// Reconcile is idempotent: a second pass neither re-attributes an
/// already-assigned row nor double-counts `recall_calls`.
#[test]
fn reconcile_is_idempotent() {
    let temp = tempdir().expect("tempdir");
    init::run(temp.path()).expect("init");
    let ctx = open(temp.path());

    insert_session(
        &ctx.conn,
        "sess-1",
        "claude-code",
        "2026-05-15T09:00:00.000Z",
        Some("2026-05-15T09:59:00.000Z"),
    );
    insert_recall(&ctx.conn, "2026-05-15 09:05:00");
    insert_recall(&ctx.conn, "2026-05-15 09:06:00");
    insert_recall(&ctx.conn, "2026-05-15 09:07:00");

    let first = maintenance::reconcile(&ctx.conn).expect("reconcile 1");
    let second = maintenance::reconcile(&ctx.conn).expect("reconcile 2");

    assert_eq!(first, 3, "all three attributed on the first pass");
    assert_eq!(second, 0, "nothing left to attribute on the second");
    assert_eq!(
        recall_calls(&ctx.conn, "sess-1"),
        3,
        "recount, not a doubling += "
    );
}

/// The pruner drops rows past the horizon, keeps recent ones, and never
/// prunes an open (NULL `ended_at`) session however old it started.
#[test]
fn prune_respects_retention_and_open_sessions() {
    let temp = tempdir().expect("tempdir");
    init::run(temp.path()).expect("init");
    let ctx = open(temp.path());

    insert_recall(&ctx.conn, "2020-01-01 00:00:00"); // ancient
    ctx.conn
        .execute(
            "INSERT INTO recall_metrics \
                (ts, session_id, query_hash, bundle_tokens, ledger_tokens, \
                 rerank_used, result_count) \
             VALUES (datetime('now'), NULL, 'h', 1, 2, 0, 1)",
            [],
        )
        .expect("recent recall");

    insert_session(
        &ctx.conn,
        "old-closed",
        "claude-code",
        "2020-01-01T00:00:00.000Z",
        Some("2020-01-01T01:00:00.000Z"),
    );
    insert_session(
        &ctx.conn,
        "old-open",
        "claude-code",
        "2020-01-01T00:00:00.000Z",
        None,
    );

    let (recalls, sessions) = maintenance::prune_old(&ctx.conn, 90).expect("prune");

    assert_eq!(recalls, 1, "only the 2020 recall is past 90 days");
    assert_eq!(sessions, 1, "only the closed 2020 session is pruned");
    assert_eq!(count(&ctx.conn, "recall_metrics"), 1, "recent recall kept");
    assert!(
        ctx.conn
            .query_row(
                "SELECT 1 FROM session_metrics WHERE session_id = 'old-open'",
                [],
                |_| Ok(())
            )
            .is_ok(),
        "open session is never pruned by age"
    );
}

/// `retention_days = 0` means keep forever — a strict no-op.
#[test]
fn retention_zero_is_a_no_op() {
    let temp = tempdir().expect("tempdir");
    init::run(temp.path()).expect("init");
    let ctx = open(temp.path());

    insert_recall(&ctx.conn, "2000-01-01 00:00:00");
    let (recalls, sessions) = maintenance::prune_old(&ctx.conn, 0).expect("prune");

    assert_eq!((recalls, sessions), (0, 0));
    assert_eq!(count(&ctx.conn, "recall_metrics"), 1);
}

/// The master switch gates the wired `open_project` path: with metrics
/// disabled (the default) the reconciler never runs even though an
/// in-window recall exists; flipping it on makes the next open attribute
/// the row.
#[test]
fn open_project_runs_maintenance_only_when_enabled() {
    let temp = tempdir().expect("tempdir");
    init::run(temp.path()).expect("init");

    {
        let ctx = open(temp.path());
        insert_session(
            &ctx.conn,
            "sess-1",
            "claude-code",
            "2026-05-15T09:00:00.000Z",
            Some("2026-05-15T09:59:00.000Z"),
        );
        insert_recall(&ctx.conn, "2026-05-15 09:05:00");
    }

    // Default config: metrics.enabled = false. open_project runs the
    // gated pass, which must early-return.
    {
        let ctx = open(temp.path());
        assert_eq!(
            session_id_of_recall(&ctx.conn, "2026-05-15 09:05:00"),
            None,
            "disabled: recall stays unattributed"
        );
    }

    // Flip the master switch on disk, reopen.
    let config_path = temp.path().join(".memhub").join("config.toml");
    let mut cfg = ProjectConfig::load(&config_path).expect("load config");
    cfg.metrics.enabled = true;
    cfg.save(&config_path).expect("save config");

    let ctx = open(temp.path());
    assert_eq!(
        session_id_of_recall(&ctx.conn, "2026-05-15 09:05:00").as_deref(),
        Some("sess-1"),
        "enabled: open_project attributed the recall"
    );
    assert_eq!(recall_calls(&ctx.conn, "sess-1"), 1);
}

//! Integration coverage for Component B of the token-accounting
//! subsystem (decision 74, task #29): the Claude Code transcript
//! scraper wired into `db::open_project`.
