// binaries, so the fixture (still at `tests/fixtures/`, untouched) is now one
// level further up.
const FIXTURE: &str = include_str!("../fixtures/claude_session_sample.jsonl");

struct Row {
    agent: String,
    started_at: String,
    ended_at: Option<String>,
    input: i64,
    output: i64,
    cache_read: i64,
    cache_creation: i64,
