fn last_writes_log_for_table(repo: &Path, table: &str) -> Option<(String, String, String)> {
    let ctx = db::open_project(repo).expect("open project");
    ctx.conn
        .query_row(
            "SELECT actor, table_name, action
             FROM writes_log
             WHERE table_name = ?1
             ORDER BY id DESC
             LIMIT 1",
            params![table],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )
        .ok()
}

