    )
    .expect("add fact");
    backdate_fact(temp.path(), "build-command", 200);
    assert!(fact::list(temp.path()).expect("list").remove(0).is_stale);

    // Same key, new value — verified_at should be refreshed by the upsert.
    fact::add(
        temp.path(),
        "build-command",
