//! Isolation + end-to-end coverage for the session-transcript archiver
//! (Wave 6 W3, issue #96). The tier:opus core here is the *exclusion*
//! invariants — a transcript is a compressed file plus a pointer row and
//! must never leak into embedding, recall, or export/import. These tests
//! are modeled on the docs / M11 isolation tests (`export_excludes_*`,
//! the code-index "never read by recall" posture).

use std::fs;
use std::path::Path;

use memhub::commands::{export, fact, import, init, search, transcript};
use memhub::config::ProjectConfig;
use memhub::db;
use tempfile::tempdir;

/// A distinctive token planted in the transcript body so a leak into any
/// searchable/exported surface is unambiguous.
const MARKER: &str = "TRANSCRIPTSECRETMARKER42";

fn set_claude_dir(repo: &Path, dir: &Path) {
    let config_path = repo.join(".memhub").join("config.toml");
    let mut cfg = ProjectConfig::load(&config_path).expect("load config");
    cfg.metrics.claude_transcripts_dir = dir.to_string_lossy().into_owned();
    cfg.save(&config_path).expect("save config");
}

/// Init a repo, point the Claude transcripts dir at a temp dir, drop a
/// session JSONL carrying the unique marker, and archive it (approved).
fn archive_a_marked_transcript(repo: &Path) -> transcript::ArchiveReport {
    init::run(repo).expect("init");
    let tdir = repo.join("claude-transcripts");
    fs::create_dir_all(&tdir).expect("tdir");
    let source = tdir.join("sess-iso.jsonl");
    fs::write(
        &source,
        format!("{{\"type\":\"assistant\",\"secret\":\"{MARKER}\"}}\n"),
    )
    .expect("write transcript");
    set_claude_dir(repo, &tdir);
    transcript::archive(repo, transcript::Agent::Claude, "sess-iso", true).expect("archive")
}

#[test]
fn archive_writes_a_compressed_copy_under_memhub_and_a_pointer_row() {
    let temp = tempdir().expect("tempdir");
    let report = archive_a_marked_transcript(temp.path());

    assert!(report.archive_path.exists());
    assert!(
        report
            .archive_path
            .to_string_lossy()
            .ends_with(".jsonl.zst")
    );
    assert!(
        report
            .archive_path
            .starts_with(temp.path().join(".memhub").join("transcripts")),
        "archive must land under .memhub/transcripts/: {}",
        report.archive_path.display()
    );

    let ctx = db::open_project(temp.path()).expect("open");
    let count: i64 = ctx
        .conn
        .query_row(
            "SELECT COUNT(*) FROM session_transcripts WHERE session_id = 'sess-iso'",
            [],
            |r| r.get(0),
        )
        .expect("count");
    assert_eq!(count, 1, "exactly one pointer row for the archived session");
}

fn embeddings_count(repo: &Path) -> i64 {
    let ctx = db::open_project(repo).expect("open");
    ctx.conn
        .query_row("SELECT COUNT(*) FROM embeddings", [], |r| r.get(0))
        .expect("count embeddings")
}

#[test]
fn archived_transcript_is_never_embedded() {
    let temp = tempdir().expect("tempdir");
    init::run(temp.path()).expect("init");
    let tdir = temp.path().join("claude-transcripts");
    fs::create_dir_all(&tdir).expect("tdir");
    fs::write(
        tdir.join("sess-iso.jsonl"),
        format!("{{\"type\":\"assistant\",\"secret\":\"{MARKER}\"}}\n"),
    )
    .expect("write transcript");
    set_claude_dir(temp.path(), &tdir);

    // Snapshot the total embeddings row count, archive, snapshot again:
    // archiving a transcript must add exactly zero embedding rows. This
    // catches a leak even if it were ever mis-tagged with some other
    // source_type (which the string-scoped check below cannot).
    let before = embeddings_count(temp.path());
    transcript::archive(temp.path(), transcript::Agent::Claude, "sess-iso", true).expect("archive");
    let after = embeddings_count(temp.path());
    assert_eq!(
        before, after,
        "archiving a transcript must add zero embedding rows (was {before}, now {after})"
    );

    // And, specifically, nothing is ever tagged as a transcript source —
    // there is no `SourceType::Transcript`.
    let ctx = db::open_project(temp.path()).expect("open");
    let transcript_embeddings: i64 = ctx
        .conn
        .query_row(
            "SELECT COUNT(*) FROM embeddings WHERE source_type = 'transcript'",
            [],
            |r| r.get(0),
        )
        .expect("count transcript embeddings");
    assert_eq!(transcript_embeddings, 0);
}

#[test]
fn archived_transcript_is_never_in_recall_or_search() {
    let temp = tempdir().expect("tempdir");
    archive_a_marked_transcript(temp.path());

    // FTS search (hermetic; no embedding model) for the unique marker
    // returns nothing: a transcript lives in no FTS-backed source table,
    // so recall/search cannot surface it.
    let response = search::run(temp.path(), MARKER, 10).expect("search runs");
    assert!(
        response.results.is_empty(),
        "transcript content leaked into search: {:?}",
        response.results
    );
}

#[test]
fn archived_transcript_is_excluded_from_export() {
    let temp = tempdir().expect("tempdir");
    archive_a_marked_transcript(temp.path());

    let dest = temp.path().join("export.json");
    export::run(temp.path(), &dest).expect("export succeeds");
    let raw = fs::read_to_string(&dest).expect("read export");

    // No session_transcripts key in the export shape ...
    let object = serde_json::from_str::<serde_json::Value>(&raw)
        .expect("parse json")
        .as_object()
        .expect("top-level object")
        .clone();
    assert!(
        !object.contains_key("session_transcripts"),
        "export must not carry a session_transcripts table"
    );
    // ... and the raw transcript content never appears anywhere in it.
    assert!(
        !raw.contains(MARKER),
        "transcript content leaked into the export payload"
    );
}

#[test]
fn transcript_archive_does_not_travel_through_import() {
    let source = tempdir().expect("source tempdir");
    archive_a_marked_transcript(source.path());
    // A durable row so the export/import path has something to carry.
    fact::add(source.path(), "build", "cargo build", "user", "cli:user").expect("fact");

    let export_path = source.path().join("export.json");
    export::run(source.path(), &export_path).expect("export");

    let target = tempdir().expect("target tempdir");
    init::run(target.path()).expect("target init");
    import::run(target.path(), &export_path, false).expect("import");

    let ctx = db::open_project(target.path()).expect("open target");
    let count: i64 = ctx
        .conn
        .query_row("SELECT COUNT(*) FROM session_transcripts", [], |r| r.get(0))
        .expect("count");
    assert_eq!(count, 0, "import must not materialize any transcript rows");
    // The durable data still crossed — proving the import actually ran.
    let facts = fact::list(target.path()).expect("list facts");
    assert_eq!(facts.len(), 1);
}

#[test]
fn archive_errors_clearly_for_a_missing_session() {
    let temp = tempdir().expect("tempdir");
    init::run(temp.path()).expect("init");
    let tdir = temp.path().join("claude-transcripts");
    fs::create_dir_all(&tdir).expect("tdir");
    set_claude_dir(temp.path(), &tdir);

    let err = transcript::archive(temp.path(), transcript::Agent::Claude, "nope", true)
        .expect_err("must error on a missing transcript");
    assert!(
        err.to_string().contains("no Claude transcript found"),
        "unexpected error: {err}"
    );
}

#[test]
fn archive_refuses_without_explicit_approval_even_with_a_valid_session() {
    let temp = tempdir().expect("tempdir");
    let tdir = temp.path().join("claude-transcripts");
    init::run(temp.path()).expect("init");
    fs::create_dir_all(&tdir).expect("tdir");
    fs::write(tdir.join("sess-x.jsonl"), "{}\n").expect("write");
    set_claude_dir(temp.path(), &tdir);

    let err = transcript::archive(temp.path(), transcript::Agent::Claude, "sess-x", false)
        .expect_err("must refuse without approval");
    assert!(err.to_string().contains("explicit approval"), "{err}");

    // Nothing was written: the refusal is total, not partial.
    let ctx = db::open_project(temp.path()).expect("open");
    let count: i64 = ctx
        .conn
        .query_row("SELECT COUNT(*) FROM session_transcripts", [], |r| r.get(0))
        .expect("count");
    assert_eq!(count, 0);
    assert!(!temp.path().join(".memhub").join("transcripts").exists());
}

#[test]
fn archive_refuses_a_path_traversal_session_id_without_reading_outside() {
    let temp = tempdir().expect("tempdir");
    init::run(temp.path()).expect("init");
    let tdir = temp.path().join("claude-transcripts");
    fs::create_dir_all(&tdir).expect("tdir");
    set_claude_dir(temp.path(), &tdir);

    // Plant a "secret" transcript OUTSIDE the transcripts dir that a
    // traversal id like `../outside` would path-resolve to
    // (<tdir>/../outside.jsonl == <temp>/outside.jsonl).
    fs::write(
        temp.path().join("outside.jsonl"),
        format!("{{\"leaked\":\"{MARKER}\"}}\n"),
    )
    .expect("write outside secret");

    for evil in ["../outside", "..\\outside", "a/b", ".."] {
        let err = transcript::archive(temp.path(), transcript::Agent::Claude, evil, true)
            .expect_err("traversal id must be refused");
        let msg = err.to_string();
        assert!(
            msg.contains("path separator") || msg.contains(".."),
            "expected a traversal-refusal message for {evil:?}, got: {msg}"
        );
    }

    // No read happened, no archive was written, no pointer row exists, and
    // the planted secret never entered `.memhub/`.
    assert!(
        !temp.path().join(".memhub").join("transcripts").exists(),
        "a refused traversal must not create the archive dir"
    );
    let ctx = db::open_project(temp.path()).expect("open");
    let count: i64 = ctx
        .conn
        .query_row("SELECT COUNT(*) FROM session_transcripts", [], |r| r.get(0))
        .expect("count");
    assert_eq!(count, 0, "no pointer row for a refused traversal id");
}

//! CLI-level tests for `memhub wrapup-policy [--json]` (Wave 6 W1+W2,
//! issue #95): the resolved level and full policy text render correctly
//! for each `[wrap_up] verbosity`, the `--json` shape is the wrapped
//! `{"wrapup_policy": {...}}` object (Q29 convention, matching
//! `doctor`/`audit_md`'s own siblings), and the command never writes to
//! the DB.
//!
//! Real-binary spawn (not a direct library call) is deliberate here: it
//! is the only way to exercise the actual `--json` text a user/script
//! sees, since `cli::output`'s JSON builders are crate-private (same
//! reasoning `tests/audit_md.rs` uses for `audit md --json`).

use std::path::Path;
use std::process::Command;

use memhub::commands::init;
use memhub::config::{ProjectConfig, WrapUpVerbosity};
use memhub::db;
use serde_json::Value;
use tempfile::tempdir;

fn memhub_bin() -> &'static str {
    env!("CARGO_BIN_EXE_memhub")
}

fn run_cli(repo: &Path, args: &[&str]) -> std::process::Output {
    Command::new(memhub_bin())
        .args(args)
        .current_dir(repo)
        .env("MEMHUB_LOG", "off")
        .output()
        .expect("spawn memhub binary")
}

fn verbosity_from_label(level: &str) -> WrapUpVerbosity {
    match level {
        "minimal" => WrapUpVerbosity::Minimal,
        "standard" => WrapUpVerbosity::Standard,
        "full" => WrapUpVerbosity::Full,
        "transcript" => WrapUpVerbosity::Transcript,
        other => panic!("unknown wrap_up verbosity label {other:?}"),
    }
}

fn set_verbosity(repo: &Path, level: &str) {
    let paths = db::discover_paths(repo).expect("discover paths");
    let mut config = ProjectConfig::load(&paths.config_path).expect("load config");
    config.wrap_up.verbosity = verbosity_from_label(level);
    config.save(&paths.config_path).expect("save config");
}

fn wrapup_policy_json(output: &std::process::Output) -> Value {
    let root: Value = serde_json::from_slice(&output.stdout).unwrap_or_else(|e| {
        panic!(
            "invalid json on stdout: {e}\nstdout: {}\nstderr: {}",
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        )
    });
    root["wrapup_policy"].clone()
}

#[test]
fn default_repo_resolves_standard_and_exits_zero() {
    let temp = tempdir().expect("tempdir");
    init::run(temp.path()).expect("init");

    let output = run_cli(temp.path(), &["wrapup-policy", "--json"]);
    assert!(
        output.status.success(),
        "stderr: {}",
        String::from_utf8_lossy(&output.stderr)
    );

    let wrapup_policy = wrapup_policy_json(&output);
    assert_eq!(wrapup_policy["verbosity"], "standard");
    let instructions = wrapup_policy["instructions"]
        .as_str()
        .expect("instructions is a string");
    assert!(instructions.contains("level: standard"));
    assert!(instructions.contains("Synthesize eight things"));
}

#[test]
fn human_output_prints_the_resolved_level_and_instructions() {
    let temp = tempdir().expect("tempdir");
    init::run(temp.path()).expect("init");

    let output = run_cli(temp.path(), &["wrapup-policy"]);
    assert!(
        output.status.success(),
        "stderr: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    let stdout = String::from_utf8_lossy(&output.stdout);
    assert!(stdout.contains("Level: standard"), "stdout: {stdout}");
    assert!(stdout.contains("## Detection"), "stdout: {stdout}");
}

#[test]
fn each_configured_level_is_reflected_in_json_output() {
    let temp = tempdir().expect("tempdir");
    init::run(temp.path()).expect("init");

    for level in ["minimal", "standard", "full", "transcript"] {
        set_verbosity(temp.path(), level);

        let output = run_cli(temp.path(), &["wrapup-policy", "--json"]);
        assert!(output.status.success(), "level {level}");
        let wrapup_policy = wrapup_policy_json(&output);
        assert_eq!(wrapup_policy["verbosity"], level, "level {level}");
        let instructions = wrapup_policy["instructions"]
            .as_str()
            .unwrap_or_else(|| panic!("instructions missing for level {level}"));
        assert!(
            instructions.contains(&format!("level: {level}")),
            "level {level}: {instructions}"
        );
    }
