}

/// True when `s` is a YAML block-scalar indicator on its own: `>` or `|`,
/// optionally followed by chomping (`-`/`+`) and/or an explicit indentation
/// digit, and nothing else. Anything past that is the block's own
/// (indented, continuation-line) content, not part of the indicator.
fn is_block_scalar_indicator(s: &str) -> bool {
    let mut chars = s.chars();
    match chars.next() {
        Some('>') | Some('|') => {}
        _ => return false,
    }
    chars.all(|c| c == '-' || c == '+' || c.is_ascii_digit())
}

/// True when `s` is entirely wrapped in matching single or double quotes,
/// i.e. a quoted YAML scalar rather than a bare plain scalar.
fn is_safely_quoted(s: &str) -> bool {
    let bytes = s.as_bytes();
    if bytes.len() < 2 {
        return false;
    }
    let first = bytes[0];
    let last = bytes[bytes.len() - 1];
    (first == b'"' && last == b'"') || (first == b'\'' && last == b'\'')
}

/// Guards the F13 regression class: task 77 appended `Trigger on:
/// "..."` phrase lists into skill frontmatter `description:` fields as
/// plain, unquoted YAML scalars. A plain scalar containing `": "`
/// (colon-space) is invalid YAML — most parsers respond by silently
/// dropping the whole `description` field rather than raising an error,
/// so four high-traffic skills (recall/locate/metrics/doc) lost their
/// routing description on all three agents with nothing failing a
/// build. This test intentionally does not depend on a YAML parser
/// (memhub does not pull in serde_yaml or any other yaml crate); it
/// only checks the one shape that broke: a plain or quoted
/// `description:` scalar must not contain a bare `": "` unless it is
/// switched to a block-scalar form (`description: >` / `description:
/// |`) or the whole value is wrapped in matching quotes.
#[test]
fn skill_frontmatter_descriptions_are_valid_yaml_scalars() {
    let mut failures = Vec::new();

    for path in all_skill_template_files() {
        let content =
            fs::read_to_string(&path).unwrap_or_else(|e| panic!("read {}: {e}", path.display()));

        let mut lines = content.lines();
        if lines.next() != Some("---") {
            failures.push(format!(
                "{}: does not start with a `---` frontmatter delimiter",
                path.display()
            ));
            continue;
        }

        let mut frontmatter: Vec<&str> = Vec::new();
        let mut closed = false;
        for line in lines {
            if line.trim() == "---" {
                closed = true;
                break;
            }
            frontmatter.push(line);
        }
        if !closed {
            failures.push(format!(
                "{}: frontmatter has no closing `---`",
                path.display()
            ));
            continue;
        }

        let Some(description_line) = frontmatter.iter().find(|l| l.starts_with("description:"))
        else {
            failures.push(format!(
                "{}: frontmatter has no `description:` key",
                path.display()
            ));
            continue;
        };

        let inline = description_line["description:".len()..].trim();

        if is_block_scalar_indicator(inline) || is_safely_quoted(inline) {
            continue;
        }

        if inline.contains(": ") {
            failures.push(format!(
                "{}: `description:` is a plain scalar containing `\": \"`, \
                 which is invalid YAML (the parser drops the whole field) — \
                 wrap it in a block scalar (`description: >`) or quote the \
                 whole value. Offending value: {inline:?}",
                path.display()
            ));
        }
    }

    assert!(
        failures.is_empty(),
        "skill frontmatter `description:` scalars are invalid YAML:\n{}",
        failures.join("\n")
    );
}

//! Shared test-only synchronization helpers for the `upgrade_harness` binary.
//!
//! `db::home_dir()` (which reads `$HOME` / `%USERPROFILE%`) is consulted by
//! `db::discover_paths` **unconditionally as its first line**, before any
//! ancestor-walk short-circuit — so *every* call to `discover_paths` /
//! `open_project` / `open_global` / `global_store_exists` reads these vars,
//! whether or not the specific call ends up depending on the value. Several
//! tests here additionally override `HOME`/`USERPROFILE` (and one also
//! `MEMHUB_REGISTRY_TMP_OK`) with `std::env::set_var`/`remove_var` to
//! redirect machine-global-store resolution at a throwaway tempdir.
//!
//! Before Wave 5 U4 (issue #90) each such test lived in its own `tests/*.rs`
//! binary — its own OS process — so none of this mattered: a read or write
//! in one process can never race a read or write in another, and nothing
//! needed to be undone (the process was about to exit anyway). Consolidating
//! every integration-test file into a handful of shared harness binaries
//! puts these tests in the same process on `cargo test`'s default
//! multi-threaded harness, where two new hazards appear:
//!
//! 1. A **writer** test's `set_var`/`remove_var` racing a **reader** test's
//!    concurrent `var_os` read of the same variable is a data race at the
//!    OS/libc level — exactly why `std::env::set_var`/`remove_var` are
//!    `unsafe` — regardless of whether the reading test's own assertions
//!    end up depending on the value it read. `env_read_lock()` /
//!    `env_write_lock()` below close this for every test that reaches
//!    `home_dir()`, reader or writer, not only the ones whose behavior is
//!    observably sensitive to the value.
//! 2. A writer that overrides `HOME`/`USERPROFILE` and only *partially*
//!    restores them on the way out (several of these tests `remove_var`
//!    the one they set but never restore the other one they also cleared
//!    during setup) permanently corrupts environment resolution for every
//!    later test in the process. `env_write_lock()` returns an RAII guard
//!    that snapshots `HOME` / `USERPROFILE` / `MEMHUB_REGISTRY_TMP_OK` on
//!    entry and restores the exact prior state (present with its prior
//!    value, or absent) on drop, regardless of what the test itself did or
//!    whether it panicked.
//!
//! Implementation: a single `RwLock<()>` rather than a plain `Mutex`, so
//! reader tests (the majority — anything that calls `open_project` et al.
//! without itself mutating `HOME`) can still run concurrently with each
//! other; only a writer excludes everyone (readers and other writers alike)
//! for the — brief — duration of its override.
//!
//! ## Reader-trigger closure — when a NEW test needs `env_read_lock()`
//!
//! `db::home_dir()` is resolved, in-process, by every function below —
//! directly or by calling something else in this list. If a test in this
//! harness calls ANY of these (or a `commands::*` function not listed here
//! that itself calls `open_project`/`init::run`/one of these — the command
//! surface keeps growing, so treat "does it take a repo `Path` and touch
//! `db`/`commands`" as the default-unsafe assumption, not this list as
//! exhaustive-forever), it needs `env_read_lock()` (or `env_lock()` if it
//! also mutates `HOME`/`USERPROFILE`/`MEMHUB_REGISTRY_TMP_OK` itself):
//!
//! - `db::home_dir`, `db::global_db_path`, `db::global_store_exists`
//! - `db::discover_paths`, `db::open_project`, `db::open_global`
//! - `db::registry::{record_open_best_effort, register, list_known}`
//! - `commands::audit_md::run`, `commands::upgrade::check_audit_md`
//! - `commands::global::{begin_write, enable, status}`
//! - `commands::status::run`
//! - `commands::pending_write::{insert_pending_write, propose_fact, ...}`
//! - `commands::upgrade::{sync_skills, verify_global, verify_last,
//!   write_last_upgrade, cargo_bin_path, local_bin_shadow, abbrev,
//!   detect_codex_sessions_dir, detect_claude_transcripts_dir}`
//! - `commands::sync::expand_home`, `commands::doctor::run`
//!
//! Genuinely outside the closure (no lock needed) is a short, specific
//! list, not a default: `db::ProjectPaths::for_repo_root` (pure path join),
//! `ProjectConfig::load`/`::save` (plain `fs`+`toml`, no path resolution),
//! `db::init_project` **called on its own** (it never is, in this harness),
//! `commands::init::run` (as of the `sync_md` channel's retirement — audit
//! C5 / task 119 — its only step that reaches `db::home_dir()` was the
//! trailing `sync_md::sync_project` call, now gone; `db::init_project`,
//! which it calls, is clean in isolation).
//! Tests that still wrap an `init::run`-only setup in `env_read_lock()` are
//! being conservative, not wrong — the guard is harmless, just no longer
//! load-bearing for that call alone. Also outside the closure: any
//! `memhub::*` function whose signature takes no repo `Path` at all
//! (e.g. `agents_md::generate_agents_md`, `managed_block::parse_managed_block`
//! — pure string transforms), raw `std::fs`/`tempfile` calls on a path the
//! test already has in hand, and spawning the compiled binary as a child
//! process (`std::process::Command`) — a child gets its own independent
//! snapshot of the environment at spawn time, in a separate address space,
//! so nothing it does in-process can race the parent test's threads,
//! however deep into this closure the *child's own* execution goes.
use std::env;
use std::ffi::OsString;
use std::sync::{OnceLock, RwLock, RwLockReadGuard, RwLockWriteGuard};

static ENV_LOCK: OnceLock<RwLock<()>> = OnceLock::new();

fn lock() -> &'static RwLock<()> {
    ENV_LOCK.get_or_init(|| RwLock::new(()))
}

/// Held for a test that only *reads* `HOME`/`USERPROFILE` resolution
/// in-process (directly, or transitively via `open_project` /
/// `discover_paths` / `open_global` / `global_store_exists` /
/// `check_audit_md` / `db::home_dir`) without mutating it. Takes a shared
/// read guard: any number of reader tests run concurrently with each
/// other, but all are excluded while a writer (see `env_write_lock`) holds
/// the exclusive write guard, so a reader's `var_os` call can never
/// overlap a writer's `set_var`/`remove_var`.
pub struct EnvReadGuard {
    _guard: RwLockReadGuard<'static, ()>,
}

/// Acquire the shared read guard. Bind to a variable held for the whole
/// test body (e.g. `let _env_guard = crate::support::env_read_lock();` as
/// the first line) so it spans every in-process call the test makes.
pub fn env_read_lock() -> EnvReadGuard {
    let guard = lock()
        .read()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    EnvReadGuard { _guard: guard }
}

/// Held for a test that *mutates* `HOME` / `USERPROFILE` /
/// `MEMHUB_REGISTRY_TMP_OK` (directly with `set_var`/`remove_var`). Takes
/// the exclusive write guard (blocking every reader and every other
/// writer), and restores all three vars to their exact pre-test state on
/// drop.
pub struct EnvWriteGuard {
    _guard: RwLockWriteGuard<'static, ()>,
    home: Option<OsString>,
    userprofile: Option<OsString>,
    registry_tmp_ok: Option<OsString>,
}

/// Acquire the exclusive write guard and snapshot `HOME` / `USERPROFILE` /
/// `MEMHUB_REGISTRY_TMP_OK`. Bind to a variable held for the whole test
/// body (e.g. `let _env_guard = crate::support::env_lock();` as the first
/// line) so both the lock and the restore-on-drop span the entire test,
/// including any early return via `?` or a panic from a failed assertion.
///
/// Recovers from a poisoned lock rather than propagating the poison: the
/// guarded resource is "don't race on / leak ambient env vars", not data
/// that a panicking test could leave in a genuinely corrupt state, so one
/// test's panic must not cascade into spurious failures for every later
/// test that needs this same lock.
pub fn env_lock() -> EnvWriteGuard {
    let guard = lock()
        .write()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    EnvWriteGuard {
        _guard: guard,
        home: env::var_os("HOME"),
        userprofile: env::var_os("USERPROFILE"),
        registry_tmp_ok: env::var_os("MEMHUB_REGISTRY_TMP_OK"),
    }
}

impl Drop for EnvWriteGuard {
    fn drop(&mut self) {
        // SAFETY: `self._guard` (held until this whole struct finishes
        // dropping, i.e. until after this fn returns) still excludes every
        // reader and writer in this process, so restoring here cannot race
        // a sibling test's read or write of the same variables.
        unsafe {
            match self.home.take() {
                Some(v) => env::set_var("HOME", v),
                None => env::remove_var("HOME"),
            }
            match self.userprofile.take() {
                Some(v) => env::set_var("USERPROFILE", v),
                None => env::remove_var("USERPROFILE"),
            }
            match self.registry_tmp_ok.take() {
                Some(v) => env::set_var("MEMHUB_REGISTRY_TMP_OK", v),
                None => env::remove_var("MEMHUB_REGISTRY_TMP_OK"),
            }
        }
    }
}

//! `memhub upgrade`'s best-effort audit-md nag (Wave 2 C7, issue #33).
//!
//! Two guarantees are load-bearing and tested here:
//!
//! 1. The nag line appears when `memhub audit md` finds something — a
//!    drifted `AGENTS.md` (the same fixture shape
//!    `tests/audit_md.rs::drifted_agents_md_is_a_finding` uses)
//!    produces `AuditNagStatus::Findings` and a human-readable nag
//!    line; a clean repo produces neither (issue #33: "prints a single
//!    nag line when findings exist", not on every run — unlike the
//!    always-printed skills/gc lines).
//! 2. The audit itself failing to even run (e.g. `.memhub` not
//!    discoverable from `cwd`) degrades to `AuditNagStatus::Warn`
//!    rather than propagating an error. `check_audit_md` returns a
//!    plain `AuditNag`, never a `Result`, so there is no `?` for an
//!    upgrade caller to trip over — this is the structural guarantee
//!    that an audit failure can never fail the upgrade path.
//!
//! Neither test overrides `HOME` itself (unlike `upgrade_registry.rs` /
//! `upgrade_skills.rs`) and `check_audit_md` is read-only and never opens
//! a DB — but it does call `commands::audit_md::run`, which calls
//! `db::discover_paths`, which resolves `db::home_dir()` **unconditionally
//! as its first line**, before any ancestor-walk short-circuit — so the
//! `var_os` read always happens here, on every call, regardless of what
//! the walk goes on to do with it. Both tests therefore take
//! `support::env_read_lock()` for the whole test — see
//! `upgrade/support.rs` (Wave 5 U4, issue #90) — so a sibling writer
//! test's `HOME`/`USERPROFILE` override in this shared harness binary can
//! never race that read (a reader/reader overlap between these two tests
//! is fine and allowed). Neither test itself mutates `HOME`, so
//! `env_read_lock()` — not the exclusive `env_lock()` the writer tests
//! use — is the correct guard here.

use std::fs;

use memhub::agents_md::generate_agents_md;
use memhub::commands::init;
use memhub::commands::upgrade::{AuditNagStatus, check_audit_md};
use tempfile::tempdir;

/// Satisfies every `audit md` check at once (size, managed block,
/// keystones) so only the thing each test mutates produces a finding —
/// same fixture `tests/audit_md.rs::clean_claude_md` uses.
const CLEAN_CLAUDE_MD: &str = "# memhub\n\n\
    Local-first. Agents are untrusted writers.\n\n\
    <!-- memhub:managed-block v=1 -->\n\
    memhub-primary: true\n\
    db: .memhub/project.sqlite\n\
    rendered: .memhub/rendered/\n\
    config: .memhub/config.toml\n\
    <!-- /memhub:managed-block -->\n\n\
    ## Session Continuity\n\n\
    stale_embeddings gate. sync_adopt gate.\n";

#[test]
fn nag_line_appears_on_a_drifted_fixture_and_is_silent_when_clean() {
    // Held for the whole test (see module header and `upgrade/support.rs`).
    let _env_guard = crate::support::env_read_lock();

    let temp = tempdir().expect("tempdir");
    init::run(temp.path()).expect("init");

    // --- clean repo: status Clean, no nag line in either mode --------
    let generated = generate_agents_md(CLEAN_CLAUDE_MD);
    fs::write(temp.path().join("CLAUDE.md"), CLEAN_CLAUDE_MD).expect("write CLAUDE.md");
    fs::write(temp.path().join("AGENTS.md"), &generated).expect("write AGENTS.md");

    let clean = check_audit_md(temp.path());
    assert_eq!(clean.status, AuditNagStatus::Clean, "{clean:?}");
    assert_eq!(clean.count, 0);
    assert!(
        clean.nag_line(false).is_none(),
        "a clean repo must not print a nag line: {clean:?}"
    );
    assert!(
        clean.nag_line(true).is_none(),
        "a clean repo must not print a would-nag line either: {clean:?}"
    );

    // --- drifted fixture: AGENTS.md no longer matches the generator --
    fs::write(
        temp.path().join("AGENTS.md"),
        "stale, hand-edited content\n",
    )
    .expect("write stale AGENTS.md");

    let drifted = check_audit_md(temp.path());
    assert_eq!(drifted.status, AuditNagStatus::Findings, "{drifted:?}");
    assert!(drifted.count >= 1, "{drifted:?}");

    let line = drifted
        .nag_line(false)
        .expect("a drifted repo must produce a nag line");
    assert!(line.contains("finding"), "nag line: {line:?}");
    assert!(
        line.contains("audit md") || line.contains("audit-md"),
        "nag line should point at the audit command or skill: {line:?}"
    );

    let dry_line = drifted
        .nag_line(true)
        .expect("dry-run must report it would nag");
    assert!(
        dry_line.contains("would"),
        "dry-run nag line should read as a preview: {dry_line:?}"
    );
}

#[test]
fn audit_error_degrades_to_a_warn_row_not_a_failure() {
    // Held for the whole test (see module header and `upgrade/support.rs`):
    // this is the one that actually walks past its own (nonexistent)
    // project dir up to real ancestors, so it is genuinely outcome-sensitive
    // to a racing `HOME` override — but the read-lock is required either way.
    let _env_guard = crate::support::env_read_lock();

    // A tempdir with no `.memhub` anywhere in its ancestry (deliberately
    // no `init::run` here): `audit md`'s own `db::discover_paths` call
    // fails with `NotInitialized`. `check_audit_md` must not propagate
    // that — it surfaces as a `Warn` row instead of a crash or an `Err`
    // an upgrade caller would have to handle.
    let temp = tempdir().expect("tempdir");

    let nag = check_audit_md(temp.path());
    assert_eq!(nag.status, AuditNagStatus::Warn, "{nag:?}");
    assert_eq!(nag.count, 0);
    assert!(
        nag.detail.is_some(),
        "a Warn nag must carry the underlying error as detail: {nag:?}"
    );

    // The degrade-to-warn contract: a caller still gets a one-line,
    // human-readable summary rather than nothing.
    let line = nag
        .nag_line(false)
        .expect("a Warn nag still renders a line");
    assert!(line.starts_with("skipped"), "nag line: {line:?}");

    // The dry-run preview degrades identically — no special-casing that
    // could hide a broken audit specifically in `--dry-run`.
    let dry_line = nag
        .nag_line(true)
        .expect("a Warn nag renders in dry-run too");
    assert!(
        dry_line.starts_with("skipped"),
        "dry nag line: {dry_line:?}"
    );
}

//! U7: `memhub upgrade` degrades instead of aborting on a corrupt registry.
//!
//! Overrides `HOME` to redirect `~/.memhub/global.sqlite` into a tempdir,
//! matching `upgrade_registry.rs`'s discipline (both take
//! `support::env_lock()` for the whole test — see `upgrade/support.rs`,
//! Wave 5 U4 issue #90 — to stay isolated from sibling tests in this
//! shared harness binary). A corrupt registry read used to propagate via
//! `?` and abort the whole `--finish` phase *after* the new binary was
//! already installed. It must now degrade to a warning and a
//! source-repo-only continuation.

use memhub::commands::upgrade::known_projects_or_warn;
use tempfile::tempdir;

#[test]
fn corrupt_registry_degrades_to_source_repo_only_plus_warning() {
    // Held for the whole test (see module header and `upgrade/support.rs`).
    let _env_guard = crate::support::env_lock();

    let home = tempdir().expect("home");
    unsafe {
        std::env::set_var("HOME", home.path());
        std::env::remove_var("USERPROFILE");
    }

    // No global store yet => a clean, empty enumeration, and crucially
    // NOT a warning (absence is normal, not a degrade).
    let mut warnings: Vec<String> = Vec::new();
    let known = known_projects_or_warn(&mut warnings);
    assert!(known.is_empty(), "no store => no known roots");
    assert!(
        warnings.is_empty(),
        "absence of a global store is normal, not a warning: {warnings:?}"
    );

    // Deliberately corrupt the registry. The global store is a SQLite
    // file; garbage bytes make every read of it fail.
    let global = home.path().join(".memhub").join("global.sqlite");
    std::fs::create_dir_all(global.parent().unwrap()).expect("mk .memhub");
    std::fs::write(&global, b"this is not a sqlite database, at all").expect("corrupt store");

    // The upgrade must NOT abort: it degrades to an empty enumeration plus
    // a warning, so the source repo (and any --also roots) still upgrade.
    let mut warnings: Vec<String> = Vec::new();
    let known = known_projects_or_warn(&mut warnings);
    assert!(
        known.is_empty(),
        "a corrupt registry contributes no roots (source-repo-only continuation)"
    );
    assert_eq!(
        warnings.len(),
        1,
        "exactly one degrade warning: {warnings:?}"
    );
    assert!(
        warnings[0].contains("registry") && warnings[0].to_lowercase().contains("unreadable"),
        "the warning must name the corrupt registry: {}",
        warnings[0]
    );

    unsafe {
        std::env::remove_var("HOME");
    }
}

//! Install-manifest resync honesty (Wave 5 / U6, decision Q15).
//!
//! End-to-end over `sync_skills` against a **fabricated** source repo, so
//! the template set is entirely under the test's control. All assertions
//! live in ONE test because it overrides `HOME` (process-global) — it
//! takes `support::env_lock()` for the whole test, same as
//! `upgrade_skills.rs` / `upgrade_registry.rs` (see `upgrade/support.rs`,
//! Wave 5 U4 issue #90).
//!
//! Only the Claude template dir is populated: every other agent's target
//! dir is absent, so those agents skip before their source is ever read.

use std::path::Path;

use memhub::commands::upgrade::{SkillSync, sync_skills};
use tempfile::tempdir;

fn write(path: &Path, contents: &[u8]) {
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent).expect("mkdir");
    }
    std::fs::write(path, contents).expect("write");
}

fn claude_report(repo: &Path) -> SkillSync {
    sync_skills(repo, false)
        .agents
        .into_iter()
        .find(|a| a.agent == "claude")
        .expect("claude agent report")
}

#[test]
fn resync_never_clobbers_user_files_and_reports_orphans() {
    // Held for the whole test (see module header and `upgrade/support.rs`).
    let _env_guard = crate::support::env_lock();

    let home = tempdir().expect("home");
    unsafe {
        std::env::set_var("HOME", home.path());
        std::env::remove_var("USERPROFILE");
    }

    let repo = tempdir().expect("repo");
    let claude_tpl = repo.path().join("templates").join("skills").join("claude");
    write(&claude_tpl.join("foo.md"), b"memhub foo v1");
    write(&claude_tpl.join("bar.md"), b"memhub bar v1");

    // memhub only syncs into a dir the user has already set up.
    let commands = home.path().join(".claude").join("commands");
    std::fs::create_dir_all(&commands).expect("mk commands");

    // --- Run 1: fresh install ---------------------------------------
    let r1 = claude_report(repo.path());
    assert_eq!(r1.synced, 2, "both templates install: {r1:?}");
    assert_eq!(r1.protected, 0);
    assert_eq!(
        std::fs::read(commands.join("foo.md")).unwrap(),
        b"memhub foo v1"
    );
    assert_eq!(
        std::fs::read(commands.join("bar.md")).unwrap(),
        b"memhub bar v1"
    );

    // The manifest is written and records what memhub installed.
    let manifest = home.path().join(".memhub").join("install-manifest.json");
    let manifest_body = std::fs::read_to_string(&manifest).expect("manifest written");
    assert!(
        manifest_body.contains("foo.md") && manifest_body.contains("bar.md"),
        "manifest must record the files memhub wrote: {manifest_body}"
    );

    // --- Run 2: a user's own, same-named file must NOT be clobbered ---
    // The user hand-authors baz.md; memhub then starts shipping a
    // *different* baz.md. memhub never wrote the user's file, so it must
    // leave it exactly as-is.
    write(&commands.join("baz.md"), b"the user's own baz");
    write(&claude_tpl.join("baz.md"), b"memhub baz (different)");
    let r2 = claude_report(repo.path());
    assert_eq!(
        std::fs::read(commands.join("baz.md")).unwrap(),
        b"the user's own baz",
        "a user-authored, same-named file must survive resync untouched"
    );
    assert!(
        r2.protected >= 1,
        "the user's file is reported as protected: {r2:?}"
    );
    assert!(
        r2.synced >= 2,
        "memhub's own files (foo, bar) still sync: {r2:?}"
    );

    // --- Run 3: an orphan is reported but NEVER deleted -------------
    std::fs::remove_file(claude_tpl.join("foo.md")).expect("drop template");
    let full = sync_skills(repo.path(), false);
    assert!(
        full.orphans.iter().any(|o| o.contains("foo.md")),
        "a no-longer-shipped file memhub wrote must be reported as an orphan: {:?}",
        full.orphans
    );
    assert!(
        commands.join("foo.md").exists(),
        "an orphan must be reported, NEVER deleted"
    );
    assert_eq!(
        std::fs::read(commands.join("foo.md")).unwrap(),
        b"memhub foo v1",
        "the orphaned file's contents are left exactly as-is"
    );

    // --- Run 4: a corrupt manifest fails safe -----------------------
    // Corrupt the manifest, then ship a NEW bar.md. With no trustworthy
    // ownership record, memhub must NOT overwrite the existing bar.md —
    // an unknown file is treated as the user's.
    std::fs::write(&manifest, b"}}} not json").expect("corrupt manifest");
    write(&claude_tpl.join("bar.md"), b"memhub bar v2 (new)");
    let r4 = claude_report(repo.path());
    assert_eq!(
        std::fs::read(commands.join("bar.md")).unwrap(),
        b"memhub bar v1",
        "a corrupt manifest must fail safe: never overwrite an existing file"
    );
    assert!(
        r4.protected >= 1,
        "with a corrupt manifest, pre-existing files read as user-owned: {r4:?}"
    );

    unsafe {
        std::env::remove_var("HOME");
    }
}

//! Machine-wide upgrade registry (decision 96 / task 49).
//!
//! Two guarantees are load-bearing and tested here:
//!
//! 1. The registry is self-maintaining, gated on the global store
//!    already existing, and debounced — it never creates the store and
//!    an immediate re-open does not rewrite the row.
//! 2. The **eval-regression guarantee**: a populated `known_projects`
//!    must not change recall output one bit while the repo has
//!    `[global] enabled = false`. Registry membership is not M9 opt-in.
//!
//! All assertions live in ONE test so the `HOME` override (which
//! redirects `~/.memhub/global.sqlite` into a tempdir) stays in one
//! place. It takes `support::env_lock()` for the whole test — see
//! `upgrade/support.rs` (Wave 5 U4, issue #90) — to stay isolated from
//! sibling tests in this shared harness binary.

use memhub::commands::{fact, global, init};
use memhub::config::RetrievalMode;
use memhub::db;
use memhub::retrieval::{RecallOptions, RecallResponse, recall};
use tempfile::tempdir;

fn fts_recall(path: &std::path::Path, query: &str) -> RecallResponse {
    recall(
        path,
        RecallOptions {
            query: query.to_string(),
            mode: Some(RetrievalMode::Fts),
            max_results: 10,
            source_types: vec![],
            include_stale: None,
            accepted_only: None,
            use_reranker: None,
            min_rerank_score: None,
            log_metrics: false,
            surface: None,
        },
    )
    .expect("recall")
}

/// Compare everything that recall promises to be stable. `elapsed_ms`
/// lives on the response and varies run to run, so it is deliberately
/// excluded — the guarantee is "byte-identical modulo wall-clock".
fn assert_recall_identical(a: &RecallResponse, b: &RecallResponse) {
    assert_eq!(
        format!("{:?}", a.results),
        format!("{:?}", b.results),
        "recall results changed when known_projects was populated \
         while [global] disabled — eval-regression guarantee violated"
    );
    assert_eq!(a.candidate_count, b.candidate_count);
    assert_eq!(a.returned_count, b.returned_count);
    assert_eq!(a.available_docs, b.available_docs);
    assert_eq!(a.mode, b.mode);
}

#[test]
fn registry_and_eval_regression_guarantee() {
    // Held for the whole test (see module header and `upgrade/support.rs`).
    let _env_guard = crate::support::env_lock();

    let home = tempdir().expect("home tempdir");
    // The TMP_OK seam lets the registry accept the tempdir repos this test
    // necessarily uses; production excludes OS-temp paths (covered by the
    // registry unit test).
    unsafe {
        std::env::set_var("HOME", home.path());
        std::env::remove_var("USERPROFILE");
        std::env::set_var("MEMHUB_REGISTRY_TMP_OK", "1");
    }

    let repo = tempdir().expect("repo");
    init::run(repo.path()).expect("init");
    fact::add(
        repo.path(),
        "registry-probe",
        "alpha-value",
        "user",
        "cli:user",
    )
    .expect("seed fact");

    // --- baseline recall with NO global store ------------------------
    assert!(
        !db::global_store_exists().expect("exists check"),
        "no global store should exist yet"
    );
    let baseline = fts_recall(repo.path(), "registry-probe");
    assert!(
        !baseline.results.is_empty(),
        "seed fact must be recallable so the comparison is meaningful"
    );

    // --- no global store => registry is inert, store NOT created -----
    assert!(
        db::registry::list_known().expect("list").is_empty(),
        "registry must be empty with no global store"
    );
    let _ = db::open_project(repo.path()).expect("open with no global store");
    assert!(
        !db::global_store_exists().expect("exists check"),
        "opening a project must NOT create the global store"
    );
    assert!(
        db::registry::list_known().expect("list").is_empty(),
        "still empty — record-on-open is gated on the store existing"
    );

    // --- create the store via enable, then opt the repo back OUT ----
    global::enable(repo.path()).expect("enable");
    global::disable(repo.path()).expect("disable");
    assert!(
        db::global_store_exists().expect("exists check"),
        "enable creates the store; disable keeps it on disk"
    );

    // Opening the project now self-registers it (store exists).
    let _ = db::open_project(repo.path()).expect("open with store present");
    let known = db::registry::list_known().expect("list");
    assert_eq!(known.len(), 1, "repo should self-register exactly once");
    assert_eq!(
        known[0].last_schema.as_deref(),
        Some(db::latest_schema_version()),
        "registry records the head schema the repo was brought to"
    );

    // --- debounce: an immediate re-open does not rewrite the row ----
    let seen_before = known[0].last_seen.clone();
    let _ = db::open_project(repo.path()).expect("re-open");
    let known2 = db::registry::list_known().expect("list2");
    assert_eq!(known2.len(), 1, "no duplicate row");
    assert_eq!(
        known2[0].last_seen, seen_before,
        "debounce: last_seen unchanged within the hour window"
    );

    // --- explicit register() adds an --also-style path --------------
    let other = tempdir().expect("other repo");
    let added =
        db::registry::register(other.path(), db::latest_schema_version()).expect("register");
    assert!(added, "register persists when the global store exists");
    assert_eq!(
        db::registry::list_known().expect("list3").len(),
        2,
        "explicit register adds a second known root"
    );

    // --- self-heal: a vanished repo is pruned, not left as junk -----
    let ghost = tempdir().expect("ghost repo");
    init::run(ghost.path()).expect("init ghost");
    let _ = db::open_project(ghost.path()).expect("open ghost");
    assert_eq!(
        db::registry::list_known().expect("list4").len(),
        3,
        "ghost repo registered (repo + other + ghost)"
    );
    let ghost_path = ghost.path().to_path_buf();
    drop(ghost); // tempdir deleted on disk; registry row now dead
    let dead = db::registry::dead_roots().expect("dead_roots");
    assert!(
        dead.iter().any(|p| p == &ghost_path
            || p.canonicalize().ok() == ghost_path.canonicalize().ok()
            || p.to_string_lossy()
                .contains(ghost_path.file_name().unwrap().to_str().unwrap())),
        "the deleted ghost repo must be detected as a dead root"
    );
    let removed = db::registry::prune_dead().expect("prune");
    assert!(removed >= 1, "prune removes at least the ghost row");
    assert!(
        !db::registry::list_known()
            .expect("list5")
            .iter()
            .any(|kp| kp
                .root_path
                .to_string_lossy()
                .contains(ghost_path.file_name().unwrap().to_str().unwrap())),
        "ghost row is gone after prune"
    );

    // --- THE GUARANTEE: populated registry + [global] disabled ------
    // Recall must be byte-identical to the pre-store baseline.
    let after = fts_recall(repo.path(), "registry-probe");
    assert_recall_identical(&baseline, &after);

    unsafe { std::env::remove_var("MEMHUB_REGISTRY_TMP_OK") };
}

//! U6 resync robustness (Wave 5, follow-up review REQUIRED 1b + REQUIRED 2).
//!
//! 1. First-run adoption hint: the first resync over an EMPTY manifest that
//!    leaves a pre-existing, unverifiable file untouched sets `first_run_hint`.
//! 2. A transient source-read failure must NOT cede ownership. A still-owned
//!    file's manifest entry is carried forward so a later run can still UPDATE
//!    it — instead of dropping it (which would freeze the file at its old
//!    version forever, silently).
//!
//! Overrides HOME, matching the other `upgrade_*` tests — takes
//! `support::env_lock()` for the whole test (see `upgrade/support.rs`,
//! Wave 5 U4 issue #90) to stay isolated from sibling tests in this shared
//! harness binary. A *second*, successful agent (opencode-commands) is set
//! up on purpose: it
//! makes the rebuilt manifest non-empty so `save()` actually runs — the exact
//! condition under which the pre-fix code would have DROPPED the failed
//! agent's still-owned entries.

use std::path::Path;

use memhub::commands::upgrade::sync_skills;
use tempfile::tempdir;

fn write(path: &Path, contents: &[u8]) {
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent).expect("mkdir");
    }
    std::fs::write(path, contents).expect("write");
}

#[test]
fn transient_source_failure_preserves_ownership_and_first_run_is_flagged() {
    // Held for the whole test (see module header and `upgrade/support.rs`).
    let _env_guard = crate::support::env_lock();

    let home = tempdir().expect("home");
    unsafe {
        std::env::set_var("HOME", home.path());
        std::env::remove_var("USERPROFILE");
    }

    let repo = tempdir().expect("repo");
    let claude_tpl = repo.path().join("templates").join("skills").join("claude");
    write(&claude_tpl.join("keep.md"), b"memhub keep v1");
    write(&claude_tpl.join("user.md"), b"memhub user (canonical)");
    // A second agent that will keep succeeding, so the rebuilt manifest is
    // non-empty and `save()` runs even while claude's source is unreadable.
    let oc_tpl = repo
        .path()
        .join("templates")
        .join("commands")
        .join("opencode");
    write(&oc_tpl.join("oc.md"), b"memhub oc v1");

    let commands = home.path().join(".claude").join("commands");
    std::fs::create_dir_all(&commands).expect("mk claude commands");
    let oc_commands = home
        .path()
        .join(".config")
        .join("opencode")
        .join("commands");
    std::fs::create_dir_all(&oc_commands).expect("mk oc commands");
    // Pre-existing user file, same name as a template memhub ships.
    write(&commands.join("user.md"), b"the user's own user.md");

    // --- Run A: first run over an EMPTY manifest --------------------
    let a = sync_skills(repo.path(), false);
    assert!(
        a.first_run_hint,
        "first run leaving a pre-existing file untouched must flag the notice"
    );
    let claude = a.agents.iter().find(|x| x.agent == "claude").unwrap();
    assert!(claude.protected >= 1, "{claude:?}");
    assert!(
        claude
            .detail
            .as_deref()
            .unwrap_or_default()
            .contains("unverified owner"),
        "protected detail must be surfaced and honest: {claude:?}"
    );
    assert_eq!(
        std::fs::read(commands.join("keep.md")).unwrap(),
        b"memhub keep v1"
    );
    assert_eq!(
        std::fs::read(commands.join("user.md")).unwrap(),
        b"the user's own user.md",
        "the user's file is left untouched"
    );

    // --- Run B: claude's source becomes momentarily unreadable ------
    // Replace templates/skills/claude (a dir) with a FILE so read_dir fails.
    // opencode-commands still succeeds, so the manifest is saved this run.
    std::fs::remove_dir_all(&claude_tpl).expect("rm src dir");
    std::fs::write(&claude_tpl, b"transiently not a directory").expect("clobber src");

    let b = sync_skills(repo.path(), false);
    assert!(
        !b.orphans.iter().any(|o| o.contains("keep.md")),
        "a still-owned file must NOT be orphaned because its source read failed: {:?}",
        b.orphans
    );
    assert_eq!(
        std::fs::read(commands.join("keep.md")).unwrap(),
        b"memhub keep v1",
        "the owned file is untouched during the transient failure"
    );
    let manifest_body =
        std::fs::read_to_string(home.path().join(".memhub").join("install-manifest.json"))
            .expect("manifest still present");
    assert!(
        manifest_body.contains("keep.md"),
        "the owned entry must be carried forward through the failure, not dropped: {manifest_body}"
    );

    // --- Run C: source recovers, with a CHANGED template ------------
    // If ownership had been ceded in run B, keep.md would now read as
    // user-owned and freeze at v1. Because it was carried, the update lands.
    std::fs::remove_file(&claude_tpl).expect("rm clobber file");
    write(&claude_tpl.join("keep.md"), b"memhub keep V2");
    write(&claude_tpl.join("user.md"), b"memhub user (canonical)");

    let _c = sync_skills(repo.path(), false);
    assert_eq!(
        std::fs::read(commands.join("keep.md")).unwrap(),
        b"memhub keep V2",
        "ownership survived the transient failure, so the update lands"
    );
    assert_eq!(
        std::fs::read(commands.join("user.md")).unwrap(),
        b"the user's own user.md",
        "the user's file remains untouched throughout"
    );

    unsafe {
        std::env::remove_var("HOME");
    }
}

//! `memhub upgrade` installed-skill resync (decision 97 / task 50).
//!
//! Guarantees that are load-bearing and tested here:
//!
//! 1. An agent dir that does **not** exist is skipped, never created
//!    (mirrors `upgrade`'s "only act on what exists" posture).
//! 2. A present agent dir is additively synced from the repo's
//!    `templates/skills/`; the copy is real and idempotent.
//! 3. `--dry-run` counts but mutates nothing.
//! 4. A path that exists but is not a directory is skipped, not
//!    clobbered.
//!
//! All assertions live in ONE test so the `HOME` override stays in one
//! place. It takes `support::env_lock()` for the whole test — see
//! `upgrade/support.rs` (Wave 5 U4, issue #90) — to stay isolated from
//! sibling tests in this shared harness binary.

use std::path::Path;

use memhub::commands::upgrade::{SkillSync, SkillSyncStatus, sync_skills};
use tempfile::tempdir;

fn find(reports: &[SkillSync], agent: &str) -> SkillSync {
    reports
        .iter()
        .find(|r| r.agent == agent)
        .unwrap_or_else(|| panic!("no report for agent {agent}"))
        .clone()
}

fn active_template(path: &Path) -> bool {
    let name = path
        .file_stem()
        .and_then(|s| s.to_str())
        .unwrap_or_default();
    match name {
        "metrics" => cfg!(feature = "metrics"),
        "viz" => cfg!(feature = "viz"),
        _ => true,
    }
}

fn count_claude_templates(repo: &Path) -> usize {
    std::fs::read_dir(repo.join("templates").join("skills").join("claude"))
        .expect("claude templates dir")
        .flatten()
        .filter(|e| e.path().extension().and_then(|x| x.to_str()) == Some("md"))
        .filter(|e| active_template(&e.path()))
        .count()
}

fn count_codex_templates(repo: &Path) -> usize {
    std::fs::read_dir(repo.join("templates").join("skills").join("codex"))
        .expect("codex templates dir")
        .flatten()
        .filter(|e| e.path().is_dir())
        .filter(|e| active_template(&e.path()))
        .count()
}

fn count_opencode_skill_templates(repo: &Path) -> usize {
    std::fs::read_dir(repo.join("templates").join("skills").join("opencode"))
        .expect("opencode skill templates dir")
        .flatten()
        .filter(|e| e.path().is_dir())
        .filter(|e| active_template(&e.path()))
        .count()
}

fn count_opencode_command_templates(repo: &Path) -> usize {
    std::fs::read_dir(repo.join("templates").join("commands").join("opencode"))
        .expect("opencode command templates dir")
        .flatten()
        .filter(|e| e.path().extension().and_then(|x| x.to_str()) == Some("md"))
        .filter(|e| active_template(&e.path()))
        .count()
}

#[test]
fn skill_resync_additive_idempotent_and_conservative() {
    // Held for the whole test, across both HOME overrides below (see module
    // header and `upgrade/support.rs`).
    let _env_guard = crate::support::env_lock();

    let repo = Path::new(env!("CARGO_MANIFEST_DIR"));
    let expect_claude = count_claude_templates(repo);
    let expect_codex = count_codex_templates(repo);
    let expect_opencode_skills = count_opencode_skill_templates(repo);
    let expect_opencode_commands = count_opencode_command_templates(repo);
    assert!(
        expect_claude > 0
            && expect_codex > 0
            && expect_opencode_skills > 0
            && expect_opencode_commands > 0,
        "fixture sanity: the source repo must ship skill templates"
    );

    let home = tempdir().expect("home tempdir");
    unsafe {
        std::env::set_var("HOME", home.path());
        std::env::remove_var("USERPROFILE");
    }

    // --- 1. Neither agent dir exists => skipped, NOT created ----------
    let reports = sync_skills(repo, false).agents;
    let claude = find(&reports, "claude");
    let codex = find(&reports, "codex");
    let opencode_skills = find(&reports, "opencode-skills");
    let opencode_commands = find(&reports, "opencode-commands");
    assert_eq!(claude.status, SkillSyncStatus::Skipped);
    assert_eq!(codex.status, SkillSyncStatus::Skipped);
    assert_eq!(opencode_skills.status, SkillSyncStatus::Skipped);
    assert_eq!(opencode_commands.status, SkillSyncStatus::Skipped);
    assert_eq!(claude.synced, 0);
    assert!(
        !home.path().join(".claude").join("commands").exists(),
        "absent Claude dir must NOT be created by a resync"
    );
    assert!(
        !home.path().join(".codex").join("skills").exists(),
        "absent Codex dir must NOT be created by a resync"
    );
    assert!(
        !home
            .path()
            .join(".config")
            .join("opencode")
            .join("skills")
            .exists(),
        "absent OpenCode skills dir must NOT be created by a resync"
    );
    assert!(
        !home
            .path()
            .join(".config")
            .join("opencode")
            .join("commands")
            .exists(),
        "absent OpenCode commands dir must NOT be created by a resync"
    );

    // --- 2. Create the agent dirs => additive real copy --------------
    let claude_dir = home.path().join(".claude").join("commands");
    let codex_dir = home.path().join(".codex").join("skills");
    let opencode_skills_dir = home.path().join(".config").join("opencode").join("skills");
    let opencode_commands_dir = home
        .path()
        .join(".config")
        .join("opencode")
        .join("commands");
    std::fs::create_dir_all(&claude_dir).expect("mk claude dir");
    std::fs::create_dir_all(&codex_dir).expect("mk codex dir");
    std::fs::create_dir_all(&opencode_skills_dir).expect("mk opencode skills dir");
    std::fs::create_dir_all(&opencode_commands_dir).expect("mk opencode commands dir");
    // A user's own skill in the shared dir must survive (additive only).
    std::fs::write(claude_dir.join("user-own.md"), b"keep me").expect("seed user skill");

    let reports = sync_skills(repo, false).agents;
    let claude = find(&reports, "claude");
    let codex = find(&reports, "codex");
    let opencode_skills = find(&reports, "opencode-skills");
    let opencode_commands = find(&reports, "opencode-commands");
    assert_eq!(claude.status, SkillSyncStatus::Synced, "{claude:?}");
    assert_eq!(codex.status, SkillSyncStatus::Synced, "{codex:?}");
    assert_eq!(
        opencode_skills.status,
        SkillSyncStatus::Synced,
        "{opencode_skills:?}"
    );
    assert_eq!(
        opencode_commands.status,
        SkillSyncStatus::Synced,
        "{opencode_commands:?}"
    );
    assert_eq!(claude.synced, expect_claude);
    assert_eq!(codex.synced, expect_codex);
    assert_eq!(opencode_skills.synced, expect_opencode_skills);
    assert_eq!(opencode_commands.synced, expect_opencode_commands);
    // The copy is real, not just a count.
    assert!(
        claude_dir.join("recall.md").is_file(),
        "a known Claude skill template must land on disk"
    );
    assert!(
        codex_dir.join("recall").join("SKILL.md").is_file(),
        "a known Codex skill dir (with SKILL.md) must land on disk"
    );
    assert!(
        opencode_skills_dir
            .join("recall")
            .join("SKILL.md")
            .is_file(),
        "a known OpenCode skill dir (with SKILL.md) must land on disk"
    );
    assert!(
        opencode_commands_dir.join("recall.md").is_file(),
        "a known OpenCode command wrapper must land on disk"
    );
    assert_eq!(
        claude_dir.join("metrics.md").exists(),
        cfg!(feature = "metrics"),
        "metrics skill installation must follow the compile-time feature"
    );
    assert_eq!(
        codex_dir.join("viz").exists(),
        cfg!(feature = "viz"),
        "viz skill installation must follow the compile-time feature"
    );
    // Additive: the user's unrelated skill is untouched.
    assert_eq!(
        std::fs::read(claude_dir.join("user-own.md")).expect("user skill"),
        b"keep me",
        "additive resync must not disturb a user's own skill"
    );

    // --- 3. Idempotent re-run: same result, no error -----------------
    let reports = sync_skills(repo, false).agents;
    assert_eq!(find(&reports, "claude").status, SkillSyncStatus::Synced);
    assert_eq!(find(&reports, "claude").synced, expect_claude);
    assert_eq!(find(&reports, "codex").synced, expect_codex);
    assert_eq!(
        find(&reports, "opencode-skills").synced,
        expect_opencode_skills
    );
    assert_eq!(
        find(&reports, "opencode-commands").synced,
        expect_opencode_commands
    );

    // --- 4. Dry-run counts but mutates nothing -----------------------
    let probe = claude_dir.join("__dry_probe__.md");
    assert!(!probe.exists());
    let before = std::fs::read_dir(&claude_dir).unwrap().count();
    let reports = sync_skills(repo, true).agents;
    assert_eq!(find(&reports, "claude").status, SkillSyncStatus::Synced);
    assert_eq!(find(&reports, "claude").synced, expect_claude);
    assert_eq!(
        std::fs::read_dir(&claude_dir).unwrap().count(),
        before,
        "dry-run must not add or remove any installed skill"
    );

    // --- 5. Path exists but is not a directory => skipped ------------
    let other = tempdir().expect("home2");
    unsafe { std::env::set_var("HOME", other.path()) };
    std::fs::create_dir_all(other.path().join(".codex")).expect("mk .codex");
    std::fs::write(other.path().join(".codex").join("skills"), b"not a dir")
        .expect("file where dir expected");
    let reports = sync_skills(repo, false).agents;
    let codex = find(&reports, "codex");
    assert_eq!(codex.status, SkillSyncStatus::Skipped);
    assert!(
        codex.detail.unwrap_or_default().contains("not a directory"),
        "a non-dir at the agent path must be reported, not clobbered"
    );
    assert_eq!(
        std::fs::read(other.path().join(".codex").join("skills")).unwrap(),
        b"not a dir",
        "the offending file must be left exactly as-is"
    );

    unsafe { std::env::remove_var("HOME") };
}

